// 自動生成: tools/build-why.mjs(1125 問・3375 選択肢)。{ 問題id: { 不正解の選択肢の番号: [なぜ間違いか, [間違いに直結する部分...]] } }
export default {"AIB-C01-001":{"0":["正解ラベルを付ける作業は学習の前に行うデータ準備（アノテーション）です。完成したモデルを使って出力を得る推論とは別の工程です。",["正解のラベルを付ける"]],"1":["データを使ってモデルのパラメータを調整するのは学習（トレーニング）の説明です。推論は学習が終わったモデルを使う段階で、パラメータは変わりません。",["パラメータを調整する"]],"2":["評価用データで性能を測るのはモデルの評価の工程です。推論は新しい入力に対して予測や回答を得ることで、合否判定ではありません。",["性能を評価用データで測定し"]]},"AIB-C01-002":{"1":["項目名と値が決まった JSON は半構造化データで、表形式に変換しやすいデータです。音声や自由記述の文章のような非構造化データには当たりません。",["項目名と値が決まった形式"]],"2":["顧客マスタの CSV は行と列で項目が定義された表形式のデータで、構造化データです。非構造化データではありません。",["顧客マスタの CSV"]],"3":["会計システムの仕訳テーブルはデータベースの表に項目ごとに格納された構造化データです。音声や文章のような非構造化データではありません。",["仕訳テーブル"]]},"AIB-C01-003":{"0":["文書の長さに応じて自動的に上位モデルへ切り替わる仕組みはありません。利用するモデルは利用者が指定し、料金はそのモデルのトークン単価で決まります。",["自動的に上位のモデルに切り替わって"]],"1":["推論時にモデルが追加で学習することはありません。長い文書ほど高くなるのは、処理する入出力のトークン数が増えるためです。",["追加で学習を行う"]],"3":["オンデマンドの生成 AI の料金は利用者数ではなく入出力のトークン数で決まります。長い文書を利用者数として数える仕組みはありません。",["料金は利用者数で決まり"]]},"AIB-C01-004":{"0":["マネージドサービスでも、データのアクセス権の設定は利用企業の責任です。すべてを AWS が負うわけではなく、責任共有モデルに反します。",["すべて AWS が責任を負う"]],"1":["AWS が AI の出力内容の正確性を保証することはありません。出力をどう検証し業務に使うかは利用企業の責任です。",["正確性は AWS が保証し"]],"3":["マネージドサービスではソフトウェアの保守や運用も AWS が担います。物理的な安全だけを AWS が担うという分担は誤りです。",["ソフトウェアの保守は利用企業が行う"]]},"AIB-C01-005":{"0":["ルールベースは人があらかじめ条件を決めて判定する方式で、データから未知のグループを見つけることはできません。似た行動の顧客群の発見には向きません。",["ルールベースの判定"]],"2":["強化学習は行動に対する報酬をもとに最適な行動を学ぶ手法で、ロボット制御などに使われます。ラベルのない購買履歴からのグループ分けには使いません。",["強化学習"]],"3":["分類は正解ラベル付きのデータで学習する教師あり学習です。今回は正解ラベルがないため、分類モデルを学習できません。",["教師あり学習（分類）"]]},"AIB-C01-006":{"1":["人が条件分岐を書いたプログラムはルールベースのシステムで、データから学習したモデルではありません。多様なタスクに応用できる基盤モデルとは異なります。",["条件分岐として書いたプログラム"]],"2":["1 社の売上データだけで学習した予測モデルは特定用途向けの従来型 ML です。幅広いデータで事前学習し多様なタスクに使える基盤モデルとは異なります。",["1 社の売上データだけで学習した"]],"3":["データベースの設計図はスキーマや ER 図のことで、AI のモデルではありません。基盤モデルの説明とは無関係です。",["データベースの設計図"]]},"AIB-C01-007":{"1":["3 つは無関係ではなく包含関係にあります。ML は AI を実現する手法の一つで、ディープラーニングは ML の一分野です。",["互いに無関係な技術"]],"2":["包含関係が逆です。最も広い概念が AI で、その中に ML、さらにその中にディープラーニングがあります。",["ディープラーニングの中に ML があり"]],"3":["ML は AI の一部であって同じものではありません。またディープラーニングは ML の一分野なので AI に含まれます。",["同じもの","AI に含まれない"]]},"AIB-C01-008":{"0":["生成 AI は確率的に次の語を選ぶため、同じ質問でも表現が変わるのは通常の動作です。故障を示すものではありません。",["システムが故障している"]],"1":["生成 AI は入力が同じでも確率的なサンプリングで出力が変わることがあります。利用者の操作ミスではありません。",["出力は常に同じになるはず"]],"2":["出力のばらつきはキャッシュの削除とは関係なく、確率的な生成によるものです。表現が変わっても必ず誤りになるわけではありません。",["キャッシュから削除された","必ず誤った回答になる"]]},"AIB-C01-009":{"0":["同時利用者数はサービスの同時実行数やクォータの話で、コンテキストウィンドウとは無関係です。コンテキストウィンドウは 1 回に扱えるトークン数の上限です。",["同時に利用できる利用者の人数"]],"1":["学習に使ったデータの期間は知識のカットオフに関する話です。コンテキストウィンドウは 1 回の処理で扱える入出力の情報量の上限を指します。",["学習に使ったデータの期間"]],"2":["コンテキストウィンドウは画面表示の大きさではありません。モデルが 1 回の処理で入力と出力を合わせて扱えるトークン数の上限を指します。",["画面の大きさ"]]},"AIB-C01-010":{"0":["分類モデルは既存の選択肢から振り分けるだけで、新しい商品説明文を作れません。文章の作成は生成 AI が得意な領域です。",["過去の説明文を分類して流用する"]],"1":["生成 AI に売上表を渡して数値を生成させると、根拠や精度の検証が難しくなります。数値予測は過去データで学習する従来型 ML が適しています。",["売上予測も過去の売上表をプロンプトに入れて"]],"2":["組み合わせが逆です。数値の予測は従来型 ML、新しい文章の作成は生成 AI が適しており、分類モデルでは説明文を作れません。",["売上予測は生成 AI","従来型 ML の分類モデル"]]},"AIB-C01-011":{"0":["最新で高性能なモデルでもハルシネーションは起こりえます。モデル選定だけでは顧客に誤った回答が表示されるリスクを防げません。",["ハルシネーションは起きない"]],"2":["温度を 0 にすると出力のばらつきは減りますが、事実の誤りはなくなりません。設定変更だけでは顧客への誤回答を防げません。",["温度を 0 に設定すれば誤りはなくなる"]],"3":["注意書きを表示するだけでは誤った回答がそのまま顧客に届きます。出典の提示や人の確認など、影響を抑える仕組みが必要です。",["それ以外の対策は行わない"]]},"AIB-C01-012":{"2":["画像から不良品を見つけるには、見た目の多様なパターンを捉える必要があり、明確なルールで書き切れません。画像認識の AI が向く課題です。",["商品画像からの不良品検出"]],"3":["自由記述のメールは表現がさまざまで、キーワードのルールだけでは正確に分類しにくい課題です。自然言語処理の AI が向いています。",["内容に応じた自動分類"]],"4":["顧客ごとの購買傾向は複雑なパターンで、人がルールで書き切れません。データから学習する推薦の AI が向く課題です。",["購買傾向に基づく商品推薦"]]},"AIB-C01-013":{"0":["回帰モデルは査定額のような数値を予測するもので、写真と説明文を合わせて分析したり、査定の下書き文章を作ったりはできません。",["査定額を予測する回帰モデル"]],"2":["テキストのみを扱うモデルでは事故車の写真を入力できません。写真と説明文を合わせて分析する要件を満たせません。",["テキストのみを扱う"]],"3":["画像分類モデルは損傷の有無を判定するだけで、説明文を合わせた分析や査定の下書き文章の作成はできません。",["損傷の有無だけを判定する"]]},"AIB-C01-014":{"0":["画面のデザインは予測値そのものの精度に影響しません。検証では高精度なのに実データで外れるのは、モデルの汎化性能の問題です。",["画面のデザインが悪い"]],"1":["モデルの名前は予測の精度とは無関係です。検証で高精度、本番で外れるという現象は過学習の典型的な兆候です。",["モデルの名前"]],"3":["利用者が多いと応答の遅延などは起こりえますが、予測値が大きく外れる原因にはなりません。原因は新しいデータへの対応力の不足です。",["利用者が多すぎる"]]},"AIB-C01-015":{"0":["取引明細を要約しても、どの取引が不正かは判定できません。正常から外れた取引を検知するという目的に合いません。",["要約する生成 AI"]],"1":["時系列予測は件数の将来の推移を予測する手法で、個々の取引が不正かどうかは判定できません。",["取引件数を予測する時系列予測"]],"3":["顔写真の照合は本人確認の手段で、取引のパターンから不正利用を見つけるものではありません。新しい手口の検知にも対応できません。",["顔写真を照合する画像認識"]]},"AIB-C01-016":{"0":["他業界のデータで学習したモデルは、新規市場の状況を反映していません。根拠を検証せずにそのまま採用すると誤った経営判断につながります。",["他業界のデータで学習した","そのまま採用する"]],"2":["モデルのサイズを大きくしても、根拠となる過去データがなければ予測の精度は上がりません。データ不足という根本の問題は解決しません。",["モデルのサイズを大きくする"]],"3":["ML の予測は過去データのパターンに基づくため、データがない領域では信頼できません。どんなデータでも正確に予測できるという前提が誤りです。",["どのようなデータでも AI は正確に予測できる"]]},"AIB-C01-017":{"0":["生成 AI は確率的に出力するため、計算を誤ったり結果が毎回変わったりすることがあります。法令どおり常に同じ結果が必要な税額計算には向きません。",["生成 AI に毎回税額を計算させる"]],"1":["予測モデルは過去データから近似値を推定するもので、誤差が生じます。計算式で一意に決まる税額を正確に出す要件に合いません。",["過去の給与明細で学習した予測モデル"]],"3":["画像認識モデルは画像の内容を識別するもので、税額の計算はできません。業務の性質と無関係な技術です。",["画像認識モデル"]]},"AIB-C01-018":{"0":["音声認識は音声を文字に変換する技術で、契約条項どうしの意味の近さを比べることはできません。",["音声を文字に変換する音声認識"]],"1":["画像生成は文章から画像を作る技術で、意味の近い条項を探す検索には使えません。",["文章を画像に変換する画像生成"]],"2":["文字数を数えても文章の意味は比較できません。キーワードが一致しなくても内容の近い条項を探すには、意味をベクトルで表す必要があります。",["文字数を数える集計処理"]]},"AIB-C01-019":{"1":["温度を 0 にすると出力が安定する一方で多様性がなくなり、アイデア出しで幅広い案を得られません。用途に応じた使い分けが必要です。",["どちらも温度を 0 にする"]],"2":["温度を最大にすると出力のばらつきが大きくなり、社内規程に基づく定型回答の一貫性が損なわれます。",["どちらも温度を最大にする"]],"3":["温度は料金ではなく出力の多様性と安定性に影響するパラメータです。用途に応じて調整する必要があります。",["温度は料金だけに影響する"]]},"AIB-C01-020":{"0":["モデルが故意に古い情報を答えることはなく、学習データの時点（カットオフ）以降の知識を持たないのが原因です。言語を変えても解決しません。",["故意に古い情報を答えている"]],"1":["回答の文字数を増やしても、モデルが持たない最新の知識は得られません。最新の法令文書を外部から与える必要があります。",["回答の文字数を増やせば"]],"2":["生成 AI は学習した時点までの知識しか持たず、常に最新情報を知っているわけではありません。質問の仕方だけの問題ではありません。",["常に最新情報を知っている"]]},"AIB-C01-021":{"1":["生成 AI の評価だけを根拠にすると、偏りや誤りがそのまま採否に影響します。人の人生に関わる判断は人が責任を持って行う必要があります。",["唯一の根拠として採用する"]],"2":["本人の同意なく面接の録音を入力するのは、個人情報の適切な取り扱いに反します。プライバシーと法令遵守の面で問題があります。",["本人の同意なく"]],"3":["合否を生成 AI に決めさせてそのまま通知すると、人による確認や説明責任がなくなります。重要な判断を AI に丸投げすべきではありません。",["生成 AI に合否を決めさせ"]]},"AIB-C01-022":{"0":["学習にかかった時間は開発の効率の指標で、不良品の見逃しの多さは測れません。品質部門の要件と無関係です。",["学習にかかった時間"]],"2":["処理枚数は処理能力の指標で、不良品をどれだけ見逃したかは分かりません。見逃しを減らすには再現率を見る必要があります。",["処理できる画像の枚数"]],"3":["適合率は誤検知（良品を不良と判定）の少なさを測る指標です。今回は誤検知をある程度許容し見逃しを減らしたいので、重視すべきは再現率です。",["実際に不良だった割合（適合率）"]]},"AIB-C01-023":{"0":["画像生成モデルは画像を作るもので、検索窓の文字の候補を出す用途に合いません。応答速度やコストの要件以前に機能が異なります。",["画像生成モデル"]],"1":["モデルの規模は速度とコストに大きく影響します。大型のモデルほど応答が遅く、トークン単価も高くなる傾向があります。",["速度やコストに影響しない"]],"2":["最も大きいモデルは高品質でも応答が遅く高価で、大量アクセス時のコストが膨らみます。即時の候補表示という要件に合いません。",["常に最も大きく高性能なモデル"]]},"AIB-C01-024":{"0":["時系列モデルは出張件数の推移を予測するだけで、規程確認や登録、承認依頼といった手順を実行できません。",["出張件数を予測する時系列モデル"]],"1":["画像分類モデルは画像の内容を判定するだけで、複数システムにまたがる申請手続きを進めることはできません。",["画像を分類するモデル"]],"3":["1 回答えるだけのチャットボットは、計画を立ててツールや API を順に呼び出すことができません。複数ステップの業務を自動化できません。",["1 つの質問に 1 回答えるだけ"]]},"AIB-C01-025":{"0":["法定の計算式による集計は構造化データの決まった処理で、従来のプログラムで正確に行えます。非構造化データの活用でもありません。",["法定の計算式で集計する"]],"3":["社員番号の重複チェックは構造化データに対する単純な照合で、通常のプログラムで十分です。生成 AI を使う必要はありません。",["社員番号の重複をチェックする"]],"4":["決まった時刻の転記は定型のデータ連携で、ジョブのスケジュール実行などで自動化できます。生成 AI が得意な非構造化データの活用ではありません。",["決まった時刻に別システムへ転記する"]]},"AIB-C01-026":{"0":["他行のモデルは自行の顧客層や基準に合っているとは限りません。検証せずに使うと誤った否決が起き、当局への説明もできません。",["検証せずに使う"]],"1":["数百件のデータでは深層学習モデルは過学習しやすく、判断根拠の説明も困難です。説明責任が重い審査を全自動化するのは不適切です。",["数百件のデータで深層学習モデル"]],"3":["判断理由を記録しなければ、誤った否決について顧客や規制当局に説明できません。説明責任の要件に反します。",["判断理由を記録せずに"]]},"AIB-C01-027":{"0":["文章作成という生成 AI の利点まで捨てることになり、効率化の機会を失います。計算だけを確実な仕組みに切り分ければ両立できます。",["すべて手作業に戻す"]],"1":["計算に誤りがある資料を提出すると経営判断を誤らせます。文章が自然でも数値の正確さは保証されないため、検証と修正が必要です。",["そのまま経営会議に提出する"]],"2":["温度を最大にすると出力のばらつきが増え、計算の誤りはむしろ起きやすくなります。正確な計算の手段にはなりません。",["温度を最大にして"]]},"AIB-C01-028":{"0":["回答を長くしても誤りは減らず、むしろ誤った記述が増えるおそれがあります。誤りを目立たなくするのは苦情や法的リスクへの対策になりません。",["誤りが目立たないようにする"]],"1":["モデルの品質は継続的に評価しないと、誤回答の増加に気付けません。評価をやめるとハルシネーションの影響を把握できなくなります。",["評価を行わない"]],"2":["温度を高くすると出力のばらつきが増え、根拠のない内容が出やすくなります。正確さが重要な約款の回答には逆効果です。",["温度を高くして"]]},"AIB-C01-029":{"0":["生成 AI が出す数値は根拠や精度の検証が難しく、そのまま生産計画に使うと過剰生産や欠品につながります。数値予測には時系列予測モデルが適しています。",["出力された数値をそのまま生産計画に使う"]],"2":["技術の新しさは手法を選ぶ根拠になりません。生産計画に直接使う予測値を、精度の検証なしに採用するのは危険です。",["精度の検証なしに採用する"]],"3":["過去 5 年分の出荷実績と気象データが整っているのに使わないのは、精度の高い予測の機会を捨てることになります。",["データは使わない"]]},"AIB-C01-030":{"1":["正解率 85% のまま確認なしで自動入力すると、月 2 万件のうち多くの誤りが決算に混入します。99% 以上という要件を満たせません。",["確認なしで全件を自動入力する"]],"2":["算出方法を変えて数値をよく見せても、実際の誤りは減りません。決算への影響が残るうえ、不正確な報告は信頼を損ないます。",["算出方法を変えて 99% と報告する"]],"3":["AI 単体で要件に届かなくても、人の確認と組み合わせれば正確さを満たせる可能性があります。完全に断念すると人手不足を解消できません。",["完全に断念する"]]},"AIB-C01-031":{"0":["RPA は記録した固定手順を繰り返すだけで、目標に向けて自ら計画を立てたり判断したりはしません。AI エージェントとは異なります。",["画面操作の記録どおりに繰り返し実行する"]],"1":["登録済みの質問と回答に従うだけのチャットボットは、ツールを使って複数ステップの作業を自律的に進めることはできません。",["あらかじめ登録した質問と回答の組み合わせ"]],"3":["文書を検索して 1 回回答を生成するのは RAG の仕組みです。自ら計画を立てて複数ステップの作業を進めるエージェントとは異なります。",["根拠付きの回答文を 1 回生成する"]]},"AIB-C01-032":{"0":["Amazon Personalize は購買履歴などから推薦を行う特化型サービスです。複数の基盤モデルを比較してアプリに組み込む用途には使えません。",["Amazon Personalize"]],"2":["Amazon Polly はテキストを音声に変換する音声合成サービスです。複数の基盤モデルを選んで生成 AI を組み込む機能はありません。",["Amazon Polly"]],"3":["Amazon Comprehend は感情分析などのテキスト分析に特化したサービスです。複数社の基盤モデルを API で比較・利用する機能はありません。",["Amazon Comprehend"]]},"AIB-C01-033":{"0":["Amazon Personalize は推薦に特化したマネージドサービスで、任意の予測モデルを自由に開発・学習・デプロイする基盤ではありません。",["Amazon Personalize"]],"2":["Amazon Quick はビジネス向けの AI アシスタントや分析の機能で、データサイエンスチームが独自モデルを学習・デプロイする基盤ではありません。",["Amazon Quick"]],"3":["Bedrock Knowledge Bases は社内文書を検索して回答に使う RAG の仕組みです。独自の予測モデルを学習・デプロイする機能ではありません。",["Knowledge Bases"]]},"AIB-C01-034":{"0":["Amazon Polly はテキストを音声に変換するサービスで、音声を文字に起こす文字起こしとは処理が逆です。",["Amazon Polly"]],"1":["Amazon Rekognition は画像や動画を分析するサービスで、通話録音の音声を文字に起こす機能はありません。",["Amazon Rekognition"]],"2":["Amazon Translate はテキストを別の言語に翻訳するサービスで、音声を文字に起こすことはできません。",["Amazon Translate"]]},"AIB-C01-035":{"1":["Amazon Polly はテキストを音声に変換するサービスで、画像の内容を分析して不適切なものを検出することはできません。",["Amazon Polly"]],"2":["Amazon Comprehend はテキストの自然言語処理サービスで、画像に含まれる不適切な内容は検出できません。",["Amazon Comprehend"]],"3":["Amazon Transcribe は音声を文字に起こすサービスで、アップロードされた画像の内容をチェックする機能はありません。",["Amazon Transcribe"]]},"AIB-C01-036":{"1":["Amazon Rekognition は画像や動画を分析するサービスで、レビュー文章の感情分析やキーフレーズ抽出はできません。",["Amazon Rekognition"]],"2":["Amazon Textract は文書の画像や PDF から文字や表を抽出するサービスで、文章の感情やキーフレーズの分析は行いません。",["Amazon Textract"]],"3":["Amazon Polly はテキストを音声に変換するサービスで、レビューの感情分析やキーフレーズ抽出の機能はありません。",["Amazon Polly"]]},"AIB-C01-037":{"0":["音声合成サービスはテキストを音声にするもので、コードの生成や改善提案はできません。開発チームの生産性向上という目的に合いません。",["音声合成サービス"]],"2":["レコメンデーションサービスは購買履歴から商品を推薦するもので、コードの生成や説明を行う機能はありません。",["レコメンデーションサービス"]],"3":["画像分析サービスは画像や動画の内容を検出するもので、コードの生成や既存コードの改善提案には使えません。",["画像分析サービス"]]},"AIB-C01-038":{"0":["ゼロからの事前学習は大量のデータでモデル自体を作る工程で、プロンプトに例を示す手法ではありません。",["ゼロからの事前学習"]],"2":["ファインチューニングは追加データでモデルの重みを更新する手法です。プロンプトに例を含めるだけでモデルを変えない手法とは異なります。",["ファインチューニング"]],"3":["データの匿名化は個人情報を識別できないようにする処理で、例を示して出力の形を誘導するプロンプトの手法ではありません。",["データの匿名化"]]},"AIB-C01-039":{"0":["AWS Direct Connect はオンプレミスと AWS を専用線で接続するネットワークサービスで、生成 AI アプリの試作には使えません。",["AWS Direct Connect"]],"2":["AWS Snowball は大容量データを物理デバイスで AWS に移行するサービスで、ノーコードで生成 AI を試す環境ではありません。",["AWS Snowball"]],"3":["Amazon EBS は EC2 にアタッチするブロックストレージで、プログラミングなしで生成 AI アプリを試作する機能はありません。",["Amazon EBS"]]},"AIB-C01-040":{"0":["RAG は根拠となる文書を使うことで誤りを減らせますが、原理的になくなるわけではありません。人による確認の仕組みは引き続き必要です。",["誤りが原理的になくなり"]],"2":["知識をモデルの重みに組み込むのはファインチューニングの考え方です。RAG は回答時に文書を検索して使うため、文書がなければ回答できません。",["モデルの重みに組み込み"]],"3":["文体や口調を恒久的に合わせるのはファインチューニングの得意分野です。RAG の主な価値は最新の社内文書に基づいて回答できることです。",["文体や口調を自社のスタイルに恒久的に"]]},"AIB-C01-041":{"0":["RAG は事実情報の参照には向きますが、文体を安定して定着させる効果は限られます。プロンプトで安定しなかった文体の問題を解決しにくい方法です。",["RAG で検索させ"]],"1":["温度を上げると表現のばらつきが増え、ブランドの文体に一貫して合わせるという目的と逆の結果になります。",["温度を上げて"]],"3":["基盤モデルをゼロから事前学習するには膨大なデータとコスト、期間が必要です。文体を合わせるだけの目的には過剰です。",["ゼロから事前学習する"]]},"AIB-C01-042":{"1":["対象を短い提案書に限定すると業務の範囲が狭まるだけで、ばらつきの原因である曖昧な指示は改善されません。",["短い提案書に限定する"]],"2":["ファインチューニングはデータの準備や学習にコストと時間がかかります。プロンプトの改善で解決しない場合に検討する手段で、最初に試すものではありません。",["ファインチューニングを行う"]],"3":["高価なモデルへの切り替えはコストが増えるうえ、指示が曖昧なままではばらつきが残ります。まず低コストなプロンプトの改善を試すべきです。",["より高価で高性能なモデル"]]},"AIB-C01-043":{"0":["SageMaker AI での独自モデル開発はデータの準備や学習に時間がかかり、最も手早い導入という要件に合いません。",["独自の文書理解モデル"]],"1":["Amazon Rekognition は画像内の物体や顔の認識が主な用途で、請求書の金額や日付といった項目を構造的に抽出する用途には向きません。",["物体や顔を検出する Amazon Rekognition"]],"2":["Amazon Comprehend はテキストの感情やキーフレーズを分析するサービスで、PDF の請求書から金額や日付の項目を読み取る機能はありません。",["感情やキーフレーズを分析する"]]},"AIB-C01-044":{"1":["部署ごとに独自に工夫すると、良いプロンプトが共有されずばらつきが残ります。全社で品質をそろえるという目的に合いません。",["それぞれが独自にプロンプトを工夫する"]],"2":["1 つの汎用プロンプトに固定し変更を禁止すると、業務ごとの要件に対応できず、継続的な改善もできません。",["変更を禁止する"]],"3":["研修を一度行うだけでは、その後の品質は各自の力量に左右され、ばらつきが残ります。良いプロンプトの共有や改善の仕組みがありません。",["その後は各自に任せる"]]},"AIB-C01-045":{"0":["利用者に毎回書き添えてもらう方法では、書き忘れや書き方の違いで方針が守られません。利用者に依存せず一貫させる要件に合いません。",["利用者に毎回"]],"1":["後から手作業で削除するのは事後対応で、方針に反した回答が一度は利用者に届きます。運用の負荷も大きくなります。",["後から手作業で削除する"]],"2":["温度を最大にすると出力のばらつきが増え、丁寧語や回答範囲といった方針はむしろ守られにくくなります。",["温度を最大にする"]]},"AIB-C01-046":{"2":["短く答えるよう指示すると途中の検討が省かれ、複数の条件を見落として結論を誤りやすくなります。",["とにかく短く答えて"]],"3":["料金プランの情報を削除すると、モデルは根拠なく推測で比較することになり、誤りがかえって増えます。",["プロンプトから削除する"]],"4":["英語の大文字で書いても条件の整理や段階的な検討にはつながらず、比較の正確さは向上しません。",["英語の大文字で書く"]]},"AIB-C01-047":{"0":["担当者の記憶に頼ると、今回のように変更前の内容が分からず切り戻せません。担当者の異動などでも情報が失われます。",["担当者の記憶に任せる"]],"1":["原因がプロンプトの変更にあるのにモデルを切り替えても、問題の把握や再発防止にはなりません。変更履歴がない状態も変わりません。",["別のモデルに切り替える"]],"3":["プロンプトを一切変更しないと、品質の改善や業務の変化への対応ができなくなります。変更を管理して切り戻せるようにすべきです。",["今後一切変更しない"]]},"AIB-C01-048":{"0":["AWS Backup は AWS リソースのバックアップを一元管理するサービスで、プロンプトの作成やバージョン管理の機能はありません。",["AWS Backup"]],"1":["Amazon Route 53 は DNS サービスで、生成 AI アプリのプロンプトを作成・管理する機能はありません。",["Amazon Route 53"]],"2":["AWS Cost Explorer は利用料金の実績を分析するツールで、プロンプトを保存してバージョンを管理する機能はありません。",["AWS Cost Explorer"]]},"AIB-C01-049":{"0":["AWS Pricing Calculator は利用料金を見積もるツールで、社内文書を取り込んで検索し回答に使う仕組みは提供しません。",["AWS Pricing Calculator"]],"2":["Amazon Rekognition は画像や動画を分析するサービスで、マニュアルや FAQ を検索して回答する RAG の機能はありません。",["Amazon Rekognition"]],"3":["Amazon Polly はテキストを音声に変換するサービスで、社内文書の取り込みや検索の仕組みは提供しません。",["Amazon Polly"]]},"AIB-C01-050":{"1":["翻訳モデルをゼロから開発すると多大なデータとコスト、期間がかかります。標準的な翻訳を低コストで行う要件に合いません。",["ゼロから開発する"]],"2":["Amazon Transcribe は音声を文字に起こすサービスで、Web サイトの文章を他言語に翻訳する機能はありません。",["Amazon Transcribe"]],"3":["画像生成モデルは文章から画像を作るもので、案内文の機械翻訳には使えません。",["画像生成モデル"]]},"AIB-C01-051":{"1":["学習データの件数はプロンプトインジェクションへの耐性とは関係しません。指示の上書きを狙う入力を防ぐ対策にはなりません。",["学習データの件数を増やす"]],"2":["システムプロンプトでの禁止指示は、攻撃者の入力で上書きされるおそれがあります。機密情報を書き込むこと自体が漏えいの原因になります。",["システムプロンプトに機密情報を書き込み"]],"3":["温度は出力の多様性を調整するもので、攻撃への耐性とは無関係です。むしろ予期しない出力が増えるおそれがあります。",["温度を上げて"]]},"AIB-C01-052":{"1":["毎日ファインチューニングし直すと、学習のコストと手間が大きく、更新の反映にも時間差が出ます。頻繁に変わる情報には RAG が適しています。",["毎日モデルをファインチューニングし直す"]],"2":["物件データを与えなければ、モデルは最新の物件情報を知りません。言い回しを工夫しても正しい回答はできません。",["物件データをモデルに与えずに"]],"3":["基盤モデルをゼロから学習するのは膨大なコストと期間がかかり、毎日更新される情報にも追従できません。",["ゼロから学習させる"]]},"AIB-C01-053":{"0":["SageMaker AI での独自モデル開発には専門家が必要で、開発者に頼らず自然な言葉で分析するという条件に合いません。",["独自の予測モデルを開発する"]],"1":["Amazon Transcribe は音声を文字に起こすサービスで、売上データの分析やグラフの作成はできません。",["Amazon Transcribe"]],"2":["AWS Direct Connect はオンプレミスと AWS を専用線で結ぶネットワークサービスで、データ分析の機能はありません。",["AWS Direct Connect"]]},"AIB-C01-054":{"0":["Amazon Polly はテキストを音声に変換するサービスで、文書作成支援、生成 AI の組み込み、予測モデル開発のいずれにも対応できません。",["3 つとも Amazon Polly を使う"]],"1":["割り当てがずれています。SageMaker AI は ML 開発基盤で全社員の文書作成支援には向かず、独自の予測モデル開発には Bedrock ではなく SageMaker AI が適しています。",["①Amazon SageMaker AI","③Amazon Bedrock"]],"3":["すべてをゼロから開発すると時間とコストがかかり、すぐ使える文書作成支援や基盤モデルの組み込みで早く価値を出す機会を失います。",["ゼロから開発する"]]},"AIB-C01-055":{"0":["独自の基盤モデルをゼロから開発すると膨大なコストと期間がかかり、コストを抑えるという要件に反します。",["独自の基盤モデルをゼロから開発する"]],"1":["研究報告書を使わなければ、モデルは社内の研究内容を知らず、報告書に基づく質問応答ができません。",["研究報告書は使わず"]],"3":["毎週ファインチューニングし直すと学習コストがかさみ、追加される報告書の反映も遅れます。頻繁に変わる知識は RAG で参照する方が低コストです。",["毎週","ファインチューニングし直す"]]},"AIB-C01-056":{"1":["評価せずに本番へ反映すると、品質が下がっても苦情が出るまで気付けません。契約書チェックの誤りは業務に大きな影響を与えます。",["苦情が出たら考える"]],"2":["担当者 1 人の感想は主観的で、改善の根拠として不十分です。共通の評価データと基準で新旧を比較する必要があります。",["担当者の感想を根拠に"]],"3":["プロンプトは長いほど良いとは限らず、不要な指示が品質を下げることもあります。評価をせず長さで選ぶのは根拠がありません。",["長いプロンプトのほうが必ず良い"]]},"AIB-C01-057":{"1":["ルールで固定するとデータを使わないため、自社の閲覧・購買データに基づく推薦という要件を満たせません。",["データは使わない"]],"2":["SageMaker AI でゼロから推薦アルゴリズムを作るには ML の専門家が必要です。専門家不在で 3 か月以内に公開するという制約に合いません。",["推薦アルゴリズムをゼロから開発する"]],"3":["毎回すべての商品一覧を渡すとトークン数が膨らみコストが大きく、コンテキストウィンドウの上限も超えやすくなります。購買データに基づく推薦にもなりません。",["毎回すべての商品一覧を渡して"]]},"AIB-C01-058":{"1":["初日から全取引を完全自動化すると、誤りがあった場合に大量の誤った支払い登録が発生します。段階的な導入と人の確認が必要です。",["導入初日から全取引を完全に自動化する"]],"2":["管理者権限を与えると、誤動作や悪用の際に影響が全システムに及びます。最小権限の原則に反します。",["管理者権限をエージェントに与える"]],"3":["ログを無効にすると、エージェントが何をしたか追跡できず、誤りの原因究明や監査ができなくなります。",["ログを無効にする"]]},"AIB-C01-059":{"1":["音声認識と翻訳のモデルをゼロから開発するのは時間とコストがかかります。開発の手間を抑えるという要件に反します。",["SageMaker AI でゼロから開発する"]],"2":["Textract は文書の画像から文字を抽出するサービスで音声は扱えず、Comprehend はテキスト分析のサービスで翻訳はできません。",["音声を読み取り","Comprehend で翻訳する"]],"3":["Polly はテキストから音声を作るサービスで文字起こしの逆です。Rekognition は画像・動画の分析で、音声の翻訳はできません。",["Amazon Polly で音声を合成し"]]},"AIB-C01-060":{"0":["無料の一般向けサービスに社内文書を貼り付けると、情報漏えいのリスクがあり、社内のアクセス権限も反映されません。",["社内文書を自由に貼り付けて"]],"1":["アクセス権限の要件を外すと、閲覧権限のない社員が機密文書を見られてしまいます。セキュリティ要件に明確に反します。",["アクセス権限の要件を外して"]],"3":["IT 部門 3 名で機能ごとにゼロから開発すると、提供までに時間がかかり運用負荷も大きくなります。早く全社員に提供する要件に合いません。",["機能ごとにゼロから開発する"]]},"AIB-C01-061":{"0":["AWS Budgets は設定した予算に対する実績や予測を監視して通知するツールで、利用開始前の利用量から費用を見積もるものではありません。",["AWS Budgets"]],"2":["AWS Cost Explorer は過去の実績コストを分析するツールで、まだ運用していないアプリの月額を見積もるには向きません。",["AWS Cost Explorer"]],"3":["AWS Trusted Advisor は既存環境のコストやセキュリティの改善提案を行うツールで、想定利用量からの費用見積もりはできません。",["AWS Trusted Advisor"]]},"AIB-C01-062":{"0":["AWS Artifact は AWS のコンプライアンスレポートや契約を入手するサービスで、サードパーティーの AI ソリューションは購入できません。",["AWS Artifact"]],"1":["Generative AI Innovation Center は AWS の専門家による支援プログラムで、ソリューションを購入して AWS の請求にまとめる場ではありません。",["Innovation Center"]],"3":["AWS Skill Builder は AWS の学習コンテンツを提供するサービスで、業界向けの AI ソリューションを調達する仕組みはありません。",["AWS Skill Builder"]]},"AIB-C01-063":{"0":["他社事例は自社の経営目標や課題に合っているとは限りません。事例を起点にすると、技術ありきの施策になりやすくなります。",["同業他社が発表している AI 導入事例"]],"1":["部門の要望は参考になりますが、経営目標との整合を確認しないまま並べても優先順位を付けられません。戦略の出発点としては不十分です。",["AI で試したいことの要望一覧"]],"3":["利用可能な技術やツールから考えると、解くべき課題が後回しになり技術ありきの戦略になります。経営目標から逆算すべきです。",["AI 技術とツールの一覧"]]},"AIB-C01-064":{"1":["SWOT 分析は自社の強み・弱み・機会・脅威を整理する環境分析で、プレスリリースや FAQ を先に書いて顧客価値から逆算する手法ではありません。",["SWOT 分析"]],"2":["ウォーターフォール型の要件定義は開発工程を順に進める進め方で、完成後の顧客体験を文章化してから施策を固める手法ではありません。",["ウォーターフォール型の要件定義"]],"3":["ベンチマークテストはシステムやモデルの性能を測定する試験で、顧客にとっての価値から施策を逆算する企画手法ではありません。",["ベンチマークテスト"]]},"AIB-C01-065":{"0":["ライセンスの有効期間は契約上の期間で、投資額をいつ回収できるかとは関係ありません。",["ライセンスが有効な期間"]],"1":["学習の完了までの期間は開発の工程の話です。投資回収期間は累積の正味効果が初期投資額に達するまでの期間を指します。",["学習が完了するまでにかかる期間"]],"3":["パイロットの実施期間は検証の期間で、投資額を正味の効果で回収し終えるまでの期間とは異なります。",["パイロットの開始から終了までの期間"]]},"AIB-C01-066":{"0":["パラメータ数が最大のモデルが最適とは限らず、実現可能性の判断材料にもなりません。AI の成果はまず利用できるデータに左右されます。",["パラメータ数が最大かどうか"]],"1":["担当者の関心は推進力にはなりますが、ユースケースが技術的に実現できるかの判断材料にはなりません。データの有無を確認すべきです。",["担当者が AI に興味を持っているか"]],"3":["競合の動向は優先度の参考にはなっても、自社で実現できるかの判断材料にはなりません。必要なデータを利用できるかが中心です。",["競合他社がすでに同じ施策を発表しているか"]]},"AIB-C01-067":{"1":["撤退基準の目的は責任追及ではなく、客観的に継続・中止を判断して資源を適切に再配分することです。",["担当者の責任を問うため"]],"2":["撤退基準は成果が出ない施策を止めるためのもので、予算を自動的に増やす仕組みではありません。",["予算を毎年自動的に増額する"]],"3":["中止条件を決めても成功が保証されるわけではありません。成果が出ない場合に早く見切りを付けるための基準です。",["必ず成功させるため"]]},"AIB-C01-068":{"0":["AWS Artifact は AWS のコンプライアンス報告書を入手するサービスで、専門家と協力してユースケースの特定や概念実証を進めるプログラムではありません。",["AWS Artifact"]],"1":["AWS Health Dashboard は AWS サービスの障害やメンテナンスの情報を確認する仕組みで、生成 AI の活用を支援するプログラムではありません。",["AWS Health Dashboard"]],"2":["AWS Trusted Advisor はアカウントのコストやセキュリティなどのベストプラクティスを自動で確認するツールで、専門家による生成 AI の支援は行いません。",["AWS Trusted Advisor"]]},"AIB-C01-069":{"0":["価値だけで選ぶと、データ不足やリスクの高さで頓挫しやすくなります。実現可能性もあわせて評価する必要があります。",["実現の難しさに関係なく選ぶ"]],"1":["各部門から同時に着手すると資源が分散し、どの案件も成果が出にくくなります。価値と実現性で絞り込むべきです。",["公平に同時に着手する"]],"2":["最新技術を試せるかは技術者側の動機で、ビジネス価値や実現可能性を基準にしていません。成果が出にくい案件を選ぶおそれがあります。",["最新の生成 AI 技術を試せる案件"]]},"AIB-C01-070":{"1":["利用回数の伸びは関心の高さを示すだけで、業務成果や本番運用のコストを示しません。展開判断の主な根拠にはなりません。",["利用回数の伸び"]],"2":["モデルが最新かどうかは業務成果と直接関係しません。事前に合意した KPI の達成状況とコスト・リスクで判断すべきです。",["現在も最新のモデルであるかどうか"]],"3":["使いやすさの評価は参考になりますが、業務成果やスケール時のコストを示すものではありません。",["「使いやすい」と答えた割合"]]},"AIB-C01-071":{"1":["初期費用だけで選ぶと、施策から得られる便益の大きさを比較できません。期待価値と機会費用を含めて判断すべきです。",["初期費用が少ないほうを選び"]],"2":["予算を半分ずつに分けると、どちらの施策も資源不足で中途半端になりやすく、成果が出にくくなります。",["半分ずつ配分し"]],"3":["すでにかけた時間は埋没費用で、今後の価値とは関係ありません。これを理由に選ぶと判断を誤ります。",["これまでの投資を無駄にしない"]]},"AIB-C01-072":{"0":["データが整っていない案件は準備に時間がかかり、早期に成果を示すことができません。",["データが整っていない"]],"1":["3 年かかる全社の刷新は成果が出るまでに長い期間が必要で、早く成果を示して支持を得るという目的に合いません。",["3 年かかる全社基幹システムの AI 刷新"]],"3":["規制上のリスクが大きい自動与信判断は、検証や説明責任への対応に時間がかかり、最初の施策としては失敗の影響も大きくなります。",["規制上のリスクが大きい"]]},"AIB-C01-073":{"0":["データサイエンティストの採用から始めると時間とコストがかかり、初期投資を抑えて数週間で試すという要件に合いません。",["データサイエンティストを 10 名採用してから"]],"1":["GPU サーバーの購入と独自モデルの事前学習は多額の投資と長い期間が必要で、専門チームのない 200 名規模の企業には過剰です。",["独自の大規模言語モデルを事前学習する"]],"3":["生成 AI の要約が 100% 正確になることはありません。この基準では導入できず、数週間で試すという要件も満たせません。",["確実に 100% になるまで"]]},"AIB-C01-074":{"0":["サーバーを常時稼働させると、処理していない時間も費用がかかります。翌朝までにまとめて処理すればよい要件に対して割高です。",["サーバーを常時稼働させる"]],"1":["即時性が不要なのに 1 件ずつリアルタイムで高性能モデルを使うと、単価が高くなりコストを抑える要件に反します。",["1 件ずつリアルタイムで処理し"]],"3":["毎月 50 万件を人手で分類すると人件費が膨大になり、かえってコストが増えます。生成 AI のバッチ処理で十分対応できます。",["分類は人手で行う"]]},"AIB-C01-075":{"1":["成功時の効果だけで比べると不確実性を見落とします。期待価値は施策 X が 3,000 万円で、施策 Y の 4,000 万円より小さくなります。",["施策 X を必ず優先する"]],"2":["成功確率が 100% の施策はほとんどありません。期待価値で比較すれば、施策 Y は投資する価値があると判断できます。",["どちらも実施しない"]],"3":["予算は 1 件分のみで、半分ずつに分けるとどちらも中途半端になりやすくなります。期待価値の高い施策 Y に集中すべきです。",["半分ずつに分けて同時に進める"]]},"AIB-C01-076":{"0":["1,800 万円を毎月の正味効果 150 万円で割ると 12 か月です。18 か月は計算が誤っています。",["18 か月"]],"1":["1,800 万円 ÷ 150 万円 = 12 か月で、6 か月では累積の正味効果は 900 万円にしかならず、初期投資を回収できていません。",["6 か月"]],"2":["1,800 万円 ÷ 150 万円 = 12 か月です。24 か月では累積効果が 3,600 万円となり、回収期間を過大に見積もっています。",["24 か月"]]},"AIB-C01-077":{"0":["汎用の既製品は自社データに合わせた調整ができないと問題文で示されています。自社の配送データに基づく予測という要件を満たせません。",["調整のできない汎用の既製品"]],"2":["施策を凍結すると、半年以内に導入するという期限を守れません。不足する専門性はパートナーで補えます。",["施策を凍結する"]],"3":["専門チームを一から採用・育成するには長い時間がかかり、半年以内の導入に間に合いません。",["一から採用・育成してから"]]},"AIB-C01-078":{"0":["楽観的な利用量だけの試算では、利用が想定を上回った場合の予算超過のリスクを見落とします。",["最も楽観的な利用量だけで試算し"]],"2":["見通しを出さないと財務部門は予算を組めません。不確実でも前提を示した試算を出すべきです。",["費用の見通しは出さない"]],"3":["前年の IT 予算は新しい生成 AI サービスの利用量や料金とは無関係で、根拠のある見通しになりません。",["前年の IT 予算と同額になる"]]},"AIB-C01-079":{"0":["施策に関係しない部門の新入社員は、業務課題や法的なリスクを判断する立場にありません。",["施策に関係しない部門の新入社員"]],"1":["競合企業の担当者を巻き込むと、自社の戦略や顧客データに関する情報が漏れるおそれがあります。",["競合企業の担当者"]],"2":["個別の施策の初期検討に社外の株主全員を巻き込むのは現実的ではなく、業務や法務の判断にも役立ちません。",["社外の株主全員"]]},"AIB-C01-080":{"0":["業務データがまったくないと、AI の精度も導入前後の効果も測れません。最初のパイロットには不向きです。",["業務データがまったく存在しない"]],"1":["最も大規模で複雑な基幹業務は失敗時の影響が大きく、成果が出るまでにも時間がかかります。最初の対象には不向きです。",["最も規模が大きく複雑な基幹業務"]],"3":["関係者が多く合意形成に時間がかかる業務は、パイロットの開始や判断が遅れ、短期間で学びを得にくくなります。",["合意形成に時間がかかる"]]},"AIB-C01-081":{"1":["利用量が少なく変動する段階で最大利用量の容量を確保すると、使わない分の費用が無駄になります。",["最初から長期間の容量を確保する"]],"2":["Amazon Bedrock のオンデマンド料金はトークン数などの利用量に応じて変わります。料金が一定という前提が誤りです。",["利用量に関係なく一定"]],"3":["利用量の変動を理由にサービスを停止する必要はありません。従量課金なら使った分だけの支払いで済みます。",["サービスを停止する"]]},"AIB-C01-082":{"0":["個人の無料チャットでは、データの保管場所や学習への不使用を契約で確認できず、未公開の経営情報を管理できません。",["個人で無料の生成 AI チャット"]],"2":["開発者の採用と体制づくりを待つと、3 か月以内に全社で使えるようにする期限に間に合いません。",["体制が整ってから自社で要約機能を開発する"]],"3":["差別化につながらない機能を開発者がほとんどいない状態でゼロから作ると、期限に間に合わずコストも高くなります。",["自社でゼロから開発する"]]},"AIB-C01-083":{"0":["効果が不確実なまま全社展開の予算を一括で確保すると、効果がなかった場合の損失が大きく、財務部門の懸念に反します。",["予算を一括で確保して導入し"]],"1":["効果が未確認のまま 3 年契約で一斉展開すると、効果がなかった場合に解約できず損失が大きくなります。",["3 年契約を結んで全営業部門に一斉展開する"]],"3":["競合の結果を待つと導入が遅れ、競合に後れを取るという経営陣の懸念に応えられません。",["競合の導入結果が公表されるまで待ち"]]},"AIB-C01-084":{"0":["最も安いモデルで一律に処理すると、高い正確性が必要な契約・料金の回答で誤りが増えます。注意書きだけでは苦情や返金を防げません。",["最も安いモデルで処理し"]],"2":["中位モデルの一律適用では契約・料金の回答の正確性が不十分なおそれがあり、苦情が来てからの対応では返金などの損失を防げません。",["苦情が来た時点で個別に対応する"]],"3":["9 割の一般的な質問まで最高性能のモデルで処理すると、件数の倍増で予算を超えます。件数の上限は顧客対応の低下につながります。",["すべての問い合わせを最も高性能なモデルで処理する"]]},"AIB-C01-085":{"0":["すべてを 1 年間の ROI で評価すると、3 年後の顧客満足度を高める戦略的な施策が一律に却下され、顧客体験の責任者の支持を失います。",["同じ 1 年間の ROI 基準で評価し"]],"1":["短期の施策だけに集中すると中長期の戦略的施策が排除され、顧客体験の責任者の支持を失います。",["中長期の施策は検討しない"]],"2":["同額を配分して評価を任せると、全社としての優先順位や評価基準がなくなり、経営層として施策を管理できません。",["評価はそれぞれに任せる"]]},"AIB-C01-086":{"0":["パイロットで作業時間 20% 削減と高い評価という成果が出ています。モデルやプロンプトの見直しで採算が合う可能性があり、即時の中止は情報を活かしていません。",["直ちに完全に中止する"]],"1":["コスト試算を隠して展開後に予算を追加申請するのは、経営層の適切な判断を妨げ、組織の信頼を損ないます。",["コストの試算を公表せず"]],"3":["試算では利用料が人件費削減額を上回るため、そのまま全社展開すると赤字が続きます。利用者の評価だけでは採算の問題は解決しません。",["試算のとおり全社展開する"]]},"AIB-C01-087":{"0":["審査の仕組みが見えない汎用 SaaS では、判断根拠の説明やデータを自社管理下に置く規制要件を満たしにくく、独自ノウハウも生かせません。",["審査の仕組みが外部から見えない汎用の SaaS"]],"1":["大規模言語モデルを一から事前学習するのは膨大なコストと期間がかかり過剰です。マネージドな基盤モデルと自社データの組み合わせで十分です。",["一から事前学習する"]],"2":["差別化領域だからこそ、自社ノウハウを組み込んだ AI で競争力を高められます。AI を使わないと効率化や品質向上の機会を逃します。",["AI は使わず従来どおり人手で審査を続ける"]]},"AIB-C01-088":{"0":["AWS Pricing Calculator は利用開始前の見積もり用のツールで、実際の利用料金の推移を分析することはできません。",["AWS Pricing Calculator"]],"1":["AWS CloudTrail は API 操作の記録を残すサービスで、利用料金の推移を部門別に分析する機能はありません。",["AWS CloudTrail"]],"2":["AWS Budgets は予算のしきい値を超えたときに通知するツールで、それだけでは料金の推移を部門別に詳しく分析できません。",["AWS Budgets のみ"]]},"AIB-C01-089":{"0":["記憶に基づく回答は不正確で、導入前の実態を反映しません。導入前に実測したベースラインが必要です。",["導入前の処理時間を思い出して"]],"2":["導入後の値を基準にすると、導入による効果が基準値に含まれてしまい、導入前後の比較ができません。",["導入後 1 か月の指標を基準値とし"]],"3":["業界平均の改善率は自社の業務の実態を反映せず、自社での導入前後の効果を測る基準になりません。",["業界平均の改善率"]]},"AIB-C01-090":{"0":["利用者数は利用状況の指標で、業務成果が維持されているかは分かりません。成果の低下を見落とすおそれがあります。",["利用者数が増え続けている限り"]],"1":["データや業務の変化で効果は変わるため、年 1 回の確認では悪化に気付くのが遅れます。継続的なモニタリングが必要です。",["年 1 回の決算時にのみ確認する"]],"3":["稼働率や応答時間は技術的な指標で、業務成果の低下は分かりません。KPI を継続的に追跡する必要があります。",["稼働率と応答時間だけを監視し"]]},"AIB-C01-091":{"1":["年間の顧客離反率は結果として後から表れる遅行指標で、早い段階で変化が見える先行指標ではありません。",["年間の顧客離反率"]],"2":["年度末の売上高は施策の結果として後から確定する遅行指標です。",["年度末の売上高"]],"3":["前年度の営業利益は過去の結果で、AI 導入の効果を早期に示す先行指標にはなりません。",["前年度の営業利益"]]},"AIB-C01-092":{"0":["対照群は比較のために設けるもので、そのグループの業務を減らすことが目的ではありません。",["業務を減らすため"]],"2":["対照群を設けても AI の利用料が半分になるわけではありません。目的は外部要因を除いて AI の効果を切り分けることです。",["AI の利用料を半分にする"]],"3":["対照群を設けると比較のためのデータはむしろ必要になります。データ量を減らすことが目的ではありません。",["データ量を減らすため"]]},"AIB-C01-093":{"0":["AWS Marketplace はサードパーティーのソフトウェアを購入する場で、予算の上限に近づいたときに通知する機能はありません。",["AWS Marketplace"]],"1":["AWS Artifact はコンプライアンス報告書を入手するサービスで、費用を監視して通知する機能はありません。",["AWS Artifact"]],"2":["AWS Pricing Calculator は導入前に費用を見積もるツールで、実際の費用を監視して通知することはできません。",["AWS Pricing Calculator"]]},"AIB-C01-094":{"0":["サーバーの台数はインフラの規模を示すだけで、問い合わせ対応の費用対効果を表しません。マネージドサービスでは台数自体を意識しないこともあります。",["導入したサーバーの台数"]],"1":["モデルの名前は費用対効果を示す指標になりません。",["モデルの名前"]],"2":["総額だけでは、利用量が増えたのか効率が悪化したのかを区別できず、利用量が変わる中での比較に向きません。",["総額のみ"]]},"AIB-C01-095":{"0":["GPU の数は計算資源の量で、下書きが業務で実際に使える品質かどうかは分かりません。",["GPU の数"]],"1":["画面のデザインの評価は使い勝手の話で、生成された下書きの内容が実務で役立っているかを示しません。",["画面のデザインの評価"]],"3":["総文字数は生成量を示すだけで、下書きがそのまま使える品質かどうかは分かりません。",["総文字数"]]},"AIB-C01-096":{"0":["リクエスト数は利用量の指標で、サポート業務の成果が上がったかは分かりません。補助的な指標にとどまります。",["1 日あたりのリクエスト数"]],"1":["平均トークン数は応答の長さを示すだけで、問い合わせの解決や効率化といった業務成果を表しません。",["平均トークン数"]],"2":["アカウントの付与人数は導入範囲を示すだけで、ビジネス価値を示す KPI にはなりません。",["アカウントを付与された人数"]]},"AIB-C01-097":{"0":["平均応答時間は測定できる性能の指標で、数値化しにくい便益ではありません。それ自体は業務上の便益も示しません。",["平均応答時間"]],"1":["質問件数は測定できる利用の指標で、数値化しにくい定性的な便益には当たりません。",["1 日あたりの質問件数"]],"2":["月間アクティブ利用者数は定量的な利用指標で、従業員体験の向上のような定性的な便益を示すものではありません。",["月間アクティブ利用者数"]]},"AIB-C01-098":{"1":["会議の回数は社内の活動量を示すだけで、広告やキャンペーンの成果を表しません。",["AI に関する会議を開いた回数"]],"3":["トークンの合計数は利用量やコストの目安にすぎず、顧客の行動や制作効率といったビジネス成果を示しません。",["トークンの合計数"]],"4":["利用したモデルの数は技術的な構成の話で、施策のビジネス成果とは関係ありません。",["利用した基盤モデルの数"]]},"AIB-C01-099":{"0":["12 月は全店で売上が増える時期のため、前月比 15% には季節要因が含まれます。そのまま AI の効果とすると過大評価になります。",["そのまま AI の効果として報告する"]],"1":["予測精度だけでは売上などのビジネス成果への寄与が分かりません。季節要因を除いた効果を示す必要があります。",["予測精度だけを報告する"]],"2":["店長の印象は主観的で、季節要因と AI の効果を切り分けられません。",["店長の印象を集めて"]]},"AIB-C01-100":{"0":["アカウントの総数もログイン数と同じく活動の量を示すだけで、業務成果や投資効果は分かりません。",["利用者アカウントの総数"]],"1":["紹介ページへのアクセス数は関心の高さを示すにすぎず、業務成果に結び付く指標ではありません。",["紹介ページへのアクセス数"]],"3":["ログイン画面の表示回数はログイン数と同様の見栄えだけの指標で、投資効果の判断に使えません。",["ログイン画面の表示回数"]]},"AIB-C01-101":{"0":["生成コードの行数は量を示すだけで、品質や開発の速さが向上したかは分かりません。行数が多いほど良いわけでもありません。",["AI が生成したコードの行数"]],"1":["ツールの起動回数は利用量の指標で、事業への効果を示すものではありません。",["AI ツールを起動した回数"]],"3":["座席数はチームの規模を示すだけで、AI コーディングアシスタントの効果とは無関係です。",["開発チームの座席数"]]},"AIB-C01-102":{"0":["月額利用料はコストの指標で、通話時間の短縮によって応対品質が下がっていないかは確認できません。",["AI の利用料の月額"]],"2":["電話機の台数は設備の規模を示すだけで、応対品質を表す指標ではありません。",["使用している電話機の台数"]],"3":["出勤時刻は勤怠の情報で、顧客への応対品質とは関係ありません。",["オペレーターの出勤時刻"]]},"AIB-C01-103":{"1":["料金が高いモデルが自社の問い合わせで最も良い回答を出すとは限りません。自社データで客観的に比較すべきです。",["最も料金が高いモデルは品質も高い"]],"2":["一般的なランキングは汎用的なベンチマークの結果で、自社の質問での回答品質を保証しません。",["一般的なランキングで 1 位"]],"3":["1 名が数回試した印象は主観的でサンプルも少なく、客観的な比較になりません。",["担当者 1 名が数回試した印象"]]},"AIB-C01-104":{"0":["KPI の数を増やしても、確認して対応する責任者がいなければ同じ問題が残ります。かえって管理が難しくなります。",["KPI の数を 3 倍に増やす"]],"1":["年 1 回の監査では悪化に気付くのが遅れ、日常的な改善の行動につながりません。",["年に 1 回の監査に任せる"]],"3":["悪化した KPI を削除すると問題が見えなくなるだけで、改善にはつながりません。",["数値が悪化した KPI を削除する"]]},"AIB-C01-105":{"0":["人件費は変わっていないため、時間に時給を掛けた金額を削減額とすると実際の費用削減と混同し、効果を過大に見せます。",["そのままコスト削減額として計上する"]],"1":["利用者数は利用状況を示すだけで、削減した時間がどのような価値を生んだかを説明できません。",["利用者数だけを報告する"]],"3":["人件費が変わらなくても、削減した時間を付加価値業務に回したり増員を回避したりすれば価値があります。効果なしとは言えません。",["効果はなかったと結論付ける"]]},"AIB-C01-106":{"0":["導入直後は習熟のために一時的に生産性が下がりやすく、1 か月目だけで中止すると本来の効果を確認できません。",["すぐに中止する"]],"2":["処理件数の測定をやめると、習熟後に改善したかを客観的に確認できなくなります。",["処理件数の測定をやめ"]],"3":["評価期間を無期限に延ばすと、効果のない施策にも資源を使い続けることになります。途中経過の指標で判断すべきです。",["無期限に延長する"]]},"AIB-C01-107":{"0":["従量課金でも、紙と PDF のデジタル化や統合、運用、教育の費用は発生します。利用料だけをコストにすると総コストを過小評価します。",["モデル利用料だけをコストとして計上し"]],"1":["70% の削減は実証されていないベンダーの数値で、最終確認が必須なことやデータ準備の費用も考慮されていません。効果を過大に見せます。",["ベンダーの説明どおり"]],"3":["法務担当者の最終確認は今後も必須で、削減時間をすべて人員削減とみなすのは非現実的です。最大値だけでは CFO の判断に耐えません。",["すべて人員削減として金額換算し"]]},"AIB-C01-108":{"0":["電話窓口の受付時間を短縮すると、顧客は解決できないまま困るだけで、顧客満足度がさらに下がります。根本原因の分析になりません。",["電話窓口の受付時間を短縮する"]],"2":["顧客満足度の低下と再問い合わせの増加は、未解決の離脱を成功と数えている可能性を示します。KPI の改善だけで成功とは言えません。",["施策は成功と報告する"]],"3":["調査を中止すると品質の悪化が見えなくなるだけです。補完指標の悪化は KPI の定義を見直すべきサインです。",["調査を中止する"]]},"AIB-C01-109":{"0":["成績のよい支店だけの結果を全社の効果とすると偏りが生じ、効果を過大評価します。",["最も成績のよい支店だけの結果"]],"2":["同時導入して前年平均と比べるだけでは、景気や季節などの外部要因を除けず、AI の効果を切り分けられません。",["導入前年の全社平均と比較する"]],"3":["利用状況だけでは業務成果を示せません。導入時期をずらせば比較群を確保して効果を測れます。",["効果測定をあきらめ"]]},"AIB-C01-110":{"0":["熱心な利用者数名の感想は偏りがあり、全社の効果を代表しません。取締役会への根拠として信頼性に欠けます。",["熱心な利用者数名の感想だけ"]],"1":["全社員が 1 日 1 時間削減できるという前提に根拠がなく、最大値を示すと過大評価として信頼を損ないます。",["1 日 1 時間の削減を掛けた最大値"]],"3":["直接測定できなくても、抽出調査やログを組み合わせた推計で説明できます。説明を放棄すると投資の妥当性を示せません。",["ROI は説明できないと回答する"]]},"AIB-C01-111":{"0":["最新のモデルへの切り替えは競合も同じように実行でき、持続的な差別化になりません。",["最新の基盤モデルに切り替え続ける"]],"2":["パラメータ数の大きいモデルは誰でも選べるため、競合との差別化の源泉になりません。",["最もパラメータ数の大きい基盤モデル"]],"3":["ライセンスの配布は競合もすぐに実行でき、それだけでは競争優位につながりません。",["ライセンスを全社員に配布する"]]},"AIB-C01-112":{"0":["データ量が増えても AI の利用料が無料に近づくことはありません。データフライホイールの価値は改善の好循環にあります。",["利用料が無料に近づく"]],"1":["データフライホイールは改善を回し続けることが前提で、一度集めれば改善不要になるという説明は逆です。",["改善の必要がなくなる"]],"3":["データフライホイールは自社サービスの利用から得たデータで回るもので、競合他社のデータを自由に使えるようになるわけではありません。",["競合他社のデータを自由に使える"]]},"AIB-C01-113":{"0":["自社顧客の利用履歴は自社だけが持つデータで、それに基づく提案は模倣されにくく差別化につながります。",["自社顧客の利用履歴に基づく"]],"2":["自社独自の業務ノウハウを組み込んだアシスタントは他社が再現しにくく、差別化につながる施策です。",["自社独自の業務ノウハウを組み込んだ"]],"3":["自社だけが持つ長年の保守記録は独自のデータ資産で、それを使った故障診断は差別化につながります。",["自社だけが持つ長年の保守記録"]]},"AIB-C01-114":{"0":["Amazon Polly はテキストを音声に変換するサービスで、閲覧・購入履歴に基づく商品のおすすめはできません。",["Amazon Polly"]],"1":["AWS Glue はデータの抽出・変換・ロード（ETL）を行うサービスで、パーソナライズされたおすすめを提供する機能はありません。",["AWS Glue"]],"3":["Amazon Textract は文書から文字や表を抽出するサービスで、顧客ごとの商品推薦はできません。",["Amazon Textract"]]},"AIB-C01-115":{"0":["モデル名を伏せても、同じようなサービスは他社も作れます。秘匿だけでは長期的な優位を保てません。",["基盤モデルの名前を公開しない"]],"2":["仕様を変えずにいると、改善を続ける後発企業に追い抜かれます。生成 AI のサービスは模倣されやすいため改善の継続が必要です。",["仕様を変えずに維持する"]],"3":["最初に発表したという事実は長く続く優位にならず、広告で繰り返してもサービスの価値は高まりません。",["最初に発表したという事実を広告で"]]},"AIB-C01-116":{"1":["Bedrock Guardrails は有害な内容のフィルタリングなどの安全対策の機能で、自社の技術資料を検索して回答に反映する役割はありません。",["Amazon Bedrock Guardrails"]],"2":["AWS Cost Explorer は利用料金を分析するツールで、技術資料を回答に反映する RAG の機能はありません。",["AWS Cost Explorer"]],"3":["モデル評価は候補モデルの品質を比較する機能で、自社資料を検索して回答の根拠に使う仕組みではありません。",["Amazon Bedrock のモデル評価"]]},"AIB-C01-117":{"0":["問い合わせ対応での人件費削減はコスト削減で、稼働データを生かした新たな収益源にはなりません。",["サポート部門の人件費を減らす"]],"1":["稼働データを第三者に一括売却すると、顧客の信頼や契約上の問題を招くおそれがあり、継続的な収益にもなりません。",["第三者のデータ販売業者に一括で売却する"]],"3":["製造工程の効率化と値下げはコスト面の取り組みで、稼働データと AI を組み合わせた新しい収益源にはなりません。",["機器の販売価格を下げる"]]},"AIB-C01-118":{"0":["1 つのモデルに利用条件を固定すると、性能や価格の良い新しいモデルへ切り替えられず、かえって競争力を損ないます。",["特定の 1 つの基盤モデルと長期契約を結び"]],"1":["先行者であることは他社がすぐに追随でき、ブランドだけでは長期的な優位を保てません。",["先行者としてのブランドを確立する"]],"2":["価格の引き下げは競合も追随しやすく、改善を続ける組織能力のような持続的な優位にはなりません。",["すべて価格の引き下げに充てる"]]},"AIB-C01-119":{"1":["顧客は新しいアプリの導入に消極的なため、乗り換えを求めると利用が定着せず、体験の改善につながりません。",["顧客に乗り換えを求める"]],"2":["広告で強調するだけでは、修理依頼の体験そのものは改善されず差別化になりません。",["広告で強調するだけ"]],"3":["顧客が使っていないチャネルに AI を置いても利用されず、主な接点である既存アプリの体験は変わりません。",["顧客が使っていない新しい SNS チャネル"]]},"AIB-C01-120":{"1":["競合他社が販売データを提供することは通常なく、待っていても予測精度は向上しません。",["競合他社の販売データを入手できるまで待つ"]],"2":["モデルを最新版にしても、店頭の売れ行きが分からないというデータの不足は解消されません。",["最新版に置き換えることだけに投資する"]],"3":["公開ニュースは誰でも入手でき差別化にならず、店頭の売れ行きのデータも得られません。",["公開されているニュース記事だけ"]]},"AIB-C01-121":{"0":["汎用チャット画面は他社もすぐに提供でき、会計事務所の業務に特化した価値にもなりません。",["汎用チャット画面を追加し"]],"1":["同じ機能を 1 か月早く出しても、すぐに模倣されて差はなくなります。持続的な差別化になりません。",["1 か月早く同じ機能を出す"]],"2":["対応言語の数は他社も追随しやすく、会計実務に特化した価値を生みません。",["対応する言語の数を増やす"]]},"AIB-C01-122":{"0":["1 つのモデルに全機能を固定すると、性能や価格の良いモデルが出ても切り替えられず、競争力を保てません。",["1 つのモデルに全機能を固定する"]],"2":["モデルの更新を評価せずに使い続けると、品質の変化や他の選択肢の優位に気付けません。",["評価せずに使い続ける"]],"3":["短期間で性能と価格が変わる中で年 1 回だけの選定に固定すると、変化に素早く対応できません。",["年に 1 回だけ行う"]]},"AIB-C01-123":{"0":["価格の一律引き下げは既存の請負事業の話で、新たな収益源にはならず利益も減ります。",["価格を一律に引き下げる"]],"1":["データを活用しなければ、独自データという資産から新しい価値も収益も生まれません。",["活用しない"]],"3":["担当部署の廃止は新規事業の創出につながらず、データを蓄積・活用する体制も失われます。",["担当部署を廃止する"]]},"AIB-C01-124":{"0":["汎用的な文章校正ツールは市販品で十分で、自作しても差別化にはなりません。",["汎用的な文章校正ツールを自作する"]],"1":["データセンターの管理は AWS などのクラウドに任せられ、生成 AI による差別化の源泉にはなりません。",["データセンターの建物を管理する"]],"3":["基盤モデルの一からの事前学習は多くの企業にとって過剰な投資で、マネージドなモデルを使えば済むため差別化になりません。",["一から事前学習する"]]},"AIB-C01-125":{"1":["長いプロンプトはすでに試して表現の一貫性が不十分でした。書き込みを増やしてもトークンのコストが増えるだけで安定しにくい方法です。",["より長いプロンプト"]],"2":["人手に戻すと、自社が持つ大量の校閲済み文書を生かせず、生成 AI による効率化の機会も失います。",["すべて人手で作成する"]],"3":["基盤モデルを一から開発するのは膨大なコストと期間がかかり過剰です。既存モデルのファインチューニングで十分です。",["基盤モデルを一から開発する"]]},"AIB-C01-126":{"0":["パンフレットを増やしても、顧客の要望に応じた旅程の提案や空き状況の確認、予約手配を自動で一貫して進めることはできず、差別化になりません。",["AI は使わず"]],"1":["定型回答のチャットボットは決まった質問に答えるだけで、空き確認や予約などの複数の手順を自律的に進めることはできません。",["定型回答だけを返す"]],"3":["提案文の生成だけでは予約まで一貫して支援できません。顧客に別窓口での手続きを強いるため、問題文の求める一貫した体験になりません。",["提案文だけを生成し","別の窓口で行ってもらう"]]},"AIB-C01-127":{"0":["機能では勝てなくても、地域の顧客との信頼関係という強みを AI 体験に生かせば差別化できます。検討の中止は機会を捨てる判断です。",["検討を中止する"]],"1":["担当者を廃止すると、自行の強みである顧客との長い関係と信頼を手放すことになります。コスト競争では大手やフィンテックに勝てません。",["人の担当者を廃止し","コストで勝負する"]],"2":["機能の豊富さでは勝てないと分かっているのに大手を追随しても差別化になりません。引き継ぎを後回しにすると信頼という強みも生かせません。",["すべて揃えることを最優先","後回しにする"]]},"AIB-C01-128":{"0":["プレスリリースの回数は広報活動にすぎず、AI の能力や業務上の優位を生みません。競合もすぐに同じことができます。",["プレスリリースの回数"]],"3":["最新の基盤モデルは誰でも利用できるため、早く採用しても競合はすぐ追いつけます。1 年以上続く持続的な優位にはなりません。",["他社より早く採用"]],"4":["一般的なチャットツールは競合も同じように配布できるため、模倣が容易で持続的な優位にはつながりません。",["一般的な AI チャットツール"]]},"AIB-C01-129":{"0":["独自の生産データは差別化の源泉です。競合にも販売されるモデルの学習に使われると、自社の優位が失われるおそれがあります。",["データの価値はない","どのような条件でも"]],"2":["取引の全面禁止は極端で、AI ベンダーとの有益な協業の機会まで失います。条件を確認してリスクと便益を比較すべきです。",["取引自体を全社で禁止"]],"3":["無償でも、データの利用範囲や権利を確認せずに提供すると、競合の能力向上に使われて自社の優位を失うリスクがあります。",["条件を確認せずに直ちに提供"]]},"AIB-C01-130":{"0":["独自の会員データを使う②こそ他社が真似できない差別化の源泉です。そこに投資しないと差別化を重視する方針に反します。",["②には投資せず"]],"2":["汎用的な①③まで自社で一から開発すると、既製品で安く済む部分にも費用がかかり、限られた予算でコストを抑えられません。",["すべてを自社で一から開発"]],"3":["議事録作成は一般的な業務で既製品で十分です。差別化にならない用途に最大の予算を投じるのは非効率です。",["③に最も多くの予算"]]},"AIB-C01-131":{"1":["尋ねられたときだけの開示では、多くの顧客は AI と対話していると気付けません。透明性には最初から明示することが必要です。",["尋ねられた場合にのみ"]],"2":["担当者の名前で表示して人が対応しているように見せるのは顧客を欺く行為で、透明性に真っ向から反し信頼を損ないます。",["担当者の名前で表示し","人が対応しているように見せる"]],"3":["利用規約の中だけに記載しても顧客は自然に認識できません。対話の画面で分かりやすく開示しなければ透明性を確保できません。",["利用規約の中にのみ記載"]]},"AIB-C01-132":{"1":["各部門が自部門の案件を審査すると、基準が部門ごとにばらつき、利害関係から客観的な審査も難しくなります。",["自部門の案件をそれぞれ審査"]],"2":["AI のリスクは技術だけでなく法務や業務にもまたがります。IT 部門だけでは法令や事業上の観点が欠けて審査が偏ります。",["IT 部門だけで構成"]],"3":["法務単独では、セキュリティやデータ、業務への影響といった技術・事業面の観点が欠け、全社方針の策定や審査には不十分です。",["法務部門が単独で"]]},"AIB-C01-133":{"0":["システムプロンプトの指示だけでは、巧妙な入力で回避されることがあり、個人情報の出力も確実には防げません。",["書くことだけで対応する"]],"1":["Amazon Macie は S3 に保存されたデータの機密情報を検出するサービスで、生成 AI アプリの入出力を制御する機能はありません。",["Amazon Macie","出力の制御を任せる"]],"3":["AWS CloudTrail は API 呼び出しを記録して監査に使うサービスで、モデルの出力内容をフィルタリングして防ぐことはできません。",["AWS CloudTrail","不適切な出力を防ぐ"]]},"AIB-C01-134":{"0":["Trusted Advisor のコスト最適化チェックは未使用リソースなどの費用削減を提案するもので、公平性や透明性など責任ある AI の評価には使えません。",["コスト最適化チェック"]],"1":["AWS Artifact は AWS 自身の認証やコンプライアンスレポートを入手するサービスで、自社の AI ワークロードを責任ある AI の観点で評価する枠組みではありません。",["AWS Artifact"]],"3":["AWS Pricing Calculator は利用料金を見積もるツールで、AI システムの公平性や透明性を評価する機能はありません。",["AWS Pricing Calculator"]]},"AIB-C01-135":{"0":["精度のために属性情報を多く含めるのはデータ最小化の原則に反し、漏えい時の被害やプライバシーのリスクを増やします。",["できるだけ多く含める"]],"1":["別用途のために取得できる個人データをすべて送るのは、目的外利用につながりデータ最小化の原則に反します。",["別の用途に使えるよう","すべて送っておく"]],"3":["暗号化は送信時の保護にすぎず、必要以上の個人データを扱うこと自体のリスクは減りません。量の制限は依然として必要です。",["量に制限は設けない"]]},"AIB-C01-136":{"0":["利用ポリシーはルールを定めるもので、利用料金とは関係がありません。料金を無料にする効果はありません。",["利用料金を無料にする"]],"1":["全員に開放する前提で、活用を促しつつリスクを抑えるのがポリシーの目的です。全面禁止は開放の方針と矛盾します。",["全面的に禁止する"]],"3":["利用ポリシーは入力してよい情報や禁止用途を定めるもので、業務時間を一律に短くするための規則ではありません。",["業務時間を一律に短くする"]]},"AIB-C01-137":{"1":["エッジ AI は端末側で推論する構成を指す言葉で、承認されていない AI サービスの無断利用を表すものではありません。",["エッジ AI"]],"2":["説明可能な AI は判断の根拠を示す技術を指します。無断利用はむしろ管理が及ばず透明性が下がる状況です。",["説明可能な AI"]],"3":["転移学習は学習済みモデルを別のタスクに流用する手法で、社員が未承認サービスに資料を入力する状況とは無関係です。",["転移学習"]]},"AIB-C01-138":{"0":["利用状況を一覧にしても料金が自動的に下がるわけではありません。台帳の目的はリスクの所在を把握することです。",["自動的に下がる"]],"1":["一覧化は管理のための可視化で、AI モデルの精度には影響しません。精度の向上には評価や改善の取り組みが別に必要です。",["精度が自動的に向上する"]],"2":["利用状況の台帳を作っても AI の処理速度は変わりません。ガバナンスの取り組みと性能は別の話です。",["処理速度が上がる"]]},"AIB-C01-139":{"1":["低リスク案件まで同じ厳格な審査を課すと審査の負荷が膨らみ、活用が遅れてシャドー AI を招きます。負荷の適切な配分になりません。",["すべての案件に高リスク案件と同じ"]],"2":["予算規模とリスクの大きさは一致しません。少額でも人事評価など影響の大きい用途を審査から漏らしてしまいます。",["予算規模の大きい案件だけ"]],"3":["社内向けでも人事評価のように個人に大きく影響する用途があります。社外公開の有無だけで判断すると高リスク案件を見落とします。",["社内向けの案件はすべて審査を省略"]]},"AIB-C01-140":{"0":["精度が上がるかどうかは利用してよいかの根拠になりません。まず目的や同意など法令・規程への適合を確認すべきです。",["精度がどの程度上がるか"]],"1":["暗号化は重要な保護策ですが、そもそも個人データをその目的で使ってよいかという適法性の確認が先です。",["暗号化して保存できる"]],"2":["他社が利用しているかどうかは自社の利用が適法かの根拠になりません。目的・同意・保管場所の法令適合を確認すべきです。",["同業他社が同様のデータ"]]},"AIB-C01-141":{"0":["「AI 生成」と表示しても、既存の著作物に類似していれば権利侵害のリスクはなくなりません。類似性の確認が必要です。",["「AI 生成」と表示すれば"]],"1":["プロンプトに他社名を含めなくても、生成物が既存の著作物や商標に似てしまうことはあり、権利の問題は生じ得ます。",["他社名を含めていなければ"]],"3":["有料プランで生成しても、既存作品との類似による侵害リスクは残ります。権利の帰属も規約次第で、確認なしの利用は危険です。",["確認せずに使う"]]},"AIB-C01-142":{"0":["担当者に見せなくても、脆弱な顧客を狙って広告を出し分けること自体が顧客に不利益を与えます。害は解消されません。",["システム内部だけで使う"]],"1":["データの出所が社内であっても、借金の悩みなどの弱みを推定して狙う用途は顧客を害するおそれがあり、責任ある AI の観点で問題です。",["社内の購買履歴だけ"]],"2":["規約に一般的な記載があっても、脆弱性を推定して狙い撃ちする用途まで顧客が想定しているとはいえず、害や信頼の損失は解消されません。",["利用規約に","記載済みであれば"]]},"AIB-C01-143":{"1":["利用者を匿名にすると、誤用が起きても誰が行ったか追跡できず、抑止や是正が難しくなります。",["利用者を匿名にし"]],"2":["経営層だけに限定すると誤用は減っても、社員が業務で活用する機会が失われ、社内公開の目的を果たせません。",["経営層だけに限定"]],"3":["利用ログを一切取らないと、不適切な利用を発見・調査できません。誤用への備えとして監視は必要です。",["利用ログを一切取得しない"]]},"AIB-C01-144":{"0":["社内報の見出し案は人が確認して選ぶもので、誤りがあっても個人の権利や機会への影響は小さく、低リスクの用途です。",["社内報の見出し案"]],"1":["誤字の検出は誤りがあっても影響が限定的で、個人の機会や権利を左右しない低リスクの用途です。",["誤字を検出する"]],"3":["会議室の予約検索は個人に重大な影響を与える判断ではなく、厳格な審査が必要な高リスク用途には当たりません。",["会議室の予約状況"]]},"AIB-C01-145":{"0":["EU AI 法は EU 域内で提供・利用される AI に適用され、規制の有無は開発国ではなく用途のリスクで決まります。",["開発国によって"]],"1":["規制の強さは利用料金ではなく、AI の用途がもたらすリスクの大きさによって決まります。",["利用料金の大きさ"]],"2":["EU AI 法はすべてを禁止するのではなく、許容できないリスクの用途のみを禁止し、他はリスクに応じた義務を課します。",["一律に禁止する"]]},"AIB-C01-146":{"0":["外部サービスによっては入力データが学習に使われたり保管されたりします。個人情報や取引条件を自由に入力すると漏えいのリスクがあります。",["どの外部サービスでも自由に"]],"1":["元の記録を削除しても、外部サービスに入力したデータの扱いは変わりません。学習や保管によるリスクは残ります。",["元の商談記録を削除すれば"]],"2":["一律禁止では、データの扱いを確認できる安全なサービスでの活用まで妨げられ、活用とリスク管理の両立ができません。",["一律に禁止する"]]},"AIB-C01-147":{"0":["Amazon Bedrock では料金の多少にかかわらず、入出力データが基盤モデルの学習に使われることはありません。",["料金を多く払った場合のみ"]],"1":["データの取り扱いは方針として定められており、ランダムに決まることはありません。入出力は学習に使われません。",["毎回ランダムに決まる"]],"3":["Amazon Bedrock では入出力データがモデル提供者と共有されたり、学習に使われたりすることはなく、記述は逆です。",["モデル提供者に送られ","学習に使われる"]]},"AIB-C01-148":{"0":["AWS Pricing Calculator は料金を見積もるツールで、誰がいつどの操作をしたかを記録する機能はありません。",["AWS Pricing Calculator"]],"2":["Amazon Polly はテキストを音声に変換するサービスで、API 操作の履歴の記録や監査には使えません。",["Amazon Polly"]],"3":["Amazon Translate は機械翻訳サービスで、操作の記録を取る機能はなく監査要件を満たせません。",["Amazon Translate"]]},"AIB-C01-149":{"0":["審査を全廃すると、規制当局が求める高リスク用途の管理ができなくなります。スピードと管理の両立になりません。",["審査を全廃し"]],"2":["審査をさらに厳しくすると承認がもっと遅れ、現場の不満とシャドー AI の利用がかえって増えます。処分では根本原因を解決できません。",["さらに厳しくし","処分する"]],"3":["全面停止は極端で、規制当局が求めるのは高リスク用途の管理であり、低リスクの活用まで止める必要はありません。",["全面的に停止する"]]},"AIB-C01-150":{"0":["規制を待つだけでは、すでに存在するリスクを管理できず、全社で一貫した仕組みも作れません。",["何もしない"]],"1":["最も緩い基準に合わせると、規制の厳しい国の要件を満たせず違反のリスクがあります。",["最も規制の緩い国の基準だけ"]],"3":["国ごとに無関係なルールで本社が把握しないと、全社での一貫性が失われ、リスクの全体像も管理できません。",["本社では把握しない"]]},"AIB-C01-151":{"1":["サーバーの設置場所は遅延やデータ所在地に関係しますが、判定が特定集団に偏る原因にはなりません。",["サーバーの設置場所"]],"2":["画面の色は見た目の設定で、モデルの判定内容には影響せず、バイアスの原因にはなりません。",["画面の色の設定"]],"3":["パスワードの長さは認証のセキュリティに関係するもので、モデルの判定の偏りとは無関係です。",["パスワードの長さ"]]},"AIB-C01-152":{"1":["データ件数の多さ自体は偏りの原因ではありません。性別と相関する別の項目が残っていることが問題です。",["件数が多すぎる"]],"2":["性別の項目を除外しても AI が誤作動するわけではありません。偏りは代理変数を通じて残ります。",["必ず誤作動する"]],"3":["画面の表示はモデルの判定に影響しません。判定に使われる特徴量に性別と相関する項目があることが原因です。",["画面に性別が表示"]]},"AIB-C01-153":{"1":["全体の正解率が高くても、特定の集団だけ誤りが多いことがあります。属性別に比較しないと公平性は確認できません。",["全体の正解率だけ"]],"2":["開発者の主観では公平性を客観的に評価できません。属性ごとの承認率などの指標で確認する必要があります。",["公平だと思うかを尋ねる"]],"3":["審査件数の合計は処理量を示すだけで、属性間で結果に不当な差があるかは分かりません。",["審査件数の合計だけ"]]},"AIB-C01-154":{"0":["過学習は学習データに適合しすぎて汎化性能が落ちる現象で、属性間の承認率の差を評価する考え方ではありません。",["過学習"]],"2":["再現率は陽性をどれだけ見つけられたかを示す性能指標で、属性ごとの承認割合の同等性を表す公平性の考え方ではありません。",["再現率"]],"3":["データドリフトは入力分布の変化による性能低下の原因で、属性間の結果の差を直接評価するものではありません。",["データドリフト"]]},"AIB-C01-155":{"0":["レイテンシーは応答の遅さを指す性能の問題で、生成画像の性別や人種の偏りとは関係ありません。",["レイテンシーの増加"]],"1":["過学習は学習データに適合しすぎて新しいデータで性能が落ちる現象で、社会的な固定観念の再生産を表す言葉ではありません。",["過学習"]],"3":["プロンプトインジェクションは悪意ある入力でモデルの指示を乗っ取る攻撃で、学習データ由来の偏りとは別の問題です。",["プロンプトインジェクション"]]},"AIB-C01-156":{"0":["地域の項目を削除しても、郵便番号など相関する代理変数で偏りが残ることがあります。原因を分析せず運用を続けるのは危険です。",["地域の項目を削除し","運用を続ける"]],"2":["原因を分析しないまま一律に加点すると、別の不公平を生むおそれがあり、根本的な是正になりません。",["一律で加点する補正"]],"3":["全体の承認率が範囲内でも、特定地域への不利な判定は続きます。影響が大きい公平性の問題を放置することになります。",["現行のまま運用を続ける"]]},"AIB-C01-157":{"0":["全体の正解率が維持されていても、特定の集団の結果だけが悪化することがあります。全体の指標だけでは偏りを見逃します。",["全体の正解率を毎月監視し"]],"1":["データは時間とともに変化するため、稼働前に合格していても後からバイアスが生じます。継続的な確認が必要です。",["確認は不要とする"]],"2":["年 1 回の確認では、偏りが生じてから発見までに時間がかかり、その間に顧客への不利益が続きます。",["年 1 回の内部監査"]]},"AIB-C01-158":{"1":["運用中もデータの変化でバイアスは後から生じます。開発時の確認だけでは、本番での偏りを発見できません。",["運用中は確認しない"]],"2":["測定しても誰にも報告しなければ、問題が見つかっても対応につながりません。報告先と対応手順を決めて初めて監視が機能します。",["誰にも報告しない"]],"3":["指摘を待つだけでは発見が遅れ、気付かれない偏りは放置されます。定期的な測定による能動的な監視が必要です。",["指摘された場合にのみ調査"]]},"AIB-C01-159":{"0":["名前を変えてもモデルの中身は変わらず、顧客構成の変化による予測精度の低下は解消されません。",["名前を変更する"]],"1":["若年層を対象外にして報告しないのは問題の隠蔽で、データドリフトという原因にも対処できず、説明責任にも反します。",["予測の対象から外し","報告しない"]],"3":["新プランの開始で顧客構成が変わっており、一時的とはいえません。データドリフトを放置すると誤った予測が続きます。",["そのまま使い続ける"]]},"AIB-C01-160":{"0":["同じデータを複製しても件数が増えるだけで、地方店舗や多様な客層の代表性は改善されません。",["同じデータを複製する"]],"1":["都市部だけのデータでは地方の客層を代表できず、地方店舗で性能が落ちることが予想できます。問題が出てからでは対応が遅れます。",["問題が出てから考える"]],"2":["地方導入の計画を伏せても、データの代表性の問題は解決しません。透明性にも反し、公平性への対応になりません。",["伏せて計画を進める"]]},"AIB-C01-161":{"0":["奨学金の選考は個人の機会に大きく影響するため、公平性の評価をやめると偏った選考を見逃し、説明責任も果たせません。",["公平性の評価をやめ"]],"2":["計算のしやすさは定義を選ぶ根拠になりません。どの公平性を重視するかは事業目的や法令、関係者の合意で決めるべきです。",["最も計算しやすい定義"]],"3":["定義を決めないまま開発すると、何をもって公平とするかの基準がなく、評価も説明もできません。",["定義を決めずに"]]},"AIB-C01-162":{"0":["生成 AI の偏りは職種や条件によって現れるため、1 件だけの確認では不適切な表現を見逃します。",["1 件だけ生成して"]],"1":["応募者の指摘を待つと、公開後に差別的な表現が広まってしまい、公開前に確認するという要件を満たせません。",["応募者からの指摘に任せる"]],"3":["生成 AI は学習データの偏りを反映するため中立とはいえません。確認を省くと差別的な表現が公開されるおそれがあります。",["中立なので確認は不要"]]},"AIB-C01-163":{"0":["Amazon EBS は EC2 用のブロックストレージで、基盤モデルの正確さや有害性を比較評価する機能はありません。",["Amazon EBS"]],"2":["AWS Cost Explorer は利用料金の分析ツールで、モデルの回答品質や偏りを比較する機能はありません。",["AWS Cost Explorer"]],"3":["AWS Direct Connect はオンプレミスと AWS を専用線で接続するサービスで、モデル評価とは無関係です。",["AWS Direct Connect"]]},"AIB-C01-164":{"0":["全社で使われている以上、半年待つ間にも不公平な配置判断が積み重なります。影響の把握と是正を先送りすべきではありません。",["半年後の定期点検"]],"2":["記録を削除して隠すのは不誠実で、代理変数による偏りも残り得ます。影響の把握や是正もできなくなります。",["問題を隠す"]],"3":["社員に見えなくても、不公平な推薦で重要案件の機会を奪われる不利益は続きます。放置は責任ある判断ではありません。",["そのまま使い続ける"]]},"AIB-C01-165":{"0":["手続きなしで偏りのあるモデルに戻すと、顧客や法令、評判上のリスクが検討されず、ガバナンスが機能しません。",["手続きなしで切り替える"]],"2":["指標を測らなければ偏りの有無を把握できず、リスクを見えなくするだけで問題は解決しません。",["測定しないことにする"]],"3":["精度だけで判断すると、偏りによる顧客への不利益や法令違反のリスクを無視することになります。常に精度が優先とはいえません。",["常に正しい"]]},"AIB-C01-166":{"0":["全体の平均値だけでは、高齢者など特定の年齢層で認識精度が低いことを見逃します。",["全体の平均値だけ"]],"2":["テストを省略すると、高齢者の発話を聞き取れないといった偏りを公開前に発見できません。",["テストを省略して"]],"3":["20〜30 代の開発チームの声だけでは、高齢者特有の話し方による精度低下に気付けず、偏りを見落とします。",["開発チームの声だけ"]]},"AIB-C01-167":{"0":["データは変化するため、導入時 1 回の確認では後から生じる偏りを発見できません。苦情を待つ方式では支援の遅れが生じます。",["1 回だけ公平性を確認し"]],"2":["処理件数や処理時間は効率の指標で、地域や年齢、国籍による偏りや誤った低優先判定は把握できません。",["処理件数と平均処理時間だけ"]],"3":["属性情報を記録しないと、属性別の誤り方を測定できず、偏りの有無を検証できません。説明責任も果たせません。",["属性情報を一切記録せず"]]},"AIB-C01-168":{"0":["過去の実績は当時の社会的な偏りを含んでおり、それを再現することは正しくありません。偏りの再生産を放置することになります。",["正しいと説明する"]],"2":["注意書きを表示しても表示される求人の偏りは変わりません。学習データという根本原因に対処していません。",["注意書きを表示する"]],"3":["モデルを大きくしても偏ったデータを学習すれば偏りは再現されます。自然に消えることはありません。",["より大きなモデルに替える"]]},"AIB-C01-169":{"0":["ベンダーの検証は自社の高齢者比率の高い顧客層で行われたとは限りません。自社データで検証せずに導入すると偏りを見逃します。",["そのまま導入する"]],"1":["購入した AI でも、利用する企業は自社の顧客に対する公平性に責任を負います。ベンダー任せにはできません。",["自社は対応不要"]],"3":["高齢者を対象から外すと、自社の主要な顧客層を不利に扱うことになり、別の不公平を生みます。",["高齢者の顧客をスコアリングの対象から外して"]]},"AIB-C01-170":{"0":["努力を示しても対策の効果は分かりません。経営判断には地域別の精度の変化という客観的な結果が必要です。",["努力したことを示す"]],"2":["追加したデータの件数は投入量にすぎず、方言の強い利用者の精度がどれだけ改善したかという効果を示せません。",["データの件数だけ"]],"3":["全体の平均精度が上がっても、方言地域との差が縮まったとは限りません。地域別に比較しないと公平性の効果は分かりません。",["全体の平均精度"]]},"AIB-C01-171":{"2":["開発者の個人名と連絡先は公平性の説明に不要で、個人のプライバシーや安全上の問題も生じます。",["開発者の個人名と連絡先"]],"3":["不利な結果を伏せて良い結果だけを示すのは不誠実で、発覚すれば顧客や規制当局の信頼を大きく損ないます。",["良い結果だけ"]],"4":["全パラメータの数値を示しても、顧客や規制当局には理解できず、公平性の説明として役立ちません。",["全パラメータの数値"]]},"AIB-C01-172":{"1":["AI の判定を医師より優先すると、AI の誤りがそのまま診断に反映されます。診断の最終責任は医師が持つべきです。",["AI の判定を優先する"]],"2":["月 1 回の抜き取り確認は事後の点検で、確認前に誤った判定が診療に使われてしまいます。",["月に 1 回","抜き取りで確認"]],"3":["信頼度が高くても誤りはあり得ます。確定診断を AI に任せると、重大な判断から医師の関与が外れてしまいます。",["そのまま確定診断とし"]]},"AIB-C01-173":{"0":["プロンプトエンジニアリングはモデルへの指示文を工夫する技術で、人による監督の形態を指す言葉ではありません。",["プロンプトエンジニアリング"]],"1":["Human-in-the-loop は個々の判断に人が関与して承認する形態です。全件を確認せず監視と介入を行う形態とは異なります。",["Human-in-the-loop"]],"3":["ファインチューニングは追加データでモデルを調整する手法で、運用時の人による監督の形態ではありません。",["ファインチューニング"]]},"AIB-C01-174":{"0":["利用者の報告任せでは、誤った結果が登録・公開されてから見つかることになり、自信のない結果を事前に確認できません。",["誤りに気付いた人が報告する"]],"2":["月末の抜き取りは事後の傾向確認で、自信のない個々の結果を登録前に確認する仕組みになりません。",["月末にまとめて","抜き取り"]],"3":["全件確認では、自信のないものだけに絞るという要件に反し、担当者の負荷とコストが大きくなります。",["すべての抽出結果を担当者が 1 件ずつ確認"]]},"AIB-C01-175":{"0":["データドリフトは入力データの分布が変化する現象で、人が AI の提案を過信する傾向を指す言葉ではありません。",["データドリフト"]],"2":["プロンプトインジェクションは悪意ある入力でモデルを操る攻撃で、確認担当者の心理的な傾向とは無関係です。",["プロンプトインジェクション"]],"3":["選択バイアスはデータの集め方が偏ることで生じる偏りで、AI の判断を過信して承認する傾向ではありません。",["選択バイアス"]]},"AIB-C01-176":{"0":["問題を顧客に知らせない方法を決めるのは透明性に反し、発覚すれば信頼を大きく損ないます。",["顧客に知らせない方法"]],"1":["名称を変えても不適切な回答は止まりません。被害を抑えるには停止や切り替えの手順が必要です。",["名称の変更手順"]],"2":["広告の出稿計画は不適切な回答への対応と無関係で、問題発生時の被害拡大を防げません。",["新しい広告の出稿計画"]]},"AIB-C01-177":{"0":["人による判断の過程を記録しないと、誰がどのような理由で最終判断したかを後から検証できません。",["人による判断の過程は記録しない"]],"1":["結果と日付だけでは、どの入力とモデルに基づいて判断したかが分からず、経緯を検証できません。",["判断結果と判断日だけ"]],"2":["開発時の評価レポートはモデル全体の性能を示すだけで、個々の判断が何に基づいて行われたかは検証できません。",["個々の判断の記録は不要"]]},"AIB-C01-178":{"1":["免責表示を付けても、AI を使ってサービスを提供した企業の責任が一切なくなるわけではありません。",["一切の責任を負わない"]],"2":["責任共有モデルでは、AI の出力をどう使うかは顧客の責任です。出力内容の責任を AWS が負うわけではありません。",["責任は AWS が負う"]],"3":["モデルを業務に組み込み顧客に提供したのは企業であり、出力の利用と顧客への影響の責任はその企業が負います。",["モデルの提供者が"]]},"AIB-C01-179":{"0":["返金の可否判断は顧客の不利益に直結するため、人の確認なしでは誤判断を防げません。影響に応じた監督が必要です。",["どちらも人による確認は不要"]],"2":["影響の小さい説明文を全件承認し、影響の大きい返金判断を確認しないのは逆で、監督の配分が誤っています。",["②は確認しない"]],"3":["全件を 3 人で確認するとコストが過大で、影響の小さい説明文にまで過剰な監督をかけることになります。",["全件を担当者 3 人で確認"]]},"AIB-C01-180":{"1":["承認率が高いのは確認が形骸化している兆候かもしれず、工程を廃止すると誤った支払い判定を止める手段がなくなります。",["確認の工程を廃止する"]],"2":["人数を減らすと 1 人あたりの負荷が増え、確認はさらに形だけになります。形骸化の改善とは逆の対策です。",["人数を半分に減らす"]],"3":["判定案を見せずに承認させると、担当者は内容を確認できず、監督がまったく機能しなくなります。",["担当者に見せず"]]},"AIB-C01-181":{"0":["判定理由を記録しないと、誤判定を検証・是正できず、顧客への説明もできません。権利保護に逆行します。",["理由を社内でも記録しない"]],"1":["問い合わせを受け付けないと、誤った判定で回線を止められた顧客が是正を求められず、権利が守られません。",["問い合わせを受け付けない"]],"3":["解除できないと、誤判定で停止された顧客の回線を復旧できず、顧客に重大な不利益を与えます。",["解除できない仕組み"]]},"AIB-C01-182":{"0":["生活困窮や健康不安などの深刻な相談を AI だけで完結させると、適切な支援につながらず住民に大きな影響が出るおそれがあります。",["最後まで対応する"]],"2":["受け付けずに終了すると、支援を必要とする住民が行き場を失います。専門の窓口へ引き継ぐ仕組みが必要です。",["受け付けない旨を表示して終了"]],"3":["定型文だけでは個別の深刻な状況に対応できず、必要な支援につながりません。人への引き継ぎが必要です。",["定型文だけを返す"]]},"AIB-C01-183":{"0":["実績を確認せずに初日から全面自動化すると、誤発注などのリスクを抑えられません。段階的な拡大が必要です。",["初日からすべての発注を自動化"]],"1":["上限金額だけでは、上限内の誤発注を防げません。精度を確認せずに任せるのはリスクの管理として不十分です。",["精度を確認せず"]],"3":["自律性の範囲を決めないと、エージェントがどこまで発注できるかを統制できず、誤りの影響が無制限になります。",["自律性の範囲は決めず"]]},"AIB-C01-184":{"0":["担当者の判断を記録しないと、AI の指摘がどこで誤っていたかが分からず、改善に生かせません。",["担当者の判断は記録せず"]],"1":["不採用を不利に評価すると、担当者が AI の指摘を盲目的に採用するようになり、自動化バイアスを助長します。",["評価で不利にする"]],"3":["すべて採用させると担当者の判断が形骸化し、AI の誤った指摘もそのまま契約に反映されてしまいます。",["すべて採用するよう指示"]]},"AIB-C01-185":{"0":["確認をやめれば誤った数値が公開されるリスクはさらに高まります。原因である責任者の不在にも対処していません。",["公開前の確認をやめる"]],"1":["AI の出力を使って公開した責任は組織にあります。ベンダーに責任を求めても、確認体制の欠如という原因は残ります。",["AI ベンダーに責任を求めて"]],"3":["全面禁止は極端で、活用の機会を失います。原因は確認責任者が決まっていないことで、利用自体ではありません。",["全社で禁止する"]]},"AIB-C01-186":{"0":["人の確認を完全になくすと、不適切な投稿の見逃しや正当な投稿の誤削除を検知・是正できず、ブランドや出品者との関係を損ないます。",["完全になくす"]],"1":["全件を人が確認すると年間数億円のコストがかかり、コストを抑えるという要件を満たせません。",["全件を人が確認し"]],"3":["削除判定をすべて自動にすると、正当な投稿の誤削除による出品者の苦情を防げません。掲載判定の全件確認もコストが過大です。",["削除判定はすべて自動"]]},"AIB-C01-187":{"0":["注意喚起だけでは、30 秒しか確認できない多忙な状況という根本原因が変わらず、再発を防げません。",["注意喚起の文書を配るだけ"]],"2":["医師の確認をなくすと、薬の用量の誤りがそのまま確定し、患者の安全に重大なリスクが生じます。",["医師の確認なしで確定"]],"3":["問題を分析しないまま利用をやめても、確認がすり抜けた原因が分からず、改善の機会を失います。",["問題の分析は行わない"]]},"AIB-C01-188":{"1":["権限を広げると、エージェントが誤った判断をしたときの損失がさらに大きくなり、再発防止と逆行します。",["権限を広げ"]],"2":["今回の問題は週末に起きており、週末の監視をなくすと同様の異常を検知できなくなります。",["週末は監視を行わない"]],"4":["判断の記録を削除すると、なぜ予算を集中させたかを分析できず、原因究明や再発防止ができません。",["記録を削除する"]]},"AIB-C01-189":{"0":["評価結果を開示しないと、本人が不当な評価に異議を唱えられず、説明責任や信頼を損ないます。",["一切開示しない"]],"1":["申し立てを受け付けないと、根拠の記録もない評価の誤りを是正できず、派遣スタッフに不当な不利益が続きます。",["申し立てを受け付けず"]],"3":["AI を参考にした判断でも、最終的な責任は会社と担当者にあります。AI を理由に責任を否定することはできません。",["会社に責任はない"]]},"AIB-C01-190":{"0":["出勤日数は勤怠の情報にすぎず、担当者が AI の判断を実際に検証・修正しているかどうかは分かりません。",["出勤日数だけ"]],"3":["モデル名とリリース日はモデルの属性情報で、人による監督が実際に機能しているかを示す指標になりません。",["モデル名とリリース日だけ"]],"4":["利用料金の総額はコストの情報で、担当者が AI の判断を実質的に監督しているかは評価できません。",["利用料金の総額だけ"]]},"AIB-C01-191":{"0":["現状を把握する前にツールを配布すると順序が逆で、利用状況からはデータ基盤やガバナンスの不足を評価できません。",["全社員に生成 AI ツールを配布し"]],"2":["他社の施策を模倣しても自社の課題は分かりません。自社のデータや人材、ガバナンスの状況を評価するのが先です。",["同じ施策を順に導入する"]],"3":["システム構成だけの棚卸しでは技術面しか分からず、人材やプロセス、ガバナンスの不足を見落とします。",["IT 部門のシステム構成だけ"]]},"AIB-C01-192":{"1":["Generative AI Lens は生成 AI ワークロードの設計のベストプラクティスで、6 つの観点で組織能力を整理する枠組みではありません。",["Generative AI Lens"]],"2":["責任共有モデルは AWS と顧客のセキュリティの責任分担を示すもので、AI 導入に必要な組織能力の整理には使いません。",["責任共有モデル"]],"3":["Trusted Advisor は AWS リソースの設定やコストの改善を提案するツールで、組織能力を整理する枠組みではありません。",["AWS Trusted Advisor"]]},"AIB-C01-193":{"0":["調達担当者は製品やサービスの購買を担う役割で、データの定義や品質を日常的に管理する役割ではありません。",["調達担当者"]],"2":["外部監査人は独立した立場で定期的に監査する役割で、日常的なデータ管理や利用者対応は行いません。",["外部監査人"]],"3":["ネットワーク管理者は通信基盤を運用する役割で、業務部門の立場からデータの定義や品質基準を管理する役割ではありません。",["ネットワーク管理者"]]},"AIB-C01-194":{"0":["可用性はシステムやデータが必要なときに利用できるかを表す観点で、項目の欠損の有無を表すものではありません。",["可用性"]],"1":["適時性はデータが十分に新しいかを表す観点で、必要な項目が欠けずに入力されているかとは異なります。",["適時性"]],"2":["一意性は同じ対象が重複して登録されていないかを表す観点で、項目の欠損とは別の観点です。",["一意性"]]},"AIB-C01-195":{"0":["ヘルプデスクのチケットは問い合わせの管理に使うもので、データの所在や意味、責任者を一覧で探す仕組みではありません。",["ヘルプデスクのチケット"]],"1":["請求書は取引の記録で、社内データのメタデータを整理して検索できるようにする仕組みではありません。",["請求書"]],"2":["ファイアウォールは通信を制御するセキュリティの仕組みで、データの所在や意味を整理する機能はありません。",["ファイアウォール"]]},"AIB-C01-196":{"0":["セキュリティパースペクティブはデータやワークロードの保護を扱い、組織文化や人材育成は主な対象ではありません。",["セキュリティ（Security）"]],"1":["オペレーションパースペクティブはクラウドサービスの運用を扱い、文化や人材育成、組織構造の見直しは扱いません。",["オペレーション（Operations）"]],"2":["プラットフォームパースペクティブは技術基盤の構築を扱い、人と組織の変革は人材パースペクティブの領域です。",["プラットフォーム（Platform）"]]},"AIB-C01-197":{"0":["Amazon Personalize はレコメンデーションを作るサービスで、S3 内の個人情報を検出する機能はありません。",["Amazon Personalize"]],"1":["Amazon Polly はテキストを音声に変換するサービスで、機密データの検出には使えません。",["Amazon Polly"]],"2":["AWS Budgets は費用の予算超過を通知するサービスで、文書に含まれる個人情報は検出できません。",["AWS Budgets"]]},"AIB-C01-198":{"0":["匿名化は個人を特定できる情報を取り除く処理で、画像に良品・不良品の正解を付ける作業ではありません。",["データの匿名化"]],"1":["プロンプトのテンプレート化は生成 AI への指示文を定型化する工夫で、学習用の正解ラベルを付ける作業とは異なります。",["プロンプトのテンプレート化"]],"2":["推論は学習済みモデルで新しいデータを予測する処理で、学習前に正解を付ける作業ではありません。",["モデルの推論"]]},"AIB-C01-199":{"0":["データ基盤が未整備のまま全社規模の高度な活用を始めると、データ品質の問題で失敗しやすく、順序が逆です。",["全社規模の高度な AI 活用 → データ基盤整備"]],"2":["基盤とガバナンスを最後に回すと、全社展開後にデータ品質やリスク管理の問題が表面化します。",["全社展開 → データ基盤とガバナンスの整備"]],"3":["基盤もガバナンスもないまま全社展開を先に行うと、データの不備やリスクの管理不足が全社に広がります。",["全社展開 → データ基盤整備"]]},"AIB-C01-200":{"1":["利用者は回答の根拠となった規程の版を見抜けないことが多く、古い規程に基づく誤った対応を招きます。",["利用者が見抜けばよい"]],"2":["RAG の回答は参照する文書に左右されます。モデルを高性能にしても、古い版を参照すれば誤った回答になります。",["より高性能なモデルを選べば"]],"3":["古い版や下書きまで取り込むと、最新版と矛盾する内容が回答に混ざります。量より文書の質が重要です。",["すべての文書をそのまま取り込む"]]},"AIB-C01-201":{"0":["定義や ID の体系が異なるまま結合すると、別の顧客を同一とみなすなどして誤った分析結果になります。",["定義を揃えずに単純に結合"]],"1":["一方の部門のデータだけでは、営業と保守を組み合わせて解約予兆を分析するという目的を果たせません。",["一方の部門のデータだけ"]],"2":["AI は定義の違いを自動的に解消できません。誤って結合されたデータを学習すれば誤った結果を出します。",["自動的に解消される"]]},"AIB-C01-202":{"0":["本社の所在地は AI の準備状況と関係がなく、データや人材、ガバナンスの成熟度を示しません。",["本社の所在地"]],"2":["広告予算の増減は AI 導入の準備状況を示す指標ではなく、データや体制の整備状況は分かりません。",["広告予算が増えているか"]],"3":["パソコンのメーカーの統一は AI の活用能力と無関係で、準備状況の評価観点になりません。",["パソコンのメーカー"]]},"AIB-C01-203":{"0":["Amazon Polly はテキストを音声に変換するサービスで、データレイクのアクセス権限を管理する機能はありません。",["Amazon Polly"]],"1":["AWS Artifact は AWS のコンプライアンスレポートを入手するサービスで、データレイクの権限管理はできません。",["AWS Artifact"]],"2":["AWS Pricing Calculator は料金を見積もるツールで、部門ごとのデータの参照範囲を制御できません。",["AWS Pricing Calculator"]]},"AIB-C01-204":{"0":["顧客数の多さは利用の適法性と関係がありません。取得時の利用目的や同意の範囲に新しい用途が含まれるかを確認すべきです。",["100 万人を超えているか"]],"2":["保存期間が短くても、利用目的や同意の範囲外の用途に使えば問題になります。確認すべき要点ではありません。",["保存期間が 1 年未満"]],"3":["ファイル形式は技術的な扱いやすさの問題で、そのデータを新しい用途に使ってよいかの判断には関係しません。",["Excel 形式かどうか"]]},"AIB-C01-205":{"0":["標準がないまま実験を増やすと、重複やばらつきが広がるだけで、本番運用やスケールへの準備が進みません。",["標準を作らずに"]],"1":["実験を全面中止すると、得られた知見や成果を捨てることになります。成果の出たものを本番化へつなげるべきです。",["全面的に中止し"]],"3":["共通の基盤や標準がない段階で全面変革に進むと、基盤不足で失敗しやすく、段階を飛ばしています。",["全面的な変革をすぐに開始"]]},"AIB-C01-206":{"0":["問い合わせを受け付けないと顧客の不便が増すだけで、データの鮮度という根本原因は解決しません。",["受け付けないようにする"]],"2":["文章が流暢になっても参照する在庫情報が古いままでは、誤った回答は変わりません。",["流暢なモデルに切り替える"]],"3":["注意書きを表示しても回答の誤りは解消されず、顧客の苦情の原因である古いデータの問題が残ります。",["常に表示するだけ"]]},"AIB-C01-207":{"0":["施策ごとの個別抽出を続けると、手間とデータの不整合が増え、全社展開のたびに同じ作業を繰り返します。",["個別に作り続ける"]],"2":["施策を増やしても基盤は自然には整いません。むしろ個別抽出が増えて不整合が広がります。",["自然に整う"]],"3":["手作業の抽出は時間がかかりミスも生じやすく、再現性がないため全社規模の活用に耐えられません。",["すべて手作業で行う"]]},"AIB-C01-208":{"1":["専門家の採用を待つと評価が遅れ、AI 活用の着手も先送りになります。外部の支援で今すぐ評価できます。",["評価を延期する"]],"2":["関心の有無だけでは、データ基盤やガバナンス、人材のスキルなどの準備状況を客観的に評価できません。",["質問だけで判定する"]],"3":["評価せずに他社を模倣しても、自社の課題に合った施策になるとは限らず、失敗のリスクが高まります。",["評価を行わずに"]]},"AIB-C01-209":{"1":["基準を変えると前回の結果と比較できず、この 1 年でどれだけ前進したかを示せません。",["異なる新しい評価基準"]],"2":["前回の結果を再提出しても 1 年間の変化は分からず、取締役会の問いに答えられません。",["そのまま再提出する"]],"3":["プロジェクトの件数は活動量を示すだけで、データや人材、ガバナンスなど成熟度の変化は分かりません。",["件数だけを報告する"]]},"AIB-C01-210":{"0":["スキャン画像のままでは文字情報として検索・活用できず、生成 AI による保守支援に生かせません。",["スキャン画像のまま"]],"2":["20 年分の報告書には貴重な保守の知見が含まれています。廃棄すると取り戻せないデータ資産を失います。",["すべて廃棄し"]],"3":["作業報告書には過去の故障や対処の知見が蓄積されており、デジタル化すれば保守支援に活用できます。",["活用を見送る"]]},"AIB-C01-211":{"0":["Polly の音声サンプルは音声合成の例にすぎず、生成 AI ワークロードの設計のベストプラクティスは示していません。",["音声サンプル"]],"1":["月次請求書は利用料金を示すだけで、設計上のベストプラクティスに照らした点検には使えません。",["月次請求書"]],"3":["AWS Marketplace はサードパーティ製品の購入窓口で、ワークロードの設計を点検するための指針ではありません。",["AWS Marketplace"]]},"AIB-C01-212":{"0":["各社員が空き時間に個別に整備すると、基準がばらつき品質も揃わず、計画的な整備になりません。",["各社員が空き時間に個別に"]],"1":["利用予定のないデータまで同じ優先度で整備すると、限られた予算が分散し、成果が出るまで時間がかかります。",["全データを同じ優先度"]],"3":["膨大なデータの整備完了を待つと AI の活用がいつまでも始まらず、成果を示して次の投資につなげられません。",["完了するまで"]]},"AIB-C01-213":{"0":["データ品質の問題はモデルの性能では補えません。品質の低いデータで学習すれば需要予測も不正確になります。",["品質の低いデータのまま"]],"2":["全社一括の統合は時間と費用がかかり、今年度中に需要予測で成果を出すという期限と予算の制約に合いません。",["すべてのデータを一度に統合"]],"3":["毎回の手作業による収集は再現性がなく工数もかかり、部門ごとにバラバラな品質の問題も解決しません。",["毎回各部門から手作業で"]]},"AIB-C01-214":{"1":["全面禁止では経験を積む機会がなくなり、高い関心や経営層の支援も生かせず、ガバナンス整備も進みません。",["あらゆる AI の利用を禁止"]],"2":["データガバナンスや利用ルールが未整備のまま顧客向けに公開すると、情報漏えいや不適切な回答のリスクが大きくなります。",["ルールが未整備のまま"]],"3":["利用ルールがない状態で外部サービスを自由に使わせると、シャドー AI による情報漏えいなど新たなリスクが生じます。",["各自が自由に外部の AI サービス"]]},"AIB-C01-215":{"0":["手書きのスキャン画像や年代ごとに異なる形式を扱うため、データ準備の費用がモデル利用料を上回ることもあり得ます。",["他の費用は考えなくてよい"]],"2":["手書き書類の読み取りは誤りが生じ得るうえ、形式もばらばらなため、整形や品質確認などの準備は不可欠です。",["すべて自動で正確に処理"]],"3":["データ準備を後回しにすると、運用開始後に予算超過や遅延が発覚します。承認前に計画へ含めるべきです。",["運用開始後に考えればよい"]]},"AIB-C01-216":{"1":["回答を短くしても、閲覧権限のない人事評価の情報が回答に含まれる可能性は残り、漏えいを防げません。",["回答の文字数を短くして"]],"2":["利用者を管理職に絞っても、管理職が閲覧できない文書が回答に出る問題は残り、根本的な解決になりません。",["管理職だけが使える"]],"3":["注意喚起だけでは、関連する質問で意図せず機密情報が回答に含まれることを防げません。技術的な権限制御が必要です。",["注意喚起するだけ"]]},"AIB-C01-217":{"0":["顧客データの利用制約を無視すると、法令や規程に違反し、顧客の信頼を損ないます。",["利用制約を無視して"]],"1":["合成データは実際の傾向と異なる可能性があります。実データでの検証を省くと、本番での性能を確かめられません。",["実データでの検証は省略"]],"2":["事例が少なくても、合成データで補うなどの方法があります。AI の活用を最初から諦める必要はありません。",["使うことはできないと結論付ける"]]},"AIB-C01-218":{"0":["現場任せでは部門間の調整や投資の確保ができず、全社的な方向性もそろいません。経営層の関与が不可欠です。",["現場の自主性に任せ"]],"2":["基盤モデルやツールの選定は技術的な判断で、実務の担当者に任せるべきです。経営層の主な役割ではありません。",["経営層自身が選定する"]],"3":["週次の進捗管理は実務の担当者が担う細かな管理で、経営層はビジョンの提示と資源配分に注力すべきです。",["直接、週次で行う"]]},"AIB-C01-219":{"0":["既存の手順に確認作業を追加すると、かえって手間が増えます。プロセス自体を見直さなければ大きな効果は得られません。",["AI による確認作業を追加する"]],"1":["モデルを高性能にしても既存の手順に組み込むだけでは、業務の構造が変わらず効果は限定的です。",["既存の手順に組み込む"]],"2":["手順を変えずに利用者を増やしても、AI を前提とした効率化は起きず、効果は限定的なままです。",["既存の手順を維持したまま"]]},"AIB-C01-220":{"1":["Bedrock の API を使った独自アプリは開発が必要で、自前開発なしで導入したいという要件に合いません。",["独自アプリの開発"]],"2":["Amazon Personalize は推薦機能に特化したサービスで、データ分析や問い合わせ回答、作業自動化のアシスタントではありません。",["Amazon Personalize"]],"3":["SageMaker AI はモデルの構築・学習・デプロイの基盤で、業務部門が自前開発なしで使えるアシスタントではありません。",["Amazon SageMaker AI"]]},"AIB-C01-221":{"0":["完全集中型は中央チームがすべてを担うため、各事業部門の業務知識を生かしにくく、部門に担当者を置くモデルとは異なります。",["完全集中型"]],"2":["外部委託一括型は AI 活用を外部に任せる形で、中央チームの標準化と部門担当者の組み合わせではありません。",["外部委託一括型"]],"3":["完全分散型は各部門が独自に進めるため中央の標準や共通基盤がなく、重複やばらつきが生じやすくなります。",["完全分散型"]]},"AIB-C01-222":{"0":["AI チャンピオンは監視や処分の役割ではありません。取り締まりを担わせると相談しにくくなり、利用の定着を妨げます。",["違反者を処分する"]],"1":["サーバー管理は IT 部門などの技術的な役割で、現場で活用を後押しするチャンピオンの目的ではありません。",["サーバーを管理する"]],"2":["予算の承認権限の集中はチャンピオンの役割ではなく、現場での活用の手本や相談相手という目的と異なります。",["予算の承認権限を集中"]]},"AIB-C01-223":{"0":["調達委員会は購買を審議する公式の会議体で、社員が自主的に事例やノウハウを共有し合う場ではありません。",["調達委員会"]],"2":["監査委員会は経営の監督や監査を担う公式の機関で、部門横断で知見を自主的に共有する場ではありません。",["監査委員会"]],"3":["取締役会は経営の意思決定機関で、AI に取り組む社員が自主的に学び合う場ではありません。",["取締役会"]]},"AIB-C01-224":{"1":["AWS Budgets は費用の予算を設定して超過を通知するサービスで、学習コンテンツは提供していません。",["AWS Budgets"]],"2":["AWS Cost Explorer は利用料金を分析するツールで、役割別に AWS の知識を学ぶ環境ではありません。",["AWS Cost Explorer"]],"3":["Amazon Macie は S3 内の機密データを検出するサービスで、社員教育のための学習環境ではありません。",["Amazon Macie"]]},"AIB-C01-225":{"0":["RAG は外部の文書を検索して生成 AI の回答に生かす技術で、タスクごとの役割と責任を整理する手法ではありません。",["RAG"]],"1":["KPI は目標の達成度を測る指標で、誰が実行し誰が最終責任を持つかを整理する手法ではありません。",["KPI"]],"2":["ROI は投資に対する利益の割合を示す指標で、役割分担の整理には使いません。",["ROI"]]},"AIB-C01-226":{"1":["業務時間外の試用を求めると社員の負担が増え、業務での活用にもつながりません。管理職の姿勢という原因も残ります。",["業務時間外に"]],"2":["管理職を通さない指示は業務の優先順位を決める管理職と矛盾し、現場が混乱します。管理職を巻き込む必要があります。",["管理職を通さずに"]],"3":["利用状況の確認をやめても、管理職が試用を認めていないという原因は変わらず、普及の状況も把握できなくなります。",["確認をやめる"]]},"AIB-C01-227":{"0":["議事録作成は事務的な作業で、権限ある後ろ盾として方向性を示す経営スポンサーの役割ではありません。",["議事録を作成する"]],"2":["モデルの技術的な設定は実務担当者の仕事で、経営スポンサーには資源確保や部門間の調整が期待されます。",["技術的な設定を自ら行う"]],"3":["利用履歴の日々の確認は細かな監視で、変革の方向性を示し資源を確保するスポンサーの役割ではありません。",["利用履歴を毎日確認する"]]},"AIB-C01-228":{"0":["年 1 回の報告会では知見が日常的に共有されず、部門ごとのばらばらな取り組みが続いて展開が加速しません。",["年 1 回の全社報告会"]],"2":["外部への全面委託では社内に能力やノウハウが残らず、持続的な全社展開の体制になりません。",["社内には推進組織を置かない"]],"3":["すべてを IT 部門に集約すると依頼が滞留し、各部門の業務知識も生かしにくくなり、展開が遅れます。",["IT 部門に集約し"]]},"AIB-C01-229":{"1":["一律の操作マニュアルでは自分の業務でどう使えばよいかが分からず、利用の定着につながりません。",["一律で同じ内容の操作マニュアル"]],"3":["利用が広がらない原因は業務での使い方が分からないことで、機能の多い製品に替えても解決しません。",["別の生成 AI 製品に入れ替える"]],"4":["利用回数を評価すると、成果につながらない形だけの利用を招き、本来の業務改善の目的から外れます。",["利用回数を人事評価の項目"]]},"AIB-C01-230":{"0":["説明を導入後に回すと、その間に不安と不信感が高まり、導入への抵抗が強まります。",["説明は導入後にまとめて"]],"1":["不安を表明した社員を外すと、現場の知見を失い、不安を口にしにくい雰囲気を作って不信を広げます。",["導入対象の業務から外す"]],"4":["計画を伏せると、後で知った社員の不信感が高まり、かえって不安と抵抗が大きくなります。",["社員に知らせない"]]},"AIB-C01-231":{"0":["全面委託では社内に知見が残らず、外部依存が続くため、中長期的に持続可能な体制になりません。",["すべての AI 開発と運用を外部パートナーに委託"]],"2":["育成が終わるまで取り組みを始めないと機会を逃します。外部の力を借りながら並行して育てるべきです。",["取り組みを始めない"]],"3":["AI 人材は市場での獲得競争が激しく、中途採用だけで必要な人数をすべて確保するのは困難です。",["中途採用だけで"]]},"AIB-C01-232":{"0":["予算消化率やプロジェクト件数は活動量を示すだけで、業務への効果や財務的な価値は分かりません。",["予算の消化率","プロジェクトの件数"]],"1":["リクエスト数や応答時間は技術的な利用状況を示すだけで、変革による業務成果や価値を表しません。",["月間リクエスト数","平均応答時間"]],"3":["ツール数や研修受講者数は取り組みの量を示すだけで、業務の効率化や売上への貢献は示せません。",["導入した AI ツールの数","受講者数"]]},"AIB-C01-233":{"0":["部門ごとに矛盾したルールを残すと、全社展開で混乱が生じ、リスク管理の一貫性も保てません。",["現状のまま維持する"]],"1":["ルールを廃止して個人の判断に任せると、情報漏えいや不適切な利用のリスクを統制できなくなります。",["ルールを廃止し"]],"2":["最も厳しいルールの一律適用で例外を認めないと、部門ごとの事情に対応できず、活用が大きく妨げられます。",["例外は一切認めない"]]},"AIB-C01-234":{"0":["ゼロから考えさせると、成功事例の知見が生かされず、展開に時間がかかって加速しません。",["ゼロから独自の方法"]],"1":["担当者 1 人に他部門の作業をすべて代行させると負荷が集中して持続せず、各部門に能力も残りません。",["作業をすべて代行させる"]],"3":["細部が異なる業務に同じ仕組みを強制すると、各部門の実情に合わず使われなくなるおそれがあります。",["細部まで変更せず","強制する"]]},"AIB-C01-235":{"0":["提供を停止すると活用の機会を失います。問題は利用料の可視化であり、基盤そのものではありません。",["基盤の提供を停止する"]],"2":["部門に知らせないと各部門がコストを意識せず、使い方の改善や予算の議論が進みません。",["部門には知らせない"]],"3":["均等割りでは実際の利用量と負担が一致せず、公平な予算配分にならず、コストを意識した利用も促せません。",["部門数で均等に割り当てる"]]},"AIB-C01-236":{"0":["業務部門の意見を導入後に聞くと、使えない仕組みが完成してから手戻りが発生し、頓挫の原因が解消されません。",["導入後に聞く"]],"2":["技術チームだけで開発して引き渡す方式こそ、業務部門に使えないと判断される原因です。分断を強めるだけです。",["技術チームだけで開発し"]],"3":["業務部門だけでは技術や法務・リスクの知見が不足し、品質や安全性に問題のある仕組みになりかねません。",["業務部門だけで"]]},"AIB-C01-237":{"0":["一度きりの決定事項の通知では、目的や影響が伝わらず、社員の理解と納得を得られません。",["一度メールで通知"]],"2":["不安の声に答えないと不信感が高まり、変革への抵抗が強まります。懸念を受け止める姿勢が必要です。",["回答しない方針"]],"4":["技術的な詳細だけでは、なぜ導入するのか、自分の仕事がどう変わるのかが伝わらず、納得につながりません。",["技術的な仕組みの詳細だけ"]]},"AIB-C01-238":{"1":["外部委託で罰するような対応は、効率化すると損をするという評価制度の矛盾を解消せず、社員の不信を招きます。",["外部に委託する"]],"2":["制度をそのままにして推奨しても、効率化すると手当が減るという動機の問題が残り、行動は変わりません。",["仕組みはそのままにして"]],"3":["義務化と処分は反発を招くだけで、効率化が不利になる報酬制度という根本原因に対処していません。",["利用しない社員を処分する"]]},"AIB-C01-239":{"0":["導入を中止すると効率化の機会を失います。担当者の役割を再設計すれば、人材を生かしながら導入できます。",["導入を中止して"]],"1":["業務を与えずに待機させると人材を無駄にし、社員の意欲も下がります。付加価値の高い業務へ再配置すべきです。",["待機させる"]],"3":["説明なしの業務廃止は社員の強い不信と抵抗を招き、変革の定着を妨げます。",["事前の説明なく"]]},"AIB-C01-240":{"0":["希望者だけで支援もないと、利用が一部にとどまり、3 部門で確認された効果を全社で得られません。",["支援は行わない"]],"1":["効果はすでに 3 部門で確認されており、同じパイロットを繰り返しても新たな知見は少なく、展開が遅れるだけです。",["もう一度 3 部門で同じパイロット"]],"3":["1 万人への一斉展開で問い合わせを各自に任せると、混乱が起き、支援がないため定着しません。",["同じ日に一斉に展開","各自で解決"]]},"AIB-C01-241":{"0":["AI アプリは利用者の声やモデルの変化に合わせて改善し続ける必要があり、変更しない方針では利用がさらに減ります。",["一切変更しない"]],"1":["不具合時だけの対応では、継続的な改善や成果への責任を持つ人がおらず、利用の減少は止まりません。",["不具合が出たときだけ"]],"3":["利用者には改善のための権限や技術がなく、責任の所在も曖昧になるため、継続的な改善は実現しません。",["利用者が自分で行う"]]},"AIB-C01-242":{"0":["処分では業務上のニーズという根本原因が解消されず、利用が隠れて行われるようになり、かえって把握が難しくなります。",["特定して処分する"]],"2":["対応しないと、承認外のサービスへの機密情報の入力などのリスクが放置され、統制できません。",["特に対応しない"]],"3":["実態を把握せずに即時禁止すると業務効率が下がり、ニーズが満たされないため隠れた利用が続くおそれがあります。",["実態を把握しないまま","即時に禁止"]]},"AIB-C01-243":{"0":["年 1 回だけで結果も通知しないと、提案が施策に反映されたか分からず、提案の意欲が失われます。",["結果は通知しない"]],"1":["提案者に費用を負担させると誰も提案しなくなり、現場のアイデアを集める仕組みとして機能しません。",["費用をすべて負担させる"]],"3":["経営企画部門だけで決める現行方式を続けると、現場の課題が反映されないという問題がそのまま残ります。",["現行の方式の継続"]]},"AIB-C01-244":{"0":["各部門がそれぞれツールを選ぶとツールが乱立し、セキュリティ部門が認めない状態になります。",["各部門が選んで導入"]],"1":["3 名で 1 部門ずつ個別に作り込むと時間がかかり、半年以内に 3 部門へ展開する期限に間に合いません。",["1 部門ずつ順番に","個別に作り込む"]],"3":["人事や経理は機密度が異なるため、設定をそのまま適用して利用者の注意に頼ると、情報の取り扱いを管理できません。",["利用者の注意で対応する"]]},"AIB-C01-245":{"0":["多くのパイロットは精度十分と報告されており、本番化しない原因はモデルの性能ではありません。やり直しは費用の無駄です。",["最も高性能なモデルでやり直す"]],"2":["技術部門の判断だけで本番化しても、業務部門の責任者や費用負担が決まっていないため、業務で使われず定着しません。",["技術部門の判断で本番化"]],"3":["件数を増やしても、責任者や費用負担が決まっていないという原因が残る限り、本番化の割合は改善しません。",["件数を増やし"]]},"AIB-C01-246":{"0":["一律の上限は業務価値の高い利用まで妨げ、品質の問題を利用者の注意に任せても根本的な改善になりません。",["一律の上限","利用者に注意を促して"]],"1":["問題が大きくなるまで放置すると、コスト増と品質低下が進み、責任の所在も曖昧なままです。",["問題が大きくなるまで"]],"3":["運用をすべてベンダーに任せると、社内で品質・コスト・リスクに責任を持つ人がいないままで、丸投げになります。",["運用をすべて任せる"]]},"AIB-C01-247":{"0":["現状維持では重複したチャットボットや把握されていない費用の無駄が続き、統制が取れません。",["現状の進め方を維持し"]],"1":["すべてを本社の承認制にすると、事業部の判断の速さが失われ、機動力を犠牲にします。",["事業部の判断権限をなくす"]],"3":["全面停止と 1 年間の凍結は、既存の価値も今後の機会も失う極端な対応で、統制と機動力の両立になりません。",["すべて停止し","1 年間凍結する"]]},"AIB-C01-248":{"0":["規制の違いは現地に合わせた調整で対応できます。展開しないと本社で上げた成果を海外拠点で生かせません。",["展開は行わない"]],"2":["本社の仕組みをそのまま展開すると、各地のデータ保護規制への違反や、言語・業務慣行に合わず使われないリスクがあります。",["変更せずに","同時に展開"]],"3":["各拠点にゼロから作らせると、本社の成果や共通基盤を再利用できず、重複と非効率が生じます。",["ゼロから独自の仕組み"]]},"AIB-C01-249":{"0":["低優先度の依頼を却下しても、CoE がすべてを開発するというボトルネックの構造は変わりません。",["すべて却下する"]],"2":["CoE を解散すると、標準やガバナンス、知見の共有が失われ、重複や統制の欠如が生じます。",["CoE を解散し"]],"3":["人員を倍増しても、すべてを CoE が開発する構造のままでは依頼の集中が続き、根本的な解決になりません。",["人員を倍増し"]]},"AIB-C01-250":{"0":["従業員代表を通さない個別交渉は、正式な協議の相手を無視する対応で、強い不信と反発を招きます。",["従業員代表を通さず"]],"1":["結果だけを事後に通知すると強い反発を招き、かえって定着が遅れて早期の効果も得られません。",["結果だけを通知する"]],"3":["無期限の延期は変革の機会を失い、早期に効果を出したいという経営層の目標を達成できません。",["無期限に延期する"]]},"AIF-C01-001":{"1":["包含関係が逆です。AI が最も広い概念で、ML はその中の一分野にあたります。ML が AI を含むわけではありません。",["AI を含む上位概念"]],"2":["AI は最も広い概念で、ディープラーニングは ML の中の一手法です。AI をディープラーニングの一手法とするのは包含関係が逆です。",["ディープラーニングの一手法"]],"3":["ディープラーニングは多層ニューラルネットワークでデータから学ぶ ML の一分野です。ML から独立した分野ではありません。",["ML とは独立した別の分野"]]},"AIF-C01-002":{"0":["自己教師あり学習はデータ自体から疑似的なラベルを作って学ぶ方式です。人が付けた「スパム」「正常」のラベルで学ぶこのケースは教師あり学習です。",["自己教師あり学習"]],"1":["教師なし学習はラベルのないデータから構造を見つける方式です。正解ラベル付きのメールで分類を学ぶこのケースには当てはまりません。",["教師なし学習"]],"2":["強化学習は環境との試行錯誤で報酬を最大化する方式です。ラベル付きデータから分類を学ぶこのケースとは異なります。",["強化学習"]]},"AIF-C01-003":{"0":["回帰は正解の数値が付いたデータから連続値を予測する教師あり学習です。ラベルのないデータから顧客グループを見つける目的には合いません。",["回帰"]],"1":["強化学習は報酬を手がかりに行動を学ぶ方式で、ラベルのない購買履歴を似た者同士にまとめる用途ではありません。",["強化学習"]],"3":["二値分類は 2 つの正解ラベルが付いたデータで学ぶ教師あり学習です。ラベルがない状態でグループを見つけることはできません。",["二値分類"]]},"AIF-C01-004":{"0":["クラスタリングはラベルのないデータを似たもの同士にまとめる手法で、賃料という連続値を予測するものではありません。",["クラスタリング"]],"2":["多クラス分類は決まったカテゴリから 1 つを選ぶタスクです。賃料のような連続した金額を予測するのは回帰です。",["多クラス分類"]],"3":["異常検知は通常と異なるデータを見つけるタスクで、物件の特徴から賃料の金額を予測する目的には合いません。",["異常検知"]]},"AIF-C01-005":{"0":["次元削減は高次元のデータを少ない変数に圧縮する教師なし学習の手法で、報酬を受けて行動を改善する仕組みではありません。",["次元削減"]],"1":["転移学習は学習済みモデルの知識を別のタスクに再利用する手法です。試行錯誤と報酬で行動を学ぶ方式そのものではありません。",["転移学習"]],"3":["教師あり学習は正解ラベル付きデータで学ぶ方式です。ロボットが試行錯誤し報酬で行動を改善するのは強化学習です。",["教師あり学習"]]},"AIF-C01-006":{"1":["学習はデータからモデルのパラメータを求める処理です。学習済みモデルに新しいデータを入れて予測を得る処理は推論と呼びます。",["学習"]],"2":["特徴量選択はモデルの入力に使う変数を選ぶ前処理の作業で、学習済みモデルで予測結果を得る処理ではありません。",["特徴量選択"]],"3":["ラベリングは学習データに正解を付ける作業です。学習済みモデルで新しいデータの予測を得る処理ではありません。",["ラベリング"]]},"AIF-C01-007":{"1":["CSV ファイルは行と列の決まった形を持つ表形式のデータで、構造化データにあたります。",["CSV ファイル"]],"2":["列と型が決まったテーブルは典型的な構造化データです。音声や画像のように決まった形を持たないデータではありません。",["列と型が決まった"]],"3":["リレーショナルデータベースの表は行と列で整理された構造化データで、非構造化データには該当しません。",["リレーショナルデータベースの表"]]},"AIF-C01-008":{"0":["コンピュータビジョンは画像や動画を扱う分野です。文章や話し言葉の意味を処理するのは自然言語処理です。",["コンピュータビジョン"]],"1":["強化学習は報酬で行動を学ぶ学習方式の一つで、言語の意味を理解・処理する AI の分野を指す名前ではありません。",["強化学習"]],"2":["時系列分析は時間順に並んだ数値データの傾向や将来値を扱う分野で、文章や言葉の意味を処理するものではありません。",["時系列分析"]]},"AIF-C01-009":{"0":["ストリーミング学習は流れてくるデータでモデルを更新し続ける学習の方式で、毎晩まとめて予測を出す推論方式ではありません。",["ストリーミング学習"]],"1":["リアルタイム推論は即時応答のためにエンドポイントを常時用意する方式です。1 日 1 回まとめて計算すればよいなら、コスト面で無駄が出ます。",["リアルタイム推論"]],"2":["エッジ推論は端末側で推論して低遅延やオフライン対応を実現する方式です。前日の全取引を夜間に一括処理する要件とは合いません。",["エッジ推論"]]},"AIF-C01-010":{"1":["高次元データを 2 次元に圧縮するのは次元削減で、正解ラベルを使わない教師なし学習のタスクです。",["2 次元に圧縮する"]],"2":["対戦を繰り返し報酬を最大化する戦略を学ぶのは強化学習で、正解ラベル付きデータから学ぶ教師あり学習ではありません。",["報酬を最大化する戦略"]],"4":["ラベルのない記事を内容の近さでグループ分けするのはクラスタリングで、教師なし学習のタスクです。",["ラベルのない記事"]]},"AIF-C01-011":{"0":["二値分類はカテゴリが 2 つの場合のタスクです。5 つのカテゴリから 1 つを選ぶこのケースは多クラス分類です。",["二値分類"]],"1":["回帰は連続した数値を予測するタスクです。メールを決まった部署のカテゴリに振り分ける用途には合いません。",["回帰"]],"2":["クラスタリングはあらかじめ決まったカテゴリなしにデータをまとめる手法です。指定した 5 つの部署に振り分けることはできません。",["クラスタリング"]]},"AIF-C01-012":{"0":["画像分類は画像をカテゴリに分けるタスクです。時間ごとの電力使用量から翌日の需要を見込む用途には合いません。",["画像分類"]],"1":["感情分析は文章の肯定・否定などを判定する自然言語処理のタスクで、数値の時系列から将来値を予測するものではありません。",["感情分析"]],"3":["クラスタリングは似たデータをまとめる手法で、時間の順序を持つ過去データから翌日の値を予測することはできません。",["クラスタリング"]]},"AIF-C01-013":{"0":["アンサンブル学習は複数のモデルの予測を組み合わせる手法です。学習済みモデルを出発点に自社画像で追加学習する手法ではありません。",["アンサンブル学習"]],"1":["次元削減は特徴量の数を減らす前処理的な手法で、学習済みモデルの知識を再利用して少量データで適応させるものではありません。",["次元削減"]],"3":["強化学習は報酬による試行錯誤で行動を学ぶ方式です。学習済みの画像モデルを自社データに適応させる用途とは異なります。",["強化学習"]]},"AIF-C01-014":{"1":["ルールベースのシステムは人が定義した規則で判断する仕組みで、ラベル付きとラベルなしのデータを組み合わせて学習するものではありません。",["ルールベースのシステム"]],"2":["教師なし学習だけではせっかくある 500 枚のラベル情報を使えません。少量のラベルと大量のラベルなしを併用するのは半教師あり学習です。",["教師なし学習のみ"]],"3":["強化学習は環境から得る報酬で行動を学ぶ方式で、ラベル付き・ラベルなしの医療画像を併用する学習には当てはまりません。",["強化学習"]]},"AIF-C01-015":{"0":["ディープラーニングは大量のデータを必要とします。学習データがほとんどない状態では性能が出にくく、利点は大きくありません。",["学習データがほとんどない"]],"1":["小さな表形式データで判断根拠の説明を重視する場面では、決定木などの従来手法のほうが適しており、ディープラーニングの利点は小さいです。",["判断根拠を明確に説明できる"]],"3":["決められた式で税額を求める処理は ML 自体が不要です。計算資源を最小限にしたい場合、ディープラーニングはむしろ不利です。",["決められた式で税額を求める"]]},"AIF-C01-016":{"0":["サーバーレス推論はペイロードサイズや処理時間の上限が小さく、最大 1 GB の動画を数分かけて解析する処理には対応できません。",["サーバーレス推論"]],"2":["リアルタイム推論は同期応答が前提でペイロードや処理時間の制約があり、インスタンスを 0 まで減らせないため夜間もコストがかかります。",["リアルタイム推論"]],"3":["毎晩 1 回のバッチ変換では、日中に随時届くリクエストを順次処理できず、利用者への結果通知が翌日まで遅れます。",["毎晩 1 回"]]},"AIF-C01-017":{"0":["非同期推論は大きなペイロードや長時間処理向けで、結果を S3 に出力してあとで受け取る方式です。数 KB の入力に数秒で応答する用途には過剰です。",["非同期推論"]],"1":["バッチ変換はまとまったデータを一括処理するジョブで、不規則に届く 1 件ずつのリクエストに数秒以内で応答できません。",["バッチ変換"]],"2":["常時稼働のインスタンスはリクエストがないアイドル時にも費用がかかり、1 日数十回の利用ではコストの無駄が大きくなります。",["常時稼働のインスタンス"]]},"AIF-C01-018":{"0":["正常時のデータだけでは故障の発生日という目的変数を学べず、回帰モデルで故障日を予測することはできません。",["故障の発生日を予測する"]],"1":["故障事例が数件しかないと分類モデルは汎化できず、見逃しや誤検知が多くなります。ラベルが乏しい場合は異常検知が適しています。",["故障事例の数件だけ"]],"3":["全センサー分の閾値を手作業で設定し見直さない方法は運用負荷が高く、パターンの変化にも追従できず早期検知に向きません。",["見直しは行わない"]]},"AIF-C01-019":{"0":["Comprehend はテキストの感情分析やエンティティ抽出を行う自然言語処理サービスで、画像から人物や物体を検出できません。",["Amazon Comprehend"]],"1":["Lex は音声・テキストの会話ボットを作るサービスで、監視カメラ画像の人物や物体の検出には使えません。",["Amazon Lex"]],"2":["Textract は文書から文字や表、フォームを抽出するサービスです。監視カメラ画像から人物や物体を検出する用途ではありません。",["Amazon Textract"]]},"AIF-C01-020":{"0":["Personalize は行動データに基づくレコメンデーションのサービスで、レビュー文から感情やキーフレーズを抽出する機能はありません。",["Amazon Personalize"]],"1":["Forecast は時系列データから将来の数値を予測するサービスで、文章の感情分析やキーフレーズ抽出は行えません。",["Amazon Forecast"]],"3":["Polly はテキストを音声に変換する音声合成サービスで、文章の感情やキーフレーズを分析する機能は持ちません。",["Amazon Polly"]]},"AIF-C01-021":{"1":["Rekognition は画像や動画を解析するサービスで、会議の音声をテキストに変換する機能はありません。",["Amazon Rekognition"]],"2":["Translate はテキストを別の言語に翻訳するサービスで、音声を入力として文字起こしすることはできません。",["Amazon Translate"]],"3":["Polly はテキストを音声に変換する逆方向のサービスです。音声からテキストへの変換は Transcribe が担います。",["Amazon Polly"]]},"AIF-C01-022":{"0":["Textract は文書画像から文字や表を抽出するサービスで、記事を音声で読み上げる機能はありません。",["Amazon Textract"]],"1":["Comprehend はテキストを分析する自然言語処理サービスで、テキストから音声を合成することはできません。",["Amazon Comprehend"]],"3":["Transcribe は音声をテキストに変換するサービスで、逆にテキストを音声で読み上げる用途には使えません。",["Amazon Transcribe"]]},"AIF-C01-023":{"0":["需要の変動パターンは決まった式で求められず、過去データから傾向を学ぶ ML が有効な典型例です。",["需要の変動パターンを予測する"]],"1":["大量の画像から不良品を見つける検査は、人がルールを書きにくいパターンを学べる ML が有効な典型例です。",["不良品を見つける検査"]],"4":["自由な文章である問い合わせの分類はルールで書き切りにくく、データからパターンを学ぶ ML が有効な場面です。",["問い合わせ文の分類"]]},"AIF-C01-024":{"0":["Translate はテキストを翻訳するサービスで、スキャンした PDF から請求元や金額、表を項目として抽出する機能はありません。",["Amazon Translate"]],"1":["Rekognition の文字検出は画像内の短いテキスト向けで、請求書のフォームのキーと値や表の構造は扱えません。",["Amazon Rekognition"]],"3":["Comprehend はテキストを分析するサービスで、スキャン画像から文字や表の構造を読み取る OCR 機能は持っていません。",["Amazon Comprehend"]]},"AIF-C01-025":{"1":["Transcribe は音声をテキストに変換するサービスで、投稿された口コミのテキストを他言語に翻訳することはできません。",["Amazon Transcribe"]],"2":["Lex は会話ボットを構築するサービスで、口コミを閲覧者の言語に機械翻訳する用途ではありません。",["Amazon Lex"]],"3":["Polly はテキストを音声に変換するサービスで、言語間の翻訳機能は持っていません。",["Amazon Polly"]]},"AIF-C01-026":{"0":["Polly はテキストを音声に変換するだけで、患者の発話から意図や日時を読み取って会話を進める機能はありません。",["Amazon Polly"]],"1":["Personalize はおすすめを提示するレコメンデーションサービスで、発話の意図とスロットを認識する対話ボットは作れません。",["Amazon Personalize"]],"3":["Textract は文書から文字や表を抽出するサービスで、電話やチャットの発話を理解して予約を受け付けることはできません。",["Amazon Textract"]]},"AIF-C01-027":{"0":["Comprehend はテキストの感情やエンティティを分析するサービスで、視聴履歴に基づく個人別のおすすめは生成できません。",["Amazon Comprehend"]],"1":["Rekognition は画像・動画の内容を解析するサービスで、利用者ごとの視聴履歴からおすすめを作る機能はありません。",["Amazon Rekognition"]],"2":["Kendra は自然言語の質問で文書を探す検索サービスで、行動履歴に基づく個人向けレコメンデーションを提供するものではありません。",["Amazon Kendra"]]},"AIF-C01-028":{"0":["Polly はテキストを音声に変換するサービスで、自然文の質問に対して社内文書の該当箇所を検索する機能はありません。",["Amazon Polly"]],"2":["Personalize は行動履歴に基づくレコメンデーションのサービスで、質問に答える文書検索には使えません。",["Amazon Personalize"]],"3":["Textract は文書から文字や表を抽出するだけで、自然文の質問に対して関連する箇所を探す検索機能は持ちません。",["Amazon Textract"]]},"AIF-C01-029":{"0":["Translate はテキストを翻訳するサービスで、診療記録から薬剤名や投与量などの医療エンティティを抽出できません。",["Amazon Translate"]],"2":["Polly はテキストを音声に変換するサービスで、医療テキストの内容を解析して情報を抽出する機能はありません。",["Amazon Polly"]],"3":["Rekognition は画像・動画を解析するサービスで、テキストの診療記録から医療情報を抽出する用途には使えません。",["Amazon Rekognition"]]},"AIF-C01-030":{"1":["Transcribe は音声をテキストに変換するサービスで、投稿画像の暴力的・性的な内容を検出することはできません。",["Amazon Transcribe"]],"2":["Textract は文書から文字や表を抽出するサービスで、画像に含まれる不適切なコンテンツを判定する機能はありません。",["Amazon Textract"]],"3":["Comprehend はテキストを分析するサービスで、画像そのものの内容をモデレーションすることはできません。",["Amazon Comprehend"]]},"AIF-C01-031":{"0":["パラメータ数を増やすことは導入可否の判断材料になりません。まず学習に使える解約データがあるかを確認しないと、モデルは作れません。",["パラメータ数を最大にできるか"]],"1":["GPU の確保は手段の話で、学習に必要な解約の記録データがなければ意味がありません。最初に確認すべきはデータの有無と品質です。",["最新の GPU インスタンス"]],"2":["生成 AI のチャットボットの有無は解約予測とは関係がありません。解約予測にはラベル付きの過去データが不可欠です。",["生成 AI のチャットボット"]]},"AIF-C01-032":{"1":["Polly はテキストを音声に変換するサービスで、通話録音をテキスト化したり不満を検出したりする機能はありません。",["Amazon Polly"]],"2":["Textract は文書画像から文字や表を読み取るサービスで、通話音声の処理や感情分析には使えません。",["Amazon Textract"]],"3":["Rekognition は画像・動画を解析するサービスで、通話音声の文字起こしやテキストの感情分析は行えません。",["Amazon Rekognition"]]},"AIF-C01-033":{"0":["最初に Translate を置いても、入力は音声なので翻訳できません。先に Transcribe で日本語音声をテキスト化する必要があります。",["Amazon Translate → Amazon Transcribe"]],"1":["Comprehend はテキスト分析用で音声を文字起こしできず、翻訳前に Polly で音声化しても英語の音声にはなりません。",["Amazon Comprehend → Amazon Polly"]],"3":["処理順が逆です。Polly はテキストを音声にするサービスで、最初に置いても日本語の音声入力を扱えません。",["Amazon Polly → Amazon Translate"]]},"AIF-C01-034":{"1":["Transcribe は音声をテキストに変換するサービスで、商品推薦にも説明文の生成にも使えません。",["Amazon Transcribe"]],"2":["Kendra は文書を検索するサービスで、閲覧履歴に基づく推薦や商品説明文の生成は行えません。",["Amazon Kendra"]],"3":["Textract は文書から文字や表を読み取るサービスで、推薦や文章生成の機能はありません。",["Amazon Textract"]]},"AIF-C01-035":{"1":["チャットボットに質問しても、数値データから学習した予測モデルがなければ根拠のある予測は得られず、毎週大量に実行する要件にも合いません。",["チャットボットに店舗スタッフが毎週予測を質問する"]],"2":["画像生成モデルはグラフの見た目を作るだけで、売上データから販売数を予測する機能はなく、根拠の説明もできません。",["画像生成モデル"]],"3":["毎回全データをプロンプトに渡すとトークン数が膨大になり推論コストが高く、数値の出力も安定せず根拠も説明しにくくなります。",["全データを毎回プロンプトとして渡して"]]},"AIF-C01-036":{"0":["モデルモニタリングはデプロイ後に本番の性能やデータの変化を監視する作業で、入力変数を作る作業ではありません。",["モデルモニタリング"]],"1":["ハイパーパラメータ調整は学習率などモデルの設定値を最適化する作業で、日付から曜日などの入力変数を作る作業とは異なります。",["ハイパーパラメータ調整"]],"3":["デプロイは学習済みモデルを本番で使える状態にする工程で、生データから特徴量を作る作業ではありません。",["モデルのデプロイ"]]},"AIF-C01-037":{"0":["SageMaker Neo は学習済みモデルを特定のハードウェア向けに最適化するコンパイル機能で、ノーコードでモデルを作る機能ではありません。",["SageMaker Neo"]],"2":["SageMaker Debugger は学習ジョブの内部状態を監視して問題を見つける開発者向け機能で、業務担当者がノーコードで予測モデルを作る用途ではありません。",["SageMaker Debugger"]],"3":["SageMaker Edge Manager はエッジデバイス上のモデルを管理する機能で、表形式データからノーコードで予測モデルを作る機能ではありません。",["SageMaker Edge Manager"]]},"AIF-C01-038":{"0":["モニタリングから始まりビジネス目標の定義が最後になっており、順序が逆です。目標を決めずにデータ収集や学習は進められません。",["モニタリング → モデルの学習"]],"1":["モデルがない段階でデプロイから始めることはできません。まず目標を定義し、データを準備して学習・評価してからデプロイします。",["デプロイ → データ収集"]],"3":["データ収集の前に学習を行う順序になっており成り立ちません。学習には事前に収集・前処理したデータが必要です。",["モデルの学習 → ビジネス目標の定義"]]},"AIF-C01-039":{"0":["データドリフトは本番の入力データの分布が学習時から変化する現象で、学習データにだけ過度に適合している状態を指す言葉ではありません。",["データドリフト"]],"1":["ハルシネーションは生成 AI が事実と異なる内容をもっともらしく出力する現象で、学習データと新規データの精度差を指すものではありません。",["ハルシネーション"]],"3":["過少適合は学習データでも精度が低い状態です。学習データで高精度なのに新しいデータで下がるのは過学習です。",["過少適合（アンダーフィッティング）"]]},"AIF-C01-040":{"0":["適合率は陽性と判定したもののうち本当に陽性だった割合で、誤検知を減らしたい場合の指標です。見逃しを避けるには再現率を重視します。",["適合率 (Precision)"]],"1":["RMSE は回帰モデルの誤差を測る指標で、画像分類で陽性患者の見逃しを評価する指標ではありません。",["RMSE"]],"2":["学習時間は計算コストの目安にすぎず、陽性患者をどれだけ見逃さずに検出できるかという性能は表しません。",["学習時間"]]},"AIF-C01-041":{"1":["テスト用データで調整を繰り返すとそのデータに合わせ込むことになり、本番で初めて見るデータに対する性能を過大に見積もります。",["テスト用データでハイパーパラメータを調整し続ける"]],"2":["学習データのコピーで評価すると、モデルが既に見たデータでの性能しか測れず、未知のデータに対する性能を過大に見積もります。",["そのままコピーしてテスト用データにする"]],"3":["学習に使った同じデータで精度を測ると過学習を見抜けず、本番での性能を過大に見積もってしまいます。",["同じデータで精度を測る"]]},"AIF-C01-042":{"0":["過少適合はモデルがパターンを捉えきれていない状態です。学習データを減らすとさらに学べる情報が減り、誤差は改善しません。",["半分に減らす"]],"2":["テストデータを学習に混ぜると正しい評価ができなくなるだけで、モデルの表現力不足という根本原因は解消しません。",["テストデータを学習データに混ぜて"]],"3":["正則化の強化はモデルを単純にする過学習への対策です。過少適合の状態で強めると、さらにパターンを捉えにくくなります。",["正則化をさらに強める"]]},"AIF-C01-043":{"0":["Model Cards はモデルの用途や性能などの情報を文書化する機能で、ハイパーパラメータの組み合わせを探索する機能はありません。",["SageMaker Model Cards"]],"2":["Model Monitor は本番のデータや予測の品質を監視する機能で、学習時にハイパーパラメータを探索するものではありません。",["SageMaker Model Monitor"]],"3":["Ground Truth は人によるデータのラベリングを管理する機能で、学習率などの設定値を自動で最適化することはできません。",["SageMaker Ground Truth"]]},"AIF-C01-044":{"0":["MSE は回帰モデルの予測誤差を測る指標で、迷惑メールの判定がどれだけ正しいかという分類の評価には使いません。",["平均二乗誤差 (MSE)"]],"1":["決定係数は回帰モデルがデータをどれだけ説明できるかを示す指標で、分類での誤検知の少なさは評価できません。",["決定係数 (R²)"]],"3":["再現率は実際の迷惑メールをどれだけ漏れなく捕まえたかの指標です。正常なメールの誤判定を減らしたいなら適合率を重視します。",["再現率 (Recall)"]]},"AIF-C01-045":{"0":["適合率は分類モデルの指標で、価格の予測が平均して何円ずれているかを表すことはできません。",["適合率 (Precision)"]],"1":["混同行列は分類結果の正誤を集計する表で、回帰の予測誤差を価格と同じ単位で示すものではありません。",["混同行列"]],"2":["AUC は分類モデルの判別性能を 0〜1 で表す指標で、価格の予測誤差を同じ単位で把握する用途には使えません。",["AUC"]]},"AIF-C01-046":{"1":["Ground Truth は人によるデータのラベリングを管理する機能で、本番環境の入力データの変化を継続的に監視することはできません。",["SageMaker Ground Truth"]],"2":["JumpStart は事前学習済みモデルやソリューションを使い始めるための機能で、本番モデルのドリフト検知は行いません。",["SageMaker JumpStart"]],"3":["Canvas はノーコードでモデルを作る機能で、デプロイ済みモデルの入力や予測の品質を継続的に監視する機能ではありません。",["SageMaker Canvas"]]},"AIF-C01-047":{"0":["Model Monitor は本番モデルのデータ品質やドリフトを監視する機能で、画像に人の手でラベルを付ける作業は管理できません。",["SageMaker Model Monitor"]],"2":["Clarify はデータやモデルのバイアス検出と予測の説明を行う機能で、作業者によるラベリングのワークフローは構築できません。",["SageMaker Clarify"]],"3":["自動モデルチューニングはハイパーパラメータを探索する機能で、学習データのラベル付け作業を効率化するものではありません。",["SageMaker 自動モデルチューニング"]]},"AIF-C01-048":{"0":["インスタンスサイズを上げても手作業による手順の抜けは防げず、上書きデプロイではモデルのバージョンや承認状態も管理できません。",["毎月上書きでデプロイする"]],"2":["手順書と個人 PC での保存は手作業のままで再現性が低く、承認されたモデルだけをデプロイする仕組みにもなりません。",["個人の PC に日付付きで保存する"]],"3":["ラベリングを増やしても処理の自動化やバージョン管理にはならず、評価を省略すると不合格のモデルが本番に出てしまいます。",["評価は省略する"]]},"AIF-C01-049":{"0":["不正を 1 件も検出できないモデルは正解率が高くても役に立ちません。偏ったデータでは正解率だけで判断してはいけません。",["そのまま本番にデプロイする"]],"2":["不正取引のデータを取り除くと、モデルは検出すべき不正のパターンをまったく学べなくなり、問題が悪化します。",["不正取引のデータを学習データから取り除く"]],"4":["学習データと同じデータで評価すると性能を過大に見積もるだけで、クラスの偏りによる見逃しの問題は解決しません。",["学習データと同じものにする"]]},"AIF-C01-050":{"0":["学習データの量は原因ではありません。予測時点で得られない将来の情報を特徴量に使っていることが、本番で精度が落ちる原因です。",["学習データを減らす"]],"1":["インスタンスの性能は推論速度に関わるだけで、予測精度の低下とは無関係です。原因は特徴量に含まれる将来の情報です。",["インスタンスサイズを上げる"]],"3":["検証データで異常に高い精度が出ているので過少適合ではありません。層を増やしてもデータリーケージは解消しません。",["過少適合している"]]},"AIF-C01-051":{"0":["エポックは学習データ全体を 1 回学習に使う単位で、LLM が入出力のテキストを処理する単位ではありません。",["エポック"]],"2":["バッチは学習や推論でまとめて処理するデータのかたまりを指し、単語や単語の一部に相当する単位ではありません。",["バッチ"]],"3":["ノードはニューラルネットワークの計算単位やネットワーク上の機器を指し、テキストを分割した単位ではありません。",["ノード"]]},"AIF-C01-052":{"0":["温度パラメータは生成時の出力のばらつきを調整する設定値で、文章の意味を数値の配列で表したものではありません。",["温度パラメータ"]],"1":["プロンプトはモデルに与える指示や入力の文章で、意味をベクトル空間に配置した数値表現ではありません。",["プロンプト"]],"2":["チェックポイントは学習途中のモデルの状態を保存したもので、文章の意味を表すベクトルではありません。",["チェックポイント"]]},"AIF-C01-053":{"0":["基盤モデルはファインチューニングや継続事前学習によって自社データで追加学習することもできます。追加学習に対応しないというのは誤りです。",["自社データでの追加学習には対応しない"]],"1":["基盤モデルは特定業界に限らない大量の多様なデータで事前学習されており、業界ごとに別のモデルが必要というわけではありません。",["特定の業界データだけで学習される"]],"2":["1 つのタスク専用に小さなデータで学習するのは従来型のモデルです。基盤モデルは大規模データで学習され多くのタスクに応用できます。",["特定の 1 タスクだけ"]]},"AIF-C01-054":{"1":["回帰モデルは数値を予測するモデルで、画像とテキストを同時に受け取って文章で回答することはできません。",["回帰モデル"]],"2":["単一モーダルモデルは 1 種類のデータしか扱えません。画像とテキストを同時に入力できるのはマルチモーダルモデルです。",["単一モーダルモデル"]],"3":["決定木モデルは主に表形式データの分類・回帰に使う手法で、画像の内容を文章で説明する機能はありません。",["決定木モデル"]]},"AIF-C01-055":{"1":["k 近傍法は近いデータの多数決などで分類・回帰を行う手法で、ノイズを除去しながら画像を生成する仕組みではありません。",["k 近傍法"]],"2":["ランダムフォレストは多数の決定木を組み合わせた分類・回帰の手法で、画像を生成するモデルではありません。",["ランダムフォレスト"]],"3":["線形回帰は数値を予測する単純なモデルで、ノイズから段階的に画像を生成する仕組みは持ちません。",["線形回帰"]]},"AIF-C01-056":{"0":["決定木は条件分岐で分類・回帰を行う従来型の ML 手法で、アテンションを中心としたニューラルネットワークではありません。",["決定木"]],"1":["k 平均法はデータをクラスタに分ける教師なし学習の手法で、LLM の基盤となるアーキテクチャではありません。",["k 平均法"]],"2":["サポートベクターマシンは分類などに使う従来型の ML 手法で、注意機構を持つニューラルネットワークではありません。",["サポートベクターマシン"]]},"AIF-C01-057":{"0":["LLM は入力を並べ替えるのではなく、文脈から次のトークンを確率的に予測して新しい文章を生成します。",["逆順に並べ替えて"]],"2":["用意された回答を検索して返すのは FAQ 検索の仕組みです。LLM はトークンを逐次予測して文章を生成します。",["データベースから検索して返す"]],"3":["人が定義した文法規則で文を組み立てるのは従来のルールベースの手法です。LLM はデータから学んだ確率で次のトークンを選びます。",["人が一つずつ定義したルール"]]},"AIF-C01-058":{"0":["線形回帰は数値を予測する単純なモデルで、生成器と識別器を競わせてデータを生成する仕組みは持ちません。",["線形回帰モデル"]],"2":["主成分分析はデータの次元を削減する教師なし学習の手法で、2 つのネットワークを競わせる生成モデルではありません。",["主成分分析 (PCA)"]],"3":["拡散モデルはノイズを段階的に除去して生成するモデルで、生成器と識別器を競わせる GAN とは仕組みが異なります。",["拡散モデル"]]},"AIF-C01-059":{"1":["最大トークン数は出力の長さの上限を決めるだけで、出力の一貫性やばらつきには影響しません。",["最大トークン数を増やす"]],"2":["温度を高くすると確率の低いトークンも選ばれやすくなり、出力のばらつきが増えて一貫性が下がります。",["温度 (temperature) を高くする"]],"3":["Top K を大きくすると候補となるトークンが増え、出力のばらつきが大きくなって一貫性が下がります。",["Top K を大きくする"]]},"AIF-C01-060":{"0":["最大トークン数は出力全体の長さの上限を決めるパラメータで、累積確率で次のトークン候補を絞るものではありません。",["最大トークン数"]],"1":["停止シーケンスは指定した文字列が出たら生成を止める設定で、トークン候補を確率で絞る仕組みではありません。",["停止シーケンス"]],"3":["エポック数は学習時にデータを何周使うかを決める値で、推論時のトークン選択には関係しません。",["エポック数"]]},"AIF-C01-061":{"1":["最大トークン数は出力の長さの上限を決めるもので、次のトークンを上位何個の候補から選ぶかは指定できません。",["最大トークン数"]],"2":["温度は確率分布の鋭さを変えて出力のばらつきを調整するもので、候補を上位 50 個に限定する設定ではありません。",["温度 (temperature)"]],"3":["Top-p は個数ではなく累積確率で候補を絞るパラメータです。上位 50 個という個数で絞るなら Top-k を使います。",["Top-p"]]},"AIF-C01-062":{"0":["Top-k は次のトークンを選ぶ候補の数を絞る設定で、応答全体の長さに上限を設けるものではありません。",["Top-k"]],"1":["学習率はモデルの学習時にパラメータの更新幅を決める値で、推論時の出力の長さとは関係ありません。",["学習率"]],"3":["温度は出力のばらつきを調整するパラメータで、応答の長さやそれに伴うコストを制限することはできません。",["温度 (temperature)"]]},"AIF-C01-063":{"0":["埋め込みの次元数は意味検索などのベクトル表現に関する設定で、テキスト生成をどこで止めるかには関係しません。",["埋め込みの次元数を増やす"]],"2":["Top-k を大きくすると候補が増えて出力がばらつくだけで、「Q:」の手前で生成を確実に止めることはできません。",["Top-k を大きくする"]],"3":["温度を高くすると出力のばらつきが増えるだけで、回答の終わりで生成を止める効果はありません。",["温度を高くする"]]},"AIF-C01-064":{"1":["サムネイル画像を生成しても検索の仕組みは変わらず、キーワードが異なる意味の近い記事は見つけられません。",["画像生成モデルで記事のサムネイルを作る"]],"2":["完全一致検索では「パスワードを忘れた」と表現が異なる「ログインできない場合の対処」の記事はヒットしません。",["完全一致検索"]],"3":["作成日順に並べるだけでは検索語との意味の近さが考慮されず、目的の記事を見つける助けになりません。",["作成日の新しい順に並べる"]]},"AIF-C01-065":{"0":["平均絶対誤差は回帰モデルの予測値と実測値のずれを測る指標で、ベクトル同士の向きの近さを測るものではありません。",["平均絶対誤差"]],"1":["パープレキシティは言語モデルが次のトークンをどれだけうまく予測できるかの指標で、2 つのベクトルの類似度ではありません。",["パープレキシティ"]],"2":["再現率は分類モデルが実際の陽性をどれだけ検出できたかの指標で、埋め込みベクトル間の意味の近さは測れません。",["再現率"]]},"AIF-C01-066":{"0":["評価から始まり事前学習が最後になっており順序が逆です。学習していないモデルは評価もデプロイもできません。",["評価 → デプロイ"]],"1":["デプロイが最初に来ていますが、事前学習も評価もしていないモデルはデプロイできません。",["デプロイ → 事前学習"]],"2":["ファインチューニングは事前学習済みのモデルに対して行うもので、データの選定や事前学習より前には実施できません。",["ファインチューニング → データの選定"]]},"AIF-C01-067":{"0":["Bedrock などの多くのサービスはトークン数に応じて課金されるため、トークン数が増えれば料金も増えます。",["料金に影響しない"]],"1":["トークンは文字数と常に一致するわけではなく、分割方法はモデルや言語によって異なります。",["文字数と常に等しい"]],"2":["通信の暗号化はトークン数とは無関係です。日本語で増えるのはモデルのトークン化の方法によるものです。",["暗号化されて送信される"]]},"AIF-C01-068":{"0":["温度は出力のばらつきを調整するパラメータで、出力の長さの上限には関係しないため、途中で途切れる問題は解決しません。",["温度を 0 にする"]],"1":["埋め込みモデルは検索用のベクトル化に使うもので、生成される文章の長さの上限到達とは関係ありません。",["埋め込みモデルを別のものに変更する"]],"3":["Top-k は次のトークンの候補数を絞る設定で、出力の長さの上限は変わらないため途切れは解消しません。",["Top-k を 1 にする"]]},"AIF-C01-069":{"0":["温度は生成時の出力のばらつきを調整するもので、検索段階でのベクトルの比較には影響しません。原因は質問と文書で埋め込みモデルが異なることです。",["生成用 LLM の温度を下げる"]],"2":["モデルごとにベクトル空間が異なるため、閾値を下げても意味の近さは測れず、無関係な文書が増えるだけです。",["類似度の閾値を下げる"]],"3":["モデル Y で作ったベクトルは質問文を工夫してもモデル X のベクトル空間には入りません。文書側も同じモデルで埋め込み直す必要があります。",["質問文を長くして"]]},"AIF-C01-070":{"0":["Top-k を 1 にすると常に最も確率の高いトークンだけが選ばれ、出力はかえって画一的になります。",["Top-k を 1 にする"]],"2":["停止シーケンスは指定した文字列で生成を止める設定で、案の多様性や意外性を高める効果はありません。",["停止シーケンスを追加する"]],"3":["最大トークン数を小さくすると出力が短くなるだけで、表現の多様性は増えません。",["最大トークン数を小さくする"]]},"AIF-C01-071":{"0":["モデルドリフトは時間とともに本番の状況が変わりモデル性能が低下する現象で、事実と異なる内容を生成する現象ではありません。",["モデルドリフト"]],"1":["過少適合はモデルが学習データのパターンを捉えきれていない状態で、もっともらしい誤情報の生成を指す言葉ではありません。",["過少適合"]],"3":["データ漏えいは機密情報が外部に流出することで、LLM が事実でない内容をもっともらしく生成する現象とは別物です。",["データ漏えい"]]},"AIF-C01-072":{"1":["固定ルールによる入力値の検証は毎回同じ結果が求められる処理で、確率的な生成 AI より従来のプログラムが適しています。",["固定ルールによる入力値の検証"]],"2":["法令で決まった税率の適用は正確さが必須の決まった処理で、従来のプログラムで行うべきものです。",["法令で定められた税率の適用"]],"4":["残高の計算は正確さが必須ですが、生成 AI は確率的にトークンを生成するため計算を誤ることがあり、適していません。",["残高の正確な計算"]]},"AIF-C01-073":{"0":["LLM は学習時点までの情報しか持たず、学習データにない最新情報を常に正しく答えることはできません。",["最新情報も常に正しく回答できる"]],"1":["生成 AI はハルシネーションを起こすことがあり、出力が事実として正確である保証はありません。",["常に事実として正確"]],"3":["生成は確率的に行われるため、同じ入力でも出力が変わることがあり、検証が不要になることはありません。",["必ず同じ出力を返す"]]},"AIF-C01-074":{"1":["テキストだけでなく画像なども扱えるマルチモーダルな LLM が存在するため、テキスト以外を一切扱えないというのは誤りです。",["テキスト以外のデータは一切扱えない"]],"2":["デプロイ後もインフラを拡張すれば利用者数は増やせます。これは LLM の本質的な限界ではありません。",["利用者数を増やせない"]],"3":["多くの LLM は多言語で学習されており日本語も扱えます。言語による品質差はあっても、扱えないわけではありません。",["日本語は扱えない"]]},"AIF-C01-075":{"0":["バックアップの物理的な保管は人や設備による作業で、生成 AI がテキストやコードを生成して支援する場面ではありません。",["物理的に保管する"]],"1":["ケーブルの修理は物理的な作業で、生成 AI の文章やコードの生成能力では対応できません。",["ネットワークケーブルの断線を修理する"]],"2":["CPU のクロック周波数はハードウェアの設定で、生成 AI によるコード生成の活用場面とは関係ありません。",["CPU のクロック周波数を上げる"]]},"AIF-C01-076":{"0":["生成 AI の出力は誤りを含むことがあり、法令適合性は人が確認する必要があります。人の確認なしに保証することはできません。",["人の確認なしで保証できる"]],"1":["SQL の実行速度はデータベースの性能の問題で、文章の作成を効率化する生成 AI の導入効果ではありません。",["SQL の実行速度が上がる"]],"3":["生成 AI の出力は確率的で、文面が変わらないことを保証する仕組みではありません。保存した文面の固定は生成 AI の効果ではありません。",["二度と変わらないことを保証できる"]]},"AIF-C01-077":{"0":["温度を 0 にすると最も確率の高いトークンが選ばれやすくなり、ばらつきは減ります。温度 0 の場合にだけ起こる現象ではありません。",["温度を 0 に設定している場合にだけ"]],"1":["推論のたびにモデルの重みが更新されることはありません。出力が変わるのはトークンを確率的に選んでいるためです。",["重みがリクエストのたびに少しずつ更新"]],"3":["会話の内容が都度モデルに学習されることはありません。ばらつきの原因は確率的なトークン選択です。",["その都度モデルに学習されている"]]},"AIF-C01-078":{"0":["温度は既に持っている知識からの選び方を変えるだけで、学習していない昨日の新制度の情報を生み出すことはできません。",["温度が低く"]],"1":["Top K は候補トークンの数を絞る設定で、モデルが知らない新しい情報を答えられるようにするものではありません。",["Top K が小さく設定されている"]],"3":["ゼロショットかどうかは指示の与え方の違いで、学習データにない昨日の情報を知らないという根本原因とは関係ありません。",["ゼロショットで書いている"]]},"AIF-C01-079":{"1":["パラメータ数はモデルの規模を示す技術的な情報で、チャットボット導入による業務改善やビジネス成果を表しません。",["モデルのパラメータ数"]],"2":["ROUGE は生成文と参照文の一致度を測る技術指標で、顧客満足や解決率といったビジネス価値を直接表しません。",["ROUGE スコア"]],"4":["平均入力トークン数はコストの見積もりに使う技術指標で、サポート業務のビジネス成果を示すものではありません。",["平均入力トークン数"]]},"AIF-C01-080":{"0":["誤った金額を顧客に送付すると信頼や取引に影響します。正確な計算はプログラムに任せれば誤りを防げます。",["そのまま顧客に送付する"]],"2":["指示を繰り返しても LLM が確率的に生成する仕組みは変わらず、計算の正確さは保証されません。",["繰り返し指示するだけにする"]],"3":["温度を上げると出力のばらつきが増え、誤りがかえって増えます。最大値を採用しても正しい合計になる保証はありません。",["最も大きい値を採用する"]]},"AIF-C01-081":{"0":["回答を長くしても根拠のない内容が減るわけではなく、かえって規程にない内容を含む余地が広がります。",["最大トークン数を大きくして"]],"2":["規程に関する指示を削除するとモデルが根拠を持たずに回答することになり、ハルシネーションが増えます。",["指示をすべて削除する"]],"3":["温度を上げると確率の低いトークンも選ばれやすくなり、事実と異なる内容がかえって出やすくなります。",["温度を最大値まで上げる"]]},"AIF-C01-082":{"0":["文字数の合計は売上への影響を示しません。効果は購入率などの業務指標を対照群と比べて測る必要があります。",["文字数の合計を数える"]],"1":["GPU の台数は生成にかかったリソースの話で、説明文が売上を伸ばしたかどうかは分かりません。",["GPU の台数を比較する"]],"3":["モデルのパラメータ数は規模を示すだけで、導入した説明文の売上への効果を評価する材料になりません。",["パラメータ数を報告する"]]},"AIF-C01-083":{"1":["モデル名を隠しても回答の根拠は分からず、利用者が正しさを確認しやすくはなりません。かえって透明性が下がります。",["モデルの名前を非表示にする"]],"2":["根拠を示さずに「正確です」と書いても検証の手段にはならず、誤った回答を信じ込ませる危険があります。",["「この回答は正確です」"]],"3":["文字数を短くしても回答の根拠は示されず、利用者が正しさを自分で確認する手段にはなりません。",["文字数を短くする"]]},"AIF-C01-084":{"0":["テストを廃止すると要約の品質低下を検知できなくなります。問題は評価基準であり、テスト自体をなくすべきではありません。",["テストを廃止する"]],"1":["偶然一致するまで再実行しても品質の評価にはならず、完全一致で判定するという基準の不適切さは解消しません。",["何度でも再実行する"]],"3":["期待値を結果に合わせて書き換えるとテストが常に合格し、誤った要約も検出できなくなります。",["テスト結果に合わせて書き換える"]]},"AIF-C01-085":{"0":["生成 AI はハルシネーションを起こすことがあり、誤りの影響が大きい医療分野で確認なしに患者へ送るのは危険です。",["そのまま患者に自動送信する"]],"1":["温度を上げると出力のばらつきが増え、誤った内容はかえって出やすくなります。確認なしの自動送信も危険です。",["温度を上げてから自動送信する"]],"2":["専門家が確認する運用にすればリスクを抑えて効率化できるため、活用を一切検討しないのは過度に保守的です。",["一切検討しない"]]},"AIF-C01-086":{"0":["生成 AI は問い合わせへの対応を効率化するもので、顧客からの問い合わせの発生そのものをなくすことはできません。",["件数そのものをゼロにできる"]],"1":["返金のような重要な判断を確認なしに生成 AI に任せるのは危険で、複雑な案件や判断は人に引き継ぐ設計にすべきです。",["スタッフの確認なしに返金処理を確定できる"]],"3":["生成 AI は文章の生成が得意なもので、将来の天候を正確に予言することはできません。",["天候を正確に予言できる"]]},"AIF-C01-087":{"0":["保険料率の算出は誤りの影響が大きく説明責任も求められる判断で、生成 AI に任せてそのまま反映するのは不適切です。",["そのまま約款に反映する"]],"1":["支払可否の最終決定は誤りの影響が大きく、人の確認なしに自動通知すると誤りを修正する機会がありません。",["支払可否を最終決定し"]],"3":["引き落とし金額の決定は顧客の資金に直結し、正確さが必須です。確率的な生成 AI に任せるのは不適切です。",["引き落とす金額を決める"]]},"AIF-C01-088":{"0":["検証せずに全社へ一斉導入すると費用が膨らむうえ、感想ではベースラインと比べた定量的な効果を示せません。",["全社に一斉導入し"]],"2":["ベンチマークスコアはモデルの一般的な性能で、自社業務での削減時間や総費用との比較という ROI の根拠にはなりません。",["ベンチマークスコアだけ"]],"3":["ROI はトークン料金だけでなく開発や運用を含む総費用で評価する必要があり、費用を過小に見積もることになります。",["開発や運用の費用は考慮しない"]]},"AIF-C01-089":{"0":["基盤モデルの性能は言語によって差があり、学習データの少ない言語では品質が下がることがあるため、英語の結果だけでは判断できません。",["すべての言語で同じ品質が出る"]],"1":["温度を上げると出力のばらつきが増えるだけで、学習データが少ない言語の回答品質は改善しません。",["温度を上げて回答を多様にする"]],"2":["最大トークン数を最小にすると回答が途中で途切れるだけで、言語ごとの品質差の確認や対策にはなりません。",["最大トークン数を最小にする"]]},"AIF-C01-090":{"0":["交渉メールの自動送信は誤りがそのまま相手方に伝わるおそれがあり、責任を持つ担当者の判断を経ないのは不適切です。",["交渉メールを自動送信させる"]],"1":["要約や条項の候補抽出に使い担当者が確認すれば効率化できるため、一切使わないのは効率化の機会を逃します。",["一切使わない"]],"2":["生成 AI は見落としやハルシネーションの可能性があるため、担当者が読まずに締結すると大きな損失につながります。",["担当者が読まずに締結する"]]},"AIF-C01-091":{"0":["Bedrock はサーバーレスで、利用者がインスタンスを選んで起動・管理する必要はありません。",["GPU インスタンスを選んで起動・管理し"]],"1":["Bedrock では入力したプロンプトや応答はベースモデルの学習に使われず、モデル提供者とも共有されません。",["モデル提供者と共有される"]],"2":["Bedrock では Amazon のモデルだけでなく、Anthropic や Meta など複数のプロバイダーのモデルを利用できます。",["Amazon が開発したモデルだけ"]]},"AIF-C01-092":{"1":["インスタンスの稼働時間で課金されるのは SageMaker AI のエンドポイントなどです。Bedrock のオンデマンドはトークン数で課金されます。",["GPU インスタンスの稼働時間"]],"2":["オンデマンドは使った分だけ支払う従量課金で、使用量に関係ない固定の月額料金はかかりません。",["固定の月額料金"]],"3":["テキストモデルのオンデマンド料金は入出力のトークン数に応じて決まり、長さに関係なく 1 回ごとに一定額ではありません。",["呼び出した回数のみ"]]},"AIF-C01-093":{"0":["Polly はテキストを音声に変換するサービスで、仕様の作成やコードの実装を支援する開発環境ではありません。",["Amazon Polly"]],"1":["Bedrock Guardrails は生成 AI の入出力を制御する機能で、要件から仕様やコードを作る IDE ではありません。",["Amazon Bedrock Guardrails"]],"2":["Rekognition は画像・動画を分析するサービスで、AI エージェントによる開発支援の機能はありません。",["Amazon Rekognition"]]},"AIF-C01-094":{"0":["Kendra は社内文書を検索するインテリジェント検索サービスで、基盤モデルのファミリーではありません。",["Amazon Kendra"]],"1":["Textract は文書から文字や表を抽出する AI サービスで、Bedrock で使う基盤モデルのファミリーではありません。",["Amazon Textract"]],"2":["Lex はチャットボットを構築するサービスで、Bedrock から利用する Amazon 製の基盤モデルではありません。",["Amazon Lex"]]},"AIF-C01-095":{"0":["Rekognition は画像・動画を解析するサービスで、Confluence や SharePoint の文書を取り込んで質問に回答する仕組みは作れません。",["Amazon Rekognition"]],"1":["想定問答を手作業で登録する方法は運用負荷が高く、社内文書が更新されても自動では追従できません。",["すべて手作業で登録する"]],"2":["JumpStart でのデプロイやファインチューニングは学習とインフラ管理が必要で、それを避けたいという要件に合いません。",["社内文書でファインチューニングする"]]},"AIF-C01-096":{"1":["Bedrock にスポットという購入方式はありません。中断の可能性があるスポットでは安定したスループットも確保できません。",["スポット"]],"2":["Savings Plans は EC2 などのコンピューティング利用料を割り引く仕組みで、Bedrock でカスタムモデルの処理能力を確保する方式ではありません。",["Savings Plans"]],"3":["オンデマンドは処理能力を確保しないためスロットリングの可能性があり、カスタマイズしたモデルの利用には通常プロビジョンドスループットが必要です。",["オンデマンド"]]},"AIF-C01-097":{"0":["AWS Glue はデータの抽出・変換・ロード (ETL) を行うサービスで、基盤モデルのデプロイやファインチューニングは行えません。",["AWS Glue"]],"2":["Comprehend は事前学習済みの自然言語処理サービスで、公開されている基盤モデルを選んで自社アカウントにデプロイする機能はありません。",["Amazon Comprehend"]],"3":["Kendra は文書検索サービスで、基盤モデルをワンクリックでデプロイしたり微調整したりする機能はありません。",["Amazon Kendra"]]},"AIF-C01-098":{"0":["50 万件を手動で 1 件ずつ実行するのは運用負荷が非常に高く、バッチ推論より料金も高くなります。",["1 件ずつリアルタイムで手動実行する"]],"1":["1 回限りの分類処理のために 1 年契約で処理能力を確保すると、処理後も費用がかかり続けコストを抑えられません。",["1 年契約で購入する"]],"3":["GPU サーバーの購入やモデル構築は初期費用と運用負荷が大きく、数日で結果が得られればよい今回の要件には過剰です。",["自社で GPU サーバーを購入して"]]},"AIF-C01-099":{"0":["Translate は機械翻訳のマネージドサービスで、オープンなモデルを改変したり学習やインスタンスを制御したりすることはできません。",["Amazon Translate"]],"1":["Amazon Q Business は社内データに基づくアシスタントサービスで、モデルの学習方法やインフラを細かく制御する用途ではありません。",["Amazon Q Business"]],"2":["Comprehend は事前学習済みの自然言語処理サービスで、独自のモデル改変や推論インスタンスの選択はできません。",["Amazon Comprehend"]]},"AIF-C01-100":{"0":["モデルを一から学習するのは大きな手間とコストがかかり、既存の基盤モデルの回答をコードなしで比較したいという目的に合いません。",["モデルを一から学習する"]],"2":["GPU インスタンスの起動やモデルのインストールは手間がかかり、Bedrock のモデルを手軽に比較する方法ではありません。",["GPU インスタンスを起動してモデルをインストールする"]],"3":["CloudFormation はインフラをコードで構築するサービスで、モデルにプロンプトを入力して回答を比較する機能はありません。",["AWS CloudFormation テンプレート"]]},"AIF-C01-101":{"1":["プロビジョンドスループットは期間契約で一定の処理能力に課金されるため、利用量が予測できず長期契約を避けたい段階には向きません。",["プロビジョンドスループットの 6 か月契約"]],"2":["自社に GPU サーバーを設置すると初期投資と運用負荷が大きく、試験運用で長期の負担を避けたい要件に反します。",["自社データセンターへの GPU サーバー設置"]],"3":["最大規模の処理能力を常時確保すると、利用が少ない日にも費用がかかり、変動する利用量に対して無駄が大きくなります。",["常時確保"]]},"AIF-C01-102":{"0":["Bedrock を使っても責任共有モデルは適用され、アクセス制御やデータの扱いは引き続き顧客の責任です。",["責任共有モデルが適用されず"]],"1":["Bedrock を使っても生成 AI のハルシネーションはなくならず、回答の正確性は保証されません。",["常に事実として正しい"]],"4":["Bedrock のモデルはトークン数などに応じた従量課金で、すべてが無料で使えるわけではありません。",["無料で利用できる"]]},"AIF-C01-103":{"0":["Guardrails は不適切な入出力をフィルタリングする機能で、繰り返し使う前置き部分の処理コストやレイテンシーは削減できません。",["Bedrock Guardrails"]],"1":["モデル評価はモデルの回答品質を比較・評価する機能で、リクエストごとの処理コストを減らす仕組みではありません。",["モデル評価"]],"2":["モデル呼び出しログは入出力を記録する機能で、前置き部分の再処理を省いてコストやレイテンシーを下げることはできません。",["モデル呼び出しログ"]]},"AIF-C01-104":{"0":["Translate は自然言語を翻訳するサービスで、モデルごとに異なる API リクエストの形式を変換する機能はありません。",["Amazon Translate"]],"2":["モデルを一から学習し直すのは膨大な手間とコストがかかり、リクエスト形式の書き換えを減らすという目的に見合いません。",["一から学習し直す"]],"3":["アカウントを分けてもモデルごとのリクエスト形式の違いは解消されず、管理の手間が増えるだけです。",["別の AWS アカウントを作成する"]]},"AIF-C01-105":{"0":["Comprehend は文章の分析を行うサービスで社内資料に基づく質問応答はできず、Guardrails も入出力の制御機能でコード生成は支援しません。",["Amazon Comprehend"]],"1":["Rekognition は画像・動画の分析、Transcribe は音声のテキスト化のサービスで、どちらの部門の要件にも合いません。",["Amazon Rekognition"]],"3":["組み合わせが逆です。社内資料に基づく質問応答はナレッジベースの RAG、仕様からコード生成までの支援は Kiro が適しています。",["営業部門には Kiro"]]},"AIF-C01-106":{"0":["最大量のプロビジョンドスループットを常時契約すると、利用の少ない時間帯にも費用が発生し、コスト最小化の要件に反します。",["常時契約する"]],"1":["バッチ推論は非同期のまとめ処理で、読者の質問に即時に答えるチャット機能には使えません。",["翌日にまとめて回答する"]],"3":["数万件を手作業でプレイグラウンドに貼り付けるのは現実的でなく、運用負荷が非常に高くなります。",["1 件ずつ手作業で"]]},"AIF-C01-107":{"0":["パブリックサブネットでインターネットに公開すると通信がインターネットを経由し、GPU を含むインフラの運用負荷も発生します。",["インターネットに公開する"]],"1":["海外のサービスにインターネット経由で接続すると、国内での処理や閉域での通信の要件を満たせません。",["インターネット経由で直接接続する"]],"2":["自社運用はデータ処理の要件は満たせても、GPU サーバーの運用を避けたいという要件に反します。",["GPU サーバーを購入し"]]},"AIF-C01-108":{"1":["自社ホスティングで常時稼働のエンドポイントを複数用意すると運用負荷とアイドル時の費用が大きく、専門家のいない小規模チームに向きません。",["常時稼働のエンドポイントを複数用意する"]],"2":["GPU インスタンスの予約と実行環境の構築は ML インフラの専門知識が必要で、変動する利用量に対しても費用の無駄が出ます。",["実行環境を自分たちで構築する"]],"3":["基盤モデルをゼロから学習するには膨大なデータとコストが必要で、1 か月で公開する小規模チームには現実的ではありません。",["ゼロから学習する"]]},"AIF-C01-109":{"0":["温度は出力のばらつきを調整するだけで、ピーク時のリクエスト数がクォータを超えるスロットリングは解消しません。",["温度を下げて応答を短くする"]],"2":["1 日中の最大量に合わせた長期契約は、利用の少ない時間帯にも費用がかかり、長期契約を避けたい要件にも反します。",["長期契約する"]],"3":["リクエストを破棄すると利用者の処理が失敗したままになります。再試行や処理能力の分散で対処すべきです。",["再送しない"]]},"AIF-C01-110":{"1":["1 回あたりは入力 0.002 USD と出力 0.002 USD の合計 0.004 USD で、10,000 回では 40 USD です。25 USD にはなりません。",["25 USD"]],"2":["1 回あたり 0.004 USD × 10,000 回 = 40 USD です。60 USD は入出力の料金の計算を誤った値です。",["60 USD"]],"3":["入力 2,000 トークンで 0.002 USD、出力 500 トークンで 0.002 USD、合計 0.004 USD × 10,000 回で 40 USD です。",["100 USD"]]},"AIF-C01-111":{"1":["Bedrock Agents は API などを呼び出して複数ステップのタスクを実行する機能で、文書の取り込みや埋め込み、格納を管理する機能ではありません。",["Amazon Bedrock Agents"]],"2":["モデル評価はモデルの回答品質を比較する機能で、S3 の文書をチャンク分割してベクトルストアに格納することはできません。",["モデル評価"]],"3":["Guardrails は不適切な入出力を制御する機能で、RAG 用のデータ取り込みや検索の仕組みは提供しません。",["Amazon Bedrock Guardrails"]]},"AIF-C01-112":{"1":["Athena は S3 上のデータに SQL でクエリを実行するサービスで、埋め込みベクトルを格納して類似検索するベクトルストアではありません。",["Amazon Athena"]],"3":["Kinesis Data Streams はストリーミングデータを取り込むサービスで、ベクトルを保存して類似検索する機能はありません。",["Kinesis Data Streams"]],"4":["Glue Data Catalog はデータのメタデータを管理するサービスで、埋め込みベクトルの保存や類似検索は行えません。",["AWS Glue Data Catalog"]]},"AIF-C01-113":{"0":["推論プロファイルはクロスリージョン推論などでリクエストの振り分け先を定義するもので、エージェントが呼び出す API を定義するものではありません。",["推論プロファイル"]],"1":["ガードレールは不適切な入出力を制御する仕組みで、API スキーマや Lambda などの実行先を定義する機能ではありません。",["ガードレール"]],"3":["モデル呼び出しログは入出力を記録する機能で、エージェントが外部処理を呼び出すための定義には使いません。",["モデル呼び出しログ"]]},"AIF-C01-114":{"1":["RAG はモデルの重みを変更せずに検索結果をプロンプトに加える手法で、質問ごとにファインチューニングすることはありません。",["ファインチューニングしてから"]],"2":["RAG は先に関連文書を検索し、その内容をもとに回答を生成します。生成後に検索して置き換える順序ではありません。",["回答を生成させた後に"]],"3":["RAG は学習データを作り直す手法ではなく、検索した情報を文脈として与えて回答を生成させる手法です。",["学習データを再作成する"]]},"AIF-C01-115":{"0":["PDF からテキストへの変換は文書の取り込み時の処理で、埋め込みモデルの役割はテキストをベクトルに変換することです。",["PDF からテキストに変換する"]],"1":["不適切な入力や出力のブロックは Guardrails の役割で、埋め込みモデルが担うものではありません。",["ブロックする"]],"3":["最終的な回答文を生成するのはテキスト生成モデルで、埋め込みモデルはテキストをベクトルに変換するだけです。",["最終的な回答文を生成する"]]},"AIF-C01-116":{"0":["ストリーミング応答は応答の体感速度を改善する機能で、料金は下がらず、大量処理のコスト削減策になりません。",["ストリーミング応答"]],"2":["1 件ずつリアルタイムで呼び出すと即時性が不要なのにバッチ推論より料金が高く、数十万件の処理では運用負荷も大きくなります。",["1 件ずつリアルタイムで呼び出す"]],"3":["月 1 回の処理のために 1 年契約で処理能力を確保すると、使わない期間も費用がかかりコストを抑えられません。",["1 年契約で購入する"]]},"AIF-C01-117":{"0":["ゼロからのモデル学習は膨大なデータとコストが必要で、再学習を避けたいという要件に真っ向から反します。",["ゼロからのモデル学習"]],"1":["継続事前学習はモデルを追加学習させる手法で、再学習を避けたい要件に合わず、マニュアルが更新されるたびに学習が必要になります。",["継続事前学習"]],"3":["Few-shot は回答の形式や傾向を示すもので、大量の社内マニュアルの最新内容を反映させることはできません。",["過去の回答例を数件示す"]]},"AIF-C01-118":{"0":["ゼロからの学習は最も手間とコストが大きい手法で、プロンプトエンジニアリングは最も手軽です。並びが誤っています。",["RAG → ゼロから学習"]],"2":["ファインチューニングは学習が必要で、RAG やプロンプトエンジニアリングより手間とコストが大きいため先頭に来ません。",["ファインチューニング → RAG"]],"3":["並びが逆です。最も手軽なのはプロンプトエンジニアリングで、ゼロからの学習が最も手間とコストが大きくなります。",["ゼロから学習 → ファインチューニング"]]},"AIF-C01-119":{"0":["パラメータ数が大きいモデルほど推論が遅くコストも高くなりがちで、応答速度を重視する簡単な分類には不向きです。",["最大のパラメータ数"]],"1":["対応言語の多さは今回の要件である応答速度や簡単な文章分類の精度とは直接関係しません。",["対応言語が最も多い"]],"2":["最大規模のモデルは簡単な分類には過剰で、レイテンシーが大きく、常時確保によりコストもかさみます。",["最大規模のモデル"]]},"AIF-C01-120":{"1":["ナレッジベースは文書を検索して回答に使う RAG の機能で、それだけでは在庫確認や注文の API を自律的に呼び出せません。",["ナレッジベースのみ"]],"2":["モデル評価はモデルの回答品質を比較する機能で、API を呼び出して複数ステップの処理を実行する仕組みではありません。",["Amazon Bedrock モデル評価"]],"3":["Comprehend はテキストを分析する自然言語処理サービスで、外部 API を順に呼び出してタスクを実行する機能はありません。",["Amazon Comprehend"]]},"AIF-C01-121":{"0":["画像生成への対応は多言語チャットボットの要件と関係がありません。確認すべきは対象言語への対応と品質です。",["画像生成に対応しているかどうか"]],"2":["提供開始日が新しくても、日本語・タイ語・ベトナム語で十分な品質が出るとは限りません。",["提供開始日が最も新しい"]],"3":["パラメータ数が大きくても、要件となる言語での回答品質が保証されるわけではなく、コストも高くなりがちです。",["パラメータ数が最も大きい"]]},"AIF-C01-122":{"0":["プロビジョンドスループットは処理能力を確保する購入方式で、分類や条件分岐を含むワークフローを組み立てる機能ではありません。",["プロビジョンドスループット"]],"2":["モデル呼び出しのロギングは入出力を記録する機能で、複数の処理をつないだワークフローを構築するものではありません。",["モデル呼び出しのロギング"]],"3":["モデル評価はモデルの回答品質を比較する機能で、ナレッジベースや Lambda をつなぐ処理の組み立てはできません。",["モデル評価"]]},"AIF-C01-123":{"0":["チャンクサイズは検索精度に関わる設定で、単一リージョンのクォータ上限によるスロットリングは解消しません。",["チャンクサイズを大きくする"]],"1":["Guardrails を無効にしても安全対策が失われるだけで、リクエスト数がクォータを超える問題は解決しません。",["Guardrails を無効にして"]],"2":["温度は出力のばらつきを調整するパラメータで、処理量を減らしてクォータの問題を解決する効果はありません。",["温度を下げて"]]},"AIF-C01-124":{"0":["埋め込みモデルを部署ごとに微調整しても検索対象の文書は絞り込めず、コストと手間が大きくなるだけです。",["部署ごとにファインチューニングする"]],"1":["温度は回答生成時のパラメータで、検索対象となる文書を制御することはできません。",["温度を 0 にして"]],"2":["最大トークン数は生成する出力の長さの上限で、どの部署の文書を検索対象にするかは制御できません。",["最大トークン数を減らして"]]},"AIF-C01-125":{"0":["ロギングは入出力を記録する機能で、繰り返し送る仕様書部分の処理時間や入力トークンのコストは削減できません。",["モデル呼び出しのロギング"]],"2":["温度を上げると出力のばらつきが増えるだけで、応答の遅さや入力トークンのコストは改善しません。",["温度の引き上げ"]],"3":["継続事前学習はモデルを追加学習させる手法で、学習コストがかかり、リクエストごとの入力コストを抑える機能ではありません。",["継続事前学習"]]},"AIF-C01-126":{"1":["バッチ推論は即時の応答が不要な大量処理向けで、翌朝に返すのでは待ち時間がかえって大幅に延びます。チャットの体感速度を改善する目的と逆行します。",["バッチ推論","翌朝にまとめて回答を返す"]],"2":["温度は出力の多様性(ランダム性)を調整するパラメータで、生成速度や最初の文字が表示されるまでの時間には影響しません。",["温度を上げて"]],"3":["チャンクサイズは RAG の検索精度に関わる設定で、長い回答の生成にかかる時間や表示の仕方は変わりません。体感的な待ち時間の短縮にはつながりません。",["チャンクサイズを小さくする"]]},"AIF-C01-127":{"0":["ファインチューニングは文体や振る舞いを学ばせるもので、コンテキストウィンドウの長さという制約は解決しません。学習データの準備や運用の手間も大きくなります。",["ファインチューニング","文体を身に付けさせる"]],"2":["10 ページずつ個別に要約すると、別の断片にある条項同士を同時に参照できず、離れた条項間の矛盾を見落としやすくなります。最優先の要件を満たせません。",["10 ページずつに分けて個別に要約"]],"3":["上位数チャンクだけをモデルに渡すと文書全体を同時に見られず、検索されなかった離れた条項との対応関係を見落とします。全体の矛盾を指摘する用途には不向きです。",["上位数チャンクだけを検索"]]},"AIF-C01-128":{"0":["原因はチャンクに無関係な条文が混ざる検索側の問題で、生成モデルを大きくしてもコストが増えるだけで検索品質は改善しません。",["より大きなモデルに変更"]],"1":["取得するチャンク数を増やすと、無関係な条文を含むチャンクもさらに多くモデルに渡り、回答への混入が悪化します。トークン消費によるコストも増えます。",["チャンク数を大幅に増やし"]],"3":["ファインチューニングは学習データの準備とコストが大きく、規程が更新されるたびに再学習が必要です。追加のコストと運用負荷を最小限にする要件に反します。",["ファインチューニング","RAG の利用をやめる"]]},"AIF-C01-129":{"1":["温度は生成時の語の選び方のランダム性を調整するもので、検索結果に古いチャンクが表示されている問題は解決できません。",["温度を 0 に下げる"]],"2":["検索結果自体が古いチャンクを返しているため、原因はベクトルストア側にあります。生成モデルの知識のカットオフを新しくしても社内規程の内容は反映されません。",["知識のカットオフが古い"]],"3":["Guardrails は入出力の有害な内容などをフィルタリングする機能で、ナレッジベースの検索結果に古いチャンクが出る原因にはなりません。削除すると安全対策を失うだけです。",["Guardrails を削除する"]]},"AIF-C01-130":{"0":["システムプロンプトに固定で埋め込むと、毎日の料金や空き状況の更新のたびに手作業での書き換えが必要です。根拠資料を引用として示す仕組みもありません。",["システムプロンプトに固定で埋め込む"]],"1":["毎日のファインチューニングは高コストで、再学習する余裕がないという条件に反します。学習済みのモデルは回答の根拠となった資料を出典として示せません。",["毎日の料金表でファインチューニング"]],"3":["過去 1 年分を毎回すべて入力すると入力トークンが膨大になり、コストと遅延が大きくなります。古い料金も混ざり、最新の情報を正しく示しにくくなります。",["過去 1 年分の料金表を毎回すべて入力"]]},"AIF-C01-131":{"0":["最大トークン数を一律に 50 に制限すると、複雑な推論が必要な問い合わせの回答が途中で打ち切られ、品質が下がります。",["一律に 50 に制限"]],"1":["プロビジョンドスループットは一定のスループットを確保する購入形態で、簡単な質問まで大規模モデルで処理する構成は変わらず、コスト削減につながりません。",["大規模モデルのみで処理を続ける"]],"2":["すべてを最小のモデルにすると、約 2 割を占める複雑な推論が必要な問い合わせの品質が下がり、品質を保つ要件を満たせません。",["すべての問い合わせを最小のモデル"]]},"AIF-C01-132":{"0":["ファインチューニングは学習データでモデルの重みを更新する手法で、プロンプト内に例を示すだけの方法とは異なります。",["ファインチューニング"]],"1":["ゼロショットは例を一切示さず指示だけでタスクを行わせる手法です。入力と出力の例を示している今回の手法には当たりません。",["ゼロショットプロンプト"]],"2":["プロンプトインジェクションは、入力に指示を埋め込んでモデルの本来の指示を上書きさせる攻撃で、プロンプト設計の手法ではありません。",["プロンプトインジェクション"]]},"AIF-C01-133":{"0":["ゼロショット分類は例を示さずに入力をカテゴリに分類させる使い方で、推論過程を段階的に出力させる手法ではありません。",["ゼロショット分類"]],"1":["ネガティブプロンプトは主に画像生成で含めたくない要素を指定する手法で、推論の途中過程を書かせるものではありません。",["ネガティブプロンプト"]],"2":["プロンプトキャッシュは繰り返し使うプロンプトの共通部分を再利用して、コストと遅延を下げる機能です。推論の正答率を高める手法ではありません。",["プロンプトキャッシュ"]]},"AIF-C01-134":{"1":["Chain-of-Thought は段階的に推論過程を書かせる手法です。指示だけで分類させる今回の方法とは目的が異なります。",["Chain-of-Thought プロンプティング"]],"2":["ファインチューニングは学習データでモデルを追加学習させる手法で、プロンプトで指示を与えるだけの方法ではありません。",["ファインチューニング"]],"3":["Few-shot はプロンプト内に入出力の例を示す手法です。例を一切示さない今回の条件に当てはまりません。",["Few-shot プロンプティング"]]},"AIF-C01-135":{"0":["VPC、サブネット、セキュリティグループは AWS のネットワーク構成要素で、プロンプトを構成する要素ではありません。",["VPC、サブネット、セキュリティグループ"]],"1":["学習率、エポック数、バッチサイズはモデルをトレーニングするときのハイパーパラメータで、プロンプトの構成要素ではありません。",["学習率、エポック数、バッチサイズ"]],"2":["再現率、適合率、F1 スコアは分類モデルの性能を測る評価指標で、プロンプトに含める要素ではありません。",["再現率、適合率、F1 スコア"]]},"AIF-C01-136":{"0":["Top P は推論時に次のトークンの候補を絞るパラメータで、学習に使うデータの割合とは無関係です。",["学習に使うデータの割合"]],"1":["出力の最大トークン数を指定するのは最大トークン数(最大長)のパラメータで、Top P ではありません。",["最大トークン数を指定する"]],"2":["指定した文字列で生成を止めるのは停止シーケンスの役割で、Top P は候補トークンの範囲を累積確率で絞るものです。",["生成を停止する"]]},"AIF-C01-137":{"1":["Few-shot は文章の例を示して出力形式やパターンを伝えるテキスト向けの手法で、画像から特定の要素を除外する方法ではありません。",["Few-shot で文章の例を示す"]],"2":["最大トークン数はテキスト出力の長さの上限を決めるパラメータで、生成画像に人物や文字が含まれるかどうかは制御できません。",["最大トークン数を小さくする"]],"3":["停止シーケンスはテキスト生成を指定文字列で止める仕組みで、画像生成で特定の要素を描かせないようにすることはできません。",["停止シーケンス"]]},"AIF-C01-138":{"0":["丁寧語の指定は文体に影響するだけで、出力が文の途中で打ち切られる原因にはなりません。",["丁寧語を指定"]],"1":["Top P は候補トークンの範囲を決めるランダム性のパラメータで、出力の長さの上限とは関係がなく、文章が途中で切れる原因ではありません。",["Top P が大きく"]],"2":["温度は語の選び方のランダム性を調整するもので、低くしても出力が途中で打ち切られることはありません。",["温度が低く"]]},"AIF-C01-139":{"0":["SQL インジェクションはデータベースへの問い合わせ文に不正な SQL を混入させる攻撃で、モデルへの指示を上書きさせる攻撃ではありません。",["SQL インジェクション"]],"1":["データポイズニングは学習データに不正なデータを混ぜてモデルの挙動をゆがめる攻撃で、推論時の入力で指示を回避する今回の攻撃とは異なります。",["データポイズニング"]],"3":["モデル反転攻撃はモデルの出力から学習データの内容を推測・復元する攻撃で、システムプロンプトの表示を狙う指示の上書きとは異なります。",["モデル反転攻撃"]]},"AIF-C01-140":{"0":["ユーザーに毎回入力してもらう方法は手間がかかるうえ、入力漏れや改変で制約が守られない恐れがあり、一貫して役割と制約を与えられません。",["ユーザーに毎回その指示を入力してもらう"]],"1":["最大トークン数は出力を途中で打ち切るだけで、3 文以内にまとめさせたり社外秘情報を出さないといった制約は与えられません。",["最大トークン数を小さくして"]],"2":["ファインチューニングは学習データの準備とコストが大きく、制約を変えるたびに再学習が必要です。役割と制約の付与ならシステムプロンプトで手軽に実現できます。",["ファインチューニング"]]},"AIF-C01-141":{"0":["「自由に要約」とだけ指示すると出力形式もキー名も定まらず、後続のプログラムで処理できる JSON が得られません。",["自由に要約してください"]],"1":["温度を最大にすると出力のばらつきが増え、形式が毎回変わりやすくなります。プログラムで処理するには一貫した形式が必要です。",["温度を最大にして多様な形式"]],"2":["入力メールを繰り返し入れてもトークン消費が増えるだけで、出力のキー名や JSON 形式は指定されず、抽出の一貫性は向上しません。",["複数回繰り返してプロンプトに入れる"]]},"AIF-C01-142":{"0":["質問を英語に翻訳しても、説明の対象者や言葉のやさしさは指定されません。新入社員向けの日本語の解説ボットとしてはむしろ不便になります。",["英語に翻訳してから入力する"]],"2":["最大トークン数を 10 にすると回答がほぼ必ず途中で打ち切られ、やさしい説明どころか説明そのものが成り立ちません。",["最大トークン数を 10 に設定する"]],"3":["停止シーケンスに「。」を指定すると最初の文で生成が止まり、説明が不完全になります。言葉のやさしさも制御できません。",["停止シーケンスに「。」を指定する"]]},"AIF-C01-143":{"0":["ユーザーの文章を指示部分に直接連結すると、文章内の指示のような文をモデルが本来の指示と取り違えやすくなり、プロンプトインジェクションを受けやすくなります。",["システムプロンプトの指示部分に直接連結する"]],"1":["温度は出力のランダム性を調整するもので、指示とデータを区別させる効果はありません。上げると要約の品質が不安定になります。",["温度を上げて"]],"2":["Few-shot の例を削除しても、入力データ内の文を指示と取り違えるリスクは下がりません。指示とデータを明確に区切る仕組みが必要です。",["Few-shot の例を削除する"]]},"AIF-C01-144":{"0":["バッチ推論は大量のプロンプトを非同期でまとめて処理する機能で、プロンプトの改善履歴やバージョンを管理する機能ではありません。",["バッチ推論"]],"1":["継続事前学習はラベルなしのデータでモデルを追加学習する手法で、プロンプトのバージョン管理やアプリからの呼び出しには関係しません。",["継続事前学習"]],"3":["プロビジョンドスループットはモデルの処理能力を確保する購入形態で、プロンプトを保存・バージョン管理する機能ではありません。",["プロビジョンドスループット"]]},"AIF-C01-145":{"0":["指示を省略してゼロショットにすると、モデルが何をすべきかがさらに曖昧になり、複数タスクの品質はより不安定になります。",["指示を省略してゼロショットにする"]],"2":["温度を上げると出力のランダム性が増し、品質のばらつきが大きくなります。品質を安定させたい目的と逆効果です。",["温度を上げて"]],"3":["指示を 1 文にまとめても 3 つのタスクを一度に行わせる構造は変わらず、指示が曖昧になって品質はかえって下がりやすくなります。",["1 文にまとめて短くする"]]},"AIF-C01-146":{"0":["想像力を働かせるよう促すと、資料にない内容を推測で補う回答がかえって増え、ハルシネーションを助長します。",["想像力を働かせて"]],"2":["1,000 文字以上という過度な長さを求めると、資料に記載がない内容まで埋め合わせで書かせることになり、推測が増えます。",["必ず 1,000 文字以上"]],"3":["一般的な知識での補完を促すと、約款に書かれていない内容が回答に混ざります。資料に基づかない推測を減らす目的と逆です。",["一般的な知識も積極的に補って"]]},"AIF-C01-147":{"0":["温度は語の選択のランダム性を調整するもので、上げても生成を止める効果はなく、架空の質問の生成は防げません。",["温度を上げる"]],"1":["埋め込みモデルは検索用にテキストをベクトル化するモデルで、生成モデルが不要な続きを出力する問題には関係しません。",["埋め込みモデルを変更する"]],"2":["Top P を 1 にすると候補トークンが絞られなくなるだけで、指定した位置で生成を止める機能はありません。",["Top P を 1 に設定する"]]},"AIF-C01-148":{"0":["両方で温度を 0 にすると Q&A は安定しますが、キャッチコピーも多様性が下がり、似た案ばかり出る不満がかえって強まります。",["両方の用途で温度を 0 にする"]],"2":["最大トークン数は出力の長さの上限で、回答のばらつきや案の多様性は変わりません。両方の問題とも解決しません。",["最大トークン数だけを両方で増やす"]],"3":["両方で温度を最大にするとキャッチコピーの多様性は増えますが、Q&A の回答が毎回変わる問題はさらに悪化します。",["両方の用途で温度を最大にする"]]},"AIF-C01-149":{"1":["停止シーケンスに「緊急」を指定すると、その語が出た時点で生成が止まるだけで、分類の偏りは直りません。出力が不完全になる恐れもあります。",["停止シーケンスに「緊急」を指定する"]],"2":["「緊急」の例だけを増やすと偏りがさらに強まり、通常の問い合わせまで「緊急」と分類される傾向が悪化します。",["50 件の「緊急」の例に増やす"]],"3":["例を削除して温度を最大にすると、判断の手がかりを失ったうえに出力のランダム性が増し、分類はかえって不安定になります。",["温度を最大にする"]]},"AIF-C01-150":{"0":["温度を最大にしても出力が不安定になるだけで、ロールプレイを装った禁止内容の要求を検出・拒否する防御にはなりません。",["温度を最大にして"]],"3":["最大トークン数を増やすと出力の上限が延びるだけで、ジェイルブレイクを防ぐ効果はなく、禁止内容がより詳しく出力される恐れがあります。",["最大トークン数を増やして"]],"4":["Few-shot の例を削除しても、ロールプレイを装った攻撃入力を検出・拒否する仕組みにはならず、防御は強化されません。",["Few-shot の例をすべて削除する"]]},"AIF-C01-151":{"1":["ラベルのない業界文書は継続事前学習で使うデータです。ファインチューニングにはプロンプトと期待する応答の組が必要で、PDF のままでは使えません。",["ラベルのない業界文書","PDF ファイル"]],"2":["CloudWatch Logs のモデル呼び出しログは監視・監査用の記録で、ファインチューニングの学習データとしてそのまま指定することはできません。学習データは S3 の JSONL で用意します。",["CloudWatch Logs に保存したもの"]],"3":["ベクトルストアの埋め込みベクトルは RAG の検索に使うもので、モデルの重みを更新するファインチューニングの学習データではありません。",["埋め込みベクトル"]]},"AIF-C01-152":{"1":["Top P は推論時に次のトークンの候補を累積確率で絞るパラメータで、学習の繰り返し回数とは関係ありません。",["Top P"]],"2":["学習率は 1 回の更新で重みをどれだけ変えるかを決めるハイパーパラメータで、学習データ全体を何周するかではありません。",["学習率"]],"3":["温度は推論時の出力のランダム性を調整するパラメータで、トレーニングの繰り返し回数を指定するものではありません。",["温度"]]},"AIF-C01-153":{"0":["クラスタリングはラベルなしのデータを似たもの同士のグループに分ける教師なし学習で、事前学習済みの知識を別タスクに再利用する考え方ではありません。",["クラスタリング"]],"2":["次元削減は特徴量の数を減らしてデータを扱いやすくする手法で、学習済みモデルの知識を新しいタスクに適応させるものではありません。",["次元削減"]],"3":["強化学習は環境との試行錯誤で報酬を最大化する行動を学ぶ手法で、事前学習済みモデルを少量データで別タスクに適応させる考え方とは異なります。",["強化学習"]]},"AIF-C01-154":{"1":["RAG は外部の資料を検索してプロンプトに加え回答させる手法で、人間の順位付けをもとにモデルの応答を調整するものではありません。",["検索拡張生成（RAG）"]],"2":["主成分分析はデータの次元を削減する統計的な手法で、人間の好みに合わせてモデルの応答を調整する手法ではありません。",["主成分分析"]],"3":["継続事前学習はラベルのないデータで知識を追加する手法で、人間による出力の順位付けを使って応答を好ましい方向に調整するものではありません。",["継続事前学習"]]},"AIF-C01-155":{"0":["RAG は外部の資料を検索して回答に使う手法で、モデルの重み自体は変わらないため、文体や専門用語の使い方をモデルに身に付けさせることはできません。",["RAG"]],"1":["Few-shot はプロンプト内に少数の例を示すだけで、モデル自体は変わりません。数千件のラベル付きデータを活かしてモデルに定着させる方法ではありません。",["Few-shot プロンプト"]],"2":["温度は出力のランダム性を調整する推論パラメータで、専門用語や独特の文体を学習させる効果はありません。",["温度の調整"]]},"AIF-C01-156":{"0":["指示チューニングは指示と応答のラベル付きペアで指示に従う能力を高める手法で、ラベルのない大量文書で業界知識を強化する目的には合いません。",["指示チューニングのみ"]],"1":["ガードレールは入出力の有害な内容などを制御する安全対策で、モデルの業界知識そのものを強化する機能ではありません。",["ガードレールの設定"]],"3":["Few-shot はプロンプトに例を示すだけでモデルの重みは変わらず、大量の業界ドキュメントの知識をモデル自体に取り込むことはできません。",["Few-shot プロンプト"]]},"AIF-C01-157":{"0":["プロンプトキャッシュはプロンプトの共通部分を再利用してコストと遅延を下げる機能で、指示に従う能力を学習させる手法ではありません。",["プロンプトキャッシュ"]],"1":["データポイズニングは学習データに不正なデータを混ぜてモデルをゆがめる攻撃で、指示に従えるようにする学習手法ではありません。",["データポイズニング"]],"2":["量子化は重みの数値精度を下げてモデルを軽量化・高速化する手法で、指示に従って応答する能力を身に付けさせるものではありません。",["量子化"]]},"AIF-C01-158":{"0":["モデル呼び出しのロギングは入出力を記録して監視・監査に使う機能で、大型モデルの応答で小型モデルを学習させる機能ではありません。",["モデル呼び出しのロギング"]],"2":["ナレッジベースは RAG のために資料を検索する機能で、モデル自体を学習させて小型化・低コスト化するものではありません。",["ナレッジベース"]],"3":["Guardrails は有害な入出力などをフィルタリングする安全対策の機能で、小型モデルを学習させてレイテンシーやコストを下げる機能ではありません。",["Guardrails"]]},"AIF-C01-159":{"1":["最大トークン数は推論時に出力の長さの上限を決める設定で、トレーニング中の損失の振動には影響しません。",["最大トークン数が小さすぎる"]],"2":["温度は推論時の出力のランダム性を調整するパラメータで、学習中の重みの更新や損失の安定性には関係しません。",["温度が低すぎる"]],"3":["停止シーケンスは推論時に生成を止める文字列の設定で、トレーニングの損失が上下する原因にはなりません。",["停止シーケンスが多すぎる"]]},"AIF-C01-160":{"1":["検証損失が上がっているのは学習不足ではなく過学習の兆候です。エポック数を増やすと学習データへの過適合がさらに進み、汎化性能が悪化します。",["学習不足と判断し","エポック数をさらに増やす"]],"2":["温度は推論時の出力のランダム性の設定で、学習で生じた過学習そのものは解消されません。",["推論時の温度を下げる"]],"4":["検証データを使わないと過学習を検知できなくなり、汎化性能の低いモデルになっても気付けません。問題を見えなくするだけです。",["検証データを使わずに学習を続ける"]]},"AIF-C01-161":{"0":["モデルは学習データの傾向をそのまま学ぶため、不適切な応対だけを学習させると不適切な応答を再現するモデルになり、品質向上と逆行します。",["不適切な応対だけを集めて"]],"1":["データの品質が結果を大きく左右し、誤りを含むデータのままエポック数を増やすと、誤った案内をより強く学習してしまいます。",["データの準備は不要","エポック数を増やせば"]],"2":["件数が多くても誤った案内や不適切な言葉遣いを含めると、モデルはその誤りも再現するようになります。量より質の確保が必要です。",["すべての記録をそのまま使う"]]},"AIF-C01-162":{"1":["温度は出力のランダム性を調整するだけで、独特の文体を身に付けさせることも、毎週更新される事実情報を反映することもできません。",["温度の調整で制御する"]],"2":["継続事前学習で毎週更新される事実を反映するには再学習が必要で、手間とコストが大きくなります。プロンプトキャッシュは再利用による高速化の機能で、文体は制御できません。",["継続事前学習で反映","プロンプトキャッシュで制御"]],"3":["毎週ファインチューニングし直すのは手間とコストが大きく、更新のたびに遅れも生じます。頻繁に変わる事実情報は RAG で参照する方が適しています。",["毎週のファインチューニング"]]},"AIF-C01-163":{"0":["プロンプトインジェクションは入力で指示を上書きさせる攻撃で、学習の偏りで汎用的な能力が失われた今回の現象とは無関係です。Guardrails では回復しません。",["プロンプトインジェクション"]],"1":["データドリフトは本番の入力データの傾向が学習時から変化する現象で、今回は過度な学習による能力低下です。エンドポイントの再起動でも直りません。",["データドリフト","エンドポイントを再起動"]],"2":["ハルシネーションは事実と異なる内容をもっともらしく生成する現象で、汎用タスク全般の品質低下とは異なります。温度を下げても失われた能力は戻りません。",["ハルシネーション","温度を下げる"]]},"AIF-C01-164":{"0":["基盤モデルをゼロから事前学習するには膨大なデータと計算資源が必要で、初期費用と手間を最小限にする要件に大きく反します。回答の根拠も示せません。",["ゼロから事前学習する"]],"1":["毎月の継続事前学習は学習コストと運用の手間が大きく、学習したモデルは回答の根拠となった資料を示せません。",["毎月","継続事前学習"]],"2":["数万件の質問と回答のペアを作る準備に大きな手間がかかり、マニュアル更新のたびに再学習も必要です。回答の根拠を示すこともできません。",["数万件作成してファインチューニング"]]},"AIF-C01-165":{"0":["ナレッジベースの同期は RAG の検索データを更新する操作で、カスタムモデルの学習結果が本番で反映されない問題とは関係ありません。",["ナレッジベースの同期"]],"2":["Bedrock のカスタムモデルは推論に使用できます(プロビジョンドスループットなどで呼び出します)。推論に使えないという仕様はありません。",["推論に使えない仕様"]],"3":["Bedrock ではカスタマイズに使ったデータがベースモデルの学習に使われることはありません。仮にそうでも本番で効果が出ない原因の説明になりません。",["ベースモデルの学習に使われた"]]},"AIF-C01-166":{"0":["少数回の自由な試行と印象による順位付けは主観に左右され、条件もそろわないため、モデルを公平に比較できません。",["印象で順位を付ける"]],"2":["パラメータ数が多くても特定のタスクで性能が高いとは限りません。実際の性能を同じ条件で測らずに判断するのは不適切です。",["パラメータ数が最も多いモデル"]],"3":["提供元ごとに評価条件やデータセットが異なるため、公表値をそのまま並べても同じ条件での比較になりません。",["公表している性能値を、そのまま並べて"]]},"AIF-C01-167":{"0":["レイテンシーは応答にかかる時間を表す性能指標で、翻訳出力と参照訳の一致度を測るものではありません。",["レイテンシー"]],"2":["RMSE は回帰モデルの予測値と実測値の誤差を測る指標で、翻訳文の n-gram の重なりは評価できません。",["RMSE"]],"3":["AUC は分類モデルの識別性能を評価する指標で、翻訳出力と参照訳の一致度の評価には使いません。",["AUC"]]},"AIF-C01-168":{"1":["正解率は分類の予測が正解ラベルと一致した割合で、生成文の意味的な近さを埋め込みで測る指標ではありません。",["正解率（Accuracy）"]],"2":["スループットは単位時間あたりの処理量を表す性能指標で、生成文と参照文の意味的な類似度は評価できません。",["スループット"]],"3":["平均絶対誤差は回帰モデルの数値予測の誤差を測る指標で、文章の意味の近さを評価するものではありません。",["平均絶対誤差（MAE）"]]},"AIF-C01-169":{"1":["バッチ推論は大量のプロンプトを非同期でまとめて処理する機能で、正確性や毒性などの指標でモデルを比較評価する機能ではありません。",["バッチ推論"]],"2":["Agents は API 呼び出しなどを組み合わせて複数ステップのタスクを実行する機能で、モデルを指標で比較評価するものではありません。",["Agents"]],"3":["Prompt Management はプロンプトを作成・保存・バージョン管理する機能で、複数モデルを正確性や毒性で比較評価する機能ではありません。",["Prompt Management"]]},"AIF-C01-170":{"1":["AUC は分類モデルの識別性能を評価する指標で、生成された要約と人が書いた要約の一致度は測れません。",["AUC"]],"2":["分類用の F1 スコアは予測ラベルの正誤を評価する指標で、要約文と参照文の語句の重なりを測るものではありません。",["F1 スコア（分類用）のみ"]],"3":["平均絶対誤差は回帰の数値予測の誤差を測る指標で、要約文の一致度の評価には使えません。",["平均絶対誤差 (MAE)"]]},"AIF-C01-171":{"0":["学習損失はトレーニング中のモデルの誤差を示すもので、回答のトーンやブランドイメージへの適合といった主観的な品質は分かりません。",["学習損失の確認"]],"2":["精度の自動計算は正解が明確なタスク向けで、丁寧さやブランドイメージとの適合のような主観的な品質は評価できません。",["精度 (Accuracy) の自動計算のみ"]],"3":["推論レイテンシーは応答速度を測るだけで、回答が丁寧でブランドに合っているかという内容の品質は評価できません。",["推論レイテンシーの測定"]]},"AIF-C01-172":{"0":["パラメータ数が多くても自社の保険商品に関する回答品質が高いとは限りません。業務での品質を実際に測らずに選ぶのは不適切です。",["パラメータ数が最も多いモデル"]],"1":["料金の高さは業務での回答品質を保証しません。コストだけが増え、自社の質問に適したモデルかは分かりません。",["料金が最も高いモデル"]],"3":["一般的なベンチマークは業務固有の性能を反映しないことがあり、結果が似通っている以上それだけでは判断できません。自社の質問での評価が必要です。",["一般的なベンチマークのスコアだけで判断"]]},"AIF-C01-173":{"0":["評価をせずに本番の苦情を待つと、誤った回答や有害な内容が利用者に届いてから問題に気付くことになり、品質管理として不適切です。",["評価は行わず"]],"1":["文字数は回答の長さを示すだけで、質問に正しく答えているかや有害な内容がないかといった内容の妥当性は評価できません。",["回答の文字数だけを集計"]],"3":["レイテンシーは応答速度の指標で、回答の正しさや有害性といった内容の妥当性は評価できません。",["レイテンシーだけを測定"]]},"AIF-C01-174":{"0":["BLEU は参照文との語句の一致を測るだけで、品質低下の原因が検索と生成のどちらにあるかを切り分けられません。",["BLEU スコアだけを測定する"]],"2":["埋め込みの次元数を最大にしても品質が上がる保証はなく、原因を特定する前に設定を変えるのは切り分けの手順として不適切です。",["埋め込みの次元数を最大にして"]],"3":["ストレージ使用量はコストや容量の管理指標で、検索結果の関連性や回答の忠実性といった品質の原因は分かりません。",["ストレージ使用量だけを確認する"]]},"AIF-C01-175":{"0":["パープレキシティは言語モデルが文章をどれだけうまく予測できるかを示す指標で、正解ラベルに対する分類の性能は評価できません。",["パープレキシティ"]],"1":["ROUGE は生成文と参照文の語句の重なりを測る要約向けの指標で、決まったラベルへの分類の正誤を評価する指標ではありません。",["ROUGE"]],"2":["BLEU は翻訳文と参照訳の n-gram の一致度を測る指標で、3 種類のラベルへの分類性能の評価には適しません。",["BLEU"]]},"AIF-C01-176":{"1":["API 呼び出し回数は利用量を示すだけで、商品説明文が売上やコンバージョンに貢献したかは分かりません。",["API 呼び出し回数だけを報告する"]],"2":["ROUGE は参照文との語句の重なりを測る技術指標で、売上への貢献というビジネス上の効果を直接示しません。",["ROUGE スコアだけを報告する"]],"3":["パラメータ数はモデルの規模を表すだけで、導入による売上への貢献は何も示しません。",["パラメータ数を報告する"]]},"AIF-C01-177":{"0":["評価データが 3 件では偶然の影響が大きく、医学的な正確さについて信頼できる結論は出せません。",["評価データを 3 件に絞り"]],"2":["医学的な正確さの判定には専門知識が必要で、専門分野を問わず安価に集めた評価者では信頼できる結果になりません。",["専門分野は問わず"]],"4":["モデル名を伝えると評価者の先入観が入り、回答の内容ではなく好みで評価が左右されるため、信頼性が下がります。",["モデル名を伝え","好みのモデルを選んでもらう"]]},"AIF-C01-178":{"0":["指標に限界があるなら複数の評価を組み合わせればよく、評価をやめて料金だけで選ぶと、事実の取り違えのある品質の低いモデルを採用する恐れがあります。",["評価をやめて料金の安い方を採用する"]],"1":["ROUGE は語句の重なりを測るだけで、モデル P の事実の取り違えや読みにくさを反映していません。利用者の評価を無視するのは不適切です。",["アンケート結果は無視する"]],"2":["温度を上げると出力のランダム性が増すだけで、事実の取り違えはむしろ増えやすく、両方の評価が改善する根拠はありません。",["温度を上げれば"]]},"AIF-C01-179":{"0":["品質低下のたびにベースモデルをゼロから学習し直すのは膨大なコストと時間がかかり、早期検知の仕組みにもなりません。",["ゼロから学習し直す"]],"2":["導入前の評価では、その後の制度改定や新しい質問による品質の変化を捉えられず、低下に気付けません。",["追加の評価は行わない"]],"3":["毎日全回答を全社員で人手チェックするのは運用負荷が非常に大きく、運用負荷を抑える要件に反します。",["全社員で人手チェックする"]]},"AIF-C01-180":{"0":["条件がそろっていない評価からは、どちらが優れているかを判断できません。根拠なくモデル Y を優れていると判断するのも誤りです。",["モデル Y の方が本来は優れている"]],"1":["条件の異なる評価結果を平均しても公平な比較にはならず、両方を同じ割合で使う判断の根拠になりません。",["評価結果をすべて平均し"]],"3":["モデル X の好結果はプロンプト条件の差による可能性があり、モデルの性能差とは言えません。条件をそろえずに採用するのは不適切です。",["そのまま採用する"]]},"AIF-C01-181":{"1":["制御可能性は AI システムの動作を人が監視・調整できるかという観点で、特定の性別を不当に低く評価する問題の中心ではありません。",["制御可能性"]],"2":["プライバシーとセキュリティは個人情報の保護や不正アクセスへの対策に関する観点で、属性による不当な扱いの差は公平性の課題です。",["プライバシーとセキュリティ"]],"3":["堅牢性はノイズや想定外の入力に対しても安定して動作する性質で、特定の性別に不利な評価が出る偏りの問題とは異なります。",["堅牢性"]]},"AIF-C01-182":{"0":["利用料金の予算超過はコスト管理上の問題で、法的な権利侵害のリスクではありません。予算アラートなどで管理する事柄です。",["利用料金が予算を超える"]],"2":["出力が毎回異なるのは生成 AI の非決定的な性質による品質上の特性で、それ自体が法的なリスクではありません。",["出力が毎回異なる"]],"3":["レイテンシーの超過は性能やサービスレベルの問題で、生成物が他者の著作物を侵害するような法的リスクとは性質が異なります。",["レイテンシー"]]},"AIF-C01-183":{"0":["透明性は AI の仕組みや利用していることを関係者に明らかにする観点で、想定外の入力に対しても安定して動作する性質ではありません。",["透明性"]],"2":["説明可能性はモデルの判断理由を人が理解できるようにする観点で、表記ゆれやノイズに対する安定性を表すものではありません。",["説明可能性"]],"3":["プライバシーは個人情報を適切に保護する観点で、想定外の入力があっても安定した結果を返す性質とは異なります。",["プライバシー"]]},"AIF-C01-184":{"0":["過学習は学習データに過度に適合して未知のデータへの汎化性能が下がる現象で、差別的・攻撃的な出力のリスクを指す言葉ではありません。",["過学習"]],"1":["データドリフトは本番データの分布が学習時から変化する現象で、攻撃的な表現を生成するリスクとは異なります。",["データドリフト"]],"3":["レイテンシーは応答にかかる時間を表す性能指標で、出力内容の有害さとは関係ありません。",["レイテンシー"]]},"AIF-C01-185":{"0":["推論インスタンスの性能は処理速度に関わるもので、生成される人物の性別や人種の偏りの原因にはなりません。",["推論インスタンスの性能が不足"]],"1":["解像度は画像の細かさに関する設定で、どのような属性の人物が描かれるかという偏りには影響しません。",["解像度が低すぎる"]],"3":["最大トークン数はテキスト出力の長さの上限で、生成画像に描かれる人物の属性の偏りとは無関係です。",["最大トークン数の設定が小さすぎる"]]},"AIF-C01-186":{"0":["常に最大規模のモデルを使い何度も再学習すると、計算資源と消費電力が大きく増え、環境負荷を減らす目的と逆行します。",["常に最大規模のモデル","何度も再学習する"]],"1":["使わないエンドポイントを常時起動すると、無駄な電力とコストを消費し続けるため、環境負荷が高まります。",["使わない推論エンドポイントも常に起動"]],"2":["要件に関係なく最高性能の GPU で処理すると過剰なリソースを消費し、消費電力とコストが増えて環境負荷が高まります。",["最高性能の GPU インスタンス"]]},"AIF-C01-187":{"1":["SageMaker Neo はモデルを特定のハードウェア向けに最適化・コンパイルして推論を高速化する機能で、バイアス検出や予測の説明はできません。",["SageMaker Neo"]],"2":["Model Monitor 単体ではデータ品質やドリフトの監視が中心です。バイアスの検出や特徴量の影響の説明は Clarify の機能で、それだけでは要件を満たせません。",["Model Monitor のみ"]],"3":["Ground Truth は学習データのラベル付けを行う機能で、データやモデル予測のバイアス検出や特徴量の影響の説明は行いません。",["SageMaker Ground Truth"]]},"AIF-C01-188":{"0":["ナレッジベースは RAG のために資料を検索してモデルに渡す機能で、暴力的な表現や特定の話題への回答を拒否する制御はできません。",["ナレッジベース"]],"2":["プロビジョンドスループットはモデルの処理能力を確保する購入形態で、入出力の内容を制御する機能ではありません。",["プロビジョンドスループット"]],"3":["モデル評価は導入前などにモデルの品質を測る機能で、本番の入出力をリアルタイムでフィルタリング・拒否する仕組みではありません。",["モデル評価"]]},"AIF-C01-189":{"0":["すべてをモデルだけで自動決定すると、誤った却下を人が確認して防ぐ機会がなくなり、申請者に重大な不利益を与える恐れがあります。",["モデルだけで自動的に決定する"]],"2":["却下理由を説明しないと申請者が判断の誤りに気付けず、異議申し立てなど救済の機会を失います。透明性の観点から不適切です。",["理由の説明は行わない"]],"3":["職員が異を唱えられないとモデルの誤りを正す手段がなくなり、人間による監督という責任ある AI の原則に反します。",["異を唱えられないようにする"]]},"AIF-C01-190":{"0":["不均衡なデータでは、すべてを「正常」と予測しても正解率は 99% と高く見えるため、正解率だけで評価すると問題を見逃します。",["正解率だけでモデルを評価する"]],"3":["温度は生成モデルの出力のランダム性を調整する推論時の設定で、分類モデルのクラス不均衡というデータ面の問題は解決しません。",["推論時の温度を上げる"]],"4":["多数派である正常品のデータをさらに増やすと不均衡が強まり、モデルはますます「正常」と予測しやすくなります。",["正常品のデータをさらに増やす"]]},"AIF-C01-191":{"1":["最大トークン数は推論時の出力長の上限で、ラベル付けの偏りから生じた分類の不公平さには影響しません。",["最大トークン数を減らす"]],"2":["方言やスラングの投稿を除外すると、モデルはそれらの表現を学べず、正しく扱えないまま偏りが残ります。",["すべて学習データから削除する"]],"3":["1 人だけに任せると判断は統一されても、その人の偏りがそのままデータに入り込み、偏りはむしろ強まる恐れがあります。",["1 人だけに任せて"]]},"AIF-C01-192":{"0":["バッチ推論は大量のリクエストを非同期でまとめて処理する機能で、回答が参照資料に基づいているかを確認する機能はありません。",["バッチ推論"]],"1":["プロビジョンドスループットは処理能力を確保する購入形態で、根拠の乏しい回答を検出・ブロックする機能ではありません。",["プロビジョンドスループット"]],"3":["クロスリージョン推論は複数リージョンに推論リクエストを分散してスループットを高める機能で、回答の根拠性は確認できません。",["クロスリージョン推論"]]},"AIF-C01-193":{"1":["苦情を待つ方法では、子どもに有害な出力が届いてから問題に気付くことになり、導入前に確認したいという要件に反します。",["苦情が来るまで待つ"]],"2":["料金表の比較ではコストは分かっても、有害な出力の生じやすさや回答の安定性は確認できません。",["料金表を比較する"]],"3":["パラメータ数はモデルの規模を示すだけで、毒性や入力の変化に対する堅牢性を示すものではありません。",["パラメータ数を比較する"]]},"AIF-C01-194":{"1":["プロンプトキャッシュは Bedrock でプロンプトの共通部分を再利用してコストと遅延を下げる機能で、与信モデルのバイアスの監視とは無関係です。",["プロンプトキャッシュ"]],"2":["インスタンスサイズを大きくしても処理能力が上がるだけで、特定の年齢層に不利な予測が増えていないかは監視できません。",["インスタンスサイズを大きくする"]],"3":["導入時の評価結果をそのまま報告しても、利用者層の変化による運用中のバイアスの変化には気付けません。",["導入時の評価結果を毎月そのまま報告"]]},"AIF-C01-195":{"0":["画像の合計ファイルサイズはデータ量を示すだけで、特定のグループで誤認識が集中していないかという公平性は分かりません。",["合計ファイルサイズ"]],"2":["応答時間は性能の指標で、年齢層や肌の色などのグループ間で精度に差がないかという公平性の確認にはなりません。",["応答時間を測定する"]],"3":["全体の精度を細かく計算しても、特定のグループで誤りが集中しているかどうかは見えません。グループ別の比較が必要です。",["小数点以下まで細かく計算する"]]},"AIF-C01-196":{"0":["基盤モデルによる再確認も誤りうるため、人による確認の代わりにはならず、支払いミスを防ぐ確認の強化として不十分です。",["人のレビューは行わない"]],"2":["Ground Truth は学習データのラベル付け向けの機能です。全件を人が確認すると処理の遅れと人件費が増え、要件に反します。",["SageMaker Ground Truth","全件を人が確認する"]],"3":["信頼度の低い抽出結果もそのまま支払いに連携すると誤りが支払いミスに直結し、月次の抜き取りでは事前に防げません。",["そのまま支払いシステムに連携"]]},"AIF-C01-197":{"0":["全体の精度だけを見て運用を続けると、方言や高齢の話者という特定グループの不利益が放置され、公平性が改善しません。",["苦情が出た顧客だけを有人対応"]],"1":["方言の音声を除外すると学習データの代表性がさらに失われ、方言話者の誤認識が増えて偏りが強まります。",["外れ値として除外"]],"2":["インスタンスを大きくしても処理速度が上がるだけで、学習データの不足による方言の認識精度は改善しません。",["推論インスタンスを大きくして"]]},"AIF-C01-198":{"0":["温度は生成モデルの出力のランダム性の設定で、代理変数を通じて残る評価モデルの偏りは解消できません。",["温度を下げれば"]],"1":["モデルを大きくしても、性別と相関する項目から偏りを学習する構造は変わらず、影響が自然に消えることはありません。",["モデルを大きくすれば"]],"3":["性別の項目を削除しても、部活動や出身校のような相関の強い項目が代理変数として働き、実際に評価の差が残っています。",["バイアスはもう存在しない"]]},"AIF-C01-199":{"1":["Guardrails を使わないと不適切な内容を入出力で防ぐ仕組みがなくなり、保護者の「不適切な内容を表示しない」という要求に反します。",["Guardrails は使わない"]],"2":["温度を最大にすると出力のランダム性が増し、誤った情報や予期しない内容が生成されやすくなって、リスクが高まります。",["温度を最大にして"]],"4":["子どもの入力を公開掲示板に投稿するとプライバシーを侵害し、不適切な内容に触れるリスクも高まります。学習効果とも無関係です。",["公開掲示板に投稿する"]]},"AIF-C01-200":{"0":["全体の精度が高くても高齢者で緊急度を低く見積もる誤りがあり、そのまま自動化すると重症の高齢患者の対応が遅れる重大なリスクがあります。",["そのまま判定を自動化して導入する"]],"1":["高齢者を対象外にして問題を記録しないのは問題の隠蔽で、モデルの改善にもつながらず、透明性と公平性に反します。",["問題は記録しない"]],"2":["既知の精度の問題を利用者に知らせないと、医療従事者が判定を過信して誤りを見逃す恐れがあり、透明性に反します。",["利用者には知らせずに導入する"]]},"AIF-C01-201":{"1":["ディープラーニングは層が多いほど内部の判断過程が複雑になり、重みから判断の根拠を直接読み取るのは難しくなります。",["根拠を重みから直接読み取りやすくなる"]],"2":["決定木は深くなるほど分岐が増えるため、全体の判断の流れを人が追いにくくなり、解釈しにくくなります。",["深くなるほど解釈しやすくなる"]],"3":["線形回帰は表現力が低い代わりに、係数から各特徴量の影響を読み取りやすいモデルです。説明が逆になっています。",["表現力が高い","読み取ることはできない"]]},"AIF-C01-202":{"0":["Clarify のバイアスレポートはバイアスの分析結果を示すもので、モデルの用途や学習データ、リスクなどを総合的に記録する文書ではありません。",["バイアスレポート"]],"1":["Model Registry はモデルのバージョンや承認状態を管理するのが主な役割で、用途やリスクを記載した文書を作成・共有する機能ではありません。",["SageMaker Model Registry"]],"3":["AI Service Cards は AWS が自社の AI サービスについて公開する文書で、利用者が自社モデルの情報を記録するためには使えません。",["AWS AI Service Cards"]]},"AIF-C01-203":{"1":["AWS Artifact のコンプライアンスレポートは SOC や ISO などの第三者監査レポートで、AI サービスの用途や制約、責任ある利用方法をまとめた文書ではありません。",["コンプライアンスレポート"]],"2":["SageMaker Model Cards は利用者が自分で作成したモデルを文書化する機能で、AWS が自社の AI サービスについて公開する文書ではありません。",["SageMaker Model Cards"]],"3":["Well-Architected Tool のレポートは利用者のワークロードをベストプラクティスに照らしてレビューした結果で、AI サービスの説明文書ではありません。",["Well-Architected Tool のレポート"]]},"AIF-C01-204":{"1":["学習率はトレーニング時に重みの更新幅を決めるハイパーパラメータで、各特徴量が予測に与える影響を示すものではありません。",["学習率"]],"2":["コンテキストウィンドウは言語モデルが一度に扱えるトークン数の上限で、住宅価格の予測における特徴量の影響とは無関係です。",["コンテキストウィンドウ"]],"3":["混同行列は分類モデルの予測と正解の対応を集計した表で、回帰の予測にどの特徴量が影響したかは示しません。",["混同行列"]]},"AIF-C01-205":{"0":["多層の畳み込みニューラルネットワークは内部の判断過程が複雑で、根拠を人が直接たどるのは困難です。",["多層の畳み込みニューラルネットワーク"]],"1":["数十億パラメータの大規模言語モデルは内部の判断過程が極めて複雑で、解釈性の高いモデルとは言えません。",["数十億パラメータ"]],"2":["拡散モデルはノイズを段階的に除去して画像などを生成するモデルで、判断の根拠を人がたどりやすい解釈性の高いモデルではありません。",["拡散モデル"]]},"AIF-C01-206":{"2":["AI の限界を隠すと利用者が回答を過信して誤りに気付けず、透明性の原則に反して信頼を損ないます。",["限界に関する情報は公開しない"]],"3":["人間が回答しているように見せかけるのは利用者を欺く行為で、AI との対話であることを明示するという透明性の基本に反します。",["人間のオペレーターが回答しているように見せかける"]],"4":["問い合わせがあったときだけの説明では、多くの利用者が AI と対話していることを知らないままになり、透明性として不十分です。",["問い合わせがあったときだけ説明する"]]},"AIF-C01-207":{"0":["堅牢性は想定外の入力に対しても安定して動作する性質で、個別の申請を却下した理由を説明できることにはなりません。",["堅牢性"]],"2":["汎化性能は未知のデータでも精度を保てる性質で、判断理由を規制当局に説明できるかどうかとは別の観点です。",["汎化性能"]],"3":["再現率は陽性を見逃さない割合を示す評価指標で、高くても個々の判断の理由を説明できることにはなりません。",["高い再現率"]]},"AIF-C01-208":{"0":["インスタンスタイプは推論の実行環境の情報で、その契約者の保険料が高くなった理由の説明にはなりません。",["インスタンスタイプ"]],"1":["学習データの総件数はモデル全体の情報で、特定の契約者の保険料がなぜ高いのかという個別の理由は示しません。",["学習データの総件数"]],"3":["モデル全体の正解率は平均的な性能を示すだけで、個別の契約者の予測にどの特徴量が影響したかは説明できません。",["モデル全体の正解率"]]},"AIF-C01-209":{"0":["AWS Artifact の SOC レポートは AWS のサービス基盤の統制に関する監査レポートで、自社の需要予測モデルの目的や評価結果を記載した文書ではありません。",["SOC レポート"]],"1":["CloudWatch のダッシュボードはメトリクスを可視化する監視ツールで、モデルの目的や学習データ、制約を記録しバージョンごとに管理する文書ではありません。",["CloudWatch のダッシュボード"]],"2":["AI Service Cards は AWS が自社の AI サービスについて作成した文書で、自社で開発したモデルの説明にはなりません。",["AWS AI Service Cards"]]},"AIF-C01-210":{"0":["プロビジョンドスループットは処理能力を確保する購入形態で、エージェントがどう推論しどのアクションを選んだかは確認できません。",["プロビジョンドスループット"]],"1":["チャンクサイズはナレッジベースの検索に関する設定で、エージェントの推論過程や API 呼び出しの判断を確認する手段ではありません。",["チャンクサイズを変更する"]],"3":["温度を最大にすると動作がさらに予測しにくくなるだけで、推論過程の確認にはならず、予期しない API 呼び出しも増えやすくなります。",["温度を最大にする"]]},"AIF-C01-211":{"0":["別のバケットに保存しても保管場所が分かれるだけで、配信された画像そのものから AI 生成かどうかを後から確認することはできません。",["S3 の別のバケットに保存"]],"1":["ファイル名の連番は簡単に変更でき、画像自体に情報が残らないため、AI で生成されたことの証明にはなりません。",["ファイル名に連番を付ける"]],"3":["解像度を下げても画像の見た目が粗くなるだけで、AI 生成かどうかを判別する来歴情報にはなりません。",["解像度を下げて配信"]]},"AIF-C01-212":{"0":["混同行列は分類の予測結果と正解の対応を集計した表で、契約年数の変化に伴う解約確率の変化を示すものではありません。",["混同行列"]],"2":["ROC 曲線はしきい値ごとの真陽性率と偽陽性率から分類性能を評価するもので、特定の特徴量と予測の関係は示しません。",["ROC 曲線"]],"3":["学習曲線は学習量に応じた損失や精度の推移を示すもので、契約年数が予測にどう影響するかを説明するものではありません。",["学習曲線"]]},"AIF-C01-213":{"1":["文字数を増やしても正確さは保証されず、社員が根拠を確かめる手段にもなりません。詳しく見せるだけで過信を招く恐れがあります。",["回答の文字数を増やして"]],"2":["使ったモデル名を非公開にすると透明性はむしろ下がり、社員が回答の信頼性を判断する材料が減ります。",["モデル名を非公開にする"]],"3":["断定的な口調にしても正確さは変わらず、誤りでも正しそうに見えるため過信を招き、確かめる手段にもなりません。",["より断定的な口調"]]},"AIF-C01-214":{"1":["温度は生成モデルの出力のランダム性の設定で、無関係な写り込みに依存する判定モデルの問題は解決しません。",["温度を下げて"]],"2":["他の病院の画像では精度が大きく下がっており、検証データの高精度は見せかけの相関によるものです。そのまま展開すると誤判定が多発します。",["そのまま他の病院にも展開する"]],"3":["説明可能性の結果は、モデルが病変ではなく定規などに反応しているという重要な問題を示しています。無視すると汎化しないモデルを使い続けることになります。",["無視する"]]},"AIF-C01-215":{"0":["事後的な説明手法や解釈しやすいモデルで説明義務を満たせる場合があり、どのような場合も AI をやめるのは過剰な判断です。",["どのような場合も AI の利用をやめる"]],"1":["精度と説明可能性にはトレードオフがあり、規制上の説明義務がある以上、要件に照らして選ぶ必要があります。ランダムな選択は不適切です。",["ランダムにモデルを選ぶ"]],"3":["規制による説明義務を無視すると法令違反になります。精度がやや高いことは義務を無視してよい理由になりません。",["説明の義務は無視する"]]},"AIF-C01-216":{"0":["Bedrock では顧客のプロンプトや応答がモデル提供者の学習に使われることはありません。",["モデル提供者の学習に使われる"]],"1":["Bedrock では入出力がモデル提供者と共有されることはなく、品質改善のために提供者がレビューする仕組みもありません。",["30 日間モデル提供者によってレビュー"]],"3":["Bedrock のデータは保存時に既定で暗号化されます。カスタマーマネージドキーは自社でキーを管理したい場合の選択肢で、暗号化の前提条件ではありません。",["カスタマーマネージドキーを設定した場合にのみ"]]},"AIF-C01-217":{"0":["Guardrails はモデルの入出力の内容を制御する機能で、カスタムモデルを暗号化するキーの管理やローテーションはできません。",["Amazon Bedrock Guardrails"]],"1":["CloudFront の署名付き URL はコンテンツ配信へのアクセスを期限付きで許可する仕組みで、カスタムモデルの暗号化キーではありません。",["CloudFront の署名付き URL"]],"3":["AWS WAF は Web リクエストをルールでフィルタリングするファイアウォールで、カスタムモデルを暗号化して保護する機能ではありません。",["AWS WAF のルール"]]},"AIF-C01-218":{"0":["Step Functions は複数の処理をワークフローとして連携させるサービスで、S3 内の機密データを自動で検出する機能はありません。",["AWS Step Functions"]],"1":["Amazon Polly はテキストを音声に変換するサービスで、文書内のクレジットカード番号などを検出することはできません。",["Amazon Polly"]],"2":["Amazon Forecast は時系列データから需要などを予測するサービスで、S3 の文書から機密データを検出する用途には使えません。",["Amazon Forecast"]]},"AIF-C01-219":{"0":["公開バケットに置くと誰でも API キーを取得できてしまい、漏えいに直結します。自動ローテーションの機能もありません。",["S3 の公開バケット"]],"2":["プロンプトに API キーを書くと、ログやモデルの出力、プロンプトインジェクションを通じて漏えいする危険が高まります。ローテーションもできません。",["プロンプト内への記載"]],"3":["ソースコードに直接書くと、リポジトリの共有などで漏えいしやすく、キーを変えるたびにコードの修正と再デプロイが必要になります。",["ソースコードへの直接記述"]]},"AIF-C01-220":{"1":["フィッシングは偽のメールやサイトで利用者から認証情報などをだまし取る攻撃で、推論 API の応答を集めてモデルを複製する攻撃ではありません。",["フィッシング"]],"2":["データポイズニングは学習データを汚染してモデルの挙動をゆがめる攻撃で、入出力の組を集めてモデルを複製する攻撃とは異なります。",["データポイズニング"]],"3":["DDoS 攻撃はサービスを使えなくすることが目的で、入出力の組を集めてモデルを複製するという今回の目的とは異なります。",["可用性の妨害だけを目的とした"]]},"AIF-C01-221":{"0":["インターネットゲートウェイ経由ではネットワーク ACL で送信先を絞っても、通信はインターネットを経由するため要件を満たしません。",["インターネットゲートウェイを付け"]],"1":["CloudFront はコンテンツ配信ネットワークで、VPC 内から Bedrock へのプライベート接続を提供するものではありません。",["CloudFront を経由させる"]],"2":["NAT ゲートウェイはプライベートサブネットからインターネットへ出るための仕組みで、通信はインターネット経由のままです。",["NAT ゲートウェイを追加する"]]},"AIF-C01-222":{"0":["温度は出力のランダム性の設定で、入力に含まれる個人情報がモデルに渡ることや、出力に含まれることは防げません。",["温度を 0 にして"]],"1":["システムプロンプトの指示だけではモデルが確実に従う保証がなく、個人情報もそのままモデルに送信されるため保護として不十分です。",["書くだけで対応する"]],"3":["Amazon Inspector は EC2 やコンテナなどのソフトウェアの脆弱性を検出するサービスで、プロンプト内の個人情報は検出できません。",["Amazon Inspector"]]},"AIF-C01-223":{"0":["ハルシネーションは事実と異なる内容をもっともらしく生成する現象で、外部コンテンツに仕込まれた指示に従った今回の事象とは異なります。温度を下げても防げません。",["ハルシネーション"]],"1":["データポイズニングは学習データを汚染する攻撃で、推論時に読み込んだページ内の指示に従った今回の事象とは異なります。再学習では防げません。",["データポイズニング"]],"2":["モデル抽出攻撃は API の応答を大量に集めてモデルを複製する攻撃で、ページに埋め込まれた指示に従わせる攻撃ではありません。",["モデル抽出攻撃"]]},"AIF-C01-224":{"0":["AdministratorAccess を維持すると、エージェントがプロンプトインジェクションなどで操作された場合に、アカウント全体に被害が及ぶ恐れがあります。",["そのまま AdministratorAccess を維持する"]],"1":["ルートユーザーの認証情報はアカウントのすべての操作が可能で、埋め込むと漏えい時の被害が最大になります。最小権限の原則に完全に反します。",["ルートユーザーの認証情報を埋め込む"]],"3":["温度は出力のランダム性を調整するだけで、Lambda 関数に付与された過剰な権限の問題は解決しません。",["温度を下げて"]]},"AIF-C01-225":{"0":["Top P は候補トークンの範囲を絞る推論パラメータで、社員番号や特定のコード名といった特定の情報の出力を防ぐことはできません。",["Top P を小さくする"]],"1":["プロビジョンドスループットは処理能力を確保する購入形態で、回答に含まれる機密情報をフィルタリングする機能ではありません。",["プロビジョンドスループット"]],"3":["埋め込みモデルの変更は検索の精度に影響するだけで、回答に社員番号やプロジェクトコード名が含まれることは防げません。",["埋め込みモデルを変更する"]]},"AIF-C01-226":{"0":["ハイパーパラメータチューニングは最適なパラメータを探索する機能で、学習コンテナの外部通信を遮断するセキュリティ設定ではありません。",["ハイパーパラメータチューニング"]],"2":["インスタンス数を増やすと処理能力が上がるだけで、コンテナから外部への通信を防ぐことにはなりません。",["インスタンス数を増やす"]],"3":["公開バケットに置くと誰でも医療データにアクセスできてしまい、データの持ち出しを防ぐ目的と正反対です。",["S3 の公開バケット"]]},"AIF-C01-227":{"1":["EC2 のインスタンスタイプ一覧はコンピューティングの性能や仕様の情報で、LLM アプリケーション特有のセキュリティリスクはまとめられていません。",["インスタンスタイプ一覧"]],"2":["ISO 9001 は品質マネジメントシステムの規格で、プロンプトインジェクションなど LLM 特有のリスクの一覧ではありません。",["ISO 9001"]],"3":["PCI DSS はカード情報を扱う事業者向けのセキュリティ基準で、物理セキュリティ要件は LLM アプリケーション特有のリスクを扱っていません。",["PCI DSS の物理セキュリティ要件"]]},"AIF-C01-228":{"1":["最大トークン数を減らしても、閲覧権限のない文書が検索されてモデルに渡る問題は変わらず、短い回答にも機密情報が含まれ得ます。",["最大トークン数を減らす"]],"2":["温度は出力のランダム性を調整するだけで、検索結果に含まれた経営会議資料の内容が回答に使われることは防げません。",["温度を下げて"]],"3":["プロンプトの指示だけではモデルが確実に従う保証はなく、閲覧権限のない文書がモデルに渡る根本原因も残ります。",["書くだけで対応する"]]},"AIF-C01-229":{"0":["アクセスキーをスクリプトに直接書くと、コードの共有などで認証情報が漏えいする原因になります。IAM ロールを使うべきです。",["アクセスキーを学習スクリプトに直接書き込む"]],"2":["バケットを公開すると誰でも学習データやモデルの成果物をダウンロードでき、保管中のデータ保護と正反対です。",["誰でもダウンロードできるよう"]],"3":["温度は推論時の出力のランダム性の設定で、S3 に保管しているデータの保護とは無関係です。",["推論時の温度を下げる"]]},"AIF-C01-230":{"1":["Bedrock のサービスエンドポイント自体の可用性は、マネージドサービスを運用する AWS の責任です。顧客が重複して対策する必要はありません。",["サービスエンドポイント自体の可用性"]],"2":["基盤モデルの事前学習データの選定やベースモデルの重みの管理は、AWS やモデル提供者の責任で、顧客が行うことではありません。",["ベースモデルの重みの管理"]],"4":["基盤モデルを実行するサーバーのパッチ適用やハードウェア保守は、インフラを管理する AWS の責任です。",["パッチ適用とハードウェアの保守"]]},"AIF-C01-231":{"1":["セキュリティグループは IP アドレスやポートで通信を制御するもので、同じ Bedrock エンドポイント上のモデル単位で利用を区別できません。",["セキュリティグループで大規模モデルへの通信を拒否"]],"2":["アクセスキーを共有すると CloudTrail で誰が呼び出したかを区別できず、コード側の切り替えは容易に回避されるため権限制御になりません。",["1 つの IAM ユーザーのアクセスキーを共有"]],"3":["Guardrails の拒否トピックは入出力の話題を制御する機能で、どのモデルを誰が呼び出せるかという利用権限は制御できません。",["拒否トピックに大規模モデルの名前を登録"]]},"AIF-C01-232":{"1":["信頼度のしきい値を下げても推論時の判定基準が変わるだけで、誤ラベルで不正に操作されたモデルの挙動は直りません。",["信頼度のしきい値を下げて"]],"3":["出所を確認しない Web 上の画像を追加すると、汚染されたデータが混入する経路が増え、データポイズニングのリスクが高まります。",["提供元を確認せずに Web 上の画像も追加"]],"4":["インスタンス数を増やすと処理能力が上がるだけで、汚染された学習データによるモデルの不正な挙動は防げません。",["インスタンス数を増やし"]]},"AIF-C01-233":{"0":["Guardrails や認証を省略すると、誰でも他人の口座情報を照会できる状態になり、懸念される攻撃を防ぐ手段がなくなります。",["Guardrails や認証を省略する"]],"2":["全顧客の口座を照会できる権限を与え、本人確認をモデルの判断に任せると、プロンプトインジェクションで他人の情報を取得される恐れがあります。",["全顧客の口座を照会できる権限","モデルの判断で本人確認させる"]],"3":["プロンプトの指示だけに頼ると、インジェクションで回避される可能性があります。照会範囲の制限や最小権限などの多層防御が必要です。",["それ以外の対策は行わない"]]},"AIF-C01-234":{"0":["温度は出力のランダム性の設定で、大量リクエストによる料金の急増もシステムプロンプトを引き出そうとする攻撃も防げません。",["温度を 0 に設定し"]],"1":["より大きなモデルに変更すると 1 回あたりの料金が上がり、大量リクエストによる被害はさらに拡大します。攻撃も防げません。",["より大きなモデルに変更する"]],"2":["何も対応しなければ料金の急増と攻撃が続きます。レート制限や攻撃の検出などで被害を抑えて再発を防げます。",["何も対応しない"]]},"AIF-C01-235":{"1":["Amazon Inspector は EC2 やコンテナなどの脆弱性を検出するサービスで、AWS の SOC レポートや ISO 認証の証明書は入手できません。",["Amazon Inspector"]],"2":["Audit Manager は自社の AWS 利用状況について証跡を収集するサービスで、AWS 自身の SOC レポートや ISO 証明書を入手する場所ではありません。",["AWS Audit Manager"]],"3":["Trusted Advisor はコストやセキュリティなどのベストプラクティスに基づく推奨を示すサービスで、コンプライアンス文書は提供しません。",["AWS Trusted Advisor"]]},"AIF-C01-236":{"0":["Amazon Comprehend はテキストから感情やエンティティを抽出する自然言語処理サービスで、API 操作の履歴は記録しません。",["Amazon Comprehend"]],"1":["Amazon Translate はテキストを翻訳するサービスで、誰がいつ設定を変更したかといった API 操作の履歴は記録できません。",["Amazon Translate"]],"3":["ナレッジベースは RAG のために資料を検索する機能で、Guardrails の設定変更やモデルの削除の履歴を記録するものではありません。",["ナレッジベース"]]},"AIF-C01-237":{"0":["データを保存・処理する場所はリージョンで決まるため、リージョンを考慮しないと国外で処理される恐れがあり、国内法に違反しかねません。",["リージョンは関係ない"]],"1":["応答速度でリージョンを自動選択すると、国外のリージョンでデータが処理される可能性があり、データレジデンシーの要件を守れません。",["応答が最も速いリージョンを自動的に選ばせる"]],"3":["料金だけでリージョンを選ぶと国外のリージョンになる可能性があり、顧客データを国外で保存・処理しないという法的要件を満たせません。",["最も料金の安いリージョン"]]},"AIF-C01-238":{"1":["Amazon Polly はテキストを音声に変換するサービスで、リソースの設定が社内ルールに準拠しているかを評価する機能はありません。",["Amazon Polly"]],"2":["Amazon Rekognition は画像や動画を分析するサービスで、SageMaker AI のリソース設定の準拠状況を評価するものではありません。",["Amazon Rekognition"]],"3":["Bedrock Flows はプロンプトやモデルを組み合わせた生成 AI のワークフローを構築する機能で、リソース設定の継続的な評価には使えません。",["Amazon Bedrock Flows"]]},"AIF-C01-239":{"0":["Amazon Polly はテキストを音声に変換するサービスで、学習データの欠損値や範囲外の値をルールでチェックする機能はありません。",["Amazon Polly"]],"2":["CloudFront はコンテンツ配信ネットワークで、データの品質をルールに基づいて評価する機能はありません。",["Amazon CloudFront"]],"3":["Guardrails はモデルの入出力の内容を制御する機能で、学習データの欠損値や範囲外の値を検出するものではありません。",["Amazon Bedrock Guardrails"]]},"AIF-C01-240":{"0":["VPC フローログは IP アドレスやポートなど通信のメタデータだけを記録し、プロンプトの内容や誰が呼び出したかは分かりません。",["VPC フローログ"]],"2":["Macie は S3 内の機密データを検出するサービスで、Bedrock のモデル呼び出しとプロンプトの内容を記録するものではありません。",["Amazon Macie"]],"3":["CloudTrail には API の呼び出し記録は残りますが、プロンプトや応答の本文は記録されません。本文の記録にはモデル呼び出しログが必要です。",["プロンプトと応答の本文も記録される"]]},"AIF-C01-241":{"0":["データドリフトは本番データの分布が学習時から変化する現象で、データの出所や処理の流れを追跡する考え方ではありません。",["データドリフト"]],"1":["データの匿名化は個人を特定できないようにする処理で、どのデータソースがどう処理されたかを追跡するものではありません。",["データの匿名化"]],"3":["データ拡張は既存のデータを加工して学習データを水増しする手法で、データの来歴を追跡する考え方ではありません。",["データ拡張"]]},"AIF-C01-242":{"1":["AWS Artifact は AWS 自身のコンプライアンスレポートを入手するサービスで、自社環境の証跡を継続的に収集して監査レポートを作るものではありません。",["AWS Artifact"]],"2":["Amazon Inspector はソフトウェアの脆弱性を検出するサービスで、規制要件に対する証跡の収集や監査レポートの作成は行いません。",["Amazon Inspector"]],"3":["Trusted Advisor はベストプラクティスに基づく推奨を示すサービスで、業界標準や規制要件に沿った証跡の収集や監査レポートの作成は行いません。",["AWS Trusted Advisor"]]},"AIF-C01-243":{"0":["Snow Family はデータを物理デバイスで移行・処理するためのサービスで、その利用ガイドは生成 AI の利用形態ごとのセキュリティ対策を整理するものではありません。",["AWS Snow Family の利用ガイド"]],"2":["EC2 の料金表はインスタンスの価格情報で、生成 AI のセキュリティやガバナンスの観点を整理する資料ではありません。",["Amazon EC2 の料金表"]],"3":["コスト最適化の柱だけではセキュリティやガバナンスの観点が扱われず、生成 AI の利用形態ごとの対策を整理できません。",["コスト最適化の柱だけ"]]},"AIF-C01-244":{"1":["Guardrails はモデルの入出力の内容を制御する機能で、どのリージョンで Bedrock を使えるかを制限することはできません。",["Guardrails でリージョンを指定する"]],"2":["CloudWatch のダッシュボードは状況を可視化するだけで、承認外のリージョンでの Bedrock の利用を防ぐことはできません。",["CloudWatch のダッシュボード"]],"3":["口頭での依頼には強制力がなく、誤って承認外のリージョンを使うことを技術的に防げないため、方針を確実に守れません。",["口頭でリージョンを守るよう依頼する"]]},"AIF-C01-245":{"0":["Ground Truth は学習データのラベル付けを行うサービスで、モデルのバージョンや承認状態を管理する機能ではありません。",["Ground Truth"]],"1":["Data Wrangler は学習データの準備や前処理を行う機能で、モデルのバージョン管理や承認ワークフローは提供しません。",["Data Wrangler"]],"3":["Canvas はノーコードでモデルを構築する機能で、モデルのバージョンと承認状態を一元管理する仕組みではありません。",["Amazon SageMaker Canvas"]]},"AIF-C01-246":{"0":["無期限に保存すると、1 年後に削除するという社内規程に反し、保管コストや情報漏えいのリスクも増え続けます。",["無期限に保存し続ける"]],"1":["ログを保存しないと、監査のため 1 年間保存するという規程を守れず、監査に必要な記録が残りません。",["ログの保存を無効にする"]],"3":["毎日の手作業での確認と削除は運用の手間が大きく、削除漏れや誤削除も起こり得るため、運用負荷を抑える要件に反します。",["手作業で削除する"]]},"AIF-C01-247":{"0":["高性能なモデルを 1 つに絞っても、どの業務でどう使われるかによるリスクは残るため、ガバナンスが不要になることはありません。",["ガバナンスは不要になる"]],"3":["各部署に任せて問題発生時だけ対応すると、利用状況を把握できないままリスクが放置され、全社のリスク管理になりません。",["問題が起きたときだけ対応する"]],"4":["全面禁止にすると生成 AI による価値の創出を失い、隠れた利用を招く恐れもあります。リスク管理と活用の両立になりません。",["全面的に禁止し"]]},"AIF-C01-248":{"0":["CloudFront はコンテンツ配信、AWS WAF は Web リクエストのフィルタリングで、データレイクのデータの把握やテーブル・列単位のアクセス制御はできません。",["CloudFront","AWS WAF"]],"2":["Polly は音声合成、Lex は対話型インターフェイスを作るサービスで、データの所在の管理やアクセス権限の制御はできません。",["Amazon Polly と Amazon Lex"]],"3":["Guardrails はモデルの入出力の制御、プロンプトキャッシュはコスト削減の機能で、データレイクのテーブルや列単位の権限管理はできません。",["Guardrails とプロンプトキャッシュ"]]},"AIF-C01-249":{"0":["精度だけでは学習データ、人による監督の状況、運用中の判断記録を示せず、当局から求められる説明責任を果たせません。",["モデルの精度だけを記録し"]],"2":["外部の AI サービスを使っても、採用判断に利用する企業の説明責任はなくなりません。",["自社の説明責任はなくなる"]],"3":["記録を残さないと、後から規制の対象と判断された際に学習データや判断記録を示せず、説明責任を果たせません。",["記録は一切残さない"]]},"AIF-C01-250":{"1":["ルートユーザーへの集約は最小権限の原則に反し、利用者を区別できないため誰が呼び出したかの監査もできなくなります。",["ルートユーザーに集約する"]],"2":["Guardrails の拒否トピックは入出力の話題を制御する機能で、未承認のモデルの呼び出しそのものを防ぐことはできません。",["拒否トピックに未承認のモデル名を登録"]],"3":["自己申告の報告には強制力がなく、未承認モデルの利用を防げません。30 アカウント分の手作業の集計は運用負荷も大きくなります。",["表計算ソフトで報告させる"]]},"CLF-C02-001":{"0":["初期のハードウェア投資を使った分だけの支払いに置き換える利点で、多数の顧客の利用を集約して単価が下がることを表すものではありません。",["設備投資から変動費"]],"1":["世界各地のリージョンへ短時間で展開できるという利点で、利用量の集約による単価の低下とは関係がありません。",["グローバル展開"]],"2":["リソースを素早く用意・破棄できるスピード面の利点で、AWS が利用量を集約して低い単価を提供できることとは別の概念です。",["俊敏性"]]},"CLF-C02-002":{"0":["エッジロケーションは CloudFront のキャッシュや Route 53 の DNS 応答に使う拠点で、リージョン内で電源やネットワークが独立したデータセンター群ではありません。",["エッジロケーション"]],"1":["Local Zones は大都市圏の利用者の近くにリソースを置くための拡張拠点で、リージョンを構成する独立したデータセンター群そのものではありません。",["Local Zones"]],"3":["リージョナルエッジキャッシュは CloudFront のキャッシュ階層の一部で、リージョン内でワークロードを実行するデータセンター群ではありません。",["リージョナルエッジキャッシュ"]]},"CLF-C02-003":{"0":["耐久性はデータを失わない度合いを表す特性で、数分で環境を作って検証し、すぐ削除できるというスピードの利点とは異なります。",["耐久性"]],"1":["規模の経済は利用量の集約による単価の低下を表す利点で、試行錯誤を素早く低コストで繰り返せることを指すものではありません。",["規模の経済"]],"3":["高可用性はシステムを止めずに稼働し続けることに関する利点で、短時間で環境を作って捨てられる俊敏性とは別の概念です。",["高可用性"]]},"CLF-C02-004":{"0":["VPC サブネットは VPC 内の IP アドレス範囲を分割した論理的な区画で、CloudFront のキャッシュや Route 53 の DNS 応答を行う物理拠点ではありません。",["VPC サブネット"]],"1":["アベイラビリティーゾーンはリージョン内でワークロードを実行するデータセンター群で、リージョンより多くの都市に配置されたキャッシュ用の拠点ではありません。",["アベイラビリティーゾーン"]],"3":["Outposts は AWS のインフラを顧客のオンプレミス施設に設置するサービスで、CloudFront や Route 53 が利用する拠点ではありません。",["AWS Outposts"]]},"CLF-C02-005":{"1":["冗長性は構成要素を複数持って障害に備えることを指し、需要に応じてリソースを自動で拡張・縮小する特性ではありません。",["冗長性"]],"2":["耐久性はデータを失わない度合いを表す特性で、需要の増減に合わせてリソースを伸縮させることとは関係がありません。",["耐久性"]],"3":["データの整合性はデータが矛盾なく正しい状態に保たれることを指し、コンピューティングリソースの自動的な増減とは別の概念です。",["データの整合性"]]},"CLF-C02-006":{"1":["クラウドに移行してもソフトウェアのライセンス費用はなくならず、ライセンス込みの料金や BYOL などで引き続き支払う必要があります。",["ライセンスが無料になる"]],"2":["責任共有モデルでは、データ保護やアクセス管理、OS やアプリケーションの設定などは引き続き顧客の責任であり、すべてが AWS に移るわけではありません。",["すべて AWS に移る"]],"3":["AWS が担うのは物理インフラの運用で、アプリケーションの設計は引き続き顧客の仕事です。差別化に集中できるのは設計の手間が減るからではありません。",["設計が不要になる"]]},"CLF-C02-007":{"1":["ピーク時の台数を年間を通して確保し続けると、閑散期にも遊休リソースの費用が発生し続けるため、課題そのものが解決しません。",["年間を通して確保し続けられる"]],"2":["AWS の基本は使った分だけ支払う従量課金で、すべてのワークロードの料金が固定されるわけではありません。遊休サーバーの課題とも無関係です。",["料金が固定され"]],"3":["クラウドでもサーバーの性能が自動的に向上することはありません。需要の増加には台数やサイズを増やして対応する必要があります。",["性能が自動的に向上する"]]},"CLF-C02-008":{"1":["東京から南米までの物理的な距離による遅延は、インスタンスサイズを大きくしても解消できず、低遅延の要件を満たせません。",["インスタンスサイズを大きくする"]],"2":["自社データセンターの建設には多額の設備投資と長い期間が必要で、数週間後の公開に間に合わず、設備のない現地での提供にも向きません。",["自社のデータセンターを新たに建設する"]],"3":["帯域を増やしても日本から南米までの距離による遅延は減らないため、現地プレイヤーへの低遅延での提供は実現できません。",["帯域を増やして"]]},"CLF-C02-009":{"1":["エッジロケーションはコンテンツのキャッシュや DNS 応答のための拠点で、リモートワークステーションのような任意のワークロードは実行できません。",["エッジロケーション"]],"2":["別のリージョンの AZ はその都市から離れた場所にあるため、距離による遅延が大きく、1 桁ミリ秒の低遅延を実現できません。",["別のリージョン"]],"3":["Direct Connect ロケーションはオンプレミスと AWS を専用線で接続するための拠点で、ワークステーションなどのワークロードを実行する場所ではありません。",["AWS Direct Connect ロケーション"]]},"CLF-C02-010":{"0":["エッジロケーションはキャッシュや DNS のための拠点で、業務データの保存先ではありません。同じ地域にあるため広域災害にも備えられません。",["エッジロケーション"]],"2":["同じ AZ 内の冗長化はサーバー単位の故障には有効ですが、地域全体が被災するとすべてのサーバーが同時に失われてしまいます。",["同じアベイラビリティーゾーン内"]],"3":["EBS ボリュームのサイズを大きくしても保存場所は同じ AZ のままで、データの複製先が増えないため地域規模の災害には備えられません。",["サイズを大きくする"]]},"CLF-C02-011":{"0":["エッジロケーションはキャッシュや DNS などに使われる拠点で、新機能がそこでのみ提供されるという仕組みはありません。",["エッジロケーションでのみ"]],"2":["サポートプランは技術支援の範囲や応答時間を決めるもので、プランを上げても機能の提供リージョンが増えることはありません。",["サポートプランをアップグレード"]],"3":["AWS の新しいサービスや機能は一部のリージョンから順次提供されることが多く、全リージョンで同時に提供されるわけではありません。",["全リージョンで同時に提供"]]},"CLF-C02-012":{"0":["顧客データを含むシステムを海外のリージョンに移すと、顧客データを国内に保管するという法令の要件に違反してしまいます。",["顧客データを含むすべてのシステムを移す"]],"2":["単一 AZ では広域災害に耐えられず、顧客データを含む応答を海外のエッジにキャッシュすると国内保管の規制にも反します。",["単一の AZ","海外のエッジにキャッシュ"]],"3":["災害対策用の複製であっても顧客データを海外のリージョンに置くと、国内に保管するという法令の要件を満たせません。",["海外のリージョンに置く"]]},"CLF-C02-013":{"1":["料金だけで選ぶと欧州の利用者から遠いリージョンになる可能性があり、体感速度を優先するという要件を満たせません。",["料金が最も安いリージョン"]],"2":["欧州の利用者向けのサイトを全リージョンに展開するのは費用と運用負荷が過大で、利用者に選ばせても体感速度の向上にはつながりません。",["全リージョンに同じ構成を展開"]],"3":["東京リージョンは欧州の利用者から遠く遅延が大きくなります。優先すべきは運用担当者ではなく利用者の体感速度です。",["東京リージョンを選び"]]},"CLF-C02-014":{"0":["全リージョンでの常時稼働は費用と運用負荷が非常に大きく、シンガポールの顧客向けという要件に対して過剰で、運用をシンプルにする方針にも反します。",["すべてのリージョンでサイトを常時稼働"]],"1":["単一 AZ では 1 つのデータセンター障害でサイトが止まり、別リージョンへのバックアップもないためリージョン障害時にデータを復元できません。",["単一のアベイラビリティーゾーン","CloudFront だけで"]],"3":["単一 AZ に 1 台だけでは、そのデータセンターやインスタンスの障害でサイトが止まり、別リージョンへのバックアップもありません。",["単一のアベイラビリティーゾーン","1 台配置"]]},"CLF-C02-015":{"0":["コロケーションに移しても自社でハードウェアを購入・所有する点は変わらず、初期投資を抑えて使った分だけ払う形にはなりません。",["コロケーション"]],"1":["減価償却は購入した設備の費用を年数で配分する会計処理で、初期のハードウェア購入そのものはなくならず、従量課金の考え方とは逆です。",["減価償却費に置き換える"]],"2":["リザーブド契約での前払いは長期の利用を約束して割引を得る方法で、使った分だけ支払うという考え方とは異なります。",["リザーブド契約で前払い"]]},"CLF-C02-016":{"0":["AWS Marketplace のサブスクリプションはサードパーティ製品を新たに購入・契約する仕組みで、既に保有しているライセンスを活用するものではありません。",["AWS Marketplace サブスクリプション"]],"1":["リザーブドインスタンスは長期利用の約束で EC2 などの料金を割り引く購入方法で、保有するソフトウェアライセンスの持ち込みとは関係ありません。",["リザーブドインスタンス"]],"2":["スポットインスタンスは EC2 の空きキャパシティを割安に使う購入方法で、既存のソフトウェアライセンスを活用する考え方ではありません。",["スポットインスタンス"]]},"CLF-C02-017":{"0":["SLA はサービスの稼働率などの品質について提供者と利用者が合意したもので、電力や人件費を含めた費用の比較には使いません。",["サービスレベルアグリーメント"]],"2":["減価償却は設備の購入費用を耐用年数で配分する会計処理で、電力・冷却・保守・人件費などの間接費を含めた総費用の考え方ではありません。",["減価償却"]],"3":["RTO は障害発生から復旧までにかかる時間の目標で、オンプレミスとクラウドの費用を総合的に比較する考え方ではありません。",["目標復旧時間"]]},"CLF-C02-018":{"1":["Linux のインスタンスを Windows として扱うことはできません。Windows Server を使うには Windows の AMI とライセンスが必要です。",["Windows として扱う"]],"2":["BYOL は既に保有しているライセンスを持ち込む方法で、ライセンスを持っていないこの企業は別途購入が必要になり、要件に合いません。",["ライセンス持ち込み（BYOL）"]],"3":["AWS サポートは技術的な支援を行う窓口で、ソフトウェアのライセンスを無償で提供することはありません。",["ライセンスの無償提供を依頼する"]]},"CLF-C02-019":{"1":["クラウドでもシステムの設計、構築、運用を担う人員は必要で、IT 人員がゼロになることはありません。",["IT 人員がゼロになる"]],"2":["クラウドではハードウェアを所有しないため、減価償却期間が長くなるという効果はなく、調達期間の短縮とも関係がありません。",["減価償却期間が長くなる"]],"3":["電気料金の契約単価は電力会社との契約で決まり、サーバーの調達期間が短くなることで直接下がるものではありません。",["電気料金の契約単価が下がる"]]},"CLF-C02-020":{"0":["CPU 使用率が 10% 前後と既に余っている状態で台数を増やすと、遊休リソースがさらに増え、費用はかえって高くなります。",["複数台に増やして"]],"1":["オンプレミスに戻しても過剰なスペックは変わらず、クラウドの利点である柔軟なサイズ変更も失うため、費用削減になりません。",["オンプレミスに戻して"]],"2":["課題は CPU の過剰なスペックであり、EBS ボリュームを大きくしても費用が増えるだけで、無駄は解消されません。",["より大きな EBS ボリューム"]]},"CLF-C02-021":{"1":["クラウドに移行してもアプリケーションのテストは顧客の責任として引き続き必要で、不要になることはありません。",["テストが一切不要になる"]],"2":["顧客が開発したソフトウェアの不具合を AWS が自動で修正することはなく、修正は引き続き顧客の仕事です。",["不具合が自動的に修正される"]],"3":["責任共有モデルでは、セキュリティポリシーの策定やアクセス管理は引き続き顧客の責任で、クラウドに移しても不要にはなりません。",["策定する必要がなくなる"]]},"CLF-C02-022":{"0":["EC2 のインスタンスタイプはいつでも変更でき、5 年間固定されるような制約はありません。償却期間に縛られないことがクラウドの利点です。",["5 年間変更できない"]],"1":["クラウドではハードウェアを所有しないため償却期間という概念がなく、償却期間が延びて年間費用が半分になる効果もありません。",["償却期間が 10 年に延長され"]],"2":["世代が固定されることは利点ではなく、オンプレミスと同じ課題です。クラウドでは新しい世代に自由に切り替えられることが利点です。",["世代が固定され"]]},"CLF-C02-023":{"0":["平日の日中しか使わない環境を常時稼働させると、使わない夜間や週末の時間にも料金が発生し、費用を抑えることになりません。",["常時稼働させ"]],"1":["検証環境を本番と同じ大きさに拡張しておくと常に余分な料金がかかり、費用を抑えるという目的に反します。",["本番環境と同じ大きさに拡張"]],"2":["物理サーバーを購入すると使わない時間も費用が発生し続け、使った分だけ支払うクラウドの料金モデルを生かせません。",["物理サーバーを購入して"]]},"CLF-C02-024":{"0":["S3 のストレージ料金はクラウド側で発生する費用で、オンプレミスの総所有コストに含める項目ではありません。",["Amazon S3 のストレージ料金"]],"3":["AWS からインターネットへのデータ転送料金はクラウド利用時の費用で、オンプレミスの TCO を算出する際の項目ではありません。",["AWS からインターネットへのデータ転送料金"]],"4":["AWS サポートプランの料金はクラウドを利用する場合に発生する費用で、オンプレミス環境の総所有コストには含まれません。",["AWS サポートプランの月額料金"]]},"CLF-C02-025":{"1":["3 年分を最初から確保して支払うと、オンプレミスと同じく導入直後の未使用容量に費用を払うことになり、課題が解決しません。",["最初から全量を確保して支払う"]],"2":["業務に必要なデータまで毎年削除するのは現実的でなく、容量を先に買ってしまうという課題の解決策にもなりません。",["毎年すべて削除する"]],"3":["購入時期を延ばしても、将来の容量を先に買う点は変わらず、むしろ一度に買う容量が増えて未使用の部分が大きくなります。",["5 年ごとに延ばす"]]},"CLF-C02-026":{"0":["レプリケーションや切り替えの手順を自分たちで整備すると、パッチ適用やバックアップの作業も残ったままで、運用の人件費はかえって増えます。",["手順を自分たちで整備する"]],"2":["DynamoDB は NoSQL のため、PostgreSQL のエンジンを変えたくないという要件に反し、データモデルの作り直しという大きな改修も必要になります。",["Amazon DynamoDB に移行し"]],"3":["インスタンスを大きくしてもパッチ適用やバックアップ、切り替えの作業は自前のまま減らず、単一インスタンスでは AZ 障害にも耐えられません。",["より大きいタイプに変更し","自前で運用する"]]},"CLF-C02-027":{"1":["処理時間を現在と同程度に保つという要件に反するうえ、物理サーバーを常設する以上、月末以外の遊休時間の費用は残ります。",["処理時間を延ばしてもよい"]],"2":["クラウド上でも常時稼働させれば、月末の 2 時間以外の遊休時間にも料金が発生し続け、総コストを大きく下げられません。",["常時稼働させ"]],"3":["予備のサーバーを追加購入すると費用はさらに増えます。遊休時間が長いという課題を解決するものではありません。",["もう 1 台のサーバーを購入し"]]},"CLF-C02-028":{"0":["ハードウェアを更新しても商用データベースのライセンス費用とパッチ適用などの運用作業はそのまま残り、どちらの課題も解決しません。",["保守契約を延長する"]],"1":["ライセンス込みのインスタンスでは商用ライセンスの費用が利用料金に含まれて支払い続けることになり、ライセンス費用をなくす要件を満たせません。",["ライセンス込み"]],"2":["既存ライセンスを持ち込むと商用ライセンスの費用は残り、EC2 上での自前運用ではパッチ適用やバックアップの作業も減りません。",["既存のライセンスを持ち込んで","自分で運用する"]]},"CLF-C02-029":{"0":["オペレーションの観点は、クラウドサービスが合意した水準で運用・提供されることを扱い、スキル育成や組織構造の変革は扱いません。",["オペレーション"]],"1":["セキュリティの観点は、データやワークロードの機密性・完全性・可用性の確保を扱うもので、人材育成やリーダーシップ支援とは異なります。",["セキュリティ"]],"2":["プラットフォームの観点は、クラウドのアーキテクチャやインフラの構築を扱い、人と組織の変革を扱う観点ではありません。",["プラットフォーム"]]},"CLF-C02-030":{"0":["リホストはアプリケーションに手を加えずそのまま移す戦略で、マイクロサービスやサーバーレスへの作り直しは行いません。",["リホスト"]],"1":["リテインは当面現在の環境に残す戦略で、移行を機にアプリケーションの構成を作り直すものではありません。",["リテイン"]],"2":["リタイアは不要なアプリケーションを廃止する戦略で、アプリケーションを使い続けながら設計を見直すものではありません。",["リタイア"]]},"CLF-C02-031":{"0":["リロケートは VMware などの仮想化基盤ごとクラウドへ移す戦略で、既存システムをやめて SaaS 製品に切り替えるものではありません。",["リロケート"]],"1":["リホストは既存のシステムをそのまま AWS 上へ移す戦略で、別の SaaS 製品に置き換えることは含みません。",["リホスト"]],"3":["リプラットフォームは既存システムを大きく変えずにマネージドサービスへ載せ替える戦略で、SaaS 製品への切り替えではありません。",["リプラットフォーム"]]},"CLF-C02-032":{"0":["リファクタリングはアプリケーションを作り直して移す戦略で、業務上不要なアプリケーションに手間をかけて移行するのは無駄です。",["リファクタリング"]],"2":["リホストはそのまま移す戦略ですが、ほとんど使われず不要なアプリケーションを移しても移行の手間と運用費用が増えるだけです。",["リホスト"]],"3":["リパーチェスは別の製品に置き換える戦略で、業務上不要なアプリケーションの代替製品を買う必要はありません。",["リパーチェス"]]},"CLF-C02-033":{"0":["Amazon Inspector は EC2 やコンテナイメージの脆弱性をスキャンするサービスで、移行時のコスト見積もりやビジネスケースは作成しません。",["Amazon Inspector"]],"1":["Application Migration Service は実際にサーバーを AWS へ複製・移行するサービスで、経営層向けのコスト試算を作るものではありません。",["Application Migration"]],"2":["DataSync はオンプレミスと AWS の間でファイルデータを転送するサービスで、使用状況の分析やビジネスケースの作成はできません。",["AWS DataSync"]]},"CLF-C02-034":{"0":["リファクタリングはアプリケーションの設計を見直して作り直すため時間がかかり、変更せずに早く移すという要件に合いません。",["リファクタリング"]],"2":["リタイアはアプリケーションを廃止する戦略で、業務で使い続けるために AWS へ移したいという要件とは逆です。",["リタイア"]],"3":["リパーチェスは別の製品に置き換える戦略で、アプリケーションを変更せずにそのまま移すことにはなりません。",["リパーチェス"]]},"CLF-C02-035":{"0":["リホストはサーバーを EC2 などへそのまま移す戦略で、マネージドの RDS に載せ替えて管理負荷を減らすことは含みません。",["リホスト"]],"1":["リファクタリングはアプリケーションの設計を大きく見直す戦略で、コードをほぼ変えずに RDS へ移す今回の方式とは異なります。",["リファクタリング"]],"2":["リテインは現在の環境に残す戦略で、MySQL を Amazon RDS に移す今回の方針とは逆です。",["リテイン"]]},"CLF-C02-036":{"1":["リパーチェスは別の製品に置き換える戦略で、更新したばかりのシステムを当面そのまま使い続ける方針とは合いません。",["リパーチェス"]],"2":["リタイアはシステムを廃止する戦略ですが、生産管理システムは業務で使い続けるため適しません。",["リタイア"]],"3":["リホストは AWS へそのまま移す戦略で、移行の利点が小さいため現時点では移さず数年後に再検討するという判断と矛盾します。",["リホスト"]]},"CLF-C02-037":{"1":["リファクタリングはアプリケーションの設計を作り直す戦略で、変換や再構築をせずに仮想マシンを移す要件と正反対です。",["リファクタリング"]],"2":["リタイアは不要なシステムを廃止する戦略で、多数の仮想マシンを使い続けたまま移すという目的に合いません。",["リタイア"]],"3":["リパーチェスは別の製品に置き換える戦略で、既存の仮想マシンと VMware の運用ツールをそのまま使い続けることはできません。",["リパーチェス"]]},"CLF-C02-038":{"0":["DataSync はファイルやオブジェクトのデータを転送するサービスで、サーバー全体を EC2 へ継続的に複製してリホストすることはできません。",["AWS DataSync"]],"1":["Storage Gateway はオンプレミスから AWS のストレージを利用するためのハイブリッドストレージサービスで、サーバーの移行には使いません。",["AWS Storage Gateway"]],"3":["DMS はデータベースのデータを移行するサービスで、物理サーバーや仮想マシン全体を EC2 へ移すことはできません。",["Database Migration"]]},"CLF-C02-039":{"0":["AWS Backup は AWS リソースのバックアップを一元管理するサービスで、稼働中の PostgreSQL の変更を継続的に複製して Aurora へ移行する機能はありません。",["AWS Backup"]],"2":["Application Migration Service はサーバー全体を EC2 へリホストするサービスで、PostgreSQL から Aurora へのデータベース移行には使いません。",["Application Migration"]],"3":["Transfer Acceleration は S3 へのアップロードを高速化する機能で、データベースの変更を継続的に複製して移行することはできません。",["S3 Transfer Acceleration"]]},"CLF-C02-040":{"0":["ピープルの観点は文化や組織設計、スキル育成など人と組織の変革を扱い、プログラム管理や支出・リスク管理は扱いません。",["ピープル"]],"2":["オペレーションの観点はクラウドサービスを合意した水準で運用することを扱い、プロジェクト管理や支出管理による統制は対象外です。",["オペレーション"]],"3":["プラットフォームの観点はクラウドのアーキテクチャやインフラの構築を扱うもので、プログラム管理やリスク管理を扱う観点ではありません。",["プラットフォーム"]]},"CLF-C02-041":{"0":["Transfer Acceleration は長距離の S3 へのアップロードを高速化する機能で、NAS からの転送や追加ファイルのスケジュール転送は行いません。",["S3 Transfer Acceleration"]],"2":["テープゲートウェイは既存のバックアップソフトから仮想テープとして AWS に保存する仕組みで、NAS のファイルを S3 へ移行する用途ではありません。",["テープゲートウェイ"]],"3":["DMS はデータベースの移行に使うサービスで、NAS に保存されたファイルを S3 へ転送することはできません。",["Database Migration"]]},"CLF-C02-042":{"0":["Snowball Edge は 2025 年 11 月以降は新規顧客に提供されていません。デバイスの往復による差分転送は手作業も多く、継続的な転送に向きません。",["Snowball Edge を新たに注文し","何度も往復させて"]],"1":["自作スクリプトでの毎晩のアップロードは運用担当者の手作業が多く、暗号化や整合性の検証も自前で作る必要があり、帯域不足も解消しません。",["スクリプトで毎晩"]],"3":["Transfer Acceleration はエッジ経由で長距離転送を高速化する機能で、回線帯域そのものの不足は解消せず、差分の自動転送もできません。",["既存のインターネット回線のまま","Transfer Acceleration だけ"]]},"CLF-C02-043":{"0":["市販のクラウドサービスへの置き換えはリパーチェスで、作り直すリファクタリングではありません。現行環境で使い続ける (3) もリロケートではなくリテインです。",["(2) リファクタリング","(3) リロケート"]],"1":["(1) はそのまま移すのでリホスト、(2) は置き換えたいのでリパーチェスです。(2) をリテイン、(3) をリパーチェスとするのは逆の組み合わせです。",["(2) リテイン","(3) リパーチェス"]],"3":["期限が迫る (1) を作り直すリファクタリングは時間がかかりすぎます。(3) は 2 年後まで使い続けるためリタイアではなくリテインです。",["(1) リファクタリング","(3) リタイア"]]},"CLF-C02-044":{"2":["キャパシティの推測をやめるのは信頼性の柱の設計原則で、運用上の優秀性の柱の原則ではありません。",["キャパシティの推測をやめる"]],"3":["支出を分析し、その帰属を明らかにするのはコスト最適化の柱の設計原則で、運用上の優秀性の柱には含まれません。",["支出を分析し"]],"4":["すべてのレイヤーにセキュリティを適用するのはセキュリティの柱の設計原則で、運用上の優秀性の柱の原則ではありません。",["すべてのレイヤーにセキュリティを適用"]]},"CLF-C02-045":{"0":["信頼性の柱はワークロードが意図した機能を正しく実行し、障害から復旧できることを扱い、環境への影響の最小化は扱いません。",["信頼性"]],"1":["コスト最適化の柱は不要な支出を避けて費用対効果を高めることを扱い、エネルギー消費など環境負荷の削減を主眼とする柱ではありません。",["コスト最適化"]],"2":["セキュリティの柱はデータやシステムの保護を扱う柱で、ワークロードの環境への影響を最小化することは対象外です。",["セキュリティ"]]},"CLF-C02-046":{"0":["パフォーマンス効率の柱はリソースを効率的に使って性能を維持することを扱い、トレーサビリティやデータ保護の原則は含みません。",["パフォーマンス効率"]],"2":["運用上の優秀性の柱は運用のコード化や小さく可逆的な変更などを扱い、全レイヤーのセキュリティ適用やデータ保護はセキュリティの柱の原則です。",["運用上の優秀性"]],"3":["信頼性の柱は障害からの自動復旧や水平スケーリングなどを扱い、トレーサビリティやデータの保護はセキュリティの柱の原則です。",["信頼性"]]},"CLF-C02-047":{"0":["コスト最適化の柱は支出の把握や従量課金モデルの採用などを扱い、障害からの自動復旧や復旧手順のテストは信頼性の柱の原則です。",["コスト最適化"]],"1":["持続可能性の柱は環境負荷の削減を扱う柱で、障害からの復旧や水平スケーリングによる影響の軽減は信頼性の柱の原則です。",["持続可能性"]],"3":["セキュリティの柱はアイデンティティ管理やデータ保護などを扱い、障害からの自動復旧や復旧手順のテストは含みません。",["セキュリティ"]]},"CLF-C02-048":{"1":["持続可能性の柱は環境負荷を減らすことに焦点を当てた柱で、要件に合ったリソースタイプの選定による性能の効率化が主眼ではありません。",["持続可能性"]],"2":["信頼性の柱は障害からの復旧や可用性を扱い、要件に合うリソースタイプの選択やサーバーレスの活用による効率化は扱いません。",["信頼性"]],"3":["運用上の優秀性の柱は運用のコード化や継続的な改善を扱い、リソースタイプの選定と見直しはパフォーマンス効率の柱の考え方です。",["運用上の優秀性"]]},"CLF-C02-049":{"1":["1 つのモノリシックなアプリケーションにまとめると処理同士が密結合になり、一方の停止がもう一方に直接影響してしまいます。",["モノリシックなアプリケーションにまとめ"]],"2":["大きなサーバー 1 台で両方の処理を動かすと単一障害点になり、サーバーや一方の処理の障害が他方にも波及します。",["より大きなサーバーで両方の処理を動かす"]],"3":["同期的な API 呼び出しで結果を待つ構成では、在庫更新処理が停止すると受付処理も応答できなくなり、密結合のままです。",["同期的な API 呼び出し","結果を待つ"]]},"CLF-C02-050":{"0":["セキュリティの柱はデータやシステムの保護を扱う柱で、支出の把握やクラウド財務管理の仕組みづくりは扱いません。",["セキュリティ"]],"1":["運用上の優秀性の柱は運用の自動化や継続的な改善を扱い、ワークロードごとの支出の把握や消費モデルの採用はコスト最適化の柱です。",["運用上の優秀性"]],"3":["パフォーマンス効率の柱はリソースを効率的に使って性能を維持することを扱い、費用対効果の測定やクラウド財務管理は対象外です。",["パフォーマンス効率"]]},"CLF-C02-051":{"0":["サーバーに固有の名前を付けて個別に管理するのは、壊れたら修理して使い続ける固定的な資産の考え方で、自動で置き換える運用とは逆です。",["固有の名前を付けて個別に管理"]],"1":["1 台の大きなサーバーに集約すると単一障害点になり、不具合時に破棄して置き換えるという使い捨ての考え方とも合いません。",["1 台の大きなサーバー"]],"3":["障害対応をすべて手作業で行うのは、ログインして修復する現在の運用と同じで、自動で新しいサーバーに置き換える考え方とは逆です。",["すべて手作業で行い"]]},"CLF-C02-052":{"0":["さらに大きなインスタンスに変更する垂直スケーリングでは、サーバーが 1 台のままなので、停止するとサービス全体が止まる状態は変わりません。",["さらに大きなインスタンスタイプ"]],"2":["メモリを増設しても 1 台構成のままで単一障害点は解消されず、サーバーが停止すればサービス全体が止まります。",["メモリを増設する"]],"3":["毎晩の再起動は可用性を高めず、むしろ再起動中にサービスが止まります。1 台構成という単一障害点も残ります。",["再起動を毎晩行う"]]},"CLF-C02-053":{"0":["本番環境に直接負荷をかけると利用者に影響を与えるおそれがあり、推奨されていません。一時的に本番規模の環境を作って試験するのが適切です。",["本番環境で直接負荷をかける"]],"2":["クラウドでも負荷試験は必要です。本番規模の環境を一時的に作れることが利点であり、テストを省略してよいわけではありません。",["負荷試験が不要"]],"3":["アプリケーションの負荷試験の計画と実施は顧客の責任で、AWS が顧客の代わりに実施することはありません。",["AWS が顧客の代わりに"]]},"CLF-C02-054":{"1":["Amazon Inspector は EC2 やコンテナイメージの脆弱性をスキャンするサービスで、質問に回答してベストプラクティスへの適合を評価するものではありません。",["Amazon Inspector"]],"2":["AWS Config はリソースの設定を記録し、ルールで評価するサービスで、質問形式でワークロードをレビューし改善計画を記録する機能はありません。",["AWS Config"]],"3":["AWS Artifact は AWS のコンプライアンスレポートや契約を入手するためのサービスで、自社ワークロードのレビューには使えません。",["AWS Artifact"]]},"CLF-C02-055":{"0":["手順書を読みやすくしても手作業で構築することに変わりはなく、人為的な設定ミスの根本原因は解消されません。",["文字を大きくして"]],"1":["特定の担当者に集約すると属人化を招き、手作業によるミスの可能性も残ります。自動化による再現性の確保にはなりません。",["1 人の担当者に集約する"]],"2":["確認作業を省略すると設定ミスがさらに見逃されやすくなり、手作業による構築という根本原因にも対処できません。",["確認作業を省略して"]]},"CLF-C02-056":{"1":["年に 1 回の大規模なリリースは失敗時の影響が大きく、小さく頻繁で元に戻せる変更を推奨する Well-Architected の考え方と逆です。",["年に 1 回だけ大規模にリリース"]],"2":["OS を手作業で個別に設定すると、差別化につながらない作業が増えてミスも起きやすく、自動化を推奨する設計原則に反します。",["手作業で個別に設定する"]],"3":["ピークを見込んだ大きめのサーバーの常時稼働は過剰なプロビジョニングで、キャパシティの推測をやめて需要に合わせる原則に反します。",["大きめのサーバーを常時稼働"]]},"CLF-C02-057":{"1":["別リージョンでの常時稼働は AZ 障害への対策としては過剰で、費用が大きく増えます。費用の増加を抑えるという要件に合いません。",["別のリージョンに同じ構成を常時稼働"]],"2":["Elastic IP を手動で付け替える運用では障害時に停止時間が長くなり、単一 AZ 構成のままでは AZ 障害にも耐えられません。",["手動で付け替える"]],"3":["同じ AZ 内でインスタンスを増強しても、その AZ で障害が起きればすべてのインスタンスが止まり、同じ規模の障害に耐えられません。",["同じ AZ 内で"]]},"CLF-C02-058":{"0":["Well-Architected では状況に応じて柱の間のトレードオフを判断するもので、コスト最適化が常に他のすべての柱より優先されるわけではありません。",["常に優先される"]],"2":["信頼性の柱は本番環境に限らずすべてのワークロードで考慮します。検証用システムでも、要件に照らして求める水準を判断する必要があります。",["本番環境にしか適用されない"]],"3":["すべての柱を常に最大限に満たす必要はなく、停止の影響が小さい検証用システムでマルチリージョン構成にすると費用が過大になります。",["常に最大限に満たす","マルチリージョン構成"]]},"CLF-C02-059":{"0":["通知を追加しても復旧は手作業のままで運用負荷は減らず、変換処理の負荷で受付が止まるという根本原因も解消されません。",["電話で通知する","手作業での復旧"]],"1":["最大サイズのインスタンスにしても 1 台で受付と変換を兼ねる単一障害点は残り、停止時の手作業での復旧も変わりません。",["最大サイズのインスタンス","同じサーバーで行う"]],"3":["受付時間を夜間に限定するとサービスの利便性が大きく下がり、受付と変換が同じサーバーにある密結合や手作業での復旧も解消されません。",["夜間に限定し"]]},"CLF-C02-060":{"0":["不要なデータを高性能なストレージに保持し続けると、ストレージの使用量とエネルギー消費が増え、環境負荷を減らす目的に反します。",["削除せず","高性能なストレージに保存し続ける"]],"2":["使わない時間も開発環境を稼働させると遊休リソースがエネルギーを消費し続け、使用率を高めて無駄を減らす持続可能性の考え方に反します。",["24 時間稼働させ"]],"3":["ピークの 3 倍の容量を常時確保すると大半のリソースが遊休となり、エネルギーを無駄に消費して環境負荷が増えます。",["ピーク時の 3 倍の容量を常時確保"]]},"CLF-C02-061":{"1":["データセンターの物理的なセキュリティは「クラウドのセキュリティ」として AWS が責任を負う範囲で、顧客の責任ではありません。",["物理的なセキュリティ"]],"2":["物理ネットワーク機器の保守は AWS が管理するインフラの一部で、EC2 を利用する顧客が担う作業ではありません。",["物理ネットワーク機器の保守"]],"3":["ハイパーバイザーは AWS が管理する仮想化レイヤーで、そのパッチ適用は AWS の責任です。顧客が担うのはゲスト OS 以上です。",["ハイパーバイザー"]]},"CLF-C02-062":{"0":["セキュリティグループでどの接続元を許可するかは顧客が決めて設定するもので、RDS を使っても AWS の責任にはなりません。",["許可する接続元の設定"]],"1":["RDS は暗号化の機能を提供しますが、保存データを暗号化するかどうかの判断と設定は顧客の責任です。",["暗号化するかどうかの判断"]],"3":["データベースユーザーの作成や権限の設計は顧客が行う作業で、マネージドの RDS でも AWS は担いません。",["データベースユーザーの権限設計"]]},"CLF-C02-063":{"1":["S3 に保存するデータの分類は、顧客が自分のデータをどう扱うか決める「クラウドにおけるセキュリティ」で、顧客の責任です。",["データの分類"]],"2":["EC2 上で顧客が動かすアプリケーションの脆弱性修正は顧客の責任で、AWS が担う「クラウドのセキュリティ」には含まれません。",["アプリケーションの脆弱性修正"]],"3":["IAM ユーザーにどの権限を与えるかの設計は顧客の責任で、AWS が担うインフラの保護には含まれません。",["アクセス許可の設計"]]},"CLF-C02-064":{"1":["データセンターの電源と空調の冗長化は AWS が管理する物理インフラの範囲で、どのサービスでも顧客の責任ではありません。",["電源と空調の冗長化"]],"2":["物理サーバーのファームウェア更新は AWS が担う作業で、顧客が直接触れることはできず、常に顧客の責任となるものではありません。",["ファームウェア更新"]],"3":["基盤となるホスト OS へのパッチ適用は AWS の責任です。EC2 で顧客が管理するのはその上のゲスト OS です。",["ホスト OS へのパッチ適用"]]},"CLF-C02-065":{"1":["顧客が開発したアプリケーションコードの脆弱性対策は顧客だけの責任で、AWS と分担する共有コントロールではありません。",["顧客が開発したアプリケーションコード"]],"3":["物理ストレージ機器の廃棄は AWS だけが行う作業で、顧客と責任を分担する共有コントロールではありません。",["物理ストレージ機器の廃棄"]],"4":["データセンターの入退室管理は AWS だけが責任を持つ物理的なコントロールで、顧客は AWS から継承する形になります。",["入退室管理"]]},"CLF-C02-066":{"1":["Lambda の実行環境を動かす物理ホストの保守は AWS が担う作業で、顧客が対応する必要はありません。",["物理ホストの保守"]],"2":["Lambda ではサーバーの OS を AWS が管理しており、OS へのパッチ適用は顧客の責任ではありません。",["サーバーの OS へのセキュリティパッチ適用"]],"3":["Lambda サービス自体のキャパシティ管理と可用性の確保は AWS の責任で、顧客が行う作業ではありません。",["キャパシティ管理"]]},"CLF-C02-067":{"0":["AWS が責任を持つのは S3 のインフラや耐久性で、バケットを誰に公開するかというアクセス設定は顧客が行うものです。",["運用する AWS"]],"2":["資料を閲覧した第三者は責任共有モデルの当事者ではありません。設定ミスを防ぐのはバケットを管理する顧客の責任です。",["インターネット上の第三者"]],"3":["責任共有モデルでは範囲ごとに責任者が明確に決まっており、バケットのアクセス制御は顧客が単独で責任を持ちます。",["均等に負担し"]]},"CLF-C02-068":{"1":["テーブルにアクセスできる IAM ロールの選定はアクセス管理であり、フルマネージドの DynamoDB でも顧客の責任です。",["IAM ロールの選定"]],"2":["テーブルにどの個人情報を保存するかはデータの扱いに関する判断で、AWS ではなく顧客が決める必要があります。",["個人情報の種類の決定"]],"3":["アプリケーションからのクエリの入力値の検証はアプリケーション側の処理で、顧客が実装する責任があります。",["入力値の検証"]]},"CLF-C02-069":{"0":["インターネットサービスプロバイダーがアプリケーションの通信を自動で暗号化することはなく、TLS などの設定は顧客が行う必要があります。",["自動で暗号化するため、対応は不要"]],"1":["AWS はアプリケーション層の通信を自動で暗号化しません。ユーザーとの通信の保護方法は顧客が決めて構成する責任です。",["自動的にアプリケーション層で暗号化"]],"2":["AWS が利用者のブラウザーの設定を管理することはありません。通信の暗号化はサーバー側で顧客が TLS を構成して実現します。",["ブラウザーの設定を管理"]]},"CLF-C02-070":{"1":["クラウドでも物理的な統制は必要で、AWS が管理しています。監査対象外とするのではなく、AWS の第三者監査レポートで証跡を示します。",["監査対象外であると回答"]],"2":["AWS のデータセンターの物理的なセキュリティは AWS が管理しており、顧客が監視カメラを設置することはできません。",["監視カメラを設置する"]],"3":["AWS は顧客によるデータセンターへの訪問を認めておらず、物理的な統制の証跡は SOC レポートなど第三者監査の結果で確認します。",["データセンターを訪問して"]]},"CLF-C02-071":{"0":["コンテナイメージに含めたソフトウェアは顧客が用意するもので、Fargate でもその脆弱性対応は引き続き顧客の責任です。",["コンテナイメージ"]],"2":["タスクに割り当てる IAM ロールの権限設計はアクセス管理であり、起動タイプに関係なく顧客の責任として残ります。",["IAM ロールの権限設計"]],"3":["コンテナが扱うデータを暗号化するかどうかの判断はデータ保護に関するもので、Fargate でも顧客の責任です。",["暗号化の要否の判断"]]},"CLF-C02-072":{"0":["AWS が管理するのは仮想化レイヤーなどの基盤で、セキュリティグループでどの通信を許可するかは顧客が決めて設定します。",["仮想化レイヤーを管理する AWS"]],"1":["データベースソフトウェアの開発元は AWS 上のファイアウォール設定に関与せず、セキュリティグループの管理責任はありません。",["開発元"]],"3":["AWS が保守するのは物理ネットワーク機器で、セキュリティグループのルールで許可する接続元の設定は顧客の責任です。",["ネットワーク機器を保守する AWS"]]},"CLF-C02-073":{"0":["RDS に移してもデータの暗号化やアクセス権の管理は顧客の責任のままで、すべてが AWS に移るわけではありません。",["すべて AWS の責任に移る"]],"1":["マネージドサービスに移すと AWS の責任範囲は広がります。ハードウェアの管理はどちらの場合も AWS の責任で、顧客が担うことはありません。",["AWS の責任範囲が小さくなり"]],"3":["RDS ではデータベースのインストールやパッチ適用を AWS が担うため、顧客の責任範囲は小さくなり、変わらないということはありません。",["顧客の責任範囲は変わらず"]]},"CLF-C02-074":{"0":["AZ 間を結ぶ光ファイバーなどの物理ネットワークの保守は AWS が担うもので、EC2 を利用する顧客の責任ではありません。",["光ファイバーの保守"]],"2":["廃棄時のディスク破壊など物理ストレージの処分は AWS の責任で、顧客が関与することはありません。",["ディスク破壊"]],"4":["ハイパーバイザーは AWS が管理する仮想化レイヤーで、その脆弱性への対応は AWS の責任です。",["ハイパーバイザー"]]},"CLF-C02-075":{"1":["AWS が教育するのは自社の従業員で、顧客の従業員のセキュリティ教育は顧客自身の責任です。",["顧客の従業員に対して"]],"2":["クラウドでも人による設定ミスや不正のリスクは残るため、意識向上とトレーニングは引き続き必要です。",["教育は不要"]],"3":["AWS と顧客はそれぞれ自社の従業員を教育する共有コントロールで、顧客が AWS の教育内容を承認する仕組みはありません。",["教育内容を承認する"]]},"CLF-C02-076":{"0":["原因はゲスト OS の未更新とセキュリティグループの設定で、どちらも顧客の責任です。AWS に補償を求めて構成を変えなければ再発します。",["AWS に補償を請求し","構成は変更しない"]],"2":["セキュリティグループのルールは顧客が定義・管理するもので、AWS に修正を依頼するものではありません。",["セキュリティグループは AWS が管理する"]],"3":["EC2 のゲスト OS へのパッチ適用は顧客の責任で、AWS に依頼して対応してもらうものではありません。",["OS の脆弱性は AWS の責任"]]},"CLF-C02-077":{"0":["Lambda でもデータへのアクセス権の管理は顧客の責任のままで、AWS に移ることはありません。自社で厳密に管理する必要があります。",["アクセス権の管理も AWS に移る"]],"1":["EC2 は OS 以上を顧客が管理するため、3 つの中で顧客の責任範囲が最も大きい選択肢で、パッチ管理の負担を最小にする要件と逆です。",["最も顧客の責任範囲が小さい"]],"2":["RDS でもデータを暗号化するかどうかは顧客が判断して設定します。顧客の作業がなくなることはありません。",["暗号化の要否も AWS が判断する"]]},"CLF-C02-078":{"0":["移行後も ID とアクセス、データ保護、設定の管理は顧客の責任で、セキュリティ担当者は引き続き必要です。AWS が顧客の設定を最適化することもありません。",["セキュリティ担当者が不要になり"]],"1":["責任の分担は契約金額やサポートプランによって変わりません。上位プランを契約しても顧客の責任範囲は同じです。",["契約金額に比例して"]],"2":["物理施設やハードウェアなどのインフラは AWS が責任を負い、顧客は AWS の第三者監査レポートを利用できます。自社での物理監査は不要です。",["インフラについて責任を負わない"]]},"CLF-C02-079":{"0":["RDS と Lambda ではどちらも OS へのパッチ適用を AWS が行うため、顧客の作業が増えるという評価は誤りです。",["顧客が OS にパッチを適用する必要がある"]],"2":["マネージドサービスでもデータの管理やアクセス権、暗号化の設定は顧客の責任で、監査対応だけになることはありません。",["データの管理責任も AWS に移る"]],"3":["Organizations はアカウントをまとめて管理する仕組みで、各アカウントのセキュリティ設定を AWS が自動で最適化する機能ではありません。",["AWS が自動で最適化する"]]},"CLF-C02-080":{"0":["ルートユーザーはアカウントの全権限を持ち、IAM ポリシーでその権限を制限することはできません。",["IAM ポリシーでルートユーザーの権限"]],"1":["ルートユーザーは IAM ユーザーではないため IAM グループに追加できず、グループで権限を管理することもできません。",["IAM グループに追加して"]],"4":["ルートユーザーのアクセスキーは全権限を持つため漏えい時の被害が甚大で、作成しないことがベストプラクティスです。",["アクセスキーを作成し"]]},"CLF-C02-081":{"0":["保管時と転送時の暗号化はデータを読み取られないように保護する考え方で、誰にどの操作を許可するかを決める原則ではありません。",["保管時と転送時の暗号化"]],"1":["職務の分離は重要な操作を複数の担当者に分ける考え方で、特定バケットの読み取りだけを許可するという今回の権限設計の原則ではありません。",["職務の分離"]],"2":["多層防御は複数の層で守る考え方で、必要な操作だけを許可するという権限の付与方法を表す原則ではありません。",["多層防御"]]},"CLF-C02-082":{"0":["MFA を設定してもパスワードの有効期限の管理は別の設定で、MFA によって不要になるものではありません。",["有効期限が不要になる"]],"2":["MFA は認証を強化する仕組みで、ユーザーに付与されている権限の範囲は変わらず、自動で最小化されることもありません。",["自動的に最小化される"]],"3":["API 呼び出しの記録は CloudTrail の機能で、MFA を設定しても自動で有効になるわけではありません。",["API 呼び出しの記録"]]},"CLF-C02-083":{"0":["パスワードポリシーはパスワードの長さや文字種などの要件を決めるもので、リソースへの操作の許可・拒否は定義できません。",["パスワードポリシー"]],"1":["アクセスキーはプログラムから AWS にアクセスするための認証情報で、何を許可するかを定義するものではありません。",["アクセスキー"]],"3":["IAM グループはユーザーをまとめる単位で、許可や拒否の内容はグループに付ける IAM ポリシーで定義します。",["IAM グループ"]]},"CLF-C02-084":{"0":["Cost Explorer はコストと使用量を分析するサービスで、外部からアクセス可能なリソースを洗い出すことはできません。",["AWS Cost Explorer"]],"1":["AWS Artifact は AWS のコンプライアンスレポートを入手するサービスで、自社リソースのアクセス設定は分析しません。",["AWS Artifact"]],"2":["Amazon Inspector はソフトウェアの脆弱性をスキャンするサービスで、リソースポリシーによる外部共有の検出は行いません。",["Amazon Inspector"]]},"CLF-C02-085":{"0":["アカウントごとに IAM ユーザーを作ると、既存の社内 ID と連携できず、アカウントが増えるほど管理の手間とアクセス残りのリスクが増えます。",["アカウントごとに作成する"]],"2":["Simple AD は小規模向けの独立したディレクトリで、それだけでは既存の社内 ID で複数の AWS アカウントにシングルサインオンできません。",["Simple AD のみ"]],"3":["Cognito のユーザープールは自社アプリの利用者を認証する仕組みで、社員が複数の AWS アカウントにサインインする用途ではありません。",["Amazon Cognito ユーザープール"]]},"CLF-C02-086":{"0":["1 つの IAM ユーザーのアクセスキーを共有すると、誰が操作したかを追跡できず、異動者の権限だけを外すこともできません。",["アクセスキーを部員に配布する"]],"2":["個別のインラインポリシーは 20 人分を一つずつ管理する必要があり、異動のたびに手間と設定漏れが生じます。",["個別のインラインポリシー"]],"3":["異動のたびに各ユーザーへ個別にアタッチ・デタッチすると、人数が多いほど手間がかかり設定漏れも起きやすくなります。",["各ユーザーへ個別にアタッチ・デタッチ"]]},"CLF-C02-087":{"0":["GuardDuty は不審な API 呼び出しなどの脅威を検出するサービスで、パスワードの強度を検出したり要件を強制したりはできません。",["Amazon GuardDuty"]],"1":["KMS は暗号化キーを管理するサービスで、IAM ユーザーのパスワードの長さや文字種、変更を強制する機能はありません。",["AWS KMS"]],"3":["メールでの周知は強制力がなく、ルールを守らないパスワードも設定できてしまうため、監査の指摘を解消できません。",["周知するメールを送る"]]},"CLF-C02-088":{"0":["パスワードとアクセスキーは別の認証情報で、パスワードを変えても漏えいしたアクセスキーは使える状態のままです。",["パスワードだけを変更する"]],"2":["公開されたキーは既に第三者に複製されている可能性があり、ファイルを削除しても有効なまま悪用され続けます。",["キーはそのまま使い続ける"]],"3":["アクセスキーはリージョンに関係なく有効で、リージョンを変えても不正利用は防げません。",["リージョンを変更する"]]},"CLF-C02-089":{"0":["ルートユーザーの認証情報はアカウントの全権限を持ち、外部と共有するのは極めて危険です。読み取りだけを許可する最小権限にも反します。",["ルートユーザーの認証情報を一時的に共有する"]],"1":["IAM ユーザーとアクセスキーを作ると長期的な認証情報が残り、メールでの送付は漏えいのリスクもあるため要件に反します。",["IAM ユーザーを作成し","アクセスキーをメールで送る"]],"3":["バケットを一般公開すると監査会社以外の誰でもログを読めてしまい、重大な情報漏えいにつながります。",["一般公開する"]]},"CLF-C02-090":{"0":["IAM Identity Center は従業員が AWS アカウントやビジネスアプリにアクセスするための仕組みで、一般利用者の会員登録には向きません。",["AWS IAM Identity Center"]],"1":["Directory Service は Active Directory などの社内ディレクトリを提供するサービスで、一般利用者のソーシャルログインや会員登録には向きません。",["AWS Directory Service"]],"2":["IAM ユーザーは AWS リソースを操作するための ID で、アプリの一般利用者ごとに作るものではなく、数の上限もあり大規模化に向きません。",["利用者ごとに作成する IAM ユーザー"]]},"CLF-C02-091":{"0":["Pricing Calculator は AWS の利用料金を見積もるツールで、IAM ユーザーの認証情報の使用状況は確認できません。",["AWS Pricing Calculator"]],"2":["CloudWatch のダッシュボードはメトリクスを可視化するもので、各ユーザーのパスワードやアクセスキーの最終使用日時、MFA の状況は一覧できません。",["CloudWatch のダッシュボード"]],"3":["AWS Artifact から取得できるのは AWS 自身のコンプライアンスレポートで、自社の IAM ユーザーの認証情報の状態は含まれません。",["AWS Artifact"]]},"CLF-C02-092":{"0":["AWS Budgets は費用や使用量の予算を管理するサービスで、S3 バケットへのアクセスを許可するポリシーではありません。",["AWS Budgets の予算ポリシー"]],"1":["ID ベースのポリシーはユーザーやロール側に付けるもので、バケット側でどのプリンシパルを許可するかを定義するものではありません。",["ID ベースのポリシー"]],"3":["IAM のパスワードポリシーはパスワードの要件を決めるもので、S3 バケットへのアクセス許可は定義できません。",["パスワードポリシー"]]},"CLF-C02-093":{"0":["一時的な認証情報でも、使える操作はロールに付与された権限の範囲に限られ、すべての操作ができるようにはなりません。",["すべての操作が可能になる"]],"1":["一時的な認証情報による操作も CloudTrail に記録されます。記録されなくなることは利点ではなく、事実としても誤りです。",["CloudTrail に操作が記録されなくなる"]],"2":["ロールを引き受ける際にも MFA を条件にでき、MFA の設定が不可能になることはありません。利点でもありません。",["MFA の設定が技術的に不可能"]]},"CLF-C02-094":{"0":["Secrets Manager に保管しても長期のアクセスキーは残り、AmazonS3FullAccess は特定バケットの読み取りだけという最小権限に反します。",["AmazonS3FullAccess","アクセスキーを AWS Secrets Manager に保管"]],"1":["暗号化してもアクセスキーは長期の認証情報のままで、90 日ごとの手動ローテーションという作業も残り、要件を満たしません。",["90 日ごとに手動でローテーション"]],"2":["VPC からの読み取りを全員に許可すると、同じ VPC 内の他のリソースからも読み取れてしまい、必要最小限の権限になりません。",["全員に許可する"]]},"CLF-C02-095":{"1":["1 つの管理者ユーザーを共有すると誰が操作したかを追跡できなくなり、強い権限も全員に残るため安全性は下がります。",["1 つの管理者ユーザーを共有し"]],"2":["ルートユーザーはアカウントの全権限を持ち権限を制限できないため、日常業務で使うと誤操作の被害がさらに大きくなります。",["ルートユーザーで行う"]],"3":["全員が AdministratorAccess を持つ状態が変わらず、誤操作そのものは防げません。毎日の手動バックアップは運用負荷も増やします。",["現在の権限はそのままにし","毎日手動でバックアップ"]]},"CLF-C02-096":{"0":["アカウントごとに IAM ユーザーを作って手作業で削除する運用では、退職者のアクセスが残る問題が解消されず、既存の ID プロバイダーとも統合されません。",["手作業で削除する"]],"1":["共通の IAM ユーザーでは誰が操作したか追跡できず、退職者もパスワードを変えるまで使えます。部署ごとの権限の割り当てもできません。",["共通の IAM ユーザー"]],"2":["Cognito のユーザープールは主にアプリの利用者向けで、従業員の複数アカウントへのアクセスや権限の一元管理には適しません。",["Amazon Cognito のユーザープール"]]},"CLF-C02-097":{"1":["影響を確認せずにすべてのポリシーを削除すると、実際に使われている権限まで失われ、業務が止まるおそれがあります。",["影響を確認せずに","一度に削除する"]],"2":["Inspector は EC2 などの脆弱性をスキャンするサービスで、IAM ロールの未使用権限は特定できず、広すぎる権限もそのまま残ります。",["ロールの権限はそのままにし"]],"3":["IAM ロール自体には料金がかからず、Pricing Calculator でロールごとのコストは算出できません。未使用権限の特定にも使えません。",["AWS Pricing Calculator"]]},"CLF-C02-098":{"1":["サポートプランの変更やアカウントの解約など、ルートユーザーでしか行えない作業があるため、今後一切不要とは言えません。",["今後一切必要ない"]],"2":["ルートユーザーはアカウントそのものに紐づく ID で、削除して IAM ユーザーだけで運用することはできません。",["ルートユーザーを削除し"]],"3":["全権限のアクセスキーを複数人で共有すると追跡性がなくなり漏えいのリスクも高まります。IAM ユーザーではルート専用の作業も行えません。",["アクセスキーを複数人で共有する"]]},"CLF-C02-099":{"0":["Amazon Macie は S3 内の個人情報などの機密データを検出するサービスで、ログを分析して不審な API 呼び出しを検出するものではありません。",["Amazon Macie"]],"1":["AWS Shield は DDoS 攻撃からの保護を行うサービスで、CloudTrail や DNS ログを分析して脅威を検出するものではありません。",["AWS Shield"]],"2":["Amazon Inspector はソフトウェアの脆弱性をスキャンするサービスで、各種ログから不審な通信や API 呼び出しを検出するものではありません。",["Amazon Inspector"]]},"CLF-C02-100":{"0":["Inspector はソフトウェアの脆弱性をスキャンするサービスで、IAM ユーザーのパスワードの強度は対象外です。パスワードの要件は IAM のパスワードポリシーで設定します。",["パスワードの強度"]],"1":["不審なサインインの試行などの脅威検出は GuardDuty の役割で、Inspector のスキャン対象ではありません。",["不審なサインインの試行"]],"3":["S3 のオブジェクトに含まれる個人情報の検出は Amazon Macie の役割で、Inspector のスキャン対象ではありません。",["個人情報"]]},"CLF-C02-101":{"0":["Shield Advanced は高度な DDoS 保護や専門チームの支援を提供する有料のサービスで、追加料金なしで自動適用されるものではありません。",["Shield Advanced"]],"2":["Firewall Manager は複数アカウントのファイアウォール設定を一元管理するサービスで、追加料金なしで全顧客に自動で適用される DDoS 保護ではありません。",["AWS Firewall Manager"]],"3":["AWS WAF はルールを設定して使う有料の Web アプリケーションファイアウォールで、全顧客に自動で無料適用される DDoS 保護ではありません。",["AWS WAF"]]},"CLF-C02-102":{"0":["Shield Standard はネットワーク層やトランスポート層の DDoS 攻撃を防ぐもので、HTTP リクエストの中身を検査して SQL インジェクションを止めることはできません。",["AWS Shield Standard"]],"2":["セキュリティグループは IP アドレスやポートで通信を制御するもので、HTTP リクエストの内容を検査して SQL インジェクションや XSS を防ぐことはできません。",["セキュリティグループ"]],"3":["ネットワーク ACL はサブネット単位で IP アドレスやポートを制御するもので、アプリケーション層の攻撃の中身は検査できません。",["ネットワーク ACL"]]},"CLF-C02-103":{"0":["Secrets Manager はパスワードや API キーなどのシークレットを保管・ローテーションするサービスで、S3 や EBS の暗号化キーを管理するものではありません。",["AWS Secrets Manager"]],"1":["Certificate Manager は SSL/TLS 証明書を発行・管理するサービスで、保存データを暗号化するための鍵の作成や管理は行いません。",["AWS Certificate Manager"]],"3":["Amazon Cognito はアプリ利用者の認証を提供するサービスで、データの暗号化キーの作成や使用の監査は行いません。",["Amazon Cognito"]]},"CLF-C02-104":{"0":["Parameter Store でも値は安全に保管できますが、データベースパスワードを定期的に自動ローテーションする機能はありません。",["Parameter Store の標準パラメータ"]],"2":["Run Command はインスタンスでコマンドを実行する機能で、パスワードの安全な保管や自動ローテーションを提供するものではありません。",["Run Command"]],"3":["KMS のキーポリシーは暗号化キーの利用権限を定義するもので、データベースパスワード自体の保管やローテーションはできません。",["KMS のキーポリシー"]]},"CLF-C02-105":{"2":["セキュリティグループは自動で全インスタンスに適用されるものではなく、インスタンス（ENI）ごとに関連付けて使います。",["すべてのインスタンスに自動で適用され"]],"3":["サブネット単位で適用され明示的な拒否ルールを書けるのはネットワーク ACL です。セキュリティグループは許可ルールのみです。",["サブネット単位","明示的な拒否ルール"]],"4":["ルール番号を付けて小さい順に評価するのはネットワーク ACL の特徴です。セキュリティグループはすべてのルールをまとめて評価します。",["小さい番号から順に評価される"]]},"CLF-C02-106":{"0":["Amazon Macie は S3 内の機密データを検出するサービスで、検出結果に関連するリソースや API 呼び出しの関係を可視化して調査するものではありません。",["Amazon Macie"]],"1":["Trusted Advisor はコストやセキュリティなどのベストプラクティスに基づく推奨を示すサービスで、不審な挙動の根本原因の調査には使いません。",["AWS Trusted Advisor"]],"3":["AWS Config はリソースの構成を記録して評価するサービスで、GuardDuty の検出結果をグラフで可視化して調査する機能はありません。",["AWS Config"]]},"CLF-C02-107":{"0":["AWS KMS はデータ暗号化キーを管理するサービスで、ALB や CloudFront で使う SSL/TLS 証明書の発行や自動更新は行いません。",["AWS KMS"]],"1":["Amazon Cognito はアプリ利用者の認証を提供するサービスで、SSL/TLS 証明書を発行する機能はありません。",["Amazon Cognito"]],"3":["Secrets Manager はパスワードなどのシークレットを保管するサービスで、パブリックな SSL/TLS 証明書を無料で発行・自動更新することはできません。",["AWS Secrets Manager"]]},"CLF-C02-108":{"0":["セキュリティグループは許可ルールしか設定できず、インスタンス単位で適用されるため、サブネット単位で特定の IP を明示的に拒否できません。",["セキュリティグループ"]],"1":["Certificate Manager は SSL/TLS 証明書を管理するサービスで、IP アドレスによる通信の拒否はできません。",["AWS Certificate Manager"]],"2":["IAM ポリシーは AWS API の操作に対する権限を制御するもので、サブネットへのネットワーク通信を拒否することはできません。",["IAM ポリシー"]]},"CLF-C02-109":{"0":["Amazon Detective は検出結果の根本原因を調査するサービスで、複数サービスの検出結果を集約してベストプラクティスへの準拠状況を確認するものではありません。",["Amazon Detective"]],"1":["Trusted Advisor はベストプラクティスに基づく推奨を示しますが、GuardDuty や Inspector、Macie の検出結果を集約する機能はありません。",["AWS Trusted Advisor"]],"3":["AWS Organizations は複数アカウントをまとめて管理するサービスで、セキュリティサービスの検出結果を 1 か所に集約するものではありません。",["AWS Organizations"]]},"CLF-C02-110":{"0":["Shield Standard は追加料金なしの基本的な DDoS 保護で、24 時間体制の専門チームによる支援やスケーリング料金の保護は含まれません。",["AWS Shield Standard"]],"1":["Amazon Inspector はソフトウェアの脆弱性をスキャンするサービスで、DDoS 攻撃への対応支援や料金保護は提供しません。",["Amazon Inspector"]],"2":["GuardDuty は不審な挙動を検出するサービスで、DDoS 攻撃を防いだり、専門チームの支援やスケーリング料金の保護を提供したりはしません。",["Amazon GuardDuty"]]},"CLF-C02-111":{"1":["Shield Standard は全顧客に自動適用される基本的な DDoS 保護で、組織内のアカウントに WAF ルールを一元的に適用する機能はありません。",["AWS Shield Standard"]],"2":["Amazon Detective はセキュリティ検出結果を調査するサービスで、WAF ルールを複数アカウントに展開・管理するものではありません。",["Amazon Detective"]],"3":["AWS Artifact はコンプライアンスレポートや契約を入手するサービスで、WAF ルールの一元管理や自動適用はできません。",["AWS Artifact"]]},"CLF-C02-112":{"0":["Shield Advanced は DDoS 攻撃からの保護を行うサービスで、S3 に保存するデータを暗号化する機能はありません。",["AWS Shield Advanced"]],"1":["バケット名をランダムにしても保存データは暗号化されず、推測されにくくなるだけで保護にもキー使用の監査にもなりません。",["バケット名をランダムな文字列にする"]],"3":["バージョニングはオブジェクトの過去のバージョンを保持して誤削除などに備える機能で、データを暗号化するものではありません。",["バージョニング"]]},"CLF-C02-113":{"2":["Cost Explorer はコストと使用量を分析するサービスで、脅威の検出や検出結果の集約・優先度付けは行いません。",["AWS Cost Explorer"]],"3":["Pricing Calculator は利用料金を見積もるツールで、アカウント内の脅威検出やセキュリティ結果の集約には使えません。",["AWS Pricing Calculator"]],"4":["Amazon Lightsail は簡単に仮想サーバーなどを利用できるコンピューティングサービスで、セキュリティの脅威検出とは関係がありません。",["Amazon Lightsail"]]},"CLF-C02-114":{"0":["Amazon Macie は S3 内の機密データを検出するサービスで、VPC からの通信を検査してドメインで遮断することはできません。",["Amazon Macie"]],"1":["AWS WAF は CloudFront や ALB などへの HTTP リクエストを検査するもので、VPC から外向きの通信全体をドメインで制御できません。",["AWS WAF"]],"2":["セキュリティグループは IP アドレスとポートで制御するもので、ドメイン名による許可や侵入防止のルールは適用できません。",["セキュリティグループ"]]},"CLF-C02-115":{"0":["全オブジェクトをダウンロードして検査する仕組みを自作すると、開発・保守の手間と処理コストが大きく、運用負荷を抑える要件に反します。",["仕組みを自作する"]],"2":["GuardDuty は脅威を検出するサービスで、S3 のオブジェクトの内容を分類しません。Artifact も検出結果の集約先ではありません。",["GuardDuty で S3 のオブジェクトの内容を分類","AWS Artifact に集約"]],"3":["Inspector はソフトウェアの脆弱性をスキャンするサービスで、S3 内の個人情報は検出できません。Trusted Advisor も検出結果の集約先ではありません。",["Inspector で S3 バケットの中身をスキャン","Trusted Advisor に集約"]]},"CLF-C02-116":{"1":["AWS Artifact はコンプライアンスレポートを入手するサービス、AWS Budgets は予算を管理するサービスで、どちらも調査や脆弱性の洗い出しには使えません。",["AWS Artifact で調査","AWS Budgets で脆弱性"]],"2":["Macie は S3 内の機密データを検出するサービス、Shield Standard は DDoS 対策で、通信の経緯の調査や脆弱性の洗い出しはできません。",["Amazon Macie で通信を調査","AWS Shield Standard で脆弱性"]],"3":["Trusted Advisor はベストプラクティスの推奨を示すもの、ACM は証明書を管理するもので、インシデントの調査や脆弱性の修正はできません。",["AWS Trusted Advisor で調査","AWS Certificate Manager で脆弱性"]]},"CLF-C02-117":{"0":["Inspector は脆弱性を検出するサービスで攻撃をブロックしません。すべてのポートを開放すると攻撃面が広がり、ALB 以外からの通信も受け付けてしまいます。",["すべてのポートを開放して"]],"2":["Macie は S3 の機密データを検出するサービスで SQL インジェクションは防げません。ネットワーク ACL だけで大規模な DDoS をすべて防ぐこともできません。",["Amazon Macie で SQL インジェクションを防ぎ","DDoS をすべて防ぐ"]],"3":["Secrets Manager はシークレットを保管するサービスで通信の暗号化はしません。Detective は調査用のサービスで攻撃をブロックしません。",["Secrets Manager で通信を暗号化","Detective で攻撃をブロック"]]},"CLF-C02-118":{"1":["Trusted Advisor は自社環境のベストプラクティスに基づく推奨を示すもので、AWS の SOC レポートや ISO 認証の証明書は入手できません。",["AWS Trusted Advisor"]],"2":["AWS Config は自社リソースの構成を記録・評価するサービスで、AWS 自身のコンプライアンスレポートを提供するものではありません。",["AWS Config"]],"3":["Audit Manager は自社の AWS 利用に関する監査の証跡を収集するサービスで、AWS の SOC レポートや ISO 証明書の入手先は AWS Artifact です。",["AWS Audit Manager"]]},"CLF-C02-119":{"0":["CloudWatch メトリクスは CPU 使用率などの数値データを記録するもので、誰がどの API 操作を行ったかは記録しません。",["CloudWatch メトリクス"]],"1":["AWS X-Ray はアプリケーションのリクエストを追跡して性能のボトルネックを分析するサービスで、インスタンスの終了操作を誰が行ったかは記録しません。",["AWS X-Ray"]],"3":["VPC フローログはネットワークインターフェースを通る通信の IP やポートを記録するもので、API 操作の実行者や内容は記録しません。",["VPC フローログ"]]},"CLF-C02-120":{"0":["AWS Artifact の契約は BAA などの AWS との契約を確認・締結するもので、アカウントで実行できる操作を制限する機能はありません。",["AWS Artifact の契約"]],"1":["コスト配分タグは費用を部署やプロジェクトごとに分類するためのもので、アカウントが利用できる操作の上限は制限できません。",["コスト配分タグ"]],"3":["AWS Budgets のアラートは費用や使用量がしきい値を超えたときに通知するもので、操作そのものを制限することはできません。",["AWS Budgets のアラート"]]},"CLF-C02-121":{"1":["Amazon Inspector は脆弱性をスキャンするサービスで、マルチアカウント環境の自動構築やガードレールによる統制は行いません。",["Amazon Inspector"]],"2":["Pricing Calculator は利用料金を見積もるツールで、ランディングゾーンの構築やガードレールの適用はできません。",["AWS Pricing Calculator"]],"3":["Amazon Lightsail は手軽に仮想サーバーなどを使えるサービスで、ベストプラクティスに沿ったマルチアカウント環境を構築するものではありません。",["Amazon Lightsail"]]},"CLF-C02-122":{"1":["AWS Health Dashboard は AWS 側の障害やメンテナンスの情報を通知するもので、自社の EBS ボリュームの暗号化設定は評価しません。",["AWS Health Dashboard"]],"2":["CloudTrail は API 操作の履歴を記録するサービスで、リソースの設定がルールに準拠しているかを継続的に評価する機能はありません。",["AWS CloudTrail"]],"3":["Amazon Inspector はソフトウェアの脆弱性をスキャンするサービスで、EBS ボリュームの暗号化設定の準拠状況は評価しません。",["Amazon Inspector"]]},"CLF-C02-123":{"0":["周知だけでは技術的な強制力がなく、管理者を含めて規程に反するリソースを作成できてしまいます。",["使わないよう周知する"]],"1":["Trusted Advisor は推奨事項を示すもので、特定リージョンでのリソース作成を禁止する設定はできません。",["AWS Trusted Advisor"]],"3":["Budgets で他リージョンのコストを監視しても、気付けるのは作成された後で、リソースの作成そのものを防ぐことはできません。",["コストを監視する"]]},"CLF-C02-124":{"0":["Artifact のコンプライアンスレポートは AWS 自身の監査結果で、自社のリソースの設定が業界標準に沿っているかは評価しません。",["AWS Artifact"]],"2":["Pricing Calculator は利用料金を見積もるツールで、リソース設定の準拠状況を評価したり履歴を残したりはできません。",["AWS Pricing Calculator"]],"3":["Detective の行動グラフはセキュリティ検出結果の調査に使うもので、業界標準のルールのセットで設定を継続的に評価する機能ではありません。",["Amazon Detective の行動グラフ"]]},"CLF-C02-125":{"0":["Trusted Advisor はベストプラクティスに基づく推奨を示すサービスで、BAA などの AWS との契約を確認・受け入れることはできません。",["AWS Trusted Advisor"]],"1":["AWS Config はリソースの構成を記録・評価するサービスで、AWS との契約の確認や締結の機能はありません。",["AWS Config"]],"3":["Amazon Macie は S3 内の機密データを検出するサービスで、医療データを扱うための BAA の確認や受け入れはできません。",["Amazon Macie"]]},"CLF-C02-126":{"1":["CloudWatch のメトリクスは性能などの数値データで、誰がどの API を呼んだかは記録されません。15 日だけの保持では長期保管の要件も満たせません。",["メトリクスを 15 日間だけ保持する"]],"2":["VPC フローログが記録するのはネットワークインターフェイスを通る IP 通信の情報で、API 操作の記録や改ざん検証の機能はありません。",["VPC フローログ"]],"3":["AWS Config はリソースの設定変更を記録・評価するサービスで、API 操作の記録は CloudTrail の役割です。ログファイルの整合性検証の機能もありません。",["AWS Config のルール"]]},"CLF-C02-127":{"0":["ダッシュボードを目で確認するだけでは API 操作のログは集約されず、管理者による記録の無効化も防げません。30 アカウント分を毎日見る運用負荷も大きくなります。",["CloudWatch ダッシュボードを毎日確認する"]],"1":["各アカウントで作った証跡はそのアカウントの管理者が停止・削除できてしまい、「無効化できない形」という要件を満たせません。設定漏れも起こりやすくなります。",["各アカウントの管理者に"]],"3":["AWS Budgets は費用や使用量の予算を監視するサービスで、API 操作の内容を記録・集約することはできません。",["AWS Budgets"]]},"CLF-C02-128":{"1":["Amazon Inspector は EC2 やコンテナの脆弱性を検出するサービスで、セキュリティグループの設定変更の履歴は記録しません。",["Amazon Inspector"]],"2":["AWS Artifact は AWS のコンプライアンスレポートや契約をダウンロードするポータルで、自社リソースの設定履歴は確認できません。",["AWS Artifact"]],"3":["AWS Pricing Calculator は利用料金を見積もるツールで、リソースの設定がいつどう変わったかを記録する機能はありません。",["AWS Pricing Calculator"]]},"CLF-C02-129":{"0":["AWS には世界各地にリージョンがあり、データは顧客が選んだリージョンに保存されます。すべて米国に保存されるという前提が誤りです。",["データは米国に保存される"]],"2":["エッジロケーションは CloudFront などのキャッシュ配信用の拠点で、データの保存先として国内に限定する手段にはなりません。",["エッジロケーションにデータを保存"]],"3":["AWS は顧客の同意なくデータを他のリージョンに複製・移動しません。複製は顧客が設定した場合のみ行われるため、前提が誤りです。",["自動的に世界中のリージョンに複製"]]},"CLF-C02-130":{"0":["AWS のインフラは PCI DSS の認定を受けており、AWS 上でもカード情報を扱うシステムを準拠させて構築できます。オンプレミスに限る必要はありません。",["AWS 上では利用できない"]],"1":["認定の対象は AWS のインフラ部分だけです。顧客のアプリケーションや設定、運用の準拠は顧客の責任で、自動的に準拠扱いにはなりません。",["自動的に PCI DSS に準拠"]],"3":["AWS の認定はインフラ部分に限られるため、顧客が構築したシステムについては顧客側で監査を受けて準拠を示す必要があります。",["顧客の監査は不要になる"]]},"CLF-C02-131":{"1":["IAM のパスワードポリシーはパスワードの長さや複雑さを決めるもので、リソースのタグのキーや値を標準化する機能はありません。",["IAM のパスワードポリシー"]],"2":["SCP は操作の許可・拒否の上限を定めるポリシーで、タグの値の候補を一覧表示する機能はありません。表記の標準化にはタグポリシーを使います。",["タグの値の候補を一覧表示する"]],"3":["AWS Shield Advanced は DDoS 攻撃からの保護サービスで、タグの表記ゆれの解消とは関係がありません。",["AWS Shield Advanced"]]},"CLF-C02-132":{"0":["Amazon Inspector は脆弱性を検出するサービスで、API 呼び出しの記録や、設定がルールに準拠しているかの継続的な評価は行いません。",["Amazon Inspector"]],"1":["CloudWatch のメトリクスは CPU 使用率などの性能の数値で、誰がどの API を呼んだかや設定の準拠状況は分かりません。",["CloudWatch のメトリクス"]],"2":["AWS Artifact は AWS 自身のコンプライアンス文書を入手する場で、自社アカウントの API 操作や設定の準拠状況は確認できません。",["AWS Artifact"]]},"CLF-C02-133":{"1":["AWS Artifact はコンプライアンス文書の入手先で S3 の設定は変更できず、AWS Budgets は費用の監視で設定違反は検出できません。",["S3 の設定を変更","Budgets で違反を検出"]],"2":["手順書と手作業の点検では暗号化の無効化を強制的に防げず、四半期ごとでは違反の発見が遅れます。運用負荷を抑える要件にも反します。",["四半期ごとに手作業でバケットを点検"]],"3":["Inspector は脆弱性検出、Macie は S3 内の機密データ検出のサービスで、暗号化の強制やリージョンの利用制限はできません。",["Inspector で S3 バケットの暗号化を強制","Macie でリージョンの利用を制限"]]},"CLF-C02-134":{"0":["同じアカウント・同じ IAM ユーザーのままでは権限も費用も分離できません。リージョンを分けても誤操作が本番に及ぶ問題は残ります。",["同じ IAM ユーザーで操作する"]],"2":["全員に管理者権限を与えると誤操作の影響範囲がさらに広がり、確認依頼だけでは統制になりません。ガバナンス強化の要件と正反対です。",["開発者全員に管理者権限を与え"]],"3":["名前に環境名を付けても権限や費用は分離されず、誤操作の影響範囲は変わりません。アカウント準備の標準化にもつながりません。",["1 つのアカウントのまま"]]},"CLF-C02-135":{"0":["バケットを公開すると監査ログが誰でも見られる重大なセキュリティ問題になり、削除・上書きの防止もできません。S3 標準のままでは保存コストも高くなります。",["バケットを公開して"]],"1":["管理者が削除できる状態では「管理者を含めて誰も削除できない」要件を満たせません。EBS は 7 年の長期保管には割高でもあります。",["管理者だけが削除できるようにする"]],"2":["CloudTrail のイベント履歴は過去 90 日分しか保持されないため、7 年間の保管要件を満たせません。",["イベント履歴だけを利用し"]]},"CLF-C02-136":{"0":["Lightsail は仮想サーバーを月額で使うサービスで、サーバーの管理が必要です。アップロード時だけ処理を動かすイベント駆動の実行には向きません。",["Amazon Lightsail"]],"1":["AWS Batch は大量のバッチジョブをキューで管理して実行するサービスで、アップロードごとの小さな処理を即座に動かす用途には過剰です。",["AWS Batch"]],"2":["EC2 はサーバーの OS 管理やスケーリングを自分で行う必要があり、待機中も課金されます。「サーバーを管理せずに」という要件に合いません。",["Amazon EC2"]]},"CLF-C02-137":{"0":["インスタンスタイプの変更はサイズを変える垂直スケーリングで、インスタンスの数は増減しません。自動で行われるものでもありません。",["インスタンスタイプの変更"]],"2":["Compute Optimizer は使用状況から適切なインスタンスサイズを推奨するだけで、インスタンス数を自動で増減させる機能はありません。",["AWS Compute Optimizer"]],"3":["Elastic Load Balancing はトラフィックを複数のインスタンスに分散するサービスで、インスタンスの数そのものは調整しません。",["Elastic Load Balancing"]]},"CLF-C02-138":{"1":["Amazon ECR はコンテナイメージを保存するレジストリで、コンテナを実行する環境ではありません。",["Amazon ECR"]],"2":["EC2 起動タイプではコンテナを動かす EC2 インスタンスを自分で用意・管理する必要があり、要件に反します。",["EC2 起動タイプ"]],"3":["Lightsail は仮想サーバーを月額で提供するサービスで、OS などのサーバー管理は利用者が行う必要があります。",["Amazon Lightsail"]]},"CLF-C02-139":{"0":["高速コンピューティングインスタンスは GPU などのアクセラレーターで計算を速めるもので、大容量メモリを重視するインメモリ DB には最適ではありません。",["高速コンピューティングインスタンス"]],"1":["ストレージ最適化はローカルストレージへの高い I/O が必要な処理向けで、メモリ上で大量のデータを扱う用途には合いません。",["ストレージ最適化インスタンス"]],"3":["コンピューティング最適化は CPU 性能を重視した処理向けで、メモリ容量の比率が低く、インメモリデータベースには向きません。",["コンピューティング最適化インスタンス"]]},"CLF-C02-140":{"0":["汎用インスタンスは CPU・メモリ・ネットワークのバランス型で GPU を搭載しておらず、深層学習やレンダリングの高速化には向きません。",["汎用インスタンス"]],"1":["バースト可能なインスタンスは普段の負荷が低い Web サーバーなど向けで、GPU を持たず継続的な重い計算には適しません。",["バースト可能なインスタンス"]],"3":["メモリ最適化インスタンスは大容量メモリが必要な処理向けで、GPU などのアクセラレーターは搭載していません。",["メモリ最適化インスタンス"]]},"CLF-C02-141":{"1":["AWS Outposts は AWS のインフラを自社データセンターに設置するサービスで、小さなブログ用の月額定額プランとはかけ離れています。",["AWS Outposts"]],"2":["Amazon EKS は Kubernetes でコンテナを運用するサービスで、クラウド経験の少ない個人が小さなブログを動かすには複雑すぎます。",["Amazon EKS"]],"3":["AWS Batch は大量のバッチジョブを実行するサービスで、常時動く Web サイトの公開や月額定額プランには対応しません。",["AWS Batch"]]},"CLF-C02-142":{"0":["Lightsail は月額プランの仮想サーバーで、数千件のジョブのキュー管理や、量に応じたリソースの自動用意はできません。",["Amazon Lightsail"]],"1":["単一インスタンスではジョブの量に応じて自動でリソースを増やせず、キューやスケジュールの管理も自分で運用する必要があります。",["単一インスタンス"]],"2":["Elastic Beanstalk は Web アプリケーションのデプロイを簡単にするサービスで、バッチジョブのキュー管理には向いていません。",["AWS Elastic Beanstalk"]]},"CLF-C02-143":{"0":["Lightsail は簡易な仮想サーバーのサービスで、Kubernetes のコントロールプレーンを AWS が運用してくれる仕組みはありません。",["Amazon Lightsail"]],"2":["Lambda は関数単位でコードを実行するサービスで、既存の Kubernetes のマニフェストやツールをそのまま使うことはできません。",["AWS Lambda"]],"3":["ECR はコンテナイメージを保存するレジストリで、コンテナの実行環境や Kubernetes のコントロールプレーンは提供しません。",["Container Registry"]]},"CLF-C02-144":{"0":["Lambda 関数に 1 日 1 回という実行回数の制限はありません。問題は 1 回の実行時間が最大 15 分であることです。",["1 日に 1 回しか実行できない"]],"1":["Lambda でも S3 などから動画ファイルを読み込んで処理できます。この案の問題は実行時間の上限で、ファイルの種類ではありません。",["動画ファイルを扱えない"]],"2":["Lambda 関数の 1 回の実行時間は最大 15 分に制限されており、約 3 時間の処理は途中でタイムアウトします。",["実行時間に上限がない"]]},"CLF-C02-145":{"0":["セキュリティグループは通信を制御するファイアウォールの設定で、OS の設定やミドルウェアは含まれません。",["セキュリティグループをコピーする"]],"2":["インスタンスタイプの変更は CPU やメモリのサイズを変えるもので、設定済みの OS やミドルウェアを複製する手段ではありません。",["インスタンスタイプを変更して"]],"3":["Elastic IP アドレスは固定のパブリック IP アドレスで、1 つのインスタンスにしか関連付けられず、OS の構成も含みません。",["Elastic IP アドレスを割り当てて複製"]]},"CLF-C02-146":{"0":["EBS スナップショットはボリュームのバックアップで、リクエストの分散やインスタンス数の自動調整は行いません。",["Amazon EBS スナップショット"]],"3":["S3 Glacier Flexible Retrieval はアーカイブ用の低コストストレージで、トラフィックの分散やスケーリングとは関係がありません。",["Glacier Flexible Retrieval"]],"4":["CloudFront はコンテンツをエッジでキャッシュ配信するサービスで、EC2 インスタンス数を需要に合わせて増減させる機能はありません。",["Amazon CloudFront"]]},"CLF-C02-147":{"0":["Fargate では特定バージョンの OS やカスタムドライバーを構成できず、Lambda は常時稼働の API には不向きです。数秒の処理に Batch も過剰です。",["(2) AWS Fargate","(3) AWS Lambda"]],"1":["Lambda では OS やカスタムドライバーを自由に構成できず、(3) を EC2 にするとサーバー管理が必要になり「管理なし」の要件に反します。",["(2) AWS Lambda","(3) Amazon EC2"]],"2":["(2) の Lambda では OS やドライバーを指定できず、(3) の Lightsail はサーバー管理が必要です。数秒の処理に EC2 を常時動かすのも無駄です。",["(2) AWS Lambda","(3) Amazon Lightsail"]]},"CLF-C02-148":{"0":["FSx for Windows File Server は SMB でマウントして使う Windows 向けファイルサーバーで、容量を無制限に使ってインターネットから直接アクセスする用途には向きません。",["Windows File Server"]],"1":["EFS は EC2 などから NFS でマウントして使うファイルシステムで、インターネット経由で写真や動画を直接配信する用途には向きません。",["Amazon EFS"]],"3":["EBS は EC2 にアタッチするブロックストレージでボリュームごとに容量の上限があり、インターネットから直接アクセスもできません。",["Amazon EBS"]]},"CLF-C02-149":{"0":["EFS は複数のインスタンスから共有するファイルストレージで、1 台にアタッチするブロックストレージではありません。",["Amazon EFS"]],"1":["FSx for Lustre は高性能計算向けの共有ファイルシステムで、1 台の EC2 にアタッチするブロックストレージではありません。",["Amazon FSx for Lustre"]],"3":["インスタンスストアはホストに物理的に接続された一時的なストレージで、インスタンスを停止するとデータが消えます。",["インスタンスストア"]]},"CLF-C02-150":{"0":["S3 はオブジェクトストレージで、API で読み書きする前提のサービスです。複数インスタンスから共有するファイルシステムとしてマウントする用途には向きません。",["Amazon S3"]],"1":["EBS は基本的に 1 台のインスタンスにアタッチするブロックストレージで、複数のインスタンスで共有するファイルシステムにはなりません。",["Amazon EBS"]],"3":["FSx for Windows File Server は SMB を使う Windows 向けのファイル共有で、Linux から NFS で共有する用途には EFS が適しています。",["Windows File Server"]]},"CLF-C02-151":{"0":["Lambda はイベント駆動でコードを実行するサービスで、オンプレミスからファイル共有プロトコルで S3 を使えるようにする機能はありません。",["AWS Lambda"]],"1":["CloudFront はコンテンツのキャッシュ配信サービスで、オンプレミスのアプリケーションに NFS や SMB のファイル共有を提供するものではありません。",["Amazon CloudFront"]],"3":["EBS は EC2 にアタッチするブロックストレージで、オンプレミスのアプリケーションから直接ファイル共有として使うことはできません。",["Amazon EBS"]]},"CLF-C02-152":{"1":["リクエスタ支払いはデータ転送やリクエストの料金をバケット所有者ではなく利用者に負担させる機能で、以前の状態に戻すことはできません。",["リクエスタ支払い"]],"2":["Transfer Acceleration はエッジロケーション経由でアップロードを高速化する機能で、上書きや削除からの復元とは関係ありません。",["Transfer Acceleration"]],"3":["静的ウェブサイトホスティングはバケットの内容を Web サイトとして公開する機能で、過去のバージョンは保持しません。",["静的ウェブサイトホスティング"]]},"CLF-C02-153":{"1":["インスタンスストアは停止や終了でデータが失われる一時ストレージのため、長期保存が必要なデータには EBS や S3 を使います。",["長期保存が必要なデータの保管"]],"2":["インスタンスストアはホストに物理的に接続されたディスクで、EBS のように別のインスタンスへ付け替えてデータを引き継ぐことはできません。",["別のインスタンスに付け替えて"]],"3":["インスタンスストアのデータはそのホスト上にあるだけで、リージョンをまたいだ自動複製は行われません。",["複数のリージョンに自動で複製"]]},"CLF-C02-154":{"0":["手作業でのダウンロードと削除は運用負荷が高く、「手作業なしで」という要件に反します。削除漏れも起こりやすくなります。",["手作業でダウンロードして削除"]],"2":["バージョニングで古いバージョンを保持すると保存量が増え、コストはむしろ上がります。ストレージクラスの移行や削除も自動化されません。",["古いバージョンを保持する"]],"3":["Deep Archive は取り出しに数時間かかり取り出し料金も発生するため、保存後 30 日間の頻繁な参照に対応できません。",["最初から S3 Glacier Deep Archive に保存"]]},"CLF-C02-155":{"0":["One Zone-IA はアクセス頻度の低いデータ向けで、取り出し料金がかかり単一 AZ 保存です。アクセス頻度が変わっても自動で階層を移動しません。",["S3 One Zone-IA"]],"2":["Deep Archive は取り出しに数時間かかるアーカイブ用で、アクセスが増えた時期には性能に大きく影響します。",["S3 Glacier Deep Archive"]],"3":["Express One Zone は低レイテンシーを重視した高性能なクラスで、アクセス頻度に応じて自動でコストを最適化する仕組みはありません。",["S3 Express One Zone"]]},"CLF-C02-156":{"1":["EBS は EC2 にアタッチするブロックストレージで、SMB による共有ファイルストレージや Active Directory 連携の権限管理は提供しません。",["Amazon EBS"]],"2":["EFS は主に Linux から NFS で利用するファイルシステムで、SMB でのアクセスや Active Directory と連携した権限管理には対応しません。",["Amazon EFS"]],"3":["S3 Glacier Flexible Retrieval はアーカイブ用のストレージで、取り出しに時間がかかり、業務アプリケーションの共有ファイルには使えません。",["Glacier Flexible Retrieval"]]},"CLF-C02-157":{"1":["Storage Gateway はオンプレミスからクラウドのストレージを使うためのハイブリッドサービスで、複数サービスのバックアップを一元管理する機能ではありません。",["AWS Storage Gateway"]],"2":["DataSync はストレージ間でデータを転送・同期するサービスで、バックアップのスケジュールや保持期間をポリシーで管理する機能はありません。",["AWS DataSync"]],"3":["Transfer Acceleration は S3 へのアップロードを高速化する機能で、EBS や RDS などのバックアップ管理とは関係ありません。",["Transfer Acceleration"]]},"CLF-C02-158":{"0":["Deep Archive は取り出しに 12 時間程度かかるため、作成後 30 日間の頻繁な参照や、その後のすぐに表示が必要な参照に間に合いません。",["作成時から S3 Glacier Deep Archive に保存"]],"2":["1 ゾーン-IA はデータを単一の AZ にしか保存しないため、AZ 障害でデータを失わないという前提を満たせません。",["S3 1 ゾーン-IA"]],"3":["ほとんど参照しない期間も S3 標準のままでは保存料金が高く、ライフサイクルで安いクラスに移す方法よりコストがかかります。",["11 年間 S3 標準に保存し続ける"]]},"CLF-C02-159":{"0":["Glacier Flexible Retrieval は取り出しに数分から数時間かかるため、ミリ秒単位ですぐに表示する要件を満たせません。",["Flexible Retrieval"]],"1":["S3 Standard は要件を満たせますが、四半期に 1 回程度しか参照しないデータには保存料金が高く、コストが最も低い選択になりません。",["S3 Standard"]],"3":["One Zone-IA はデータを 1 つの AZ にしか保存しないため、AZ が失われるとデータも失われ、要件を満たせません。",["S3 One Zone-IA"]]},"CLF-C02-160":{"1":["DocumentDB は MongoDB 互換のドキュメントデータベースで、MySQL や PostgreSQL と互換性のあるリレーショナルデータベースではありません。",["Amazon DocumentDB"]],"2":["ElastiCache はインメモリキャッシュのサービスで、MySQL や PostgreSQL 互換のリレーショナルデータベースではありません。",["Amazon ElastiCache"]],"3":["Keyspaces は Apache Cassandra 互換のワイドカラム型データベースで、リレーショナルデータベースではありません。",["Amazon Keyspaces"]]},"CLF-C02-161":{"0":["Neptune は関係性をたどるクエリ向けのグラフデータベースで、数 TB の売上データを集計する分析基盤には向きません。",["Amazon Neptune"]],"1":["DynamoDB はキーによる高速な読み書き向けの NoSQL で、大量データに対する複雑な集計クエリは得意ではありません。",["Amazon DynamoDB"]],"3":["DocumentDB は JSON ドキュメントを扱う MongoDB 互換のデータベースで、大規模な集計分析に最適化されたデータウェアハウスではありません。",["Amazon DocumentDB"]]},"CLF-C02-162":{"0":["リードレプリカは読み取りを分散できますが、ディスクベースのデータベースのコピーで、よく使うデータをメモリに保持するキャッシュではありません。",["Amazon RDS リードレプリカ"]],"1":["DynamoDB は NoSQL データベースそのもので、既存データベースの前段でよく使うデータをメモリに保持するキャッシュではありません。",["Amazon DynamoDB"]],"3":["CloudFront はエッジロケーションで Web コンテンツをキャッシュする CDN で、データベースへの読み取りをメモリで肩代わりするものではありません。",["Amazon CloudFront"]]},"CLF-C02-163":{"2":["アプリケーションが発行する SQL の内容は利用者が作るもので、その最適化は RDS を使っても利用者の責任のままです。",["SQL の最適化"]],"3":["保存するデータの内容の正確性は利用者が管理する範囲です。AWS が担うのはパッチ適用やバックアップなどの基盤の管理です。",["データの内容の正確性の確認"]],"4":["テーブル設計はアプリケーションの要件に依存するため、RDS を使っても利用者が行う必要があります。",["テーブル設計"]]},"CLF-C02-164":{"0":["Redshift は大量データの集計分析向けのデータウェアハウスで、利用者同士の関係を何段もたどる検索を高速に行う用途には向きません。",["Amazon Redshift"]],"2":["ElastiCache はインメモリキャッシュで、つながりの関係をたどるグラフクエリの仕組みは持っていません。",["Amazon ElastiCache"]],"3":["Timestream は時系列データ向けのデータベースで、「友達の友達」のような関係性の検索には適していません。",["Amazon Timestream"]]},"CLF-C02-165":{"0":["RDS for MySQL はリレーショナルデータベースで、MongoDB 互換の API は使えないため、アプリケーションの大幅な改修が必要になります。",["Amazon RDS for MySQL"]],"1":["Neptune はグラフデータベースで、MongoDB 互換の API を提供しないため、既存アプリケーションをそのまま使えません。",["Amazon Neptune"]],"2":["Redshift は分析用のデータウェアハウスで、アプリケーションの JSON ドキュメントを MongoDB 互換 API で読み書きする用途には使えません。",["Amazon Redshift"]]},"CLF-C02-166":{"0":["DynamoDB はキーを指定したアクセス向けの NoSQL で、複数テーブルを結合する複雑な SQL はリレーショナルデータベースの特徴です。",["複数のテーブルを結合する複雑な SQL"]],"1":["DynamoDB はデータを永続的に保存するデータベースで、すべてをメモリ上に置くキャッシュ専用のサービスではありません。それは ElastiCache の特徴です。",["キャッシュ専用のサービス"]],"2":["列指向ストレージによる数 TB の集計分析は Redshift の特徴で、DynamoDB が低遅延のキー アクセスに向く理由ではありません。",["列指向のストレージ"]]},"CLF-C02-167":{"0":["ストレージを増やしても容量が増えるだけで、AZ 障害時に別の AZ へ自動で切り替わる仕組みにはなりません。",["ストレージを増やす"]],"1":["インスタンスクラスを大きくすると性能は上がりますが、同じ AZ の 1 台のままなので AZ 障害には耐えられません。",["より大きなインスタンスクラスに変更する"]],"2":["スナップショットからの復元は手作業で時間がかかり、新しいエンドポイントに設定を変える必要も出るため、自動切り替えになりません。",["毎日手動でスナップショットを取得する"]]},"CLF-C02-168":{"0":["一般的なマルチ AZ 配置のスタンバイは障害に備えた待機用で、読み取りクエリを受け付けないため参照処理を分散できません。",["マルチ AZ 配置のスタンバイ"]],"2":["Glacier Deep Archive はアーカイブ用のストレージで、取り出しに数時間かかり、データベースの参照クエリを実行する場所ではありません。",["Amazon S3 Glacier Deep Archive 上で実行"]],"3":["負荷の原因は日中の参照クエリで、夜間に停止しても解決しません。停止中は業務システムも使えなくなります。",["毎晩停止して"]]},"CLF-C02-169":{"1":["Neptune はグラフデータベースで Cassandra との互換性がなく、既存の Cassandra 用コードをほぼそのまま使うことはできません。",["Amazon Neptune"]],"2":["Aurora は MySQL/PostgreSQL 互換のリレーショナルデータベースで、Cassandra 用のアプリケーションは大きな書き換えが必要です。",["Amazon Aurora"]],"3":["DocumentDB は MongoDB 互換のドキュメントデータベースで、Cassandra 用のコードやドライバーはそのまま使えません。",["Amazon DocumentDB"]]},"CLF-C02-170":{"0":["1 つのリージョンの RDS では遠方のプレイヤーの遅延が大きく、そのリージョンが障害になると全世界で読み書きできなくなります。",["1 つのリージョンの Amazon RDS"]],"1":["Redshift は大量データを集計する分析用のデータウェアハウスで、ゲームの低遅延な読み書きやリージョン間の同期には向きません。",["Amazon Redshift"]],"2":["EC2 上の自前構築はサーバー管理が必要で、夜間のファイル同期ではデータが最大 1 日古くなり、障害時に最新のデータで続行できません。",["夜間にファイルでデータを同期する"]]},"CLF-C02-171":{"0":["ElastiCache はインメモリキャッシュで、複数テーブルの結合や確実なトランザクションを担う主なデータベースには向きません。",["Amazon ElastiCache を主なデータベース"]],"1":["Redshift は分析用のデータウェアハウスで注文登録のようなトランザクション処理向きではなく、単一ノードでは AZ 障害にも耐えられません。",["Amazon Redshift を単一ノードで使う"]],"3":["EC2 1 台の自前構築ではパッチやバックアップの運用負荷が大きく、その AZ が障害になるとデータベースが停止します。",["EC2 インスタンス 1 台に自分で"]]},"CLF-C02-172":{"0":["Route 53 は DNS による名前解決やルーティングのサービスで、エッジロケーションでコンテンツをキャッシュする機能はありません。",["Amazon Route 53"]],"1":["Global Accelerator は AWS のネットワーク経由で通信経路を最適化しますが、コンテンツのキャッシュは行いません。",["AWS Global Accelerator"]],"2":["Elastic Load Balancing はリージョン内でトラフィックを複数のターゲットに分散するサービスで、エッジでのキャッシュ配信はしません。",["Elastic Load Balancing"]]},"CLF-C02-173":{"0":["Direct Connect ゲートウェイは専用線でオンプレミスと VPC をつなぐためのもので、インターネットからの利用には使えません。",["AWS Direct Connect ゲートウェイ"]],"2":["S3 のゲートウェイエンドポイントは VPC から S3 へプライベートに接続するためのもので、インターネットとの通信は提供しません。",["Amazon S3 のゲートウェイエンドポイント"]],"3":["VPC ピアリング接続は VPC 同士をつなぐ仕組みで、インターネットから VPC 内の Web サーバーへの経路にはなりません。",["VPC ピアリング接続"]]},"CLF-C02-174":{"0":["CloudFront はコンテンツをキャッシュ配信する CDN で、支店のネットワークと VPC を暗号化トンネルで接続する機能はありません。",["Amazon CloudFront"]],"1":["Direct Connect は専用線による接続で、開通まで数週間以上かかります。「専用線を待たずに短期間で」という要件に合いません。",["AWS Direct Connect"]],"3":["Global Accelerator は利用者からアプリケーションへの通信を高速化するサービスで、拠点と VPC 間の VPN 接続は提供しません。",["AWS Global Accelerator"]]},"CLF-C02-175":{"0":["AWS グローバルネットワークのバックボーン回線は AWS が構築・管理するもので、顧客が VPC で定義・設定するものではありません。",["バックボーン回線"]],"1":["エッジロケーションの配置は AWS が決めるインフラで、顧客が VPC の設定として定義することはできません。",["エッジロケーションの配置"]],"2":["AZ の物理的な所在地は AWS が管理し、顧客は選ぶだけで定義はできません。VPC で顧客が決めるのは IP 範囲やルートです。",["物理的な所在地"]]},"CLF-C02-176":{"0":["SQL インジェクション攻撃のブロックは AWS WAF の役割で、DNS サービスの Route 53 は提供しません。",["SQL インジェクション攻撃のブロック"]],"1":["複数の EC2 インスタンスへの HTTP リクエストの負荷分散は Elastic Load Balancing の役割で、Route 53 の機能ではありません。",["HTTP リクエストの負荷分散"]],"2":["エッジロケーションでの静的コンテンツのキャッシュは CloudFront の機能で、Route 53 は名前解決とルーティングを担います。",["静的コンテンツのキャッシュ"]]},"CLF-C02-177":{"0":["CloudFront の配信元にしても、インスタンスからインターネット上のサーバーへ更新プログラムを取りに行く経路にはなりません。",["Amazon CloudFront の配信元にする"]],"1":["パブリック IP アドレスを割り当てるとインターネット側からも到達可能になり、外部からの直接接続を防ぐ要件に反します。",["パブリック IP アドレスを割り当てる"]],"3":["VPC ピアリング接続は VPC 同士をつなぐもので、インターネットへの送信経路にはなりません。",["VPC ピアリング接続"]]},"CLF-C02-178":{"1":["Site-to-Site VPN は拠点のネットワークと VPC をつなぐ接続で、世界中のプレイヤーの通信を高速化したり固定 IP を提供したりはしません。",["AWS Site-to-Site VPN"]],"2":["Route 53 のシンプルルーティングは DNS で宛先を返すだけで、通信経路の改善や固定の接続先 IP アドレスの提供はできません。",["シンプルルーティング"]],"3":["CloudFront は主に HTTP/HTTPS のコンテンツ配信向けで、UDP のゲーム通信の高速化や固定 IP アドレスの提供には向きません。",["Amazon CloudFront"]]},"CLF-C02-179":{"0":["NAT ゲートウェイはプライベートサブネットからインターネットへ送信するためのもので、VPC 同士やオンプレミスを相互接続するハブにはなりません。",["NAT ゲートウェイ"]],"1":["CloudFront はコンテンツのキャッシュ配信サービスで、VPC やオンプレミスのネットワークを相互に接続する機能はありません。",["Amazon CloudFront"]],"2":["インターネットゲートウェイは VPC とインターネットをつなぐもので、多数の VPC やオンプレミスをハブ経由で相互接続できません。",["インターネットゲートウェイ"]]},"CLF-C02-180":{"0":["静的ウェブサイトとして公開すると S3 への通信がインターネット経由になり、データも外部に露出するため、セキュリティ方針に反します。",["静的ウェブサイトとして公開する"]],"1":["パブリック IP アドレスを使うと S3 への通信はインターネット経由になり、「インターネットに出さない」要件を満たせません。",["パブリック IP アドレスを割り当てて"]],"3":["CloudFront はインターネット上のエッジを経由する配信サービスで、VPC からの通信をインターネットに出さずに S3 へ届ける手段ではありません。",["Amazon CloudFront 経由"]]},"CLF-C02-181":{"0":["インターネットゲートウェイはインターネット経由の通信のままで、帯域の不安定さは解消されません。インスタンスタイプの変更も回線品質とは無関係です。",["インターネットゲートウェイを追加し"]],"2":["CloudFront や Global Accelerator は利用者向けの配信や高速化のサービスで、データセンターと AWS をつなぐ回線にはなりません。",["Amazon CloudFront を使い","AWS Global Accelerator に切り替える"]],"3":["Client VPN は個々の端末から接続するためのもので、インターネット経由のため通信品質を安定させる要件も満たせません。",["AWS Client VPN だけを使い続ける"]]},"CLF-C02-182":{"0":["すべてを 1 つのパブリックサブネットに置くと、データベースもインターネットから到達可能になるおそれがあり、要件に反します。",["1 つのパブリックサブネット"]],"1":["データベースをパブリックサブネットに置いてパブリック IP を付けると、インターネットから直接到達できてしまいます。",["パブリック IP アドレスを割り当てる"]],"3":["インターネットゲートウェイがない VPC では、インターネット向けの ALB に外部の利用者がアクセスできません。",["インターネットゲートウェイのない VPC"]]},"CLF-C02-183":{"0":["CloudFront はコンテンツ配信のサービスで、本社と AWS 間の主回線にはなりません。コストの高い Direct Connect をバックアップにするのも要件に反します。",["Amazon CloudFront を主回線"]],"1":["インターネット経由の VPN では大量データの帯域が安定せず、バックアップもないため主回線が止まると通信を続けられません。",["バックアップは用意しない"]],"2":["Global Accelerator は利用者からアプリへの通信を高速化するサービスで、本社と VPC をつなぐ専用線ではありません。",["専用線として使う"]]},"CLF-C02-184":{"0":["Glue DataBrew はノーコードでデータを整形・クレンジングするツールで、S3 上のログに SQL でクエリするサービスではありません。",["AWS Glue DataBrew"]],"2":["EMR は Spark や Hadoop のクラスターを使うサービスで、クラスターの構成や管理が必要になり、「サーバーを用意せずに」という要件に合いません。",["Amazon EMR"]],"3":["プロビジョニングされたクラスターは事前にノードを用意して管理する必要があり、サーバーを用意しないという要件に反します。",["プロビジョニングされたクラスター"]]},"CLF-C02-185":{"0":["Textract は文書の画像から文字や表を抽出するサービスで、音声をテキストに変換する機能はありません。",["Amazon Textract"]],"1":["Translate はテキストを別の言語に翻訳するサービスで、通話音声を文字起こしすることはできません。",["Amazon Translate"]],"2":["Polly はテキストを音声に変換するサービスで、求められている音声からテキストへの変換とは逆方向です。",["Amazon Polly"]]},"CLF-C02-186":{"1":["RDS はリレーショナルデータベースで、数千台のセンサーから毎秒届くストリーミングデータを取り込んで複数アプリで処理する用途には向きません。",["Amazon RDS"]],"2":["Glacier Flexible Retrieval はアーカイブ用のストレージで、リアルタイムのデータ取り込みや処理には使えません。",["Glacier Flexible Retrieval"]],"3":["DataSync はストレージ間でファイルやオブジェクトを転送するサービスで、リアルタイムのストリーム処理には向きません。",["AWS DataSync"]]},"CLF-C02-187":{"0":["Polly はテキストを音声に変換するサービスで、画像に写った物体の検出や不適切な画像の判別はできません。",["Amazon Polly"]],"2":["Translate はテキストの翻訳サービスで、画像を分析する機能はありません。",["Amazon Translate"]],"3":["Comprehend はテキストから感情やキーフレーズを分析するサービスで、画像の物体検出には使えません。",["Amazon Comprehend"]]},"CLF-C02-188":{"0":["Rekognition は画像や動画の物体・顔などを分析するサービスで、申込書の表や記入欄の項目と値を抽出する用途には向きません。",["Amazon Rekognition"]],"2":["Comprehend は抽出済みのテキストを分析するサービスで、スキャン画像から文字や表を読み取ることはできません。",["Amazon Comprehend"]],"3":["Lex は音声やテキストで対話するチャットボットを作るサービスで、文書画像からの文字抽出はできません。",["Amazon Lex"]]},"CLF-C02-189":{"0":["テキストを自然な音声に変換する専用サービスは Amazon Polly で、Bedrock は基盤モデルを使う生成 AI のサービスです。",["音声に変換する専用のサービス"]],"2":["Bedrock では学習済みの基盤モデルをそのまま使えます。ゼロから学習させる必要はなく、「自社でモデルを学習しない」要件にも反します。",["ゼロから学習させる必要がある"]],"3":["画像の物体や顔の検出に特化した学習済みサービスは Amazon Rekognition で、Bedrock の説明ではありません。",["物体や顔の検出に特化した"]]},"CLF-C02-190":{"0":["Direct Connect はオンプレミスと AWS を専用線でつなぐサービスで、データの変換やスキーマのカタログ管理はできません。",["AWS Direct Connect"]],"1":["ElastiCache はインメモリキャッシュのサービスで、S3 の生データを変換する ETL 処理やデータカタログの機能はありません。",["Amazon ElastiCache"]],"3":["Kinesis Data Streams はストリーミングデータを取り込むサービスで、S3 上のデータを変換する ETL やスキーマのカタログ管理は行いません。",["Kinesis Data Streams"]]},"CLF-C02-191":{"0":["Neptune はグラフデータベースで、クリックログを受信・バッファリングして S3 へ自動配信する機能はありません。",["Amazon Neptune"]],"2":["Glue DataBrew はデータを視覚的に整形するツールで、ストリーミングデータを継続的に受信して S3 へ配信するサービスではありません。",["AWS Glue DataBrew"]],"3":["DataSync はストレージ間でファイルを転送するサービスで、Web サイトのストリーミングデータを受信・バッファリングする用途には向きません。",["AWS DataSync"]]},"CLF-C02-192":{"0":["Athena は S3 上のデータに SQL でクエリするサービスで、既存の Spark や Hadoop のジョブをそのまま動かすクラスター基盤ではありません。",["Amazon Athena"]],"1":["Data Firehose はストリーミングデータを保存先へ配信するサービスで、Spark や Hadoop で大規模データを処理する基盤ではありません。",["Amazon Data Firehose"]],"2":["Lightsail は小規模向けの仮想サーバーで、数百 TB を処理する Spark や Hadoop のクラスターを構築・拡張する用途には向きません。",["Amazon Lightsail"]]},"CLF-C02-193":{"1":["Polly はテキストを音声に変換するサービスで、ログの検索・可視化や全文検索の機能はありません。",["Amazon Polly"]],"2":["DocumentDB は MongoDB 互換のドキュメントデータベースで、ログのほぼリアルタイムな可視化や本格的な全文検索には向きません。",["Amazon DocumentDB"]],"3":["Redshift は構造化データを集計するデータウェアハウスで、全文検索やログのほぼリアルタイムな検索・可視化には向きません。",["Amazon Redshift"]]},"CLF-C02-194":{"1":["AWS Glue はデータの変換やカタログ管理を行う ETL サービスで、グラフやダッシュボードで可視化する BI ツールではありません。",["AWS Glue"]],"2":["Kinesis Data Streams はストリーミングデータの取り込みサービスで、経営層がダッシュボードや自然言語で分析する機能はありません。",["Kinesis Data Streams"]],"3":["EMR は Spark などでビッグデータを処理する基盤で、クラスターの管理も必要です。ダッシュボードで閲覧する BI サービスではありません。",["Amazon EMR"]]},"CLF-C02-195":{"0":["Textract は文書から文字や表を抽出する学習済みの AI サービスで、独自のデータでモデルを構築・トレーニングする環境ではありません。",["Amazon Textract"]],"1":["Translate は学習済みの翻訳サービスで、独自モデルのトレーニングや推論エンドポイントのデプロイには使えません。",["Amazon Translate"]],"2":["Rekognition は画像・動画分析の学習済み AI サービスで、データサイエンティストが独自モデルを一から開発・デプロイする環境ではありません。",["Amazon Rekognition"]]},"CLF-C02-196":{"0":["Polly は文書を音声にするだけで、従業員の質問に回答を生成することも、根拠の文書を示すこともできません。",["Amazon Polly で文書を音声に変換"]],"2":["モデルをゼロから学習し直すのは莫大なコストと時間がかかり、「トレーニングのコストを避け、作り直さずに反映」という要件に反します。",["ゼロからトレーニングし直す"]],"3":["Comprehend はキーフレーズなどを抽出するテキスト分析サービスで、質問に対する回答文を生成することはできません。",["そのまま回答として返す"]]},"CLF-C02-197":{"0":["Polly はテキストを音声にするサービスでデータ形式の変換はできず、Lex はチャットボットの構築サービスで SQL による分析はできません。",["Amazon Polly で変換","Amazon Lex でクエリ"]],"1":["DataSync はリアルタイムの収集に向かず、Rekognition は画像分析でデータ変換はできません。Neptune はグラフ DB で S3 上のデータに SQL を実行できません。",["AWS DataSync で S3 に保存","Amazon Rekognition で変換","Amazon Neptune でクエリ"]],"2":["EC2 の自作収集サーバーはサーバー管理が必要で、要件に反します。ElastiCache はキャッシュで、S3 のデータにアドホックな SQL 分析はできません。",["自作の収集サーバー","Amazon ElastiCache でクエリ"]]},"CLF-C02-198":{"1":["Systems Manager は既存のインスタンスのパッチ適用や運用管理を行うサービスで、テンプレートで環境全体を定義して再現するものではありません。",["AWS Systems Manager"]],"2":["Elastic Beanstalk はアプリケーションの実行環境を管理するサービスで、VPC などを含むインフラ全体をテンプレートで定義する用途には向きません。",["AWS Elastic Beanstalk"]],"3":["AWS Config はリソースの構成を記録・評価するサービスで、テンプレートからインフラを作成する機能はありません。",["AWS Config"]]},"CLF-C02-199":{"0":["AWS Artifact は AWS のコンプライアンスレポートを入手するサービスで、メトリクスの収集やアラームの設定はできません。",["AWS Artifact"]],"2":["CloudTrail は API 操作の履歴を記録するサービスで、CPU 使用率などのメトリクスを監視してアラームを出す機能はありません。",["AWS CloudTrail"]],"3":["Trusted Advisor はコストやセキュリティなどのベストプラクティスに沿った推奨を出すサービスで、CPU 使用率のしきい値アラームは設定できません。",["AWS Trusted Advisor"]]},"CLF-C02-200":{"0":["AWS Marketplace はサードパーティのソフトウェアを購入・導入するカタログで、AWS の操作をコマンドで実行する手段ではありません。",["AWS Marketplace"]],"2":["AWS Health Dashboard は AWS のサービス障害やメンテナンスの情報を確認する画面で、操作の実行や自動化はできません。",["AWS Health Dashboard"]],"3":["マネジメントコンソールはブラウザで手動操作する画面で、シェルスクリプトによる定型操作の自動化には向きません。",["AWS マネジメントコンソール"]]},"CLF-C02-201":{"0":["Direct Connect はオンプレミスと AWS をつなぐ専用線のサービスで、ブラウザから CLI を使えるシェル環境は提供しません。",["AWS Direct Connect"]],"1":["WorkSpaces は仮想デスクトップのサービスで、利用するにはデスクトップの準備や CLI の設定が必要です。コンソールからすぐ認証済みの CLI を使う用途には合いません。",["Amazon WorkSpaces"]],"2":["Outposts は AWS のインフラを自社施設に設置するサービスで、ブラウザから CLI を使う手段ではありません。",["AWS Outposts"]]},"CLF-C02-202":{"0":["Inspector は EC2 などの脆弱性を検出するサービスで、コードから実行環境を自動構築する機能はありません。",["Amazon Inspector"]],"1":["Storage Gateway はオンプレミスとクラウドのストレージをつなぐサービスで、Web アプリケーションの環境構築とは関係ありません。",["AWS Storage Gateway"]],"3":["CloudTrail は API 操作を記録するサービスで、ロードバランサーや Auto Scaling の環境を自動で構築・管理することはできません。",["AWS CloudTrail"]]},"CLF-C02-203":{"0":["AWS Config はリソースの構成を記録・評価するサービスで、プログラミング言語でインフラを定義してデプロイする機能はありません。",["AWS Config"]],"1":["CloudWatch はメトリクスやログを監視するサービスで、インフラの定義やデプロイには使えません。",["Amazon CloudWatch"]],"2":["Trusted Advisor はベストプラクティスに基づく推奨を出すサービスで、TypeScript や Python でインフラをコード化する手段ではありません。",["AWS Trusted Advisor"]]},"CLF-C02-204":{"0":["CloudWatch は監視、Artifact はコンプライアンス文書の入手先で、どちらもリリースの流れの管理やコンパイル・テストの実行はできません。",["CloudWatch","Artifact"]],"1":["AWS Backup はバックアップの管理、DataSync はデータ転送のサービスで、CI/CD のパイプラインやビルドの機能はありません。",["AWS Backup と AWS DataSync"]],"3":["CloudTrail は API 操作の記録、Inspector は脆弱性検出のサービスで、リリースの流れの管理やソースコードのビルドは行いません。",["CloudTrail","Inspector"]]},"CLF-C02-205":{"0":["Outposts は AWS のインフラを顧客の施設に設置するもので、通信事業者の 5G ネットワーク内にコンピューティングを置くものではありません。",["AWS Outposts"]],"1":["Local Zones は大都市圏の近くに置かれるインフラで、通信事業者の 5G ネットワーク内には配置されないため、モバイル端末への遅延は Wavelength に劣ります。",["AWS Local Zones"]],"3":["リージョナルエッジキャッシュは CloudFront のキャッシュ層で、AR の処理を実行するコンピューティングを置く場所ではありません。",["リージョナルエッジキャッシュ"]]},"CLF-C02-206":{"0":["AWS Artifact はコンプライアンスレポートの入手先で、リクエストの経路や各サービスの処理時間を追跡する機能はありません。",["AWS Artifact"]],"1":["Macie は S3 内の機密データを検出するサービスで、マイクロサービス間のリクエストの追跡や遅延の分析はできません。",["Amazon Macie"]],"3":["AWS Budgets は費用の予算を監視するサービスで、どのサービスで処理に時間がかかっているかは分かりません。",["AWS Budgets"]]},"CLF-C02-207":{"0":["Inspector は脆弱性を検出するだけでパッチは適用できません。シリアルコンソールで数百台を個別に調査するのは運用負荷が高くなります。",["Amazon Inspector でパッチを自動適用"]],"2":["CodeDeploy はアプリケーションのデプロイ用で、SSH を全開放するとインバウンドの SSH を閉じる方針に反し、攻撃にもさらされます。",["SSH を全開放する"]],"3":["SSH でのログインはポートを閉じる方針に反し、数百台に手作業でパッチを当てる運用負荷も非常に大きくなります。",["順番に SSH でログインし","手作業でパッチを適用"]]},"CLF-C02-208":{"0":["リージョンで実行すると制御データが工場の外に出てしまい、社内規程に反します。距離があるため数ミリ秒の応答も難しくなります。",["最寄りのリージョンで実行し"]],"1":["Wavelength は通信事業者のネットワーク内にあり工場の外になるため、制御データを工場外に出さないという規程を満たせません。",["AWS Wavelength"]],"3":["Local Zones は工場の外にある AWS のインフラのため、制御データが工場外に出てしまい、社内規程を満たせません。",["AWS Local Zones"]]},"CLF-C02-209":{"0":["手作業の設定は設定ミスでリージョン間の構成がずれやすく、表計算での記録ではレビュー後の自動デプロイもできません。",["手作業で設定し","表計算ソフトに記録する"]],"1":["インスタンスのスナップショットをコピーするだけでは、ネットワークなど構成全体の一致や変更履歴の管理、レビュー後の自動デプロイはできません。",["スナップショットを毎晩米国にコピーするだけ"]],"3":["CloudTrail は API 操作を記録するサービスで、リージョン間の設定を自動で一致させる機能はありません。",["設定を自動的に東京と一致させる"]]},"CLF-C02-210":{"0":["Artifact は AWS のコンプライアンスレポートを入手する場で、エラー率の通知や設定変更の履歴の確認には使えません。",["コンプライアンスレポートを取得する"]],"2":["Pricing Calculator は利用料金を見積もるツールで、障害の検知や誰が設定を変更したかの調査には役立ちません。",["AWS Pricing Calculator"]],"4":["Polly はテキストを音声にするサービスで、エラー率の監視や設定変更の履歴の記録はできません。",["エラーメッセージを音声化"]]},"CLF-C02-211":{"0":["Direct Connect はオンプレミスと AWS をつなぐ専用線で、アプリケーション間でメッセージを一時保管する機能はありません。",["AWS Direct Connect"]],"2":["Route 53 は DNS サービスで、アプリケーション間のメッセージをためて処理側のペースで取り出させることはできません。",["Amazon Route 53"]],"3":["EBS は EC2 にアタッチするブロックストレージで、送信側と受信側を疎結合にするメッセージキューの機能はありません。",["Amazon EBS"]]},"CLF-C02-212":{"0":["Lightsail は月額プランの仮想サーバーで、従業員向けの仮想デスクトップ環境を管理・提供するサービスではありません。",["Amazon Lightsail"]],"1":["Amplify は Web やモバイルアプリの開発を支援するサービスで、仮想デスクトップは提供しません。",["AWS Amplify"]],"2":["Amazon Connect はクラウド型のコンタクトセンターのサービスで、在宅勤務用の仮想デスクトップは提供しません。",["Amazon Connect"]]},"CLF-C02-213":{"1":["IoT Core は IoT デバイスをクラウドに接続するサービスで、電話やチャットの顧客対応の機能はありません。",["AWS IoT Core"]],"2":["SQS はアプリケーション間のメッセージキューで、顧客と電話やチャットでやり取りするコンタクトセンターの機能はありません。",["Amazon SQS"]],"3":["WorkSpaces は仮想デスクトップのサービスで、通話の受付やルーティングなどコンタクトセンターの機能は持っていません。",["Amazon WorkSpaces"]]},"CLF-C02-214":{"0":["単一の SQS キューのメッセージは基本的に 1 つのコンシューマーが取り出して処理するため、複数の宛先へ同時にプッシュ配信できません。",["単一キュー"]],"1":["Storage Gateway はオンプレミスとクラウドのストレージをつなぐサービスで、メッセージの配信機能はありません。",["AWS Storage Gateway"]],"2":["ElastiCache はインメモリキャッシュで、1 つのイベントを複数のサブスクライバーへプッシュ配信する用途には向きません。",["Amazon ElastiCache"]]},"CLF-C02-215":{"0":["Amazon Connect はコンタクトセンターのサービスで、イベントをルールで Lambda などに振り分けたりスケジュール実行したりはできません。",["Amazon Connect"]],"2":["Route 53 は DNS による名前解決とルーティングのサービスで、アプリケーションのイベントを振り分ける機能はありません。",["Amazon Route 53"]],"3":["SQS はメッセージをためるキューで、ルールによるターゲットへの振り分けや、決まった時刻のスケジュール実行の機能はありません。",["Amazon SQS"]]},"CLF-C02-216":{"0":["CloudFront はコンテンツのキャッシュ配信サービスで、複数の処理を順番に実行して再試行や分岐を管理する機能はありません。",["Amazon CloudFront"]],"1":["EBS はブロックストレージで、処理の順序付けやエラー時の再試行をワークフローとして管理する機能はありません。",["Amazon EBS"]],"3":["Artifact はコンプライアンス文書の入手先で、業務処理のワークフローを管理するサービスではありません。",["AWS Artifact"]]},"CLF-C02-217":{"0":["WorkSpaces は人が使う仮想デスクトップのサービスで、数万台のセンサー機器を接続してメッセージを受け取る機能はありません。",["Amazon WorkSpaces"]],"1":["Elastic Beanstalk は Web アプリケーションのデプロイを自動化するサービスで、IoT デバイスの安全な接続やメッセージ管理の仕組みは持ちません。",["AWS Elastic Beanstalk"]],"3":["Amazon Connect は電話やチャットのコンタクトセンターのサービスで、センサー機器の接続には使えません。",["Amazon Connect"]]},"CLF-C02-218":{"0":["AWS Batch は大量のバッチジョブを実行するサービスで、Web アプリのホスティングや認証機能は提供しません。",["AWS Batch"]],"2":["EMR は Spark などでビッグデータを処理する基盤で、フロントエンド開発者向けのホスティングや認証の機能はありません。",["Amazon EMR"]],"3":["Direct Connect はオンプレミスと AWS をつなぐ専用線のサービスで、アプリ開発を支援する機能はありません。",["AWS Direct Connect"]]},"CLF-C02-219":{"0":["役割が逆です。SNS には処理の順序や再試行を管理するワークフロー機能がなく、Step Functions は 1 つのイベントを複数の宛先へ同時配信する用途向けではありません。",["Amazon SNS","Step Functions"]],"1":["Batch は大量のバッチジョブ向けで注文ごとの順序制御には不向きで、Route 53 は DNS サービスで複数システムへの通知はできません。",["AWS Batch","Route 53"]],"3":["WorkSpaces は仮想デスクトップ、Connect はコンタクトセンターのサービスで、どちらも注文処理のワークフローやイベント配信とは関係ありません。",["WorkSpaces","Connect"]]},"CLF-C02-220":{"1":["EC2 上にメールサーバーを構築すると構築・運用の負荷が大きく、「自前で構築・運用することは避けたい」という要件に反します。",["メールサーバーを構築する"]],"2":["Amazon Connect はコンタクトセンターのサービスで、アプリケーションから大量の確認メールを送信する用途向けではありません。",["Amazon Connect"]],"3":["SQS はアプリケーション間のメッセージキューで、電子メールを送信する機能はありません。",["Simple Queue Service"]]},"CLF-C02-221":{"0":["リザーブドインスタンスは 1 年または 3 年の利用を約束して割引を受けるもので、中断できる処理なら一般にスポットのほうが安くなります。",["リザーブドインスタンス"]],"1":["Compute Savings Plans は一定の利用額を長期間約束して割引を受ける仕組みで、中断を許容できる処理ではスポットより割高になります。",["Compute Savings Plans"]],"3":["オンデマンドインスタンスは割引のない通常料金で、中断を許容できるバッチ処理に使うと最も安い選択になりません。",["オンデマンドインスタンス"]]},"CLF-C02-222":{"0":["実際は逆で、インターネットへの送信（アウトバウンド）が有料、インターネットからの受信（インバウンド）が原則無料です。",["アウトバウンド）は原則無料","受信に料金がかかる"]],"2":["リージョン間のデータ転送は、同じ AWS アカウント内であっても料金がかかります。",["同じ AWS アカウント内であれば無料"]],"3":["異なる AZ 間のデータ転送は、同じ VPC 内であっても原則として料金がかかります。",["同じ VPC 内であれば常に無料"]]},"CLF-C02-223":{"0":["EC2 Instance Savings Plans は 1 年または 3 年の利用額をコミットして割引を受ける仕組みで、長期契約が前提です。",["Savings Plans"]],"2":["リザーブドインスタンスは 1 年または 3 年の期間を契約して割引を受けるもので、「長期契約なし」の条件に合いません。",["リザーブドインスタンス"]],"3":["3 年契約は長期契約そのもので、使った分だけ支払う方式ではありません。Dedicated Hosts は物理サーバーを専有するオプションです。",["3 年契約"]]},"CLF-C02-224":{"1":["Lambda の料金はリクエスト数と実行時間・メモリ量で決まり、コードの行数は料金に影響しません。",["コードの行数に応じて課金"]],"2":["Lambda は実行していない時間には課金されません。作成しただけで時間単位の料金がかかるのは EC2 のような常時稼働型の考え方です。",["実行の有無にかかわらず 1 時間単位で課金"]],"3":["Lambda に関数ごとの月額固定料金はなく、実行回数（リクエスト数）と実行時間に応じた従量課金です。",["月額固定の料金","実行回数は料金に影響しない"]]},"CLF-C02-225":{"0":["S3 の料金は保存量・リクエスト数・データ転送量などで決まり、バケットを作成した IAM ユーザーの数は関係ありません。",["IAM ユーザーの数"]],"1":["マネジメントコンソールへのサインインに料金はかからず、その回数が S3 の料金に影響することはありません。",["サインインした回数"]],"4":["バケット名の文字数は料金に影響しません。S3 の料金は保存量やストレージクラス、リクエスト数、転送量で決まります。",["バケット名の文字数"]]},"CLF-C02-226":{"0":["オンデマンドは割引がないため、3 年間稼働し続けるシステムではコストが最も高くなり、コスト削減の要件を満たせません。",["オンデマンドインスタンスのまま"]],"1":["スタンダード RI は割引率が高い反面、期間中にインスタンスファミリーを変更できず、将来の世代切り替えの柔軟性がありません。",["インスタンスファミリーを固定する"]],"3":["スポットインスタンスは AWS の都合で中断される可能性があり、3 年間稼働し続ける基幹システムには向きません。",["スポットインスタンス"]]},"CLF-C02-227":{"0":["スポットインスタンスは共有の物理サーバー上で動き中断もあり得るため、物理サーバーを専有してソケットやコアを把握する要件を満たせません。",["スポットインスタンス"]],"1":["Lambda はサーバーレスで物理サーバーを専有できず、ソケットやコアの情報も把握できないため、サーバー単位のライセンスを持ち込めません。",["AWS Lambda"]],"3":["共有テナンシーでは物理サーバーを他の顧客と共有し、ソケットやコアを把握できないため、ライセンス条件を満たせません。",["共有テナンシー"]]},"CLF-C02-228":{"0":["スタンダード RI は特定のインスタンス構成に縛られ Fargate や Lambda には適用されません。3 年は移行計画に対して長すぎます。",["スタンダードリザーブドインスタンスを 3 年間"]],"1":["スポットインスタンスは中断される可能性があり業務システムには不向きです。Fargate や Lambda への移行後の割引にもなりません。",["すべてスポットインスタンスで実行"]],"3":["EC2 Instance Savings Plans は特定のリージョンとインスタンスファミリーに限定され、Fargate や Lambda への移行後は割引が適用されません。",["特定のリージョンの EC2 Instance Savings Plans"]]},"CLF-C02-229":{"0":["ピークの 30 台分を 3 年分購入すると、セール期間以外は 20 台分が使われず無駄なコストが発生します。",["ピーク時の 30 台分をすべて"]],"2":["スポットは中断される可能性があり、常時必要な 10 台まで任せるとサービスの安定性が損なわれます。",["すべてのインスタンスをスポットインスタンス"]],"3":["常時稼働する 10 台や中断可能な処理にも割引を使わないため、コストを最小限に抑えられません。",["割引は利用しない"]]},"CLF-C02-230":{"0":["スタンダード RI は特定のインスタンスタイプの EC2 にしか適用されず、Fargate や Lambda に移行した分は割引を受けられません。",["スタンダードリザーブドインスタンス"]],"1":["RDS のリザーブドインスタンスはデータベースの料金向けで、EC2・Fargate・Lambda のコンピューティングには適用されません。",["Amazon RDS のリザーブドインスタンス"]],"2":["EC2 Instance Savings Plans は EC2 の利用にしか適用されないため、Fargate や Lambda へ移した後は割引が受けられません。",["Instance Savings Plans"]]},"CLF-C02-231":{"0":["Cost Explorer は過去のコストの分析や予測を行うツールで、予算のしきい値を超えたときにメールで通知する機能は Budgets の役割です。",["AWS Cost Explorer"]],"1":["AWS Artifact はコンプライアンスレポートを入手するサービスで、コストの監視や通知はできません。",["AWS Artifact"]],"2":["Pricing Calculator は利用前に料金を見積もるツールで、実際のコストを監視して通知することはできません。",["AWS Pricing Calculator"]]},"CLF-C02-232":{"0":["AWS Budgets は利用中のコストを予算と比べて通知するサービスで、移行前に想定構成の料金を見積もるツールではありません。",["AWS Budgets"]],"2":["Cost Explorer は実際に発生したコストの分析に使うもので、まだ利用していない構成の料金は見積もれません。",["AWS Cost Explorer"]],"3":["Cost and Usage Report は実際の利用に基づく詳細な請求データで、移行前の見積もりには使えません。",["AWS Cost and Usage Report"]]},"CLF-C02-233":{"1":["Pricing Calculator は料金を見積もるツールで、複数アカウントの請求をまとめたりボリューム割引を合算したりはできません。",["AWS Pricing Calculator"]],"2":["AWS Artifact はコンプライアンス文書の入手先で、請求の統合やボリューム割引の機能はありません。",["AWS Artifact"]],"3":["Trusted Advisor はベストプラクティスに基づく推奨を出すサービスで、複数アカウントの請求を 1 つにまとめる機能はありません。",["AWS Trusted Advisor"]]},"CLF-C02-234":{"0":["Pricing Calculator の結果は事前の見積もりで、実際の利用料金とは一致しないため、請求書上で部門別の実績を把握できません。",["実績の代わりに使う"]],"1":["リージョンで按分すると共通のサービスなどを正しく振り分けられず不正確です。部門の都合でリージョンを決めるのも非現実的です。",["リージョン別の料金で按分する"]],"2":["予算を作るだけではコストに部門の区別が付かず、タグなどで分類しなければ部門別の料金を集計できません。",["予算を作成するだけにする"]]},"CLF-C02-235":{"0":["AWS Artifact はコンプライアンスレポートを入手するサービスで、利用料金の可視化や予測はできません。",["AWS Artifact"]],"1":["Pricing Calculator は利用前に料金を見積もるツールで、過去 12 か月の実績の分析や傾向に基づく予測はできません。",["AWS Pricing Calculator"]],"3":["Health Dashboard は AWS の障害やメンテナンスの情報を確認する画面で、利用料金の分析には使えません。",["AWS Health Dashboard"]]},"CLF-C02-236":{"1":["Pricing Calculator は事前に料金を見積もるツールで、実際のコストの急増を検出して通知する機能はありません。",["AWS Pricing Calculator"]],"2":["AWS Artifact はコンプライアンス文書の入手先で、コストの異常検出とは関係ありません。",["AWS Artifact"]],"3":["Inspector はソフトウェアの脆弱性を検出するサービスで、支出パターンの異常は検出しません。",["Amazon Inspector"]]},"CLF-C02-237":{"0":["Pricing Calculator の見積もりは利用前の想定値で、リソース単位・時間単位の実際の料金と使用量のデータではありません。",["見積もり結果"]],"1":["Health Dashboard のイベント履歴は AWS の障害やメンテナンスの情報で、料金や使用量のデータは含まれません。",["Health Dashboard のイベント履歴"]],"3":["Trusted Advisor のチェック結果は改善の推奨事項で、リソース単位・時間単位の詳細な料金データを S3 に定期出力するものではありません。",["チェック結果"]]},"CLF-C02-238":{"1":["Macie は S3 内の機密データを検出するサービスで、インスタンスの使用率に基づくサイズの推奨は行いません。",["Amazon Macie"]],"2":["Shield Advanced は DDoS 攻撃からの保護サービスで、インスタンスタイプの最適化とは関係ありません。",["AWS Shield Advanced"]],"3":["AWS Artifact はコンプライアンス文書の入手先で、EC2 の使用状況を分析して推奨を出す機能はありません。",["AWS Artifact"]]},"CLF-C02-239":{"0":["見積もりを示して依頼するだけでは実際のコストを監視も通知もできず、超過時に自動で制限をかけることもできません。",["超えないよう研究者に依頼する"]],"1":["毎日の手作業での確認と削除は運用負荷が大きく、見落としもあり得ます。自動的な制限にもなりません。",["手作業でリソースを削除する"]],"2":["Trusted Advisor はベストプラクティスの推奨を出すもので、予算に近づいた通知や超過時の自動制限はできません。",["Trusted Advisor のチェックを毎週確認"]]},"CLF-C02-240":{"0":["1 つのアカウントにまとめて合計金額だけを共有しても、事業部ごとの費用や無駄なリソースの責任者は分かりません。",["請求書の合計金額だけ"]],"2":["スポットは中断される可能性があり、すべてのワークロードに適するわけではありません。費用の配分を明確にする対策にもなりません。",["スポットインスタンスだけを使うよう義務付ける"]],"3":["AWS Artifact はコンプライアンス文書を入手するサービスで、事業部別の費用レポートは提供しません。",["事業部別の費用レポート"]]},"CLF-C02-241":{"2":["Business Support+ は 24 時間 365 日の技術サポートを提供しますが、テクニカルアカウントマネージャーは付きません。",["Business Support+"]],"3":["re:Post はコミュニティの Q&A サービスでサポートプランではなく、テクニカルアカウントマネージャーの支援は含まれません。",["AWS re:Post のコミュニティ"]],"4":["Basic Support は無料のプランで、技術サポートのケースもテクニカルアカウントマネージャーも含まれません。",["Basic Support"]]},"CLF-C02-242":{"1":["Health Dashboard は AWS 側の障害やメンテナンスの情報を示すもので、アカウントの改善点を推奨する機能はありません。",["AWS Health Dashboard"]],"2":["AWS Config は自分で定めたルールに対する設定の準拠を評価するサービスで、コストや耐障害性まで含めた推奨を自動で示すものではありません。",["AWS Config"]],"3":["Compute Optimizer はコンピューティングリソースのサイズの推奨に特化しており、セキュリティや耐障害性の観点は扱いません。",["AWS Compute Optimizer"]]},"CLF-C02-243":{"0":["AWS Marketplace はサードパーティのソフトウェアを購入するカタログで、技術的な質問を投稿する Q&A サービスではありません。",["AWS Marketplace"]],"1":["AWS Budgets はコストの予算を管理するサービスで、コミュニティで質問して回答を得る仕組みはありません。",["AWS Budgets"]],"2":["AWS Artifact はコンプライアンス文書を入手するサービスで、技術的な質問を投稿できる場ではありません。",["AWS Artifact"]]},"CLF-C02-244":{"0":["AWS Artifact はコンプライアンスレポートの入手先で、AWS 側の障害やメンテナンスの情報は確認できません。",["AWS Artifact"]],"1":["Cost Explorer はコストを分析するツールで、自社リソースに影響する障害やメンテナンスの情報は提供しません。",["AWS Cost Explorer"]],"3":["Pricing Calculator は料金を見積もるツールで、AWS サービスの状態やメンテナンス予定は確認できません。",["AWS Pricing Calculator"]]},"CLF-C02-245":{"1":["AWS Artifact はコンプライアンス文書を入手するサービスで、サードパーティ製品の比較や購入はできません。",["AWS Artifact"]],"2":["Trusted Advisor はベストプラクティスに基づく推奨を出すサービスで、ファイアウォール製品を購入して AWS の請求にまとめる機能はありません。",["AWS Trusted Advisor"]],"3":["re:Post はコミュニティの Q&A サービスで、製品の情報を得られても購入や AWS の請求への統合はできません。",["AWS re:Post"]]},"CLF-C02-246":{"1":["Trusted Advisor はアカウントを自動でチェックして推奨を示すサービスで、移行作業を代行するものではありません。",["Trusted Advisor に移行作業を依頼する"]],"2":["Health Dashboard は AWS の障害やメンテナンスの情報を確認する画面で、移行業者を検索する機能はありません。",["Health Dashboard で移行業者を検索"]],"3":["AWS Budgets はコストの予算を管理するサービスで、移行計画の作成や専門企業の紹介には使えません。",["Budgets で移行計画を作成"]]},"CLF-C02-247":{"0":["Enterprise Support は TAM を含む上位プランで、TAM が不要で費用を抑えたいという要件に対して割高になります。",["Enterprise Support"]],"1":["Basic Support には技術サポートのケースが含まれず、24 時間 365 日の問い合わせや本番停止時の迅速な応答を受けられません。",["Basic Support"]],"2":["Unified Operations Support は Enterprise よりさらに上位で TAM も含まれるため、費用を抑える要件に反します。",["Unified Operations"]]},"CLF-C02-248":{"0":["Cost and Usage Report は料金と使用量の詳細データで、設計のベストプラクティスや構築手順は載っていません。",["AWS Cost and Usage Report"]],"1":["Budgets のアラートはコストが予算を超えそうなときの通知で、設計や構築手順を学ぶ資料ではありません。",["AWS Budgets のアラート"]],"2":["Artifact の契約書は AWS とのコンプライアンス関連の契約で、設計のベストプラクティスを調べる資料ではありません。",["AWS Artifact の契約書"]]},"CLF-C02-249":{"0":["AWS Artifact はコンプライアンス文書を入手するサービスで、Trusted Advisor と同じチェックを実行する機能はありません。",["AWS Artifact で同じチェックを実行"]],"2":["Trusted Advisor で使えるチェックはプランによって異なり、Basic Support では一部のみです。ブラウザーの問題ではありません。",["すべてのプランで同じチェックが利用できる"]],"3":["Trusted Advisor は Basic Support でも一部のチェックが使え、全チェックも Business Support+ 以上で利用できます。Enterprise は必須ではありません。",["Trusted Advisor 自体を利用できない"]]},"CLF-C02-250":{"0":["Unified Operations Support も要件は満たしますが、Enterprise Support よりさらに上位で費用が高く、最も費用を抑えたプランになりません。",["Unified Operations"]],"1":["Business Support+ にはテクニカルアカウントマネージャーが付かないため、専任の TAM から継続的に助言を受ける要件を満たせません。",["Business Support+"]],"3":["Basic Support には技術サポートのケースも TAM も含まれず、システム停止時の 15 分以内の応答も受けられません。",["Basic Support"]]},"DEA-C01-126":{"0":["Scan はテーブルの読み込みキャパシティを消費するため、毎日の全件読み取りで本番アプリケーションの性能に影響が出ます。",["毎日 Scan して"]],"2":["全項目を GetItem で 1 件ずつ読むと読み込みキャパシティを大量に消費し、本番の性能に影響します。全キーの把握も必要で非効率です。",["全項目を GetItem して"]],"3":["Streams は変更された項目だけを記録し、保持期間も 24 時間です。テーブルの全データを書き出す用途には使えません。",["DynamoDB Streams"]]},"DEA-C01-127":{"0":["現行バージョンを期限切れにすると最新データが削除マーカーに置き換わってしまいます。問題は蓄積する非現行バージョンであり、対象が逆です。",["現行バージョンを 30 日後に削除する"]],"2":["バージョニングを停止すると誤削除からの復旧ができなくなり、すでに蓄積した古いバージョンも残るため料金は下がりません。",["バージョニングを停止し","既存の古いバージョンは残す"]],"3":["Deep Archive に移しても古いバージョンは削除されず蓄積し続けます。最低保存期間 180 日や取り出し時間も、日次で上書きするデータに不向きです。",["S3 Glacier Deep Archive に移す"]]},"DEA-C01-128":{"0":["月 1 回の手作業では新しいオブジェクトが自動・継続的に複製されず、コピー漏れや運用負荷の問題もあります。",["毎月、手作業で"]],"1":["Transfer Acceleration はエッジロケーション経由で S3 へのアップロードを高速化する機能で、別リージョンへの複製は行いません。",["S3 Transfer Acceleration"]],"2":["ライフサイクルルールはストレージクラスの移行や削除を行う機能で、別リージョンへオブジェクトを移す機能はありません。",["ライフサイクルルールで別リージョンへ移行"]]},"DEA-C01-129":{"1":["ノード数を増やしても性能や容量が増えるだけで、リージョン障害時に別リージョンでクラスターを復元する手段にはなりません。",["ノード数を増やす"]],"2":["毎晩の UNLOAD と COPY のスクリプトは自前での運用・監視が必要で、スナップショットの自動コピーに比べて運用負荷が大きくなります。",["スクリプトを運用する"]],"3":["同じリージョン内のスナップショットはリージョン障害時には使えず、別リージョンで復元できません。手動取得の運用負荷もあります。",["同じリージョンで手動スナップショット"]]},"DEA-C01-130":{"0":["Transfer Acceleration の速度比較ツールはアップロード速度を比べるもので、オブジェクトのアクセスパターンは分析できません。",["Transfer Acceleration の速度比較ツール"]],"1":["インベントリはオブジェクトの一覧やメタデータを出力するもので、暗号化状態を見てもアクセス頻度や移行時期は判断できません。",["暗号化状態を一覧化する"]],"3":["オブジェクトロックは WORM で削除や上書きを防ぐ機能で、アクセス状況の分析とは無関係です。",["S3 オブジェクトロック"]]},"DEA-C01-131":{"1":["タグを付けてもオブジェクト数は変わらず、移行リクエスト料金やメタデータ容量は減りません。タグ自体にも料金がかかります。",["タグを付け","タグ単位でルールを分ける"]],"2":["移行日数を短くしてもオブジェクトごとの移行料金とメタデータ容量は変わらず、むしろその負担が早く発生します。",["30 日に短縮する"]],"3":["Instant Retrieval は保存単価が Flexible Retrieval より高く、オブジェクト単位の移行料金も残ります。年 1 回の参照には割高です。",["S3 Glacier Instant Retrieval"]]},"DEA-C01-132":{"0":["バージョニングを有効にすると削除したファイルの古いバージョンが S3 に残るため、データの物理的な除去と逆の結果になります。",["S3 のバージョニングを有効にする"]],"1":["パーティション射影はパーティション情報の取得を高速化する機能で、行の削除や古いスナップショットの除去とは無関係です。",["パーティション射影"]],"3":["タイムトラベルは削除前のデータを参照する操作で、削除済みデータを参照できない状態にするという要件と逆です。",["タイムトラベルクエリ"]]},"DEA-C01-133":{"0":["Deep Archive には 180 日の最低保存期間があり、20 日で削除しても残りの期間分が課金されます。取り出しにも時間がかかります。",["S3 Glacier Deep Archive"]],"1":["Glacier Flexible Retrieval は最低保存期間が 90 日で、20 日で削除すると早期削除料金が発生します。まれな参照にも取り出し料金と時間がかかります。",["S3 Glacier Flexible Retrieval"]],"2":["One Zone - 低頻度アクセスにも 30 日の最低保存期間があり、20 日で削除すると残り期間分が課金されてかえって高くなります。",["S3 One Zone - 低頻度アクセス"]]},"DEA-C01-134":{"0":["日付を VARCHAR にすると範囲比較やゾーンマップの効率が落ち、ストレージも増えます。クエリの高速化にはつながりません。",["VARCHAR 型に変更する"]],"2":["分散キーはスライスへの行の配置を決めるもので、日付範囲の絞り込みでブロックを飛ばす効果はありません。特定スライスへの偏りも生じやすくなります。",["分散キーに設定する"]],"3":["ALL 分散はテーブルを全ノードにコピーするもので、小さなディメンション向けです。日付範囲の絞り込みは速くならずストレージも増えます。",["分散スタイルを ALL にする"]]},"DEA-C01-135":{"0":["第三正規形の OLTP モデルは更新処理の整合性を重視した設計で、ファクトとディメンションに分ける分析向けモデルではありません。",["第三正規形のみで構成した OLTP モデル"]],"1":["グラフモデルはノードとエッジで関係を表すモデルで、数値のファクトと属性のディメンションに分ける構造ではありません。",["グラフモデル"]],"2":["キーバリューモデルはキーで値を取得する単純な構造で、ファクトテーブルとディメンションテーブルによる分析モデルではありません。",["キーバリューモデル"]]},"DEA-C01-136":{"0":["RAW は圧縮エンコードの指定で、データの配置には影響しません。結合時の再分散は解消されず、I/O が増えます。",["圧縮なし（RAW）"]],"1":["ファクト側の分散キーと一致しない限り、ディメンションの主キーで KEY 分散しても結合時に再分散が発生します。",["ディメンションの主キーを分散キーとする"]],"3":["EVEN 分散は行を均等に配るだけで結合キーを考慮しないため、結合のたびにデータの再分散やブロードキャストが発生します。",["EVEN 分散"]]},"DEA-C01-137":{"0":["新しい列を含むレコードを除外するとデータが欠落します。列の追加に対応するという要件を満たせません。",["取り込み時に除外する"]],"1":["CSV は列の位置で値を解釈するため、既存の列の間に挿入すると以降の列がずれ、既存のクエリが壊れます。",["既存の列の間に挿入する"]],"3":["列追加のたびに全データを再ロードするのは既存データの書き換えにあたり、コストと運用負荷が大きくなります。",["全データを新しいスキーマで再ロードする"]]},"DEA-C01-138":{"0":["EVEN 分散への変更は行の配置を変えるだけで、毎回同じ重い集計を実行する負荷は残ります。",["EVEN 分散に変更する"]],"1":["同時実行スケーリングは待ち行列の解消に効くもので、1 回の重い集計クエリそのものは速くなりません。追加料金もかかり得ます。",["同時実行スケーリング"]],"2":["通常のビューは結果を保持せず、参照のたびに重い集計を実行するため応答は改善しません。",["通常のビュー"]]},"DEA-C01-139":{"0":["Scan はテーブル全体を読むため遅くコストも高く、別テーブルへのコピーの仕組みも必要になり運用負荷が増えます。",["そちらを Scan する"]],"1":["LSI はテーブル作成時にしか定義できず、パーティションキーも注文 ID のままなので、ステータスごとの取得には使えません。",["ローカルセカンダリインデックスを既存のテーブルに追加する"]],"3":["Scan はフィルター前に全項目を読むため、キャパシティを大量に消費して遅くなります。並べ替えもアプリ側の負担になります。",["Scan にステータスのフィルター式"]]},"DEA-C01-140":{"0":["顧客ごとに別テーブルを作ると数が膨大になり、集計クエリも困難です。変更履歴を有効期間で管理する仕組みにもなりません。",["顧客ごとに別のテーブルを作る"]],"1":["上書き（SCD タイプ 1）では変更前の地域が失われ、過去の売上を当時の地域で集計できなくなります。",["上書きする"]],"2":["地域の列を削除すると地域での集計自体ができなくなり、要件と逆の結果になります。",["地域の列を削除する"]]},"DEA-C01-141":{"1":["ソートキーはスライス内の並び順を決めるもので、結合時のスライス間のデータ移動は減りません。",["ソートキーを order_id 以外の列にする"]],"2":["大きなテーブルを ALL 分散にするとストレージとロード時間の負担が大きく、問題文の前提に反します。",["もう一方を ALL 分散にする"]],"3":["数十億行と数億行のテーブルを全ノードへコピーするのはストレージとロードの負担が大きすぎ、現実的ではありません。",["両方のテーブルを ALL 分散にする"]]},"DEA-C01-142":{"0":["取り込みのたびに列やテーブルを追加するのは、事前定義なしで参照したいという要件に反し、運用負荷も大きくなります。",["取り込みのたびに列を追加する"]],"2":["入れ子の情報を捨てると必要な属性を参照できなくなり、入れ子の属性を SQL で参照する要件を満たせません。",["入れ子の情報を捨てる"]],"3":["VARCHAR に文字列として格納すると SQL で入れ子の属性を直接参照できず、アプリ側の解析が必要になります。",["アプリケーション側で解析する"]]},"DEA-C01-143":{"0":["日付ごとにテーブルを作るとテーブル数が膨大になり、月単位の取得も複数テーブルへのアクセスが必要で非効率です。",["日付ごとに別のテーブルを作る"]],"2":["Scan は店舗に関係なくテーブル全体を読むため、キャパシティを大量に消費して非効率です。",["Scan で日付を絞り込む"]],"3":["パーティションキーを日付だけにすると店舗ごとに絞り込めず、同じ日付にアクセスが集中してホットパーティションになります。",["パーティションキーを日付だけにする"]]},"DEA-C01-144":{"0":["位置で読み取る Hive テーブルでは、列の順序を入れ替えると過去のファイルの値がずれて正しく参照できません。",["列の位置で読み取る設定"]],"1":["区切り文字を変えてもテキストファイルは列の位置に依存するため、名前変更や並べ替えで過去データとの対応が崩れます。",["区切り文字を変えたテキストファイル"]],"2":["ヘッダーのない CSV は列を位置でしか判別できず、列の順序を入れ替えると過去データの値がずれます。",["ヘッダー行のない CSV"]]},"DEA-C01-145":{"1":["パーティションがないと日付で絞り込んでも全データをスキャンするため、Athena のクエリは遅くスキャン料金も高くなります。",["パーティションを使わず"]],"2":["数千万のユーザー ID で分割するとパーティションと小さなファイルが膨大になり、主な絞り込み条件の日付でも効率が出ません。",["ユーザー ID でパーティション分割する"]],"3":["ユーザー ID と秒単位の時刻はカーディナリティが極端に高く、パーティションと小さなファイルが爆発的に増えて遅くなります。",["秒単位の時刻"]]},"DEA-C01-146":{"0":["NONE は互換性チェックを行わないため、新しいスキーマで過去のデータを読めることが保証されません。",["NONE"]],"2":["FORWARD_ALL は古いスキーマで新しいデータを読めることを保証するもので、プロデューサーを先に更新する運用向けです。",["FORWARD_ALL"]],"3":["DISABLED はスキーマの新しいバージョンの登録自体を禁止するもので、スキーマを更新する運用に使えません。",["DISABLED"]]},"DEA-C01-147":{"0":["DynamoDB の項目には 400 KB のサイズ上限があり、1 日分のセンサーデータを 1 項目にまとめると収まらず、書き込みの集中も解消しません。",["1 つの大きな項目にまとめる"]],"1":["スロットリングは 1 つのパーティションキーへの集中によるもので、テーブル全体のキャパシティを増やしてもパーティション単位の上限は超えられません。",["テーブル全体の書き込みキャパシティを大きくする"]],"2":["ソートキーを削除すると同じ日付の項目を複数保存できなくなり、書き込みの集中も解消しません。キーの変更にはテーブルの再作成も必要です。",["ソートキーを削除する"]]},"DEA-C01-148":{"1":["クエリ結果の再利用は同じクエリの結果をキャッシュする機能で、列名変更による NULL の問題は解決しません。",["クエリ結果の再利用"]],"2":["過去のパーティションを削除すると過去データが失われます。今後の列名変更にも対応できません。",["過去のパーティションを削除する"]],"3":["CSV は列の位置に依存するため列の追加や並べ替えに弱く、Parquet より性能も劣ります。スキーマの安全性も損ないます。",["CSV に変更し","列の順序で読み取る"]]},"DEA-C01-149":{"0":["ソートキーに追加してもスライス間の行の配置は変わらず、NULL の集中によるスキューは解消しません。",["ソートキーにも追加する"]],"1":["大きなテーブルを ALL 分散にすると全ノードにコピーされ、ストレージとロード時間の負担が大きすぎます。",["ALL 分散にする"]],"3":["ノードを増やしても NULL の行は 1 つのスライスに集中したままで、スキューは解消せずコストだけが増えます。",["ノード数を 2 倍にする"]]},"DEA-C01-150":{"0":["EVEN 分散では結合キーで共同配置されないため、customer_id での結合のたびに再分散が発生します。",["両方のテーブルを EVEN 分散にする"]],"2":["売上日を分散キーにすると直近 1 週間のデータが一部のスライスに集中し、結合でも再分散が必要になります。",["分散キーを売上日にする"]],"3":["圧縮を無効にするとディスクの読み込み量が増え、クエリはかえって遅くなります。",["すべて RAW にする"]]},"DEA-C01-151":{"0":["対話型セッションは開発やデバッグ向けで、毎晩手動で実行すると運用負荷が増えます。夜間バッチのコスト削減にもなりません。",["対話型セッション","手動実行する"]],"3":["G.4X は DPU が大きく単価が高いワーカーで、ワーカー数を変えずに変更するとコストが増えます。処理量の変動にも対応しません。",["G.4X に変更し"]],"4":["再試行回数を増やすのは失敗への対策で、コストは下がりません。失敗時の再実行でむしろ課金が増える可能性があります。",["最大再試行回数を増やす"]]},"DEA-C01-152":{"1":["スナップショットスケジュールはバックアップの取得タイミングを決めるもので、SQL を定期実行する機能ではありません。",["スナップショットスケジュール"]],"2":["ワークロード管理のキューはクエリの優先度やリソース配分を制御するもので、クエリを定時に自動実行する機能はありません。",["ワークロード管理でキューを追加する"]],"3":["監査ログは接続やクエリの記録を残す機能で、集計 SQL を定期実行する機能はありません。",["監査ログを有効にする"]]},"DEA-C01-153":{"0":["Spectrum は S3 のデータをロードせずに直接クエリする機能で、Redshift のテーブルへ自動でロードするものではありません。",["Redshift Spectrum の外部スキーマ"]],"2":["UNLOAD は Redshift のデータを S3 へ書き出すコマンドで、方向が逆です。S3 から取り込むロードには使えません。",["UNLOAD コマンド"]],"3":["VACUUM は削除済み行の領域回収や再ソートを行うメンテナンス処理で、S3 からのロードとは無関係です。",["VACUUM を自動実行する"]]},"DEA-C01-154":{"1":["ジョブブックマークは処理済みデータを記録して再処理を防ぐ機能で、ワーカー数を自動で増減させるものではありません。",["ジョブブックマーク"]],"2":["最大同時実行数は同じジョブを並行して何本実行できるかの設定で、1 回のジョブ内のワーカー数は自動調整されません。",["最大同時実行数を増やす"]],"3":["Flex は開始の遅れを許容する安価な実行クラスで、処理の段階に応じてワーカー数を増減させる機能ではありません。",["Flex 実行クラス"]]},"DEA-C01-155":{"0":["ソートキーはクエリの読み込み効率を上げる設定で、マテリアライズドビューを自動更新する機能ではありません。",["ソートキーを設定する"]],"1":["同時実行スケーリングは待ち行列を解消するために一時的に容量を追加する機能で、ビューの更新とは無関係です。",["同時実行スケーリング"]],"3":["毎回 DROP して再作成するのは手動運用で負荷が大きく、再作成中はビューを参照できません。自動で最新に保つ方法ではありません。",["毎回 DROP して再作成する"]]},"DEA-C01-156":{"1":["all_done は上流が失敗しても下流を実行するため、データが届いていないまま処理が進み、誤った結果になります。",["all_done"]],"3":["固定で遅らせても遅延がそれを超えれば失敗し、根本的な解決になりません。遅延がない日も結果が遅くなります。",["遅延が起きないことを期待する"]],"4":["ワーカーを増やしても上流データの到着の遅れは変わらず、失敗は解消しません。コストが増えるだけです。",["環境クラスを大きくして"]]},"DEA-C01-157":{"0":["Lambda でループして状態を確認するとコードが増え、待機中も課金されます。最大 15 分の実行時間制限にも注意が必要です。",["完了するまでループで状態を確認する"]],"1":["Athena のワークグループはクエリの設定や制限を管理するもので、クエリをスケジュール実行する機能はありません。",["クエリの自動実行を設定する"]],"3":["Glue クローラーの完了で Athena のクエリが自動実行される仕組みはありません。完了を待って結果を渡す制御もできません。",["自動で実行されるのを待つ"]]},"DEA-C01-158":{"0":["実行頻度を上げても毎回すべてのフォルダを走査する点は変わらず、実行が重なってコストも増えます。",["5 分ごとに上げる"]],"1":["MSCK REPAIR TABLE も S3 のフォルダ全体を走査するため、数百万オブジェクトの大規模データでは遅く、根本的な改善になりません。",["MSCK REPAIR TABLE"]],"3":["対象を分けて同時に実行しても全体を走査する量は変わらず、管理が複雑になりコストも減りません。",["複数に分けて同時に実行する"]]},"DEA-C01-159":{"0":["終了保護はクラスターの誤削除を防ぐ機能で、ジョブの自動実行や処理後の自動削除とは逆の働きをします。",["終了保護を有効にする"]],"2":["常時稼働のクラスターは週 1 回のバッチ以外の時間も課金され続け、処理後の不要な課金を防げません。",["常時稼働のクラスター"]],"3":["毎週手動でスクリプトを実行するのでは自動化になりません。クラスターの作成や削除も手作業のまま残ります。",["毎週手動で実行する"]]},"DEA-C01-160":{"0":["名前付きクエリは固定の SQL を保存するだけで、パラメータを渡せません。顧客ごとに保存すると数も膨大で保守性が下がります。",["顧客ごとに名前付きクエリを保存"]],"1":["クエリ結果の再利用は同じクエリの結果をキャッシュする機能で、SQL インジェクション対策や SQL の組み立ての改善にはなりません。",["クエリ結果の再利用"]],"3":["ワークグループはクエリの設定やコスト管理の単位で、SQL のパラメータ化やインジェクション対策の機能はありません。",["顧客ごとにワークグループを作成する"]]},"DEA-C01-161":{"0":["S3 イベント通知は新しく追加・変更されたオブジェクトにだけ発生するため、既存の 5 億個のオブジェクトは処理されません。",["オブジェクトの追加を待つ"]],"1":["1 台の EC2 で 5 億個を順番に処理すると非常に時間がかかり、進捗の追跡や完了レポートも自前で作る必要があります。",["1 台の EC2 インスタンス","順番に呼び出して処理する"]],"2":["ライフサイクルルールはストレージクラスの移行や削除を行う機能で、タグの付与や Lambda の呼び出しはできません。",["S3 ライフサイクルルールでタグを付与する"]]},"DEA-C01-162":{"0":["無条件に 3 回実行すると重複ロードの原因になり、恒久的なエラーの検知も遅れます。どのステップで失敗したかも分かりません。",["無条件に実行する"]],"1":["すべてのエラーで 50 回再試行すると、データの不整合などの恒久的なエラーでも再試行を続け、通知と対応が大きく遅れます。",["すべてのエラーで 50 回再試行する"]],"2":["毎朝の目視確認は現状の手作業と変わらず、一時的なエラーの自動回復も即時の通知もできません。",["毎朝目視で確認する"]]},"DEA-C01-163":{"0":["プロビジョニングクラスターはノードの用意とデータのロードが必要で、インフラなしで単発の調査をする用途に合いません。",["プロビジョニングクラスター"]],"1":["RDS はデータベースインスタンスの用意とデータのロードが必要で、S3 上のログを直接 SQL で調べることはできません。",["Amazon RDS for PostgreSQL"]],"2":["DataBrew はノーコードでデータを整形・前処理するサービスで、SQL による調査を行うものではありません。",["AWS Glue DataBrew"]]},"DEA-C01-164":{"1":["Managed Grafana は運用メトリクスや時系列データの可視化が中心で、経営層向けの BI ダッシュボードには向きません。",["Amazon Managed Grafana"]],"2":["OpenSearch Dashboards は OpenSearch のデータを可視化するもので、Redshift や Athena のデータを使った BI には適しません。",["OpenSearch Dashboards"]],"3":["CloudWatch ダッシュボードは AWS リソースのメトリクスやログの監視用で、業務データの BI 分析には向きません。",["CloudWatch ダッシュボード"]]},"DEA-C01-165":{"0":["スナップショットからの復元はデータのコピーになり、復元後の本番の更新も反映されません。",["スナップショットから"]],"1":["Spectrum は S3 上のデータを外部テーブルとして参照する機能で、別の Redshift クラスターのデータは参照できません。",["Redshift Spectrum の外部スキーマ"]],"2":["UNLOAD と COPY による毎晩の複製はデータのコピーそのもので、運用負荷もかかり最新データも反映されません。",["UNLOAD と COPY でデータを複製する"]]},"DEA-C01-166":{"0":["Redshift Spectrum の外部テーブルが参照できるのは S3 上のデータで、DynamoDB のテーブルを直接クエリすることはできません。",["Redshift Spectrum の外部テーブル"]],"1":["UNLOAD は Redshift のデータを S3 へ書き出すコマンドで、データの移動を伴い、DynamoDB との結合もできません。",["UNLOAD コマンド"]],"2":["TTL は期限切れの項目を自動で削除する機能で、S3 のデータと SQL で結合する機能ではありません。",["DynamoDB の TTL"]]},"DEA-C01-167":{"0":["スキャン上限を下げると上限を超えたクエリが取り消されるだけで、表示は速くならず、ダッシュボードが表示できなくなる恐れもあります。",["スキャン上限を下げる"]],"1":["編集権限の付与は性能やコストと無関係で、最小権限の原則にも反します。",["編集権限を付与する"]],"3":["閲覧者を減らすのは利用の制限であり、改善ではありません。直接クエリのままなので表示の遅さも解消しません。",["閲覧者を減らす"]]},"DEA-C01-168":{"0":["Deep Archive は長期保管用のストレージで、取り出しに時間がかかるため検索やリアルタイムの表示はできません。",["S3 Glacier Deep Archive"]],"2":["DataBrew はデータの前処理を行うサービスで、全文検索やリアルタイムのダッシュボード機能はありません。",["AWS Glue DataBrew"]],"3":["RDS for MySQL は大量ログの全文検索や取り込みに向かず、ほぼリアルタイムのログ分析ダッシュボードの機能もありません。",["Amazon RDS for MySQL"]]},"DEA-C01-169":{"0":["COUNT(*) は重複を含めた行数を数えるため、ユニークユーザー数を求めることはできません。",["COUNT(*)"]],"2":["DISTINCT を正確に計算したうえで UNLOAD する分、処理がかえって重くなり、高速化になりません。",["UNLOAD してから数える"]],"3":["数十億行のテーブルを ALL 分散にすると全ノードにコピーされ負担が大きく、ユニーク数の計算も速くなりません。",["分散スタイルを ALL にする"]]},"DEA-C01-170":{"0":["バケットポリシーでプレフィックスを制限しても、許可された範囲の中で大量にスキャンするクエリは止められません。",["S3 バケットポリシー"]],"1":["結果の再利用は同じクエリの再スキャンを省くだけで、新しいクエリが 1 回でスキャンする量の上限にはなりません。",["クエリ結果の再利用"]],"3":["Budgets は予算超過を通知するだけでクエリの実行は止められず、アカウント全体ではチームごとの制限にもなりません。",["AWS Budgets","アカウント全体"]]},"DEA-C01-171":{"0":["分散スタイルを変えてもキューでの待ちは解消しません。ALL 分散はテーブルの大きさによってはストレージとロードの負担も増えます。",["ALL 分散に変更する"]],"2":["同じキューで同時実行数を 1 にすると、長い ETL の実行中は短いクエリが必ず待たされ、状況が悪化します。",["同時実行数を 1 に制限する"]],"4":["クラスターを縮小すると処理能力が下がり、待ち時間はさらに増えます。サイズを変えない条件にも反します。",["一時的に縮小する"]]},"DEA-C01-172":{"0":["データ共有は Redshift のクラスターやワークグループ間の機能で、Aurora のデータは共有できません。",["データ共有で Aurora のデータを共有する"]],"1":["毎日の UNLOAD と COPY はロードそのもので、在庫数がリアルタイムに反映されません。",["毎日 S3 に UNLOAD してから COPY する"]],"2":["Redshift Spectrum が参照できるのは S3 上のデータで、Aurora のテーブルは直接参照できません。",["Redshift Spectrum"]]},"DEA-C01-173":{"0":["EMR on EC2 ではクラスターの起動と管理が必要で、起動にも数分かかります。管理せず数秒で始める要件に合いません。",["EMR on EC2 クラスターを起動して"]],"1":["Athena の SQL エンジンでは Python は実行できません。Spark での分析もできません。",["SQL クエリエディタで Python を実行する"]],"3":["Quick Sight の計算フィールドはダッシュボード上の簡単な計算用で、Python や Spark での分析はできません。",["計算フィールド"]]},"DEA-C01-174":{"0":["CSV は列指向形式よりスキャン量が増えるため、コストも応答時間も悪化します。",["CSV 形式に戻す"]],"2":["プリペアドステートメントは SQL のパラメータ化の機能で、同じクエリの再スキャンを省く効果はありません。クエリの書き換えも必要です。",["プリペアドステートメントに書き換える"]],"3":["ワークグループを分けても同じクエリのたびにスキャンが発生し、コストと応答時間は改善しません。",["クエリごとにワークグループを分ける"]]},"DEA-C01-175":{"0":["すべてを 1 つの WHERE 句に詰め込むと、月次の集計と前月比較を段階的に表せず、可読性がかえって下がります。",["1 つの WHERE 句に記述する"]],"1":["全列を取得して表計算ソフトで処理すると、スキャン量が増え、手作業で再現性も下がります。クエリの可読性の改善でもありません。",["表計算ソフトで処理する"]],"3":["中間結果を毎回手動で保存・読み込みするのは手間と誤りの原因になり、クエリの可読性の改善になりません。",["毎回手動で CSV に保存して"]]},"DEA-C01-176":{"0":["クエリエディタ v2 は SQL を書いて実行するツールで、SQL を学ばずに自然言語で質問する要件に合いません。",["クエリエディタ v2"]],"2":["メール配信レポートは決まったダッシュボードを定期的に送るもので、その場の質問に答えることはできません。",["メール配信レポート"]],"3":["名前付きクエリは SQL を保存しておく機能で、利用には SQL の知識が必要です。自然言語での質問やグラフでの回答はできません。",["Athena の名前付きクエリ"]]},"DEA-C01-177":{"0":["まれにしか参照しない数 PB のログを Redshift にロードすると、ストレージとクラスターのコストが大きくなりすぎます。",["すべてのログを Redshift にロードし"]],"2":["Athena はクエリごとにスキャンして課金されるため、数百人が絶えず実行する集計では 1 秒未満の安定した応答とコストの両立が難しくなります。",["ダッシュボードも含めて Athena だけで処理する"]],"3":["DynamoDB は集計クエリ向けではなく、Scan で集計するとキャパシティを大量に消費して遅く、コストも高くなります。",["DynamoDB に格納し","Scan で集計する"]]},"DEA-C01-178":{"0":["タイムアウトを短くするとクエリが途中で失敗するだけで、ピーク時の処理能力は増えません。",["タイムアウトを短くして"]],"1":["ノード数を常時 3 倍にすると、使用率 30% 程度の閑散期にも費用がかかり、常時のコストを増やさない条件に反します。",["ノード数を常時 3 倍に増やす"]],"3":["すべてのテーブルを ALL 分散にするとストレージとロードの負担が増え、同時実行の待ち行列も解消しません。",["分散スタイルを ALL に変更する"]]},"DEA-C01-179":{"1":["ジョブメトリクスはメモリや処理量などの数値の推移を示すもので、どこで失敗したかのエラーメッセージは分かりません。",["ジョブメトリクス"]],"2":["S3 サーバーアクセスログはバケットへのリクエストの記録で、Glue ジョブの処理内容や失敗箇所は分かりません。",["S3 サーバーアクセスログ"]],"3":["CloudTrail の S3 データイベントはオブジェクトへの API 呼び出しの記録で、ジョブ実行中のログは確認できません。",["CloudTrail の S3 データイベント"]]},"DEA-C01-180":{"0":["IncomingBytes はストリームに書き込まれたデータ量で、コンシューマーの処理の遅れは分かりません。",["IncomingBytes"]],"2":["PutRecord.Success は書き込み側の成功数を示すもので、コンシューマーが追いついているかは分かりません。",["PutRecord.Success"]],"3":["WriteProvisionedThroughputExceeded は書き込みのスロットリングを示すもので、読み取り側の遅延の監視には使えません。",["WriteProvisionedThroughput"]]},"DEA-C01-181":{"0":["AWS Config はリソースの設定変更の履歴を記録するもので、Lambda のアプリケーションログは検索できません。",["AWS Config の設定履歴"]],"2":["CloudTrail は API 呼び出しの記録で、Lambda 関数が出力した ERROR などのアプリケーションログは含まれません。",["CloudTrail のイベント履歴"]],"3":["手動でダウンロードして集計するのは手間がかかり、複数関数・24 時間分では現実的でなく誤りも生じやすい方法です。",["手動でダウンロードして"]]},"DEA-C01-182":{"0":["インスタンス数を減らすと OpenSearch の処理能力が下がり、配信の失敗はかえって増えます。データ保全にもなりません。",["インスタンス数を減らす"]],"1":["バッファサイズは配信の単位を決めるだけで、配信に失敗したレコードを保持して再投入する仕組みにはなりません。",["バッファサイズを最大にする"]],"3":["暗号化を無効にしてもデータ保全には役立たず、セキュリティが低下するだけです。",["暗号化を無効にする"]]},"DEA-C01-183":{"1":["StartJobRun の記録はジョブの開始を示すだけで、失敗やタイムアウトの結果は分からず通知もできません。",["StartJobRun の API 呼び出しを記録する"]],"3":["タイムアウトを延ばしても失敗そのものは防げず、失敗時の通知にもなりません。",["タイムアウトを延長し"]],"4":["再試行で一部の一時的な失敗は回復しても、最終的に失敗したことを担当者へ通知する仕組みにはなりません。",["再試行で自動的に成功させる"]]},"DEA-C01-184":{"1":["ジョブブックマークは処理済みデータを記録する機能で、失敗や長時間実行を検知して通知することはできません。",["ジョブブックマーク"]],"2":["StartJobRun の検索で分かるのはジョブの開始だけで、失敗や実行時間の超過は検知できません。",["StartJobRun の呼び出しを検索する"]],"3":["クローラーはデータカタログを更新するもので、ジョブの失敗や遅延の通知とは無関係です。",["Glue クローラーのスケジュール"]]},"DEA-C01-185":{"0":["AWS Config のルール評価はリソース設定の準拠状況を示すもので、クエリの実行時間や実行計画は分かりません。",["AWS Config のルール"]],"1":["S3 サーバーアクセスログはバケットへのリクエストの記録で、Redshift のクエリの処理時間は分かりません。",["S3 サーバーアクセスログ"]],"3":["CloudTrail は API 呼び出しの記録で、呼び出し回数は分かってもクエリ内部の段階ごとの処理時間は分かりません。",["ExecuteStatement の呼び出し回数"]]},"DEA-C01-186":{"0":["毎朝の手動クエリでは 5 分間のしきい値超過を即時に検知できず、自動通知にもなりません。",["毎朝手動で実行する"]],"1":["保持期間を短くするとログが早く消えるだけで、文字列の出現回数の監視や通知はできません。",["保持期間を短くする"]],"2":["CloudTrail のデータイベントはリソースへの API 操作の記録で、アプリケーションのログ出力内容は監視できません。",["CloudTrail のデータイベント"]]},"DEA-C01-187":{"1":["DAG ファイルを再アップロードしてもログの送信設定は変わらず、原因調査のためのログは得られません。",["削除して再アップロードする"]],"2":["MWAA はマネージドサービスで、ワーカーに SSH 接続することはできません。",["SSH 接続して"]],"3":["CloudTrail の管理イベントは MWAA の API 呼び出しの記録で、DAG のタスクが失敗した理由は分かりません。",["CloudTrail の管理イベント"]]},"DEA-C01-188":{"1":["重複したままターゲットに格納されるため、全利用者が毎回 DISTINCT を書く必要があり、更新レコードの反映もできません。",["SELECT DISTINCT で除外する"]],"2":["再試行を無効にすると一時的なエラーで処理が止まり、手作業での重複削除は運用負荷が大きく誤りの原因にもなります。",["再試行を無効にし","手動で重複を削除する"]],"3":["Redshift の主キー制約は情報提供用で強制されないため、重複した挿入は拒否されません。",["重複する挿入を Redshift に拒否させる"]]},"DEA-C01-189":{"0":["出力形式を ORC に変えても、結合での特定キーへのデータの偏りは解消しません。",["Parquet から ORC に変更し"]],"3":["Auto Scaling でエグゼキューター数を増やしても、偏ったキーを処理する 1 つのタスクの負荷は変わりません。",["Auto Scaling を有効にして"]],"4":["ワーカーを大きく・多くしてもデータの偏りは残り、1 タスクに処理が集中したままです。コストだけが増えます。",["ワーカー数もさらに 2 倍にする"]]},"DEA-C01-190":{"0":["ジョブブックマークは処理済みデータを記録する機能で、結合キーの偏りによる特定エグゼキューターへのメモリ集中は解消しません。",["ジョブブックマークを無効にする"]],"2":["出力形式を CSV にしても結合時のデータの偏りは変わらずメモリ不足は解消しません。出力サイズが増え、下流の性能も悪化します。",["Parquet から CSV に変更する"]],"4":["タイムアウトを短くしてもメモリの集中は解消せず、失敗が早まるだけです。",["タイムアウトを短くする"]]},"DEA-C01-191":{"0":["テーブル設計に問題はなく、分散スタイルを変えても削除済みの行や未ソート領域、古い統計情報は解消しません。",["分散スタイルを EVEN に変更する"]],"2":["ノードを増やしてもコストが増えるだけで、未ソート領域と古い統計情報による非効率は残ります。",["ノード数を 2 倍にする"]],"3":["WLM のキューの統合はクエリの割り振りを変えるだけで、削除済みの行の回収や統計情報の更新にはなりません。",["WLM のキューを 1 つに統合する"]]},"DEA-C01-192":{"0":["バージョニングの有無はオブジェクトの旧版の保持に関するもので、新しいデータがクエリに表示されない原因にはなりません。",["バージョニングが無効になっている"]],"1":["スキャン上限に達するとクエリ自体が取り消されエラーになるため、最新 1 時間のデータだけが表示されない症状とは合いません。",["スキャン上限に達した"]],"3":["バッファ間隔が長くても配信は遅れるだけで、DeliveryToS3.Success は正常で S3 にオブジェクトも作られているため原因ではありません。",["バッファ間隔が長すぎる"]]},"DEA-C01-193":{"0":["Macie は S3 内の個人情報などの機密データを検出するサービスで、欠損率や値の範囲を検証してパイプラインを止める機能はありません。",["Amazon Macie"]],"2":["S3 インベントリはオブジェクトの一覧やメタデータを出力するもので、データの中身の欠損率や値の範囲は検証できません。",["Amazon S3 インベントリ"]],"3":["スキーマレジストリはスキーマの互換性を管理するもので、値の範囲や欠損率といったデータの中身は検証できません。",["スキーマレジストリ"]]},"DEA-C01-194":{"1":["クローラーが推定するのは列名やデータ型などのスキーマだけで、値の分布や欠損、重複の状況は分かりません。",["推定された列のデータ型を確認する"]],"2":["S3 Storage Lens はストレージの使用量やオブジェクト数を可視化するもので、列ごとの値の分布や欠損は分かりません。",["S3 Storage Lens"]],"3":["Macie は機密データを検出するサービスで、各列の値の分布や欠損、重複といった品質の把握には使えません。",["Amazon Macie"]]},"DEA-C01-195":{"0":["適時性はデータが必要なときに最新であるかという観点で、同じ顧客が重複登録されている問題とは異なります。",["適時性"]],"1":["完全性は必須値の欠落がないかという観点で、同じ実体が重複して存在する問題ではありません。",["完全性"]],"2":["可用性はシステムやデータを必要なときに利用できるかという観点で、データの重複の問題ではありません。",["可用性"]]},"DEA-C01-196":{"0":["Amazon States Language は Step Functions のステートマシンを定義する言語で、データ品質ルールは記述できません。",["Amazon States Language"]],"1":["PartiQL は DynamoDB や Redshift の SUPER 型などに使う SQL 互換のクエリ言語で、Glue Data Quality のルール記述言語ではありません。",["PartiQL"]],"2":["Logs Insights のクエリ言語はログを検索・集計するためのもので、データ品質ルールの定義には使えません。",["Logs Insights のクエリ言語"]]},"DEA-C01-197":{"0":["Managed Service for Apache Flink はストリーミングデータをコードで処理するサービスで、コードなしで品質ルールを確認する用途に合いません。",["Managed Service for Apache Flink"]],"2":["EMR on EC2 はクラスターを管理してコードで処理する基盤で、コードを書かずに統計や品質ルールを確認するアナリスト向けではありません。",["Amazon EMR on EC2"]],"3":["CloudTrail は API 呼び出しの記録で、データセットの統計情報や品質ルールの検証機能はありません。",["AWS CloudTrail"]]},"DEA-C01-198":{"0":["上流の障害でロードが行われないとテーブルには古いデータが残り、行数は 0 件にならないため検知できません。",["行数が 0 件になったら通知する"]],"2":["上流の障害ではロードジョブが起動しないか空振りで成功することがあり、ジョブの失敗通知では検知できない場合があります。",["ロードジョブの失敗を EventBridge で検知し"]],"3":["実行時間のアラームではジョブが起動しない場合や短時間で成功する場合を検知できず、データ鮮度の監視になりません。",["実行時間のメトリクスにアラーム"]]},"DEA-C01-199":{"1":["欠損項目を一律に 0 で埋めると誤ったデータが下流に流れて分析結果を歪め、元の不正な行を調査することもできなくなります。",["すべて 0 を入れて下流に流す"]],"2":["1 行の不正でパイプライン全体を止めると正常な行も予定どおり届かず、手動修正の運用負荷もかかります。",["パイプライン全体を停止し"]],"3":["ファイル全体を削除すると正常な行も失われ、不正な行を後で調査・修正するという要件も満たせません。",["ファイル全体を削除する"]]},"DEA-C01-200":{"0":["すべての行を破棄すると合格した行も本番に書き込まれず、違反行だけを別の出力先に分ける要件を満たせません。",["すべての行を破棄する"]],"1":["ジョブブックマークは処理済みのデータを記録して再処理を防ぐ機能で、品質ルールに違反した行を除外することはできません。",["ジョブブックマークで違反した行を除外する"]],"2":["クローラーはスキーマを推定してカタログに登録するもので、行単位のルール違反は検出できません。",["Glue クローラーで違反した行を検出する"]]},"DEA-C01-201":{"0":["Storage Lens はストレージのオブジェクト数や容量を確認するもので、ロード件数や値の傾向から外れた変化を自動検知できません。",["ストレージレンズ"]],"1":["固定の下限値では季節やキャンペーンによる変動で誤検知が多いという課題が残り、毎月の手動見直しも運用負荷になります。",["固定値で設定し","毎月手動で見直す"]],"2":["タイムアウトはジョブの実行時間の上限で、件数や値の急な変化を検知する機能ではありません。",["タイムアウトを短くする"]]},"DEA-C01-202":{"1":["ColumnLength は値の長さを検証するだけで、customer_id が顧客マスタに存在するかは確認できません。",["ColumnLength ルール"]],"2":["注文テーブルでは同じ顧客が何度も現れるため IsUnique は不適切で、顧客マスタとの対応も検証できません。",["IsUnique ルール"]],"3":["RowCount は行数を検証するだけで、顧客マスタに存在しない customer_id の割合は分かりません。",["RowCount ルール"]]},"DEA-C01-203":{"1":["ソートキーはクエリ性能のための設定で、ロードしたデータの欠落を検知する機能ではありません。",["ソートキーを設定する"]],"2":["終了コード 0 は処理が正常に終わったことを示すだけで、行の欠落がないことは保証されません。",["終了コード 0 で終われば正しい"]],"3":["実行時間が同程度でも一部の行が欠落している可能性はあり、データの完全性の確認になりません。",["実行時間が前日と同程度かを確認する"]]},"DEA-C01-204":{"0":["本番テーブルに直接書き込むと、翌日のチェックまで誤ったデータがダッシュボードに公開されてしまいます。",["本番テーブルに直接書き込み","翌日に品質チェック"]],"2":["本番テーブルを空にするとダッシュボードが使えなくなり、前日のデータを表示し続けるという要件を満たせません。",["本番テーブルを空にする"]],"3":["利用者の報告に頼ると、誤ったデータが公開された後でしか気付けず、公開を防ぐ最優先の要件を満たせません。",["報告するよう依頼する"]]},"DEA-C01-205":{"0":["スキーマの変更をそのまま受け入れると、列の入れ替わりや名前の変更が検知されず、誤ったデータがロードされ続けます。",["変更をそのまま受け入れる"]],"3":["位置だけでマッピングすると、列の順序が入れ替わったときに誤った列へ値が入る問題がそのまま残ります。",["列の位置だけでマッピングする"]],"4":["すべて VARCHAR にすると型の不一致でのエラーすら起きなくなり、誤った値が検知されないまま取り込まれます。",["すべて VARCHAR 型に変更する"]]},"DEA-C01-206":{"0":["S3 のテキストファイルでは暗号化やアクセス管理、ローテーションの仕組みがなく、認証情報の安全な管理になりません。",["テキストファイルに保存する"]],"2":["ジョブのデフォルト引数はコンソールや API から平文で参照でき、認証情報を安全に扱えません。",["ジョブのデフォルト引数に設定する"]],"3":["String パラメータは暗号化されず、権限があれば平文で読めます。ローテーションの機能もありません。",["暗号化せずに","String パラメータ"]]},"DEA-C01-207":{"0":["アクセスキーは長期的な認証情報で、ジョブの引数に渡すと平文で見えて漏えいのリスクがあります。",["アクセスキーをジョブの引数で渡す"]],"2":["ルートユーザーはアカウントのすべての権限を持ち、日常の処理に使うのは最小権限の原則に反し非常に危険です。",["ルートユーザーの認証情報"]],"3":["スクリプトに長期的なアクセスキーを埋め込むと、コードの共有や保存を通じて漏えいするリスクがあります。",["スクリプトに埋め込む"]]},"DEA-C01-208":{"1":["手作業での毎月の変更は自動化にならず、パラメータの更新とアプリケーションへの反映を誤るリスクもあります。",["手作業で毎月変更する"]],"2":["メールでの配布はパスワードの漏えいリスクが高く、定期的な自動変更も実現できません。",["メールで関係者に配布する"]],"3":["パスワードを変更しない運用は、定期的に自動で変更するという要件そのものに反し、漏えい時のリスクも残ります。",["変更しない運用にする"]]},"DEA-C01-209":{"0":["ネットワークを制限しても認証の代わりにはならず、パスワードを廃止すると社内の誰でも接続できてしまいます。",["パスワードを廃止する"]],"1":["共通の DB ユーザーでは個人を識別できず、共有パスワードは長期的な認証情報のままで一時的な認証情報になりません。",["共通の DB ユーザーを作成し"]],"4":["パスワードの定期変更は個別のパスワード管理を続けることになり、一時的な認証情報への置き換えにはなりません。",["90 日ごとに変更するポリシー"]]},"DEA-C01-210":{"1":["インターネットゲートウェイを使う経路はインターネット経由であり、インターネットを経由させない方針に反します。",["インターネットゲートウェイを VPC にアタッチし"]],"3":["マルチリージョンアクセスポイントは複数リージョンのバケットへのアクセスを束ねる機能で、VPC からのプライベート接続の手段ではありません。",["マルチリージョンアクセスポイント"]],"4":["パブリックサブネットはインターネットゲートウェイ経由で通信するため、インターネットを経由させない方針に反します。",["パブリックサブネットに変更する"]]},"DEA-C01-211":{"0":["IAM ユーザーのアクセスキーは長期的な認証情報で、環境変数に置くと漏えいのリスクがあり、要件に反します。",["アクセスキーを Lambda の環境変数に設定する"]],"2":["パブリック書き込みを許可すると誰でもデータを書き込めてしまい、データレイクのセキュリティが失われます。",["パブリック書き込み可能にする"]],"3":["ルートユーザーでの手動アップロードは自動処理にならず、最も強い権限を日常作業に使うため非常に危険です。",["ルートユーザーでログインして"]]},"DEA-C01-212":{"0":["EC2 への SSH と psql の実行は、管理するサーバーと鍵が増え、ドライバーや接続の管理も避けられません。",["EC2 に SSH 接続して psql を実行する"]],"1":["JDBC ドライバーの同梱と平文パスワードは、まさに避けたい内容で、認証情報の漏えいリスクもあります。",["JDBC ドライバーを含め","平文で設定する"]],"2":["パブリックアクセスを許可すると攻撃対象が増え、固定の DB ユーザーではパスワードの管理も必要なままです。",["パブリックアクセス可能にして"]]},"DEA-C01-213":{"0":["セキュリティグループはネットワークレベルの制御にすぎず、クライアントの認証やトピック単位の操作の認可はできません。",["セキュリティグループだけで"]],"1":["認証なしの平文接続では誰でも接続でき通信も暗号化されないため、トピック単位の制御もできません。",["認証なしの平文接続"]],"2":["同じ証明書を共有するとクライアントを識別できず、漏えい時の影響も全体に及びます。トピック単位の IAM 制御もできません。",["同じ証明書を共有する"]]},"DEA-C01-214":{"0":["共通のマスターユーザーでは利用者を識別できず全権限を与えることになり、IdP のグループに応じた制限もできません。",["共通のマスターユーザー"]],"1":["ノード数を増やすのは性能や容量の拡張で、SAML 認証やインデックス単位のアクセス制御とは無関係です。",["ノード数を増やす"]],"3":["URL を知っていれば誰でも使える運用は認証がなく、グループに応じたアクセス制限もできません。",["URL を知っている人だけが使う"]]},"DEA-C01-215":{"0":["ローテーションしても長期的なアクセスキーであることは変わらず、廃止したいという要件を満たせません。手作業の負荷もあります。",["1 年ごとに手作業でローテーション"]],"1":["認証なしで書き込ませると誰でもデータを送信でき、セキュリティ上許されません。Kinesis に認証なしの書き込み機能もありません。",["認証なしで書き込ませる"]],"3":["保存場所を設定ファイルに移しても長期的なアクセスキーのままで、漏えいリスクも廃止の要件も解決しません。",["設定ファイルに移す"]]},"DEA-C01-216":{"0":["プリンシパルをすべてのアカウントにすると、誰でもロールを引き受けられる可能性があり、危険性が大きく増します。",["すべての AWS アカウント（*）"]],"1":["セッション時間を延ばすと認証情報の有効期間が長くなるだけで、別の顧客による不正なロール利用は防げません。",["最大セッション時間を 12 時間に延ばす"]],"2":["IAM ユーザーのアクセスキーは長期的な認証情報で漏えいのリスクがあり、混乱した代理問題の対策にもなりません。",["IAM ユーザーとアクセスキーを発行する"]]},"DEA-C01-217":{"0":["パスワードをコードに書くことは要件に反し、関数ごとのユーザーを作っても接続数の上限の問題は解決しません。",["パスワードをコードに書く"]],"2":["インスタンスを最大にしても急増する接続には限界があり、コストも増えます。環境変数のパスワードも要件に反します。",["パスワードは環境変数に保存する"]],"3":["同時実行数を 1 にするとアプリケーションの処理能力が大きく落ち、パスワードの扱いも改善しません。",["同時実行数を 1 に制限する"]]},"DEA-C01-218":{"0":["AdministratorAccess はすべての操作を許可するため、読み取りだけのジョブには過剰で最小権限の原則に反します。",["AdministratorAccess"]],"1":["テーブルの削除権限は読み取りだけのジョブに不要で、全データベースを対象にすると誤操作時の影響も大きくなります。",["glue:DeleteTable を許可する"]],"2":["すべてのリソースへの glue:* は削除や変更を含む過剰な権限で、最小権限の原則に反します。",["glue:* を許可する"]]},"DEA-C01-219":{"1":["1 つのユーザーを共有すると個人を識別できず監査ができません。部署ごとに異なる権限も与えられません。",["1 つのデータベースユーザーを共有する"]],"2":["部署ごとにクラスターを作るとコストと運用負荷が大きく増え、権限管理の簡素化になりません。",["部署ごとに別のクラスターを作る"]],"3":["スーパーユーザー権限はすべての操作を許可するため、部署ごとのスキーマに限定する要件と最小権限の原則に反します。",["スーパーユーザー権限"]]},"DEA-C01-220":{"0":["ビューだけでは元のテーブルへの直接アクセスを防げず、SQL を共有しても権限の制御にはなりません。",["ビューの SQL を Wiki で共有する"]],"2":["IAM ポリシーではテーブル単位までしか制御できず、個人を特定する列や特定地域の行を絞り込めません。",["glue:GetTable の対象を顧客テーブルに限定する"]],"3":["バケットポリシーはファイルやプレフィックス単位の制御で、列を隠すことはできません。地域ごとの配置もデータの分割が前提になります。",["S3 バケットポリシー"]]},"DEA-C01-221":{"0":["ダッシュボードのフィルターは利用者が変更できるため、他の支店の行も参照でき、アクセス制御になりません。",["フィルターを初期値に設定する"]],"1":["支店ごとにテーブルを分割するのは避けたい運用そのもので、テーブル数の増加で管理負荷も大きくなります。",["支店ごとにテーブルを分割する"]],"3":["列レベルの GRANT は列を隠すだけで、行を支店ごとに絞り込むことはできません。",["列レベルの GRANT"]]},"DEA-C01-222":{"0":["すべてのチームに s3:* を許可すると、チームごとのプレフィックスや VPC の制限がなくなり、最小権限の原則に反します。",["すべてのチームに s3:* を許可する"]],"1":["チームごとにバケットをコピーすると、ストレージ料金と同期の運用負荷が大きく増え、データの不整合も生じます。",["バケットのコピーを作り","毎晩同期する"]],"3":["ACL は粒度が粗く、プレフィックスや VPC の条件を表現できません。現在は ACL を無効化することが推奨されています。",["バケットの ACL"]]},"DEA-C01-223":{"0":["地域ごとにダッシュボードを作ると、1 つのダッシュボードを共有するという要件に反し、作成と保守の負荷も増えます。",["地域ごとに別のダッシュボードを作って"]],"1":["他の地域の列を削除しても行の絞り込みにはならず、利用者ごとに表示を変えることもできません。",["他の地域の列を削除する"]],"2":["フィルターコントロールは利用者が自由に変更できるため、他の地域のデータも表示でき、アクセス制御になりません。",["フィルターコントロールを追加する"]]},"DEA-C01-224":{"1":["バージョニングはオブジェクトの旧版を残す機能で、バケット自体の削除操作は防げません。",["バージョニングを有効にする"]],"2":["CloudTrail は削除操作を記録するだけで、削除そのものを防ぐことはできません。",["CloudTrail で削除操作を記録する"]],"3":["個別の IAM ポリシーはアカウントの管理者が変更・削除できるため、管理者による削除を防げません。全アカウントへの設定も負荷が大きくなります。",["個別に拒否ポリシーを付ける"]]},"DEA-C01-225":{"0":["バケット単位の制御では事業部との組み合わせや列単位の制御に対応できず、テーブルの追加ごとにデータの配置を考える必要があります。",["機密レベルごとに S3 バケットを分け"]],"1":["全テーブルを丸ごと共有すると機密レベルによる区別ができず、機密データにも過剰にアクセスできてしまいます。",["全テーブルを RAM で丸ごと共有する"]],"2":["名前の規則を解析する独自コードは保守が必要で、規則外の名前で付与漏れが起き、テーブルの増加で権限の管理も複雑になります。",["Lambda でテーブル名の規則を解析し"]]},"DEA-C01-226":{"0":["スキャン上限はクエリのデータ量を制限するもので、列レベルの権限が効かない原因ではありません。",["スキャン上限が設定されていない"]],"2":["Athena は Lake Formation の列レベルの権限に対応しています。Redshift への移行は不要で、運用負荷も大きくなります。",["列レベルの権限は Athena では使えない"]],"3":["lakeformation:GetDataAccess は Lake Formation 経由でデータにアクセスするために必要な権限で、削除すると正しい権限での利用もできなくなります。",["lakeformation:GetDataAccess"]]},"DEA-C01-227":{"0":["データはアカウント A のカスタマーマネージドキーで暗号化されており、aws/s3 は無関係です。AWS 管理キーはキーポリシーを変更できずアカウント間共有にも使えません。",["AWS 管理キー aws/s3"]],"2":["デフォルト暗号化の変更は新しいオブジェクトにしか効かず、既存のデータは SSE-KMS のままです。バケットポリシーの許可不足も解消しません。",["SSE-S3 に変更する"]],"3":["KMS キーはアカウントやリージョンごとに固有で、同じキー ID を作ることはできません。別のキーでは既存のデータを復号できません。",["同じキー ID の KMS キーを作成する"]]},"DEA-C01-228":{"0":["バージョニングはオブジェクトの旧版を残す機能で、オブジェクトの所有者や ACL による読み取りの問題は解決しません。",["バージョニングを有効にする"]],"1":["オブジェクトの所有者が取引先のままでは ACL で許可されない限り読めず、IAM で s3:* を許可しても解決しません。過剰な権限にもなります。",["s3:* を許可する"]],"2":["取引先に設定変更を依頼しないという条件に反し、付け忘れがあれば読めないため確実性もありません。",["取引先に毎回","依頼する"]]},"DEA-C01-229":{"0":["SSE-C ではキーを AWS に保管せずアプリケーションが管理するため、キーポリシーによる制御や CloudTrail による KMS の使用履歴の監査ができません。",["SSE-C"]],"1":["AWS マネージドキーはキーポリシーを編集できないため、キーの使用を利用者ごとに制御できません。",["AWS マネージドキー（aws/s3）"]],"2":["SSE-S3 は S3 が管理するキーで暗号化するため、キーポリシーによる使用の制御やキーごとの使用履歴の監査ができません。",["SSE-S3"]]},"DEA-C01-230":{"0":["自動ローテーションはキーの素材を定期的に更新する機能で、KMS へのリクエスト数は減らず料金も下がりません。",["自動ローテーション"]],"2":["AWS マネージドキーでも KMS へのリクエストごとの料金は発生するため、API の料金は下がりません。キーポリシーでの制御もできなくなります。",["AWS マネージドキー（aws/s3）に切り替える"]],"3":["マルチリージョンキーは複数リージョンで同じキーを使うための機能で、リクエスト数は減らずコストも下がりません。",["マルチリージョンキー"]]},"DEA-C01-231":{"0":["Transfer Acceleration はエッジ経由でアップロードを高速化する機能で、HTTP での通信を拒否することはできません。",["S3 Transfer Acceleration"]],"1":["オブジェクトロックはオブジェクトの削除や上書きを防ぐ機能で、通信の暗号化を強制するものではありません。",["S3 オブジェクトロック"]],"3":["SSE-KMS は保存時の暗号化で、暗号化されていない HTTP での転送を拒否することはできません。",["SSE-KMS をデフォルト暗号化に設定する"]]},"DEA-C01-232":{"1":["シャッフルパーティション数は Spark の並列度の設定で、データの暗号化とは無関係です。",["シャッフルパーティション数を増やす"]],"2":["プライベートサブネットへの配置はネットワークの分離であり、S3 やローカルディスクのデータの暗号化の代わりにはなりません。",["プライベートサブネットに配置する"]],"3":["セキュリティグループは通信の制御で、S3 に書き込むデータやローカルディスクを暗号化する機能ではありません。",["セキュリティグループを変更する"]]},"DEA-C01-233":{"0":["暗号化はキーがあれば復号できるため、元に戻せない形にするという要件を満たしません。",["KMS の対称キーでメールアドレスを暗号化する"]],"1":["レコードごとにランダムな値にすると同じ顧客でも値が変わるため、顧客単位での集計ができません。",["レコードごとにランダムな値に置き換える"]],"3":["Base64 は単なるエンコードで誰でも簡単に元に戻せるため、元に戻せない変換になりません。",["Base64 でエンコードする"]]},"DEA-C01-234":{"1":["SELECT 権限を取り消すと列自体が参照できなくなり、下 4 桁だけを表示する要件を満たせません。",["SELECT 権限を一般ユーザーから取り消す"]],"2":["行レベルセキュリティは返す行を絞り込む機能で、列の値の一部を伏せて表示することはできません。",["行レベルセキュリティポリシー"]],"3":["列を暗号化すると一般ユーザーには下 4 桁も見えず、復号の仕組みを自前で用意する必要があり運用負荷も大きくなります。",["電話番号の列を KMS で暗号化し"]]},"DEA-C01-235":{"0":["列の手動暗号化はクエリやアプリケーションの大幅な変更が必要で運用負荷が大きく、クラスターの保存時の暗号化にもなりません。",["AES で手動暗号化する"]],"1":["バケットキーは S3 の SSE-KMS のリクエスト数を減らす機能で、Redshift クラスターの暗号化とは無関係です。",["S3 バケットキー"]],"2":["クラスターを削除するとデータが失われ、エンドポイントも変わります。既存クラスターを変更して暗号化を有効にできます。",["データを諦める"]]},"DEA-C01-236":{"0":["Base64 は誰でも元に戻せるエンコードで暗号化ではありません。ログやジョブブックマークも暗号化されません。",["Base64 でエンコードする"]],"1":["DPU を増やすのは処理能力の増強で、出力データやログの暗号化とは無関係です。",["DPU を増やす"]],"2":["バージョニングはオブジェクトの旧版を残す機能で、暗号化ではありません。ログやジョブブックマークにも効きません。",["バージョニングを有効にする"]]},"DEA-C01-237":{"1":["出力後に検出するのでは伏字にする前のデータが S3 に保存されてしまい、手作業での修正も運用負荷と漏れの原因になります。",["出力後に","手作業でファイルを修正する"]],"2":["個人情報の列は事前に分からず、列名だけでは電話番号などを見逃します。列を削除すると必要なデータも失われます。",["列名に「mail」が含まれる列だけを削除する"]],"3":["保存時の暗号化では、読み取り権限のある利用者には値がそのまま見えるため、伏字にする要件を満たしません。",["SSE-KMS で暗号化する"]]},"DEA-C01-238":{"0":["SSE-S3 は読み取り権限があれば透過的に復号されるため、分析チームにも電話番号が見えてしまいます。キーの使用の監査もできません。",["SSE-S3"]],"1":["Base64 は誰でも簡単に元に戻せるため、分析チームから値を隠せません。キーの使用の監査もできません。",["Base64 でエンコードする"]],"3":["ハッシュは元に戻せないため、調査チームが元の電話番号を復元するという要件を満たせません。",["ソルト付きハッシュ"]]},"DEA-C01-239":{"0":["KMS キーはリージョン外にエクスポートできません。複製先のリージョンのキーを指定して再暗号化する必要があります。",["複製先のリージョンにエクスポートする"]],"3":["暗号化を無効にしても既存のオブジェクトは SSE-KMS のままで、複製先で暗号化するという要件やセキュリティ要件にも反します。",["暗号化を無効にする"]],"4":["Transfer Acceleration はアップロードを高速化する機能で、SSE-KMS のオブジェクトが複製されない問題とは無関係です。",["S3 Transfer Acceleration"]]},"DEA-C01-240":{"0":["GuardDuty の S3 保護は不審なアクセスなどの脅威を検出するもので、ファイルの中身のクレジットカード番号は検出しません。",["Amazon GuardDuty"]],"2":["AWS Config はリソースの設定を評価するもので、S3 に保存されたファイルの中身の機密データは検出できません。",["AWS Config のマネージドルール"]],"3":["Inspector は EC2 やコンテナイメージなどの脆弱性を検査するサービスで、ファイル内の機密データは検出しません。",["Amazon Inspector"]]},"DEA-C01-241":{"0":["VPC フローログは IP アドレスやポートなどの通信の記録で、どのユーザーがどのテーブルにアクセスしたかは分かりません。",["VPC フローログ"]],"2":["テーブルのバージョン履歴は定義の変更を示すだけで、誰がいつテーブルにアクセスしたかの記録ではありません。",["テーブルのバージョン履歴"]],"3":["Storage Lens はストレージの使用量やリクエスト数の集計で、ユーザーごとのテーブルへのアクセスは分かりません。",["S3 Storage Lens"]]},"DEA-C01-242":{"0":["Service Catalog は承認済みの IaC 製品を配布するサービスで、データ資産の発見や申請・承認による共有は行えません。",["AWS Service Catalog"]],"2":["RAM はアカウント間でリソースを共有する機能で、データの検索や申請・承認の流れ、利用状況の管理はできません。",["Resource Access Manager"]],"3":["スキーマレジストリはストリーミングのスキーマの互換性を管理するもので、データ資産の共有や申請・承認の機能はありません。",["スキーマレジストリ"]]},"DEA-C01-243":{"0":["CloudWatch のメトリクスは数値の推移で、誰がいつテーブル定義を変更したかは分かりません。",["CloudWatch のメトリクス"]],"1":["ストレージクラス分析は S3 のアクセスパターンを分析する機能で、Data Catalog の変更履歴は分かりません。",["ストレージクラス分析"]],"3":["VPC フローログは通信の情報を記録するだけで、API を呼び出したユーザーや変更内容は分かりません。",["VPC フローログ"]]},"DEA-C01-244":{"0":["保持期間を延ばしても、そもそも GetObject は記録されていないため、読み取りの記録は残りません。",["保持期間を延ばす"]],"1":["バージョニングはオブジェクトの旧版を残す機能で、誰がいつ読み取ったかは記録されません。",["バージョニングを有効にする"]],"3":["ログファイルの検証は記録済みのログの改ざんを検出する機能で、記録されていないデータイベントは記録されるようになりません。",["ログファイルの検証"]]},"DEA-C01-245":{"1":["イベント履歴は過去 90 日間の管理イベントしか参照できず、1 年分は扱えません。アカウントごとの手作業も負荷が大きくなります。",["コンソールで検索し","ダウンロードして結合する"]],"2":["CloudTrail Lake は 2026 年 5 月 31 日以降、新規の利用者は使えないため、まだ利用していないこの組織では選べません。",["新たに CloudTrail Lake"]],"3":["Inspector の検出結果は脆弱性の情報で、どのプリンシパルが機密テーブルにアクセスしたかは分かりません。",["Amazon Inspector の検出結果"]]},"DEA-C01-246":{"0":["Logs Insights はログを検索・集計する機能で、S3 バケットの設定の準拠状況を継続的に評価・記録できません。",["CloudWatch Logs Insights"]],"2":["Glue Data Quality はデータの中身の品質を検証する機能で、バケットの暗号化やパブリックアクセスの設定は評価できません。",["AWS Glue Data Quality"]],"3":["Macie はデータの中身の機密情報を検出するもので、バケットの設定違反の継続的な検出と準拠状況の記録には向きません。",["機密データ検出ジョブ"]]},"DEA-C01-247":{"0":["CloudTrail は Redshift の API 呼び出しを記録しますが、データベース内で実行された SQL や接続は記録しません。",["CloudTrail の管理イベントだけ"]],"1":["スナップショットはデータのバックアップで、誰がいつ接続し何を実行したかは記録されません。",["スナップショットを毎日取得する"]],"3":["VPC フローログは IP やポートなどの通信情報だけで、ユーザーや実行された SQL は分かりません。",["VPC フローログ"]]},"DEA-C01-248":{"1":["全データを 1 つのアカウントにコピーすると、ストレージ料金と転送のコストが大きく、機密データの複製で漏えいリスクも増えます。",["1 つのアカウントにコピーしてから"]],"2":["AWS Config はリソースの設定履歴を記録するもので、バケットの中身に個人情報が含まれるかは分かりません。",["AWS Config の設定履歴"]],"3":["クローラーは列名などのスキーマしか分からず、目視での確認は数千のバケットでは現実的でなく継続的な把握もできません。",["列名を目視で確認する"]]},"DEA-C01-249":{"2":["1 日後に削除すると監査に必要なログを保管できず、削除や改ざんを防ぐという要件と逆の結果になります。",["1 日後に削除する"]],"3":["各アカウントのバケットに保存すると、そのアカウントの管理者がログを削除・改ざんできてしまいます。",["それぞれのアカウントのバケットに保存する"]],"4":["CloudWatch Logs だけでは各アカウントの管理者がロググループを削除でき、ダイジェストファイルによる整合性の検証も使えません。",["CloudWatch Logs だけに送り"]]},"DEA-C01-250":{"0":["CloudTrail での記録と月次の確認は事後の検出で、他のリージョンでのリソース作成を防ぐことはできません。",["月次で確認する"]],"1":["デフォルト暗号化は保存時の暗号化の設定で、リージョンの利用を制限する機能ではありません。",["デフォルト暗号化を有効にする"]],"3":["IAM ユーザーを削除すると東京や大阪での作業もできなくなり、業務が止まります。リージョンの制限にもなりません。",["IAM ユーザーを削除する"]]},"DVA-C03-126":{"0":["機密情報フィルターは PII などの機密データを検出してブロックやマスクを行う機能で、投資助言という話題そのものを判定して回答を止めることはできません。",["機密情報フィルター"]],"1":["単語フィルターは登録した語句との一致で判定するため、言い回しを変えた投資助言は素通りしてしまい、話題全体を制御できません。",["単語フィルター"]],"2":["グラウンディングチェックは応答が与えたソースに根拠を持つか、質問に関連しているかを評価する機能で、特定の話題への回答を禁止する用途には使えません。",["グラウンディングチェック"]]},"DVA-C03-127":{"0":["NAT ゲートウェイ経由の通信は Bedrock のパブリックエンドポイントに向かうため、インターネット側の経路を通ることになり、要件を満たしません。",["NAT ゲートウェイを経由させ"]],"1":["ゲートウェイ VPC エンドポイントが使えるのは S3 と DynamoDB だけで、Bedrock 用のゲートウェイエンドポイントは作成できません。",["ゲートウェイ VPC エンドポイント"]],"2":["パブリックサブネットから HTTPS で呼び出すと通信は暗号化されますが、インターネット経由でパブリックエンドポイントに接続するため要件に反します。",["パブリックサブネットに移し"]]},"DVA-C03-128":{"0":["出力トークン数を減らしても PII が含まれるかどうかは制御できず、要約が途中で切れるだけです。特定の部分だけを伏せ字にすることはできません。",["最大出力トークン数を減らして"]],"1":["拒否トピックに該当すると応答全体がブロックされるため、要約自体を返しつつ PII の部分だけを伏せ字にするという要件を満たせません。",["拒否トピック"]],"2":["温度は出力のランダム性を調整するパラメータで、PII の検出やマスクの機能はありません。電話番号やメールアドレスはそのまま出力され得ます。",["温度を 0 に設定する"]]},"DVA-C03-129":{"1":["最大トークン数は出力の長さの上限を変えるだけで、プロンプトインジェクションの検出や防止には効果がありません。",["最大トークン数を増やす"]],"2":["同期か非同期かは呼び出し方式の違いで、入力に含まれる指示の上書きの試みを検出したりブロックしたりする効果はありません。",["同期から非同期に変更する"]],"3":["システムプロンプトの工夫だけでは、巧妙なジェイルブレイクやプロンプトインジェクションで回避される可能性があり、確実な防御になりません。",["より長くするだけで対処する"]]},"DVA-C03-130":{"0":["空のプロンプトで InvokeModel を呼んでも Bedrock のモデルが呼ばれるだけで、外部モデルの入出力をガードレールで評価することにはなりません。",["空のプロンプトで呼び出す"]],"1":["Amazon Translate は言語を翻訳するサービスで、ガードレールのポリシーによるコンテンツの評価やブロックは行えません。",["Amazon Translate で翻訳"]],"3":["ガードレールは Bedrock 上で評価される仕組みで、設定をエクスポートして外部モデルに読み込ませても同じポリシーは適用されません。",["JSON でエクスポートして"]]},"DVA-C03-131":{"0":["温度は出力のランダム性を決めるパラメータで、ガードレールを指定しない呼び出しを拒否する強制力はありません。",["温度を全チームで 0 に統一"]],"2":["メールでの依頼は運用上のお願いにすぎず、ガードレールを指定しない呼び出しを技術的に防げないため、組織として強制できません。",["依頼するメールを送る"]],"3":["ダッシュボードでの監視は事後に状況を把握するだけで、承認済みのガードレールを指定しない呼び出しそのものを拒否できません。",["CloudWatch のダッシュボードで監視"]]},"DVA-C03-132":{"0":["CloudTrail を無効にすると API 操作の監査ができなくなるうえ、S3 に保存された呼び出しログ自体の保護には何もなりません。",["CloudTrail の記録を無効にする"]],"1":["顧客情報を含むログのバケットを公開すると、誰でも閲覧できる状態になり重大な情報漏えいにつながります。保護とは正反対の対応です。",["バケットを公開して"]],"2":["ソースコードのリポジトリにコミットすると、リポジトリを見られる全員に顧客情報が渡り、履歴からも消しにくくなるため情報漏えいにつながります。",["リポジトリにコミットする"]]},"DVA-C03-133":{"1":["管理者権限で生成 SQL をそのまま実行すると、悪意のある入力から生成された削除や他部署データの参照もすべて実行されてしまいます。",["管理者権限の DB ユーザー","そのまま実行する"]],"2":["温度を上げると出力のばらつきが増えるだけで、危険な SQL の生成を防ぐ効果はなく、むしろ予期しない SQL が出やすくなります。",["温度を上げて"]],"4":["プロンプトの指示だけでは、プロンプトインジェクションで回避される可能性があり、実行権限や検証による確実な制御になりません。",["書くだけで実行する"]]},"DVA-C03-134":{"1":["アクセスキーの共有は誰が使ったか追跡できず漏えいリスクも高いうえ、社員ごとの利用者管理もできず要件を満たしません。",["アクセスキーを共有する"]],"2":["個人の Builder ID での利用はオプトアウトしない限りコンテンツがサービス改善に使われ得るうえ、組織として利用者を一元管理できません。",["個人の AWS Builder ID"]],"3":["任意の公開拡張機能ではコードの取り扱いが保証されず、社員の利用を一元管理する仕組みもないため、情報漏えいのリスクがあります。",["任意のブラウザ拡張機能"]]},"DVA-C03-135":{"0":["CloudTrail のデータイベントは AWS リソースへのデータ操作を記録するもので、生成コードがどの公開コードに類似しているかは分かりません。",["CloudTrail のデータイベント"]],"1":["Inspector の ECR スキャンはコンテナイメージの脆弱性を検出する機能で、生成コードの参照元やライセンスの確認には使えません。",["ECR スキャン"]],"2":["AWS Artifact は AWS 自体の監査レポートやコンプライアンス文書を提供するサービスで、生成コードのライセンス確認には使えません。",["AWS Artifact"]]},"DVA-C03-136":{"0":["実行ログを無効にしても危険なコマンドの実行は防げず、何が実行されたかを追跡できなくなるだけで、かえってリスクが増します。",["実行ログを無効にする"]],"1":["すべてを自動承認にすると、破壊的なコマンドも人間の確認なしに実行されるため、本番リソースを誤削除するリスクが高まります。",["すべてのコマンドとツールを自動承認"]],"3":["本番の管理者権限を渡すと、エージェントの誤操作がそのまま本番リソースの削除につながり、被害が最大化します。最小権限に反します。",["本番環境の管理者の認証情報"]]},"DVA-C03-137":{"0":["キャッシュの無効化や CORS の削除では、送信元ごとのリクエスト数を制限できず、CORS はブラウザ以外からの大量送信を防ぐ仕組みでもありません。",["キャッシュを無効にし","CORS の設定を削除する"]],"1":["メモリを増やすと処理は速くなりますが、リクエスト数やモデルの利用量は減らず、Lambda の料金が増えるだけで悪用対策になりません。",["メモリを増やして"]],"4":["大きなモデルはトークン単価が高くなる傾向があり、大量リクエストを抑える効果もないため、コストがさらに増えてしまいます。",["より大きなモデルに変更する"]]},"DVA-C03-138":{"1":["タイムアウトを短くしても処理時間が制限されるだけで、モデルが渡した他の顧客の注文 ID によるキャンセルは防げません。",["タイムアウトを短くする"]],"2":["指示文の追記だけでは、プロンプトインジェクションで回避される可能性があり、ツール側の権限や所有者の検証による確実な制御になりません。",["追記する"]],"3":["大きなモデルでもプロンプトインジェクションを確実に防ぐことはできず、テーブル全体への書き込み権限が残る問題も解決しません。",["より大きなものに変更する"]]},"DVA-C03-139":{"0":["NAT ゲートウェイ経由ではパブリックエンドポイントを呼び出すことになり、呼び出しをエンドポイント経由に限定する要件と逆行します。",["NAT ゲートウェイを追加して"]],"2":["ゲートウェイ VPC エンドポイントは S3 と DynamoDB だけが対応しており、Bedrock では作成できません。",["ゲートウェイ VPC エンドポイント"]],"4":["パブリック IP への通信を許可するとインターネット経由の呼び出しが可能になり、エンドポイント経由への限定にもモデルの制限にもなりません。",["パブリック IP アドレスへの通信を許可"]]},"DVA-C03-140":{"0":["キャッシュは同じ質問に同じ回答を返すだけで、根拠のない回答を検出できず、誤った回答がキャッシュされると繰り返し返されます。",["応答をキャッシュして"]],"1":["単語フィルターでは正しい保証の説明までブロックされ、回答がマニュアルに根拠を持つかどうかは判定できません。",["単語フィルター"]],"3":["出力トークン数を増やして詳しく答えさせても根拠の検証は行われず、作り話の保証条件がかえって増えるおそれがあります。",["最大出力トークン数を増やして"]]},"DVA-C03-141":{"0":["Amplify Hosting は主にフロントエンドの Web アプリをホスティングするサービスで、API Gateway や Lambda をテンプレートで定義しローカルテストする用途ではありません。",["AWS Amplify Hosting"]],"1":["Elastic Beanstalk は EC2 などのサーバー上で動くアプリ向けで、サーバーレス構成を簡潔に定義してローカルで Lambda をテストする機能はありません。",["Elastic Beanstalk"]],"2":["Copilot CLI は ECS や App Runner などのコンテナアプリ向けのツールで、Lambda 中心のサーバーレス構成の定義やローカル実行には向きません。",["AWS Copilot CLI"]]},"DVA-C03-142":{"0":["Service Catalog は承認済みの製品（IaC テンプレート）を配布するサービスで、ライブラリのパッケージ管理や公開リポジトリのプロキシにはなりません。",["AWS Service Catalog"]],"1":["S3 を公開すると社内ライブラリが外部から取得可能になるうえ、npm などのリポジトリとしての機能や上流のプロキシ機能もありません。",["バケットをパッケージ置き場として公開"]],"3":["ECR のプルスルーキャッシュはコンテナイメージ用の機能で、npm や Maven などのライブラリのパッケージを扱えません。",["ECR のプルスルーキャッシュ"]]},"DVA-C03-143":{"0":["Lambda 拡張機能は監視やセキュリティなどのツールを関数のライフサイクルに組み込む仕組みで、ライブラリを切り離して共有する機能ではありません。",["Lambda 拡張機能の内部拡張"]],"2":["エイリアスは特定のバージョンを指すポインタで、ライブラリを関数のコードから切り離して共有する用途には使えません。",["Lambda エイリアス"]],"3":["予約同時実行は関数が使える同時実行数を確保・制限する設定で、ライブラリの共有やデプロイパッケージとは関係ありません。",["予約同時実行"]]},"DVA-C03-144":{"0":["プッシュ時のイメージスキャンは脆弱性を検出する機能で、既存のタグが別のイメージで上書きされることは防げません。",["イメージスキャン"]],"2":["ライフサイクルポリシーは古いイメージを自動で削除する機能で、タグの上書きプッシュを拒否することはできません。",["ライフサイクルポリシー"]],"3":["レプリケーションはイメージを別のリージョンやアカウントにコピーする機能で、タグの上書きを防ぐ効果はありません。",["レプリケーション"]]},"DVA-C03-145":{"0":["リポジトリ全体を削除すると残すべき最新 30 個のイメージも消え、Lambda の開発・運用負荷もかかるため要件に合いません。",["リポジトリ全体を削除して作り直す"]],"2":["タグのイミュータビリティはタグの上書きを防ぐ機能で、古いイメージを自動で削除する効果はありません。",["タグのイミュータビリティ"]],"3":["S3 のライフサイクルルールは S3 バケットのオブジェクト用で、ECR のイメージには適用できません。",["S3 のライフサイクルルール"]]},"DVA-C03-146":{"1":["cdk init は新しい CDK プロジェクトのひな形を作るコマンドで、既存のコードからテンプレートを生成するものではありません。",["cdk init"]],"2":["cdk destroy はデプロイ済みのスタックを削除するコマンドで、テンプレートの内容を確認する用途には使えません。",["cdk destroy"]],"3":["cdk bootstrap はデプロイ用の S3 バケットや IAM ロールなどを環境に準備するコマンドで、テンプレートは出力しません。",["cdk bootstrap"]]},"DVA-C03-147":{"0":["エフェメラルストレージは実行時に /tmp で使える領域で、デプロイパッケージの解凍後 250 MB の上限は変わりません。",["エフェメラルストレージ"]],"1":["S3 経由のデプロイは zip のアップロード方法が変わるだけで、解凍後 250 MB の上限は同じです。",["S3 にアップロードしてから"]],"3":["レイヤーは関数本体と合わせて解凍後 250 MB の上限に含まれるため、分割しても上限を超える問題は解決しません。",["複数の Lambda レイヤーに分割"]]},"DVA-C03-148":{"0":["環境ごとにテンプレートをコピーすると 1 つのテンプレートで管理するという要件に反し、変更のたびに両方を直す手間と差異のリスクが生じます。",["テンプレートをコピーし"]],"3":["Outputs はスタックの出力値を公開する仕組みで、Fn::GetAtt はリソースの属性を取得する関数です。環境ごとの値の切り替えには使えません。",["Outputs に環境ごとの値を定義し"]],"4":["Metadata はテンプレートの付加情報で、Ref で参照して値を切り替えることはできません。Ref はパラメータやリソースの参照に使います。",["Metadata に環境ごとの値を定義し"]]},"DVA-C03-149":{"0":["Description はテンプレートの説明文で、ここにコードを埋め込んでも Lambda のコードとしては扱われず、文字数の上限もあります。",["Description に埋め込む"]],"1":["ローカルパスのままでは CloudFormation がコードを取得できないため、create-stack にそのまま渡してもデプロイできません。",["そのまま aws cloudformation create-stack に渡す"]],"2":["テンプレートを変更しないとローカルパスの参照が残り、コードを取得できません。ECR を使うならイメージの URI への書き換えも必要です。",["テンプレートは変更しない"]]},"DVA-C03-150":{"0":["タグの付け方はイメージの中身に影響しないため、サイズも脆弱性も減りません。latest への統一はバージョンの追跡も難しくします。",["タグを latest に統一する"]],"2":["タグのイミュータビリティはタグの上書き可否の設定で、イメージの中身に影響しないためサイズや脆弱性は変わりません。",["タグのイミュータビリティを無効にする"]],"4":["ビルドツールを残すとイメージは大きいままで、スキャンで検出された脆弱性も攻撃対象領域も減らず、要件と逆になります。",["すべてのビルドツールを最終イメージに残し"]]},"DVA-C03-151":{"1":["初期化エラーの原因は Runtime API と通信するクライアントがないことで、メモリを増やしても Lambda のランタイムとして動作するようにはなりません。",["メモリを最大にする"]],"2":["コンテナイメージとしてデプロイする関数ではレイヤーを使えません。必要なのはランタイムインターフェイスクライアントをイメージに含めることです。",["Lambda レイヤーを追加する"]],"3":["Lambda のコンテナイメージは ECR から取得する必要があり、Docker Hub に移しても使えません。初期化エラーの原因も解決しません。",["Docker Hub に移してから"]]},"DVA-C03-152":{"0":["同じ名前のリポジトリを作っても別アカウントのリポジトリは別物で、自動的に共有されることはありません。イメージを 1 か所に置く要件にも反します。",["自動的に共有される"]],"2":["長期のアクセスキーを配布すると漏えいリスクが高く、ローテーションも困難です。ロールとリポジトリポリシーで許可すべきです。",["アクセスキーを各アカウントのタスクに配布"]],"3":["公開リポジトリにすると社内のベースイメージを誰でも取得できてしまい、3 つのアカウントだけに共有するというセキュリティ上の前提に反します。",["公開リポジトリに変更する"]]},"DVA-C03-153":{"0":["cdk synth はテンプレートを生成するだけで、アセット用の S3 バケットやデプロイ用ロールは作られないため、エラーの原因は解消しません。",["テンプレートを手動でアップロード"]],"1":["権限を広げても、ブートストラップで作られるアセット用バケットやデプロイ用ロールが存在しない状態は変わらず、最小権限にも反します。",["AdministratorAccess を付ける"]],"3":["CDK のバージョンを戻しても、環境にブートストラップのリソースがない問題は解決しません。必要なのは cdk bootstrap の実行です。",["古いものに戻す"]]},"DVA-C03-154":{"1":["パスワードを Default 値に書くとテンプレート内に平文で残り、Secrets Manager の値を使うという要件にも反します。",["Default 値に持つパラメータ"]],"2":["Outputs に出力すると、コンソールや API で誰でも値を見られる状態になり、パスワードが露出します。",["Outputs に出力して"]],"3":["Mappings はテンプレートに直接書く静的な値で、パスワードが平文でテンプレートに残ってしまいます。",["Mappings に書く"]]},"DVA-C03-155":{"0":["再起動を禁止してもノード障害や再スケジュールは避けられず、latest の中身が変わる限り混在は防げません。ロールバックも困難なままです。",["ポッドの再起動を禁止する"]],"2":["スケーリングを止めても可変タグの問題は残り、ポッドの再スケジュールで混在が起こり得ます。可用性も損なわれ、根本解決になりません。",["オートスケーリングを無効にする"]],"3":["キャッシュを削除しても、プルした時点の latest の中身が使われるだけで、どのバージョンかを固定できず再現性のあるデプロイになりません。",["イメージのキャッシュを毎晩削除する"]]},"DVA-C03-156":{"0":["exec format error はイメージの CPU アーキテクチャとノードの不一致が原因で、メモリ制限を引き上げても解決しません。",["メモリ制限を引き上げる"]],"1":["別のクラスターを作っても arm64 用のイメージがなければ起動できず、同じイメージ参照のまま両方で動かす要件も満たせません。",["別のクラスターを作る"]],"3":["シェルスクリプトを経由しても、実行するバイナリが x86 向けのままなので arm64 ノードでは動きません。",["シェルスクリプト経由に変える"]]},"DVA-C03-157":{"0":["実行時に pip でインストールすると初回呼び出しが遅く、ネットワークや外部リポジトリに依存して不安定になります。成果物の再現性も確保できません。",["初回呼び出し時に pip でインストール"]],"1":["アーキテクチャを指定しないと x86_64 で動くため、arm64 を使うという前提を変えてしまい、PC に依存しないビルドという要件も解決しません。",["アーキテクチャを指定せずに"]],"3":["インポートエラーは C 拡張がアーキテクチャに合っていないことが原因で、メモリやストレージを増やしても解決しません。",["メモリを増やし"]]},"DVA-C03-158":{"0":["タイムアウトの原因は CodeArtifact への経路がないことで、npm のキャッシュを削除しても接続できるようにはなりません。",["npm のキャッシュを削除する"]],"1":["インターネットゲートウェイへのルートを追加するとインターネットへの経路ができ、要件に反します。プライベートサブネットのままでは機能もしません。",["インターネットゲートウェイへのルートを追加"]],"3":["CodeArtifact には一般公開する設定はありません。仮に公開できても接続経路がない問題は残り、社内パッケージを公開するのも不適切です。",["公開設定にする"]]},"DVA-C03-159":{"0":["テスト環境へのデプロイは実際の DynamoDB を使う結合テストになり、時間がかかるうえ、DynamoDB に接続せずにテストする要件を満たしません。",["sam deploy でテスト環境にデプロイ"]],"1":["バックアップから復元したテーブルも実際の DynamoDB であり、接続せずにテストする要件に反します。復元の時間とコストもかかります。",["バックアップから復元したテーブル"]],"2":["開発用アカウントのテーブルに接続すると実際の DynamoDB を使うことになり、データの状態に左右されて単体テストの再現性も下がります。",["開発用アカウントの DynamoDB テーブルに接続"]]},"DVA-C03-160":{"0":["sam deploy は AWS にデプロイするコマンドで、デプロイせずにローカルで動作確認するという要件に合いません。",["sam deploy --guided"]],"1":["sam delete はデプロイ済みのスタックを削除するコマンドで、ローカルに API を起動する機能はありません。",["sam delete"]],"3":["sam logs はデプロイ済みの Lambda 関数のログを取得するコマンドで、ローカルで HTTP リクエストを受ける API は起動しません。",["sam logs"]]},"DVA-C03-161":{"0":["CodeBuild のテストレポートは実行済みのテスト結果を集計・表示する機能で、テストコードを生成することはできません。",["CodeBuild のテストレポート機能"]],"1":["X-Ray は分散トレーシングでリクエストの流れや遅延を分析するサービスで、単体テストを生成する機能はありません。",["AWS X-Ray"]],"2":["Amazon Inspector は脆弱性をスキャンするサービスで、IDE の中で単体テストを生成する機能はありません。",["Amazon Inspector"]]},"DVA-C03-162":{"0":["ビルドログの目視は手間がかかり、成功・失敗の件数やテストケース名をコンソールで集計して確認する要件を満たしません。",["目視で確認する"]],"1":["appspec.yml は CodeDeploy のデプロイ設定ファイルで、CodeBuild のテスト結果のレポートには使えません。",["appspec.yml"]],"3":["CloudTrail は AWS の API 操作を記録するサービスで、テスト結果を送って件数やテストケース名を表示する機能はありません。",["CloudTrail に送る"]]},"DVA-C03-163":{"0":["共有のステージング環境では PR 間でデプロイが干渉し、テストを順番に待つ必要もあります。テスト後に環境を削除する要件にも合いません。",["共有のステージング環境"]],"1":["本番環境でテストすると本番のデータやリソースに影響するおそれがあり、PR ごとに環境を作って削除する要件も満たしません。",["本番環境に Lambda の新バージョンを発行"]],"2":["エミュレーターだけでは実際の IAM 権限やサービスの挙動を確認しきれず、実際の AWS リソースを使う統合テストという要件に反します。",["ローカルエミュレーターだけで"]]},"DVA-C03-164":{"1":["本番バケットへのアップロードは本番環境に影響するうえ、実際に S3 にファイルを置かずにテストするという要件に反します。",["本番バケットにテストファイル"]],"2":["テスト用の JSON を関数のコードに埋め込むと本番のコードにテストデータが混ざり、実際のイベント入力を受けるテストにもなりません。",["コードに S3 イベントの JSON を直接埋め込む"]],"3":["CloudTrail のログは API 操作の記録で、Lambda が受け取る S3 イベント通知とは形式が異なるため入力として使えません。",["CloudTrail のログ"]]},"DVA-C03-165":{"0":["Express ワークフローは高頻度・短時間の処理向けのタイプで、変更しても単一のステートだけをテストすることはできません。",["Express ワークフローに変更する"]],"1":["Choice ステートや入出力の加工は Step Functions の機能であり、Lambda に置き換えると構成が変わるうえ手間も大きく、元の定義を検証できません。",["すべてのステートを Lambda 関数に置き換えて"]],"3":["本番で毎回全体を実行すると本番環境に影響するうえ、ステートマシン全体を実行せずに確認するという要件にも反します。",["毎回本番で実行して"]]},"DVA-C03-166":{"0":["空の Lambda 関数では決まった形式のレスポンスを返せず、未完成のコードを本番にデプロイすることになるため不適切です。",["空の Lambda 関数を本番にデプロイ"]],"2":["バックエンドの完成を待つと先行して結合テストを始めたいという要件を満たせず、開発期間も延びます。",["完成まで待つ"]],"3":["キャッシュはバックエンドの応答を一時保存する機能で、バックエンドがない状態で固定のレスポンスを返すことはできません。",["キャッシュを有効にする"]]},"DVA-C03-167":{"0":["S3 は DynamoDB とは API がまったく異なるため、Query や条件式の動作を確かめるテストになりません。",["DynamoDB を S3 に置き換える"]],"2":["本番テーブルへの書き込みは本番データに影響するうえ、AWS へのネットワークアクセスが制限された CI では接続もできません。",["本番の DynamoDB テーブル"]],"3":["Query のテストを省略すると、実際の Query や条件式の動作を確かめるという要件そのものを満たせません。",["テストを省略する"]]},"DVA-C03-168":{"0":["buildspec.yml の install フェーズはビルド時の依存関係の準備用で、デプロイされた新バージョンをトラフィック移行前に呼び出すことはできません。",["install フェーズ"]],"1":["手動テストは自動化の要件に反し、デプロイ後ではトラフィックが流れた後のため、失敗時にデプロイを止めることもできません。",["手動でテストする"]],"3":["AfterAllowTraffic はトラフィック移行後に実行されるため、新バージョンにトラフィックを流す前に検証するという要件を満たせません。",["AfterAllowTraffic フックだけ"]]},"DVA-C03-169":{"0":["毎回チャットで依頼するのは手作業で、開発者が毎回指示しなくても済むようにするという要件に反します。",["毎回チャットで"]],"1":["コミットメッセージにテストを書いてもテストファイルは更新されず、AI エージェントが自動で実行される仕組みにもなりません。",["コミットメッセージにテストを書く"]],"2":["CodePipeline のソースステージはリポジトリの変更を取得する段階で、テストの生成機能はなく、ファイル保存のたびに動く仕組みでもありません。",["CodePipeline のソースステージ"]]},"DVA-C03-170":{"0":["エージェントフックはイベントをきっかけにエージェントを実行する機能で、要件・設計・タスクを順に作って追跡する仕組みではありません。",["エージェントフックだけ"]],"1":["コードの短さで選んでも受け入れ条件との対応は保証されず、要件や設計を先に固めてテストと追跡するという要件に反します。",["最も短いものを採用する"]],"3":["レビューなしで本番ブランチにマージするのは危険で、要件や受け入れ条件との対応を追跡するという要件も満たしません。",["そのまま本番ブランチにマージする"]]},"DVA-C03-171":{"0":["Logs Insights はログを検索・分析する機能で、サンプルイベントが EventBridge のパターンに一致するかは判定できません。",["CloudWatch Logs Insights"]],"1":["本番に適用してから観察すると、パターンが誤っていた場合に影響が出てから分かるため、変更前に CI で確認するという要件に反します。",["ルールを本番に適用して"]],"2":["SQS のメッセージ属性は EventBridge のパターン評価とは無関係で、変換しても一致するかどうかを確認できません。",["SQS のメッセージ属性に変換"]]},"DVA-C03-172":{"0":["スタックを毎回作り直すとフルデプロイ以上に時間がかかり、反復を速くするという要件と逆になります。",["毎回スタックを削除して作り直す"]],"1":["sam sync は開発環境向けで本番では使いません。本番スタックに直接反映すると、個人の開発用スタックで確認するという前提にも反します。",["本番スタックに直接 sam sync"]],"3":["コンソールで直接編集するとテンプレートやリポジトリとの差異が生まれ、コードの管理と再現性が失われます。",["テンプレートは更新しない"]]},"DVA-C03-173":{"0":["本番でエラーが起きてから権限を追加する方法では、本番前に検出するという要件を満たせず、利用者に影響が出ます。",["発生したら権限を追加する"]],"1":["すべての単体テストで本番リソースを呼ぶと速度が落ちるうえ、本番データにも影響します。単体テストの速さを維持する要件に反します。",["すべての単体テストで本番リソースを呼び出す"]],"2":["管理者権限を付けると AccessDenied は消えますが、最小権限の原則に反し、不具合や侵害時の被害が大きくなります。",["AdministratorAccess を付与する"]]},"DVA-C03-174":{"0":["CI から外すとテストが実行されなくなり、生成されたテストの価値が失われます。品質を改善して活用するという方向に反します。",["CI の対象から外す"]],"3":["期待値を実装の出力に合わせると、実装の不具合をそのまま正解として固定してしまい、テストが不具合を見逃すようになります。",["期待値を実装の出力に合わせて自動で書き換える"]],"4":["カバレッジの数値は実行された行の割合にすぎず、期待値が仕様に沿っているかは分かりません。内容を確認しないと不具合を見逃します。",["テストの内容は確認せずにマージする"]]},"DVA-C03-175":{"0":["GSI は強力な整合性のある読み込みに対応しておらず、ConsistentRead=true を指定するとエラーになります。",["ConsistentRead=true を指定する"]],"1":["失敗を無視するとテストが本物の不具合を検出しても見逃してしまい、テストを安定させることにはなりません。",["テストの失敗を無視する"]],"2":["キャパシティモードを変えても GSI への反映の遅れは変わらないため、結果整合性による失敗は解消しません。",["オンデマンドに変更する"]]},"DVA-C03-176":{"0":["予約同時実行は同時実行数の上限で、トラフィックの割合は制御できません。$LATEST を直接更新すると旧バージョンへの振り分けもできません。",["予約同時実行で 10% に制限"]],"1":["プロビジョニングされた同時実行は初期化済みの実行環境を確保してコールドスタートを減らす機能で、トラフィックの割合を振り分ける機能ではありません。",["プロビジョニングされた同時実行"]],"3":["呼び出し元のコードで振り分けると実装と運用の負荷が増え、割合の変更や切り替えのたびにコードの修正が必要です。エイリアスの加重で十分です。",["乱数を使って振り分ける"]]},"DVA-C03-177":{"0":["appspec.yml は CodeDeploy のデプロイ設定ファイルで、CodeBuild のビルド手順や成果物は定義できません。",["appspec.yml"]],"2":["taskdef.json は ECS のタスク定義で、コンテナの設定を記述するものです。CodeBuild のビルド手順は定義できません。",["taskdef.json"]],"3":["template.yaml は SAM のテンプレートでリソースを定義するものです。CodeBuild のフェーズごとのコマンドや成果物は定義しません。",["template.yaml"]]},"DVA-C03-178":{"0":["メールの返信を待つスクリプトは自作で信頼性が低く、待機中もビルド時間の料金がかかり、タイムアウトの制約もあります。",["メールの返信を待つスクリプト"]],"1":["ロールの引き受けを制限してもパイプラインは承認を待って停止せず、承認の記録や通知も残らないため承認フローになりません。",["承認者だけに引き受けさせる"]],"2":["ステージ遷移の無効化は一時的に止めるための機能で、承認の記録や通知は行われず、承認の手続きとしては不十分です。",["遷移を無効にし"]]},"DVA-C03-179":{"0":["Cognito ユーザープールはアプリ利用者の認証基盤で、CodePipeline と GitHub の接続管理には使えません。",["Amazon Cognito ユーザープール"]],"1":["Direct Connect はオンプレミスと AWS を結ぶ専用線サービスで、GitHub リポジトリとの認証済み接続の管理には関係ありません。",["AWS Direct Connect"]],"2":["IAM ユーザーのアクセスキーは AWS API の認証情報で、GitHub への認証には使えません。長期の認証情報を扱う点でも不適切です。",["IAM ユーザーのアクセスキー"]]},"DVA-C03-180":{"1":["ローリングは既存のインスタンスをバッチごとに更新するため、既存のインスタンスに手を加えないという要件に反し、失敗時に容量が減ります。",["ローリング"]],"2":["追加バッチなしのローリングは既存のインスタンスを順に更新する方式で、新しいインスタンス群で正常起動を確認してから切り替える方式ではありません。",["ローリング（追加バッチなし）"]],"3":["一度にすべては既存の全インスタンスを同時に更新するため、ダウンタイムが発生し、失敗すると全体に影響します。",["一度にすべて"]]},"DVA-C03-181":{"0":["スタックポリシーは特定のリソースの更新を禁止する機能で、更新内容を事前に一覧して承認する用途には使えません。",["スタックポリシー"]],"1":["終了保護はスタックの誤削除を防ぐ機能で、更新でどのリソースが変わるかを事前に確認することはできません。",["終了保護"]],"3":["ドリフト検出はテンプレート外の手動変更を見つける機能で、これから行う更新の変更内容を事前に示すものではありません。",["ドリフト検出"]]},"DVA-C03-182":{"0":["自作のスケジュールでは加重の変更もアラームに基づく自動ロールバックも自前で作る必要があり、運用負荷と誤動作のリスクが大きくなります。",["1 分ごとにエイリアスの加重を変更"]],"1":["ロールバックトリガーではトラフィックが新バージョンに一度に切り替わるため、10 分かけて段階的に移行する要件を満たせません。",["一度に切り替える"]],"3":["手動承認の後に切り替えても段階的な移行にはならず、アラームによる自動ロールバックも行われません。",["手動承認アクションの後で"]]},"DVA-C03-183":{"0":["BeforeInstall は新しいファイルを配置する前に実行されるフックのため、配置後のアプリケーションの動作確認には使えません。",["BeforeInstall フック"]],"2":["ユーザーデータはインスタンスの初回起動時に実行されるもので、CodeDeploy のデプロイごとに実行されず、結果でデプロイを失敗にもできません。",["EC2 のユーザーデータ"]],"3":["buildspec.yml は CodeBuild のビルド時の定義で、EC2 に配置した後のアプリケーションを検証してデプロイを失敗扱いにはできません。",["buildspec.yml の post_build フェーズ"]]},"DVA-C03-184":{"0":["ローリング更新はタスクを順に置き換える方式で、本番トラフィックを切り替える前にテスト用リスナーで検証することはできません。",["ローリング更新で最小ヘルス率を 100%"]],"1":["Route 53 の加重ルーティングは DNS のキャッシュで切り替えや戻しが即時に反映されず、テスト用リスナーでの事前検証の仕組みもありません。",["Route 53 の加重ルーティング"]],"3":["サーキットブレーカーは起動に失敗するデプロイを検出して戻す機能で、切り替え前にテスト用リスナーで検証することはできません。",["デプロイサーキットブレーカー"]]},"DVA-C03-185":{"1":["環境変数の変更は新しいバージョンの発行が必要で、段階的な有効化やアラームによる即時の無効化の仕組みがありません。",["環境変数を更新して新しいバージョンを発行"]],"2":["Parameter Store の手動変更には段階的な展開やアラームに基づく自動ロールバックの機能がなく、全体に一度に反映されます。",["手動で書き換える"]],"3":["CodeDeploy のカナリアはコードのバージョンを切り替える仕組みで、デプロイ済みのコードのまま設定だけで機能を有効化するものではありません。",["CodeDeploy のカナリアデプロイ"]]},"DVA-C03-186":{"0":["実行中のコンテナ内で docker pull しても、そのタスクは元のイメージで動き続けます。タスクは使い捨てで、変更は管理されません。",["実行中のタスクの中で docker pull"]],"2":["タグを上書きしても実行中のタスクは自動で更新されず、どのイメージが動いているかも分かりにくくなります。",["自動で更新されるのを待つ"]],"3":["キャパシティプロバイダーはタスクを動かす基盤の容量を管理する設定で、サービスのコンテナイメージを更新するものではありません。",["キャパシティプロバイダーを更新する"]]},"DVA-C03-187":{"1":["ステージを分けて利用者に使い分けさせても割合でのトラフィック移行にならず、アラームによる自動ロールバックもできません。",["利用者に URL を使い分けさせる"]],"2":["Route 53 は DNS レベルの振り分けで Lambda 関数を直接の宛先にできず、自動ロールバックもないため最も簡単な方法とはいえません。",["Route 53 の加重ルーティング"]],"3":["予約同時実行は同時実行数の上限で、トラフィックの割合の振り分けや新バージョンの発行、自動ロールバックはできません。",["予約同時実行を 10% に設定"]]},"DVA-C03-188":{"0":["希望タスク数を 0 にするとサービスが停止するだけで、失敗の自動検出や正常なリビジョンへのロールバックにはなりません。",["希望タスク数を 0 にする"]],"1":["Container Insights はメトリクスやログを収集する監視機能で、失敗したデプロイを自動で検出して戻す機能はありません。",["Container Insights を有効にする"]],"3":["メモリ不足が原因とは限らず、今回の事象が直っても、今後の失敗するデプロイを自動で検出してロールバックする仕組みにはなりません。",["メモリを増やす"]]},"DVA-C03-189":{"0":["使用量プランはクライアントごとのリクエスト数を制限する機能で、5% のトラフィックを新しいデプロイに振り分けることはできません。",["使用量プラン"]],"2":["ステージ変数を手動で切り替えると全リクエストが一度に切り替わり、割合での振り分けやカナリア用のメトリクスの分離もできません。",["毎回手動で切り替える"]],"3":["別の API を作って利用者に案内すると、prod ステージのリクエストの一部で試す形にならず、昇格の手順も煩雑になります。",["新しい API を別に作成し"]]},"DVA-C03-190":{"0":["すべてのプッシュで実行すると無駄な実行とコストが増え、失敗の結果が本当の失敗と区別しにくく紛らわしくなります。",["変更がなければ失敗させる"]],"1":["アカウントを分けてもモノレポへのプッシュの条件で実行を絞り込むことはできず、管理の負荷が大きく増えるだけです。",["別の AWS アカウントを用意する"]],"3":["スケジュール実行では変更の有無にかかわらず実行され、services/a/ の変更やタグのプッシュをきっかけにする要件を満たせません。",["1 時間ごとにスケジュール実行"]]},"DVA-C03-191":{"0":["buildspec.yml は CodeBuild の設定ファイルで、CodeDeploy の EC2 へのデプロイが始まらない原因とは関係ありません。",["buildspec.yml の artifacts セクション"]],"1":["予約同時実行は Lambda の設定で、EC2 へのインプレースデプロイの失敗とは関係ありません。",["Lambda 関数の予約同時実行"]],"2":["ECR のタグのイミュータビリティはコンテナイメージの上書きに関する設定で、EC2 上の CodeDeploy の動作とは関係ありません。",["ECR のタグのイミュータビリティ"]]},"DVA-C03-192":{"0":["条件なしで許可すると、同じ OIDC プロバイダーを使う他のリポジトリやブランチのワークフローからもロールを引き受けられてしまいます。",["条件なしで許可する"]],"1":["暗号化しても長期の認証情報が残り、復号の鍵の管理も必要です。リポジトリにコミットすると漏えいのリスクも高まります。",["暗号化してリポジトリにコミットする"]],"3":["ローテーションしても長期のアクセスキーはなくならず、特定のリポジトリやブランチに利用を限定することもできません。",["30 日ごとに手動でローテーション"]]},"DVA-C03-193":{"0":["AWS マネージドキー（aws/s3）はキーポリシーを変更できないため、本番アカウントに復号を許可することはできません。",["aws/s3 のキーポリシーを編集"]],"1":["AWS マネージドキーは他アカウントからの復号を許可できないため、ロールに管理者権限を付けても復号できず、最小権限にも反します。",["AdministratorAccess を付ける"]],"2":["バケットを公開するとアーティファクトが誰でも読める状態になり重大なリスクです。しかも KMS の復号ができない問題は解決しません。",["バケットを公開する"]]},"DVA-C03-194":{"1":["Unauthorized は Kubernetes 側の認可の問題で、ノードのインスタンスタイプを大きくしても解決しません。",["インスタンスタイプを大きくする"]],"2":["kubectl のバージョンを上げても、CodeBuild のロールがクラスター内の権限に対応付けられていない状態は変わりません。",["kubectl のバージョンを最新に"]],"3":["S3 の権限は EKS クラスターへの認可とは無関係で、追加しても Unauthorized は解消せず、不要な権限を与えることになります。",["AmazonS3FullAccess を追加"]]},"DVA-C03-195":{"1":["終了保護はスタックの誤削除を防ぐ機能で、アラームの発報に応じて更新を自動で元に戻すことはできません。",["終了保護を有効にする"]],"2":["すべての更新を拒否するとアプリケーションの更新そのものができなくなり、問題発生時に自動で戻す仕組みにもなりません。",["すべての更新を拒否する"]],"3":["ドリフト検出はテンプレート外の手動変更を見つける機能で、エラー率の上昇を検知してスタックをロールバックすることはできません。",["ドリフト検出"]]},"DVA-C03-196":{"0":["メモリ設定の大きさはスロットリングの原因になりません。429 は同時実行数の上限を超えた場合に返されます。",["メモリ設定が大きすぎる"]],"2":["タイムアウトが短いと関数の実行がタイムアウトのエラーになるだけで、TooManyRequestsException（429）にはなりません。",["タイムアウトが短すぎる"]],"4":["実行ロールの権限不足は関数内の AWS 呼び出しが AccessDenied になるもので、Lambda の呼び出し自体の 429 とは異なります。",["必要な権限がない"]]},"DVA-C03-197":{"1":["追加のデプロイは影響を長引かせ、新たな変更で状況をさらに複雑にします。まず既存のログと変更内容から相関を確認すべきです。",["DEBUG に変更した新バージョンを追加でデプロイ"]],"2":["デプロイ直後からのエラー増加は変更が原因である可能性が高く、先に台数を増やしても原因の特定にならずコストだけが増えます。",["インスタンス数や同時実行数を増やして"]],"3":["しきい値を上げて通知を止めると、影響の拡大や新たな問題を見逃すおそれがあり、障害の復旧と原因特定に逆行します。",["通知を止め"]]},"DVA-C03-198":{"0":["メモリ不足は処理の遅れやエラーの原因にはなりますが、接続先への経路の有無とは関係せず、すべての呼び出しがタイムアウトする理由になりません。",["メモリが不足している"]],"2":["AWSLambdaBasicExecutionRole は CloudWatch Logs への書き込み権限で、外部 API への通信経路とは関係ありません。",["AWSLambdaBasicExecutionRole"]],"3":["VPC 接続前は正常に呼び出せていたため、SaaS 側の IP 対応は原因ではありません。ルートテーブルに外部への経路がないことが原因です。",["IPv6 にしか対応していない"]]},"DVA-C03-199":{"0":["キャッシュが無効でもバックエンドの処理を待つだけで、504 の原因にはなりません。処理時間が統合タイムアウトを超えていることが問題です。",["キャッシュが無効になっている"]],"1":["Lambda のタイムアウトが 15 分なら 45 秒の処理は正常に完了します。504 は API Gateway 側の統合タイムアウトが原因です。",["タイムアウトが 15 分に設定されている"]],"2":["戻り値の形式の誤りは 502 Bad Gateway の原因で、データ量が多いときだけ 504 が返る事象とは一致しません。",["statusCode が含まれていない"]]},"DVA-C03-200":{"0":["CloudTrail には StartExecution などの API 呼び出しの記録はありますが、どのステートでどの入力とエラーで失敗したかは分かりません。",["CloudTrail で StartExecution"]],"1":["Config のリソースタイムラインはリソースの設定変更の履歴で、ワークフローの実行内容や失敗したステートは確認できません。",["AWS Config のリソースタイムライン"]],"3":["定義を作り直しても失敗の原因は分からず、調査の手がかりを失うおそれがあります。まず実行履歴で失敗箇所を確認すべきです。",["削除して作り直す"]]},"DVA-C03-201":{"0":["Lambda のメモリを増やしても関数側の CPU が増えるだけで、外部 API の応答時間は変わらず、タイムアウトは防げません。",["メモリを最大にして"]],"1":["プロビジョニングされた同時実行はコールドスタートを減らす機能で、外部 API の応答の遅さによるタイムアウトには効果がありません。",["プロビジョニングされた同時実行"]],"3":["待ち続けると実行時間に比例してコストが増え、呼び出し元も長く待たされます。失敗の影響を抑える設計になりません。",["応答を待ち続ける"]]},"DVA-C03-202":{"0":["DynamoDB Streams の有効化はテーブルの読み書きキャパシティを消費しないため、スロットリングの原因にはなりません。",["DynamoDB Streams"]],"2":["強力な整合性の読み込みは消費量が 2 倍になりますが、テーブル全体の消費量に表れるため、全体に余裕がある状況の説明になりません。",["強力な整合性のある読み込み"]],"3":["ポイントインタイムリカバリはバックアップの機能で、テーブルのキャパシティを消費せずスロットリングの原因になりません。",["ポイントインタイムリカバリ"]]},"DVA-C03-203":{"1":["Lambda オーソライザーが拒否した場合は 403 が返り、バックエンドの Lambda も呼ばれないため、正常終了している状況と合いません。",["オーソライザーがリクエストを拒否"]],"2":["統合タイムアウトを超えた場合は 504 が返るため、502 が返る今回の状況とは一致しません。",["統合タイムアウトを超えている"]],"3":["API Gateway のスロットリングでは 429 が返り、Lambda は呼ばれないため、正常終了しているのに 502 になる原因ではありません。",["スロットリングの上限に達している"]]},"DVA-C03-204":{"1":["関数のタイムアウトを延ばすと処理時間が可視性タイムアウトの 30 秒をさらに超えやすくなり、重複処理が起きやすくなります。",["タイムアウトを 30 秒より長く延ばす"]],"2":["保持期間はメッセージがキューに残る最長期間で、処理中のメッセージが再び見えるようになる問題は解決せず、未処理のメッセージを失うおそれがあります。",["メッセージ保持期間を短くする"]],"3":["ロングポーリングの待機時間は受信の待ち方の設定で、処理中のメッセージが再び見えるようになる原因とは関係ありません。",["待機時間を 0 秒にする"]]},"DVA-C03-205":{"1":["CORS エラーはブラウザーがレスポンスの CORS ヘッダーを確認して起きるもので、メモリを増やしても解決しません。",["メモリを増やす"]],"2":["キャッシュはレスポンスを再利用する機能で、CORS ヘッダーやプリフライト応答の内容を変えないため解決しません。",["キャッシュを有効にする"]],"3":["execute-api:Invoke は API の呼び出し元に必要な権限で、Lambda の実行ロールに付けても CORS ヘッダーは返りません。curl では成功しており権限の問題でもありません。",["execute-api:Invoke を追加する"]]},"DVA-C03-206":{"1":["ストレージクラスが S3 標準であることは読み取りを妨げません。SSE-KMS のオブジェクトだけが失敗する状況とも関係しません。",["ストレージクラスが S3 標準"]],"2":["バージョニングの有無は GetObject の権限に影響せず、暗号化方式によって成否が分かれる状況を説明できません。",["バージョニングが無効"]],"3":["タイムアウトが短いとタイムアウトのエラーになるだけで、AccessDenied にはなりません。",["タイムアウトが短すぎる"]]},"DVA-C03-207":{"1":["タスクロールはアプリケーションが AWS を呼び出すための権限で、イメージの取得には使われません。DynamoDB の権限も無関係です。",["タスクロールに DynamoDB の権限"]],"3":["希望タスク数が 0 ならタスクはそもそも起動されず、CannotPullContainerError は起きません。起動を試みて失敗している状況と合いません。",["希望タスク数が 1 以上か"]],"4":["ポートマッピングはコンテナの通信の設定で、イメージの取得前に起きる CannotPullContainerError の原因にはなりません。",["ポートマッピングが 80 番"]]},"DVA-C03-208":{"0":["保持期間を延ばしても壊れたレコードで毎回失敗する状況は変わらず、シャードの処理は止まったままです。",["データ保持期間を延ばす"]],"1":["シャードを増やしても問題のレコードがあるシャードは同じバッチの再試行で止まり続け、根本的な解決になりません。",["シャード数を増やす"]],"3":["メモリを増やしても壊れたデータによる例外は解消されず、同じバッチの再試行でシャードの処理が止まり続けます。",["メモリを増やす"]]},"DVA-C03-209":{"1":["処理を速くしても、出力したサムネイルが再びイベントを発生させるループは止まらず、むしろ増加が速まります。",["メモリを増やして処理を速く"]],"2":["バージョニングはオブジェクトの旧版を保持する機能で、ループは止まらず、保存するバージョンが増えてストレージ料金がさらに増えます。",["バージョニングを有効にする"]],"3":["タイムアウトを短くしても、各呼び出しがサムネイルを書き込めばループは続きます。正常な処理が失敗するおそれも生じます。",["タイムアウトを短くする"]]},"DVA-C03-210":{"0":["エラーの原因はレスポンスのペイロードサイズの上限で、タイムアウトを延ばしても約 6 MB の上限は変わりません。",["タイムアウトを延ばす"]],"1":["キャッシュはレスポンスを再利用するだけで、Lambda のレスポンスのペイロード上限を超える問題は解決しません。",["キャッシュを有効にする"]],"3":["メモリを増やしてもレスポンスのペイロード上限は変わらないため、大きなファイルは返せないままです。",["メモリを最大にする"]]},"DVA-C03-211":{"0":["ローテーションを無効にするとパスワードが長期間変わらずセキュリティが下がります。キャッシュの扱いを直すべきです。",["自動ローテーションを無効にする"]],"1":["キャッシュをやめると呼び出しのたびに Secrets Manager を呼ぶためコストとレイテンシーが増え、API 呼び出しを削減する要件に反します。",["キャッシュをやめ"]],"2":["平文の環境変数はセキュリティ上不適切で、ローテーション後の値にも追従できないため、認証エラーがむしろ長く続きます。",["環境変数に平文で保存"]]},"DVA-C03-212":{"0":["日付をパーティションキーにすると同じ日の書き込みが 1 つのキーに集中し、ホットパーティションでスロットリングが悪化します。",["パーティションキーを日付に変更"]],"1":["DAX は主に読み込みを高速化するキャッシュで、書き込みのスロットリングは解消しません。",["DAX クラスターを追加"]],"3":["書き込みキャパシティを毎秒 500 にすると、5,000 件以上のピーク時にはさらにスロットリングが起きます。",["書き込みキャパシティを毎秒 500"]]},"DVA-C03-213":{"0":["標準キューにすると処理順序が保証されなくなり、顧客ごとの注文の順序が必要な要件に反します。",["標準キューに変更し"]],"1":["同じメッセージグループは失敗したメッセージが残る限り後続を処理できず、同時実行を増やしても滞留は解消しません。",["予約同時実行を増やす"]],"3":["グループ ID を同じにするとキュー全体が 1 つのグループになり、1 件の失敗で全顧客の注文が止まってしまいます。",["すべてのメッセージで同じ値にする"]]},"DVA-C03-214":{"0":["CloudTrail は管理操作の監査用で、リクエストが各区間でどれだけ時間がかかったかを追跡することはできません。",["CloudTrail で各 API 呼び出し"]],"2":["VPC フローログは IP 通信の許可・拒否を記録するもので、サービス間の処理時間は分かりません。API Gateway や Lambda の区間も追えません。",["VPC フローログ"]],"3":["Duration だけでは Lambda 内のどの呼び出しが遅いか分からず、API Gateway や DynamoDB の区間の遅延も特定できません。",["Duration メトリクスだけ"]]},"DVA-C03-215":{"0":["CloudTrail は API 呼び出しの記録で、関数内で発生したエラーの種類はログに含まれず集計できません。",["CloudTrail のイベント履歴"]],"1":["エクスポートとテーブルの作成に時間がかかり、過去 1 時間のログを素早く集計するという要件に合いません。",["S3 にエクスポートし"]],"3":["Errors メトリクスはエラーの件数だけで、エラーの種類を区別して集計することはできません。",["Errors メトリクス"]]},"DVA-C03-216":{"0":["同じログストリームにまとめても、どのログがどのリクエストのものかを識別する情報がなければ追跡できず、書き込みの管理も難しくなります。",["同じログストリームに書き込む"]],"2":["ログ量を増やしてもリクエストを結び付ける情報がなければ追跡できず、ストレージ料金と調査の手間が増えるだけです。",["DEBUG にして出力量を増やす"]],"3":["タイムスタンプだけでは同時に処理された別のリクエストと区別できず、サービス間の時刻のずれもあるため正確に追跡できません。",["同じ時刻のログを同じリクエストとみなす"]]},"DVA-C03-217":{"0":["毎月ロググループを削除すると 90 日分のログを保存できず規程に反するうえ、手作業の運用負荷もかかります。",["毎月ロググループを削除して作り直す"]],"1":["メトリクスフィルターはログからメトリクスを作る機能で、古いログを削除して保存量を減らす効果はありません。",["メトリクスフィルター"]],"2":["ログ出力を停止すると障害調査に必要な情報が得られず、90 日保存するという規程にも反します。",["ログ出力をすべて停止する"]]},"DVA-C03-218":{"0":["X-Ray のサービスマップはリクエストの経路と遅延を可視化するもので、ログの文字列を数えて通知する機能はありません。",["X-Ray のサービスマップ"]],"1":["CloudTrail は AWS の API 呼び出しを記録するサービスで、アプリケーションログの内容は扱いません。",["CloudTrail の証跡"]],"3":["AWS Config はリソースの設定を評価するサービスで、アプリケーションログの文字列を検出することはできません。",["AWS Config ルール"]]},"DVA-C03-219":{"0":["Trusted Advisor はコストやセキュリティなどのベストプラクティスを確認するサービスで、画面操作を定期的に実行して監視する機能はありません。",["AWS Trusted Advisor"]],"1":["Inspector は脆弱性をスキャンするサービスで、ログインから検索までの画面操作の正常性を監視することはできません。",["Amazon Inspector"]],"3":["CloudTrail は AWS の API 操作を記録するサービスで、利用者の画面操作を模擬して可用性を確認する機能はありません。",["AWS CloudTrail"]]},"DVA-C03-220":{"0":["保持期間はログをいつまで残すかの設定で、ログの形式やログレベルは変えられません。",["保持期間を変更する"]],"2":["X-Ray のアクティブトレースはリクエストの追跡を有効にする機能で、ログを JSON にしたりログレベルを切り替えたりはできません。",["X-Ray のアクティブトレース"]],"3":["メモリ設定は関数の性能に関わる設定で、ログの形式やレベルとは関係ありません。",["メモリ設定を変更する"]]},"DVA-C03-221":{"0":["CloudTrail は AWS の API 操作を監査するサービスで、アプリケーションの注文数のようなビジネスメトリクスを集計する仕組みではありません。",["カスタムの CloudTrail イベント"]],"2":["別の関数を経由すると呼び出しのコストと構成が増え、運用も複雑になります。EMF ならログ出力だけで済みます。",["非同期の Lambda 呼び出しで別関数に送り"]],"3":["X-Ray は遅延の分析のためのトレースで、サンプリングもされるため注文数を正確に集計するメトリクスには向きません。",["X-Ray のサブセグメント"]]},"DVA-C03-222":{"1":["メタデータはインデックス化されないため、フィルター式の検索条件に使えず、顧客 ID でトレースを絞り込めません。",["メタデータ（metadata）"]],"2":["顧客ごとに関数を作ると管理が破綻し、運用負荷が極めて大きくなります。注釈を付けるだけで絞り込めます。",["顧客ごとに別の Lambda 関数"]],"3":["ロググループ名に含めても X-Ray のトレースの絞り込みには使えず、顧客ごとにロググループが増えて管理も煩雑になります。",["ロググループ名に含める"]]},"DVA-C03-223":{"0":["評価期間を 1 日にすると障害の検知が大幅に遅れ、通知の重複という問題も解決しません。",["評価期間を 1 日にする"]],"1":["しきい値を緩めるだけでは障害の検知が遅れ、1 つの障害で複数の通知が届く問題も残ります。",["しきい値を 2 倍にする"]],"2":["アラームを削除すると障害を即時に検知できなくなり、利用者への影響が長引きます。",["毎朝ダッシュボードを確認する"]]},"DVA-C03-224":{"0":["手動で毎時実行すると検知まで最大 1 時間かかり、数秒以内に自動でチケットを作る要件を満たせません。",["手動で毎時実行する"]],"2":["メトリクスフィルターは件数しか扱えずログの内容を渡せないうえ、担当者が手作業でチケットを作るため自動化になりません。",["担当者が読んでチケットを作る"]],"3":["1 日 1 回のエクスポートでは数秒以内の対応ができず、チケットの自動作成にもなりません。",["1 日 1 回ログを S3 にエクスポート"]]},"DVA-C03-225":{"0":["CloudTrail は AWS の API 呼び出しを記録するサービスで、アプリケーションのトレースを受け取ったり X-Ray に送ったりする機能はありません。",["CloudTrail にトレースを送る"]],"1":["標準出力を S3 に保存してもトレースとして X-Ray に送られず、OpenTelemetry の計装も活用できません。",["標準出力をすべて S3 に保存"]],"3":["開発者の PC で動くデーモンには本番の Fargate タスクからトレースを送れず、他の監視基盤への送信という要件にも対応できません。",["開発者の PC で起動する"]]},"DVA-C03-226":{"0":["評価期間を 1 週間にすると深夜の急減を検知するまでに大幅な遅れが出るうえ、時間帯のパターンを考慮した判定にもなりません。",["評価期間を 1 週間にする"]],"2":["統計の種類を変えても固定しきい値で判定することに変わりはなく、時間帯によって変わる通常の範囲を考慮できません。",["最大値から最小値に変える"]],"3":["平均値の固定しきい値では、昼は常に超えて誤報が出て、深夜は常に下回るため急減も区別できません。",["昼と深夜の平均値に設定する"]]},"DVA-C03-227":{"0":["X-Ray はリクエストの経路と処理時間を記録するもので、Bedrock に送った入力やモデルの出力の本文は記録されません。",["X-Ray のサンプリング率を 100%"]],"1":["CloudTrail は API の呼び出し記録で、プロンプトやモデルの応答の本文は含まれないため、誤った回答の調査に使えません。",["CloudTrail の管理イベントだけ"]],"2":["モデルに入力内容を記憶させる機能はなく、アカウント内に監査可能な記録として残すこともできません。",["モデルに入力内容を記憶させる"]]},"DVA-C03-228":{"0":["X-Ray を無効にすると /payments の障害調査に必要なトレースも失われ、高い割合でトレースを残すという要件に反します。",["X-Ray を無効にし"]],"2":["別アカウントで動かすと構成変更と運用負荷が大きく、コードの変更を最小限にする要件に反します。サンプリング率もそれだけでは調整できません。",["別の AWS アカウントで動かす"]],"3":["全件サンプリングはトレースの記録件数に比例する料金を増やし、コストの問題を悪化させます。保持期間を短くしても記録の料金は減りません。",["100% サンプリング"]]},"DVA-C03-229":{"0":["ノードの CPU 使用率だけではサービスごとのレイテンシーやエラー、呼び出し関係が分からず、利用者から見た SLO を監視できません。",["ノードの CPU 使用率だけ"]],"1":["CloudTrail のデータイベントは S3 などのデータ操作の API 記録で、マイクロサービスのレイテンシーや SLO の監視には使えません。",["CloudTrail のデータイベント"]],"2":["各サービスのコード修正と手作業のダッシュボード作成が必要で、手作業を避けたいという要件に反し、運用負荷が大きくなります。",["ダッシュボードを手作業で作る"]]},"DVA-C03-230":{"0":["メトリクスをやめてログの目視にすると全体の処理時間の傾向を監視できず、アラームも設定できないため要件に反します。",["ログの目視で行う"]],"1":["注文 ID をディメンションに残す限りメトリクス数は減らず、高解像度にすると料金がさらに増えます。",["高解像度にする"]],"2":["注文 ID ごとのロググループは数百万個になり管理が破綻します。メトリクスのディメンションの問題も解決しません。",["別のロググループを作成する"]]},"DVA-C03-231":{"0":["各アカウントに IAM ユーザーを作ると管理する認証情報が増え、障害時に各アカウントを行き来する手間も変わりません。",["各アカウントの IAM ユーザーを作成"]],"2":["アカウントを統合すると、アカウントの分離を維持するという要件に反し、移行の負荷も大きくなります。",["1 つのアカウントに統合する"]],"3":["毎日の手作業の集約は運用負荷が高く、障害時にすぐ確認できる即時性もありません。メトリクスやトレースも対象外です。",["手作業で集約する"]]},"DVA-C03-232":{"0":["Lambda の CPU はメモリに比例して割り当てられるため、使用メモリ量に合わせると CPU が不足し、実行時間とコストが増える場合があります。",["Max Memory Used の値と同じにする"]],"1":["最小メモリは単価が安くても CPU が少なく実行時間が延びるため、総コストがかえって高くなることがあります。",["最小メモリ（128 MB）を選ぶ"]],"3":["最大メモリにしても、ある程度以上は実行時間が短くならず、単価が高い分だけコストが増えるため、バランスの良い値とはいえません。",["最大メモリ（10,240 MB）を選ぶ"]]},"DVA-C03-233":{"0":["可視性タイムアウトは受信後にメッセージを他から見えなくする時間で、受信待ちの時間とは関係せず、空の応答は減りません。",["可視性タイムアウトを長くする"]],"1":["MaxNumberOfMessages は 1 回に受け取る最大件数で、1 にすると呼び出し回数がむしろ増えます。ロングポーリングの設定ではありません。",["MaxNumberOfMessages を 1 にする"]],"4":["DelaySeconds はメッセージを配信可能になるまで遅らせる設定で、受信待ちとは関係せず、空の応答は減りません。",["DelaySeconds を設定する"]]},"DVA-C03-234":{"0":["DynamoDB Streams はテーブルの変更履歴を流す機能で、読み込みを高速化するキャッシュではありません。",["DynamoDB Streams"]],"1":["ポイントインタイムリカバリは過去の時点にテーブルを復元するバックアップ機能で、読み込みの応答時間は短くなりません。",["ポイントインタイムリカバリ"]],"2":["グローバルテーブルは複数リージョンへのレプリケーション機能で、同じ項目への大量の読み込みをマイクロ秒単位にするものではありません。",["グローバルテーブル"]]},"DVA-C03-235":{"0":["予約同時実行は同時実行数の確保と上限の設定で、実行環境を事前に初期化しないため、コールドスタートは解消しません。",["予約同時実行"]],"2":["エフェメラルストレージは実行時に使える /tmp の容量の設定で、初期化済みの実行環境を用意する機能ではありません。",["エフェメラルストレージ"]],"3":["非同期呼び出しの送信先は処理結果を別のサービスに送る設定で、コールドスタートの遅延を減らす効果はありません。",["非同期呼び出しの送信先"]]},"DVA-C03-236":{"0":["バージョニングはオブジェクトの旧版を保持する機能で、アップロードの速度や途中で切れたときの再開には効果がありません。",["バージョニングを有効にする"]],"1":["ストレージクラスを変えてもアップロードの速度や中断時のやり直しは改善せず、動画を取り出す際に時間もかかります。",["Glacier Flexible Retrieval"]],"2":["Base64 に変換するとデータ量が約 3 分の 4 倍に増え、アップロードはさらに遅くなります。中断時のやり直しも解決しません。",["Base64 に変換してから"]]},"DVA-C03-237":{"1":["スロットリングの上限を上げると受け付けるリクエストが増え、バックエンドの負荷とコストがむしろ増えます。",["スロットリングの上限を引き上げる"]],"3":["プロビジョニングされた同時実行はコールドスタートを減らすだけで呼び出し回数は減らず、待機分の費用でコストが増えます。",["プロビジョニングされた同時実行"]],"4":["メモリを増やしても呼び出し回数は減らず、バックエンドの負荷を下げる効果はありません。単価も上がります。",["メモリを増やして"]]},"DVA-C03-238":{"0":["翌日の返金は二重請求の発生自体を防げず、利用者に不利益を与えます。運用負荷もかかるため根本的な対策ではありません。",["翌日に返金する"]],"2":["タイムアウトを長くしても再試行やネットワークの再送が起きれば重複は発生し、二重請求を確実には防げません。",["タイムアウトを長くして"]],"3":["再試行を無効にしても、利用者の再操作によって同じ注文が二重に送られる可能性は残り、一時的な障害にも弱くなります。",["再試行を無効にし"]]},"DVA-C03-239":{"0":["全履歴を毎回送るとトークン数が増え続け、コストとレイテンシーが悪化し、トークン数のクォータによるスロットリングも起きやすくなります。",["過去の全履歴をそのまま"]],"2":["大きなモデルはトークン単価が高い傾向があり、コストが増えます。スロットリングの改善にもなりません。",["常に最も大きなモデルを使う"]],"3":["同じリクエストを並列に送るとリクエスト数とトークン消費が倍増し、スロットリングとコストを悪化させます。",["複数並列に送信し"]]},"DVA-C03-240":{"1":["プロビジョニングされた同時実行は効果がありますが、常時 100 の実行環境を待機させる費用がかかり、追加コストを避けたい要件に反します。",["常時 100 に設定する"]],"2":["タイムアウトを延ばしても初期化にかかる 8 秒は変わらず、コールドスタートの時間は短縮されません。",["タイムアウトを延ばす"]],"3":["予約同時実行を 0 にすると関数がまったく呼び出せなくなり、すべての呼び出しがスロットリングされます。",["予約同時実行を 0 にする"]]},"DVA-C03-241":{"0":["接続を閉じずに放置すると不要な接続が DB に残り続け、接続数の上限にさらに達しやすくなります。",["接続を閉じずに放置する"]],"2":["max_connections を 0 にすると DB に一切接続できなくなり、サービスが停止します。",["max_connections を 0 にする"]],"3":["メモリを増やしても同時実行ごとに DB 接続が作られることは変わらず、接続数は減りません。",["メモリを増やす"]]},"DVA-C03-242":{"0":["強力な整合性の読み込みにしても 1 件ずつの往復は変わらず、消費キャパシティが 2 倍になるだけで速くなりません。",["強力な整合性のある読み込み"]],"2":["パーティションキーは DynamoDB のテーブルに必須で削除できません。項目の取得を速くする方法にもなりません。",["パーティションキーを削除する"]],"3":["Scan はテーブル全体を読み込むため、読み込みキャパシティと時間を大量に消費し、キーが分かっている場合は非効率です。",["Scan で商品テーブル全体を読み込んで"]]},"DVA-C03-243":{"1":["標準 - IA は保存料金が安い代わりに取り出し料金がかかるクラスで、頻繁に配信するファイルではコストが増え、表示速度も変わりません。",["S3 標準 - IA"]],"2":["バケットを公開すると非公開にする要件に反します。Transfer Acceleration は主にアップロードを速くする機能で、配信のキャッシュもしません。",["S3 バケットを公開して"]],"3":["各リージョンにバケットを作るとファイルの同期と管理の負荷が増え、利用者に URL を使い分けさせる運用も現実的ではありません。",["利用者に URL を使い分けさせる"]]},"DVA-C03-244":{"0":["メモリを一律に最小にすると CPU も減って実行時間が延び、総コストがかえって増えることがあります。",["メモリを最小にする"]],"2":["関数を 1 つに統合するにはコードの大幅な変更が必要で、コードをほとんど変えずにという要件に反し、料金単価も下がりません。",["関数を 1 つに統合する"]],"3":["プロビジョニングされた同時実行は待機分の費用が加わるため、実行コストはむしろ増えます。",["プロビジョニングされた同時実行"]]},"DVA-C03-245":{"1":["非同期呼び出しではクライアントに結果を返せないため、生成した部分から順に利用者に送るという要件を満たせません。",["非同期呼び出しに変更する"]],"2":["認証タイプは呼び出し時の認証の有無の設定で、応答の返し方は変わらず、認証をなくすとセキュリティも下がります。",["認証タイプを NONE にする"]],"3":["タイムアウトを延ばしても全体の生成を待ってから応答する点は変わらず、最初のバイトまでの時間は短くなりません。",["タイムアウトを延ばす"]]},"DVA-C03-246":{"0":["FIFO キューは順序と重複排除を保証するもので、メッセージを蓄積してまとめて呼び出す機能ではなく、呼び出し回数は減りません。",["FIFO キューに変更する"]],"2":["メモリを最小にしても呼び出し回数は変わらず、処理時間が延びてコストが下がらないこともあります。",["メモリを最小にする"]],"3":["可視性タイムアウトを 0 にすると処理中のメッセージがすぐ再び見えるようになり、重複処理が増えて呼び出し回数もかえって増えます。",["可視性タイムアウトを 0 にする"]]},"DVA-C03-247":{"0":["強力な整合性の読み込みは結果整合性の 2 倍のキャパシティを消費するため、コストはむしろ増えます。",["強力な整合性のある読み込み"]],"1":["読み込みキャパシティは返す属性ではなく読み込む項目全体のサイズで消費されるため、射影の属性を減らしても変わりません。",["属性をさらに減らす"]],"2":["標準 - IA はストレージ料金が安い代わりに読み書きの料金が高くなるため、読み込みが多い一覧表示ではコストが増えます。",["DynamoDB 標準 - IA"]]},"DVA-C03-248":{"0":["予約同時実行は実行環境を事前に初期化しないため、コールドスタートが再び発生し、遅延の改善を保てません。",["予約同時実行を 200 に設定する"]],"2":["メモリを最小にすると初期化や処理の時間が延び、コールドスタートの遅延が悪化します。待機分の費用の問題も残ります。",["メモリを最小にして"]],"3":["手作業での変更は忘れや誤りのリスクがあり、休日や夜間の設定戻しも必要で運用負荷が大きくなります。",["開発者が手作業で設定を変更する"]]},"DVA-C03-249":{"0":["VPC に接続した Lambda はパブリックサブネットに置いてもパブリック IP が付与されず通信できません。VPC からに限定する要件も満たせません。",["パブリックサブネットに移し"]],"1":["別のリージョンに移しても NAT ゲートウェイ経由の通信は変わらず、リージョン間のデータ転送料金とレイテンシーが増えます。",["別のリージョンに移す"]],"2":["NAT ゲートウェイを増やすと時間料金がさらに増えます。データ処理料金も減らず、VPC からに限定する制御にもなりません。",["アベイラビリティーゾーンごとに追加"]]},"DVA-C03-250":{"0":["最大のモデルはトークン単価が高い傾向があり、FAQ の回答や要約のような処理ではコストが増えるだけです。",["利用できる最大のモデル"]],"2":["毎回すべての履歴を送るとトークン数が増え続け、コストとレイテンシーがさらに悪化します。",["過去のすべての会話履歴"]],"3":["並列数を増やしてもトークンあたりの料金は変わらずコストは下がりません。スロットリングも起きやすくなります。",["並列数を 10 倍にする"]]},"MLA-C02-126":{"1":["パラメータ数を増やしても、MAE 120 が良いのか悪いのかを判断する基準は得られません。比較の基準がないまま複雑さを増すだけです。",["パラメータ数を増やしてから"]],"2":["MAE は回帰の誤差指標で、AUC は分類の順位付けの指標です。回帰の誤差を AUC に変換することはできず、評価の基準にもなりません。",["AUC に変換して"]],"3":["学習データでの誤差だけでは汎化性能が分からず、過学習していても良く見えます。値の良し悪しを判断する比較対象にもなりません。",["学習データでの MAE だけ"]]},"MLA-C02-127":{"1":["GPU 使用率が 20% と低いのはデータ供給が追いついていないことが多く、GPU を増やしても待ち時間は解消しません。使用率がさらに下がりコストだけが増えます。",["GPU の台数を 2 倍にする"]],"3":["学習率は収束の速さや安定性に関わる値で、1 ステップあたりの処理速度や GPU の待機時間には影響しません。ボトルネックの特定にもなりません。",["学習率を上げる"]],"4":["エポック数を増やすと学習時間がさらに延びるだけで、GPU がデータを待っている原因は解消しません。処理速度とは関係のない設定です。",["エポック数を増やす"]]},"MLA-C02-128":{"1":["何も改善しないまま運用を続けても、関係の薄いコンテキストが検索される問題は残ります。原因の切り分けにもなっていません。",["取り込み直さずに運用を続ける"]],"2":["温度を上げると出力のばらつきが増え、むしろ不正確な回答が増えやすくなります。検索で関係の薄い内容が渡されている問題も解決しません。",["温度を上げて"]],"3":["問題は正しい文書が検索されていない検索側にあります。生成モデルを大きくしても、誤ったコンテキストに基づく回答は改善しません。",["より大きなモデルに変更する"]]},"MLA-C02-129":{"0":["同じ顧客のレコードが学習と検証にまたがる分割のままでは、評価が過大になる原因が残ります。エポックを増やすと顧客固有の情報への過学習も進みます。",["ランダム分割のまま","エポック数を増やす"]],"1":["評価指標を変えても、同じ顧客が学習と検証の両方に含まれる分割の問題は残ります。不正検知のような不均衡データでは精度は特に参考になりません。",["精度（Accuracy）で評価する"]],"2":["検証データの割合を変えても、同じ顧客のレコードが学習側にも含まれる状態は変わりません。検証件数が減り評価もぶれやすくなります。",["5% に減らす"]]},"MLA-C02-130":{"1":["AUC は順位付けの指標で、確率の値が実際の発生率と合っているか（校正）は保証しません。AUC を上げても 0.3 と 0.1 のずれは解消しません。",["AUC がさらに高くなるまで"]],"2":["閾値を決めても予測確率そのものの値は変わらないため、期待損失の計算に使う確率のずれは残ります。",["閾値を 0.3 に固定する"]],"3":["実際には予測確率のほうが過大で、2 倍にすると実態とのずれがさらに広がります。一律の倍率では確率帯ごとのずれも補正できません。",["2 倍にして使う"]]},"MLA-C02-131":{"0":["プロビジョニングされた同時実行がないサーバーレス推論は、コールドスタートで 100 ミリ秒を超えることがあります。一定のトラフィックがあるなら常時稼働のほうが適しています。",["プロビジョニングされた同時実行なし"]],"2":["バッチ変換は大量データをまとめて処理するジョブで、ページを開くたびに即時応答する用途には使えません。",["バッチ変換"]],"3":["非同期推論はリクエストをキューに入れて後から処理する方式で、100 ミリ秒以内に結果を返す要件には向きません。",["Asynchronous Inference"]]},"MLA-C02-132":{"0":["常時稼働のエンドポイントは、リクエストのないアイドル時間も課金されます。1 日数十回の不定期な利用ではコストが無駄になります。",["常時稼働"]],"1":["バッチ変換はジョブの起動に数分かかり、1 件ずつの対話的な推論には向きません。起動のたびにインスタンスの料金もかかります。",["バッチ変換ジョブを起動する"]],"2":["マルチモデルエンドポイントも常時稼働のインスタンスに課金されます。モデルが 1 つで利用が少ない場合にコストを最小化する方法ではありません。",["常時稼働"]]},"MLA-C02-133":{"0":["月 1 回の処理のために常時稼働させると、月の大半はアイドル時間の料金が無駄になります。1 件ずつのリクエストは 1,000 万件の処理に非効率です。",["常時稼働させ","1 件ずつリクエストする"]],"1":["1,000 万回の個別呼び出しはオーバーヘッドが大きく、同時実行数の上限にも当たります。一括処理にはバッチ変換のほうが適しています。",["1,000 万回リクエストする"]],"2":["非同期推論は大きなペイロードや長時間の推論向けで、1 件ずつ送る方式は 1,000 万件の一括処理に非効率です。全件をまとめて処理するならバッチ変換が適しています。",["1 件ずつ送信する"]]},"MLA-C02-134":{"0":["X 系はメモリ容量を重視したインスタンスで、深層学習用のアクセラレーターを持ちません。大量の推論を低コストで処理する用途には向きません。",["メモリ最適化の X 系"]],"2":["Trainium は主に学習向けに最適化されたアクセラレーターです。推論を低コストで処理するなら推論に特化した Inferentia が適しています。",["学習用途として最適化"]],"3":["I 系は高速なローカルストレージを重視したインスタンスで、深層学習用のアクセラレーターを持ちません。推論の高速化やコスト削減にはつながりません。",["ストレージ最適化の I 系"]]},"MLA-C02-135":{"0":["Bedrock でファインチューニングしたモデルを EC2 にエクスポートして推論する仕組みはありません。自前で運用すると管理負荷も増えます。",["EC2 のスポットインスタンスにエクスポート"]],"1":["SageMaker AI Savings Plans は SageMaker の利用料を割り引く仕組みで、Bedrock には適用されません。使った分だけ支払う方式でもありません。",["SageMaker AI Savings Plans"]],"3":["バッチ推論は非同期の一括処理で、本番アプリの即時応答には使えません。カスタムモデルの推論方式がバッチ推論だけということもありません。",["バッチ推論のみ"]]},"MLA-C02-136":{"1":["プロビジョンドスループットは一定の処理能力を期間契約で確保する方式で、一度きりの大量処理には割高です。翌日でよい処理ならバッチ推論のほうが安くなります。",["1 年契約で購入する"]],"2":["ストリーミングは応答を逐次受け取って体感の待ち時間を短くする方式です。即時性が不要な大量処理のコスト削減にはなりません。",["ストリーミング API"]],"3":["オンデマンドの同期呼び出しを数十万回行うと料金が通常単価のままで、スロットリングへの対処も必要です。対応モデルではバッチ推論のほうが低料金です。",["1 件ずつ同期で呼び出す"]]},"MLA-C02-137":{"0":["クロスリージョン推論は推論リクエストを複数リージョンにルーティングする機能で、学習データをコピーする機能ではありません。",["学習データを他リージョンにコピー"]],"1":["クロスリージョン推論の目的はスループットと可用性の向上で、データ転送料金を無料にする機能ではありません。",["データ転送料金を無料にする"]],"2":["クロスリージョン推論は AWS のリージョン間でリクエストを分散するもので、モデルをオンプレミスで実行する機能ではありません。",["オンプレミス環境で実行する"]]},"MLA-C02-138":{"1":["同期呼び出しでは Lambda とエンドポイントの両方にタイムアウトがあり、数分かかる大きな動画の解析には向きません。完了通知の仕組みもありません。",["同期呼び出しする"]],"2":["クライアントのタイムアウトを延ばしても、リアルタイムエンドポイント側の呼び出しタイムアウトとペイロードの上限は変わりません。大きな動画には向きません。",["クライアントのタイムアウトを延長"]],"3":["サーバーレス推論は処理時間とペイロードの上限が小さく、数分かかる大きな動画の解析には使えません。完了通知の仕組みもありません。",["Serverless Inference"]]},"MLA-C02-139":{"1":["アンサンブルは複数のモデルで推論するため、計算量とメモリ使用量が複数倍になります。速度向上と軽量化の要件と逆の結果になります。",["アンサンブル"]],"2":["FP64 は FP32 の 2 倍のビット数で、メモリ使用量と計算量が増えて推論は遅くなります。軽量化とは逆の変換です。",["FP32 から FP64 に変換"]],"3":["バッチサイズを大きくすると同時に載せるデータが増え、メモリ使用量は増えます。小さなデバイスでメモリを減らしたい要件に反します。",["バッチサイズを大きく"]]},"MLA-C02-140":{"1":["EC2 の Auto Scaling グループでセッション管理を自前で実装するのは、仕組みを自前で作りたくないという要件に反し、運用負荷も大きくなります。",["自前のセッション管理を実装"]],"2":["リアルタイムエンドポイントはモデルの推論を提供する仕組みで、エージェントのセッション管理やツール呼び出しの認証の機能はありません。",["リアルタイムエンドポイント"]],"3":["ナレッジベースは文書を検索して回答の根拠にする RAG の仕組みで、ツールを実行したりエージェントを本番で動かしたりする機能ではありません。",["ナレッジベース"]]},"MLA-C02-141":{"0":["エンドポイントを 3 つに分けると、クライアントが順番に呼び出す実装が必要になり、1 回の呼び出しで完結させる要件に反します。ネットワークの往復も増えます。",["3 つのエンドポイント","順番に呼び出す"]],"2":["前処理をクライアントに任せると、クライアント側の実装を変えないという要件に反します。学習時と前処理がずれるおそれもあります。",["クライアントへ依頼する"]],"3":["ブラウザで前処理を実装するとクライアントの変更が必要になり、学習時と同じ scikit-learn の処理を保証するのも難しくなります。",["クライアントのブラウザで実装"]]},"MLA-C02-142":{"0":["性質の異なる 3 つのモデルを 1 つにまとめて再学習するのは大きな手間で、元の性能を保てる保証もありません。GPU の共有で済む問題です。",["1 つのモデルにマージして再学習"]],"1":["使用率が低い状態でインスタンスを大きくすると、使われない GPU がさらに増えてコストが上がります。",["より大きなタイプに変更する"]],"2":["リージョンを分けても、モデルごとに専用の GPU インスタンスを確保している状態は変わらず、使用率もコストも改善しません。",["リージョンを分けて"]]},"MLA-C02-143":{"0":["バッチ変換は大量データの一括処理用で、チャットのような対話的な用途には使えません。待ち時間はかえって長くなります。",["バッチ変換ジョブ"]],"1":["最大出力トークン数を増やすと生成が長くなり得るだけで、生成が終わるまで何も表示されない問題は変わりません。待ち時間はかえって延びます。",["最大出力トークン数を 10 倍"]],"3":["非同期推論は完了後に結果を受け取る方式で、生成途中の内容を表示できません。チャットの体感の待ち時間は短くなりません。",["非同期推論に変更"]]},"MLA-C02-144":{"0":["シリアル推論パイプラインは全コンテナを順番に実行する仕組みで、呼び出し時にどちらか一方のモデルを選んで使うことはできません。",["シリアル推論パイプライン"]],"1":["モデルごとにエンドポイントを分けるので 1 つで提供する要件に合わず、コールドスタートは常に低レイテンシーという要件にも反します。",["コールドスタートを許容する"]],"3":["マルチモデルエンドポイントは共通のコンテナで動くモデルが前提で、TensorFlow と PyTorch を 1 つのフレームワークのコンテナで処理することはできません。",["1 つのフレームワークのコンテナ"]]},"MLA-C02-145":{"0":["ガードレールは有害な入出力をフィルタリングする安全性の機能で、API をツールとして登録して呼び出す仕組みではありません。",["ガードレールに登録する"]],"1":["ファインチューニングは学習時点のデータを覚えさせるだけで、刻々と変わる最新の在庫を API から照会することはできません。",["ファインチューニングする"]],"2":["毎日貼り付けたデータは最新の在庫を反映できず、手作業の運用負荷もかかります。エージェントが API を呼び出す仕組みにもなりません。",["システムプロンプトに貼り付ける"]]},"MLA-C02-146":{"1":["シリアル推論パイプラインはコンテナを順番に連続実行する仕組みで、500 個のモデルから 1 つを選んで推論する用途には使えません。",["シリアル推論パイプライン"]],"2":["各コンポーネントのコピーを常駐させると、1 日数回しか使われない 500 個のモデルのために資源を確保し続けることになり、コストが無駄になります。",["コピー数を 1 以上に保つ"]],"3":["500 個のエンドポイントを個別に作ると、毎週の追加・更新のたびに作成や管理が必要になり、運用負荷が大きくなります。",["それぞれにサーバーレス推論エンドポイント"]]},"MLA-C02-147":{"0":["月末 2 日のために 1 か月中常時稼働させると、閑散期のコストが無駄になります。経費チェックに GPU が必要という前提もありません。",["1 か月中常時稼働させる"]],"1":["担当者が手動で呼び出し続けるのは運用負荷が大きく、確実にコールドスタートを防げる保証もありません。",["担当者が手動でモデルを呼び出し続けて"]],"3":["非同期推論は完了を待つ方式で、月末の集中時にも遅延なく応答するという要件を満たしません。",["非同期推論に切り替え"]]},"MLA-C02-148":{"0":["300 個の GPU エンドポイントを常時稼働させると、1 日数十件の利用ではほとんどがアイドル時間の料金になり、コストが見合いません。",["それぞれに GPU のリアルタイムエンドポイント"]],"2":["サーバーレス推論は GPU に対応していません。GPU が必要な画像モデルを CPU で動かすと、数百ミリ秒の応答を保てないおそれがあります。",["CPU のサーバーレス推論"]],"3":["毎晩のバッチ変換ではリクエストに即時に応答できず、数百ミリ秒の応答時間という要件を満たしません。",["毎晩のバッチ変換"]]},"MLA-C02-149":{"1":["エンドポイントを手動で管理するのは、インスタンス管理や容量計画をしたくないという要件に反し、Bedrock の API やガードレールとも別の実装が必要になります。",["手動で管理し","別の呼び出し処理を追加"]],"2":["言語モデルの重みは Lambda のデプロイパッケージのサイズ上限を大きく超え、GPU も使えないため、推論の基盤としては現実的ではありません。",["Lambda 関数のデプロイパッケージ"]],"3":["ナレッジベースは文書を検索するための仕組みで、モデルの重みを取り込んでホストする機能はありません。",["ナレッジベースにモデルの重みファイル"]]},"MLA-C02-150":{"0":["他アカウントのアクセスキーを共有するのはセキュリティ上の重大な問題で、IAM のベストプラクティスに反します。認証情報の共有でクォータを回避すべきではありません。",["アクセスキーを共有して"]],"2":["バッチ推論は非同期の一括処理で結果が出るまで時間がかかり、数秒以内の応答が必要なリクエストには使えません。",["バッチ推論ジョブに切り替える"]],"4":["最大出力トークン数を引き上げると消費するトークンが増え、トークンのクォータに早く達してスロットリングが悪化します。",["上限まで引き上げる"]]},"MLA-C02-151":{"0":["AWS Backup はデータのバックアップと復元のサービスで、SageMaker エンドポイントの構成を他アカウントに複製する手段ではありません。",["AWS Backup でコピーする"]],"3":["AWS Config の適合パックはリソースの構成がルールに準拠しているかを評価するもので、エンドポイントを作成する機能はありません。",["適合パックでエンドポイントを作成"]],"4":["手順を共有して各アカウントで手作業すると、操作のばらつきやミスが残り、同じ構成を再現性高く作る要件を満たせません。",["作業手順を共有し"]]},"MLA-C02-152":{"1":["ノートブックインスタンスは開発用の環境で、推論エンドポイントを定義するリソースではありません。",["NotebookInstance のみ"]],"2":["エンドポイントはエンドポイント設定を参照し、エンドポイント設定はモデルを参照するため、Endpoint だけでは定義できません。",["のみ"]],"3":["Lambda 関数と S3 バケットだけでは SageMaker のモデル、エンドポイント設定、エンドポイントが定義されず、推論エンドポイントは作られません。",["AWS::Lambda::Function"]]},"MLA-C02-153":{"0":["S3 Glacier Flexible Retrieval はアーカイブ用のストレージで取り出しに時間がかかり、SageMaker がコンテナイメージを取得する保管先として使えません。",["S3 Glacier Flexible Retrieval"]],"2":["EFS は共有ファイルシステムで、SageMaker のモデルが参照するコンテナイメージのレジストリではありません。イメージは ECR から取得します。",["Amazon EFS"]],"3":["Secrets Manager はパスワードや API キーなどの機密情報を管理するサービスで、コンテナイメージは保管できません。",["AWS Secrets Manager"]]},"MLA-C02-154":{"0":["Ground Truth Plus は専門の作業者がラベル付けを行うサービスで、リポジトリやパイプライン、CI/CD を用意する機能ではありません。",["Ground Truth Plus"]],"1":["Clarify はデータやモデルのバイアス検出と予測の説明を行う機能で、プロジェクトの環境をテンプレートから用意する機能ではありません。",["SageMaker Clarify"]],"3":["Canvas はノーコードでモデルを作って予測する機能で、組織標準の CI/CD やパイプラインをまとめて用意する機能ではありません。",["SageMaker Canvas の予測機能"]]},"MLA-C02-155":{"1":["Model Monitor のスケジュールはデプロイ済みモデルの品質を定期的に監視する機能で、JupyterLab 起動時の環境設定は行えません。",["Model Monitor のスケジュール"]],"2":["S3 のイベント通知はオブジェクトの作成などで処理を起動する仕組みで、Studio のアプリ起動時に設定を実行することはできません。",["S3 のイベント通知"]],"3":["AWS Config ルールはリソースの構成を評価するもので、JupyterLab の起動時にパッケージのインストールやプロキシ設定を行う機能はありません。",["AWS Config ルール"]]},"MLA-C02-156":{"1":["Elastic Load Balancing はトラフィックを分散するサービスで、SageMaker エンドポイントのインスタンス数を増減させる機能はありません。",["Elastic Load Balancing"]],"2":["SageMaker エンドポイントのインスタンスは EC2 Auto Scaling グループでは管理されず、Application Auto Scaling に登録してスケーリングします。",["EC2 Auto Scaling グループ"]],"3":["AWS Auto Scaling プランは複数リソースのスケーリングをまとめて設定する仕組みで、SageMaker のスケーリング対象とポリシーは Application Auto Scaling に登録します。",["AWS Auto Scaling プランのみ"]]},"MLA-C02-157":{"0":["毎日手動で削除と作成を繰り返すのは運用負荷が高く、作成中は推論できません。作業ミスで停止が長引くおそれもあります。",["手動で削除し"]],"1":["SageMaker のエンドポイントは EC2 Auto Scaling グループに登録できず、Application Auto Scaling でスケーリングします。",["EC2 Auto Scaling グループに登録する"]],"2":["ピークに合わせた台数で固定すると、Savings Plans で割り引いても夜間の余剰台数の料金が残り、コストを最適化できません。",["ピークに合わせた台数で固定し"]]},"MLA-C02-158":{"1":["手動インストールはスケールアウトや再起動のたびに再現されず、運用負荷も大きくなります。エンドポイントの推論環境を安定して用意する方法ではありません。",["ノートブックから手動でインストール"]],"2":["Glue のストリーミングジョブは ETL 向けのサービスで、推論エンドポイントとしてモデルをホストする用途には向きません。",["AWS Glue のストリーミングジョブ"]],"3":["Lambda レイヤーは Lambda 関数専用の仕組みで、SageMaker のコンテナから読み込むことはできません。",["Lambda レイヤーにまとめ"]]},"MLA-C02-159":{"0":["常にピーク時の台数で固定すると、ピーク以外の時間帯も余剰のインスタンス料金がかかり、コストが無駄になります。",["常にピーク時の台数で固定する"]],"2":["スケールアウトのクールダウンを長くすると、次の台数追加までの待ち時間が延び、急増への対応はさらに遅れます。",["クールダウン期間を長くする"]],"3":["インスタンスを小さくしても、新しいインスタンスの起動にかかる時間は変わらず、増加が間に合わない問題は解消しません。予測できるピークには事前の確保が有効です。",["インスタンスタイプを小さくして"]]},"MLA-C02-160":{"1":["学習のたびに手動でインストールすると、環境の再現性が保てず手間もかかります。マージをきっかけにした自動ビルドや脆弱性スキャンも行えません。",["手動でインストールする"]],"2":["個人の PC でのビルドは環境の差異が生じ、自動化も脆弱性スキャンもされません。SageMaker はイメージを S3 ではなく ECR から取得します。",["各自の PC でビルドし","S3 にアップロードする"]],"3":["毎回手動でビルドすると、マージのたびに自動でビルドする要件を満たさず、脆弱性スキャンも組み込まれません。",["毎回手動でビルドする"]]},"MLA-C02-161":{"0":["Athena は S3 上のデータを SQL で分析するサービスで、PyTorch の深層学習を実行する環境ではありません。",["SQL に書き換えて Amazon Athena で実行"]],"1":["数個のパッケージを追加するだけなら独自コンテナは不要です。OS から作ると、イメージの作成や保守の負荷が大きくなります。",["OS から独自のコンテナイメージを作成"]],"3":["EC2 に手動で PyTorch を入れると、インスタンスの管理や環境構築の手間が増え、SageMaker のマネージドな学習の利点も失われます。",["PyTorch を手動でインストール"]]},"MLA-C02-162":{"0":["デプロイ後の手動変更は IaC の定義との差異（ドリフト）を生み、次のデプロイで設定が元に戻るおそれがあります。",["コンソールで本番のインスタンスタイプを手動で変更"]],"1":["開発環境だけ手作業で作ると環境間の構成に差異が生じ、同じコードから一貫した構成で作るという IaC の利点が失われます。",["開発環境はコンソールで作成する"]],"3":["コードを環境ごとにコピーするのは要件に反し、修正の反映漏れで環境間の差異が生じやすく保守性も下がります。",["CDK アプリをコピーして個別に修正"]]},"MLA-C02-163":{"0":["毎回文書を貼り付けるとトークンの消費が大きく、大量の文書は入りきりません。各アカウントに同じ RAG 構成を作るという要件にも答えていません。",["プロンプトに毎回貼り付ける"]],"2":["手順書を見ながらの手作業では設定の差異やミスが生じやすく、同じ内容を確実に再現することができません。",["手順書を見ながら作成する"]],"3":["本番から開発アカウントのナレッジベースを参照すると環境の分離が崩れ、開発での変更が本番に影響します。各アカウントに作成する要件も満たしません。",["本番アカウントから直接参照する"]]},"MLA-C02-164":{"1":["エンドポイント設定は作成後に変更できません。モデルを差し替えるには新しいエンドポイント設定を作る必要があります。",["既存のエンドポイント設定を直接編集"]],"2":["エンドポイントを削除すると、作り直しが終わるまで推論できない停止時間が発生し、サービスを止めないという要件に反します。",["エンドポイントを削除し"]],"3":["S3 のファイルを上書きしても、稼働中のインスタンスは起動時に読み込んだモデルを使い続けます。モデルの版管理もできなくなります。",["上書きするだけにする"]]},"MLA-C02-165":{"0":["パブリックサブネットに移すとインターネットへの経路ができ、プライベートで実行するというセキュリティ要件に反します。",["パブリックサブネットに移動する"]],"1":["S3 の権限を外すと、経路があっても学習データを読み込めなくなります。問題はネットワークの経路で、権限を外しても解決しません。",["S3 の権限を外す"]],"2":["バケットを公開しても、プライベートサブネットからは S3 への経路がないため読み込めず、データ漏えいのリスクだけが増えます。",["パブリックアクセス可能にする"]]},"MLA-C02-166":{"0":["毎回すべてのデータを各インスタンスの EBS にコピーするのは、課題になっているダウンロード時間そのもので、解決になりません。",["毎回すべてのデータをコピーする"]],"1":["Glacier Deep Archive は取り出しに数時間かかるアーカイブ用のストレージで、学習で繰り返し高速に読み込む用途には使えません。",["S3 Glacier Deep Archive"]],"2":["DynamoDB は項目サイズの上限が 400 KB のキーバリュー型データベースで、大量の画像を高スループットで読み込む学習用のストレージには向きません。",["DynamoDB に格納する"]]},"MLA-C02-167":{"0":["インターネットゲートウェイを作るとインターネットへの経路ができ、すべての通信を VPC 経由にしてインターネットを使わない要件に反します。",["インターネットゲートウェイを作成する"]],"1":["パブリックインターネットのみのモードでは、Studio の通信が SageMaker 管理のネットワークからインターネット経由になり、自社の VPC を通りません。",["パブリックインターネットのみのモード"]],"3":["個人の PC から本番データを直接操作すると、ネットワークの統制ができず情報漏えいのリスクが高まります。金融機関のセキュリティ要件に反します。",["PC から本番データを直接操作する"]]},"MLA-C02-168":{"0":["Description の文字数が問題ならテンプレートの検証の時点で失敗します。インスタンスの起動エラーとは関係ありません。",["Description 欄の文字数"]],"1":["タグの数はインスタンスの起動とは関係せず、起動に関するエラーの原因にはなりません。",["タグの数が多すぎないか"]],"3":["S3 のバージョニングはオブジェクトの履歴を残す機能で、エンドポイントのインスタンスを起動できるかどうかとは関係ありません。",["バージョニングが有効かどうか"]]},"MLA-C02-169":{"0":["スタックを削除して作り直すと、その間エンドポイントが停止して可用性が損なわれます。手動変更が上書きされる問題も防げません。",["スタックを削除して作り直す"]],"3":["手動変更を記録しないと、テンプレートとの差異に誰も気付けず、同じ巻き戻しが再発しやすくなります。",["記録しないことにする"]],"4":["IaC の管理をやめると、環境の再現性や変更の追跡ができなくなります。手作業による設定のばらつきや誤りも増えます。",["すべてコンソールで管理する"]]},"MLA-C02-170":{"0":["CPU のみにすると 70 GB の言語モデルの推論は極めて遅くなり、ロードに時間がかかってヘルスチェックが間に合わない問題も解決しません。",["CPU のみのタイプに変更する"]],"1":["データキャプチャは推論の入出力を S3 に記録する機能で、モデルのダウンロードや起動にかかる時間とは関係しません。",["データキャプチャの割合を 100%"]],"3":["最小台数の設定は起動後のスケーリングに関わるもので、エンドポイント作成時にヘルスチェックが時間切れになる問題は解決しません。",["最小台数を 0 に設定する"]]},"MLA-C02-171":{"0":["Glue DataBrew は視覚的にデータを整形・準備するツールで、学習や評価、条件付きのモデル登録を含む ML のワークフローは組めません。",["AWS Glue DataBrew のジョブ"]],"1":["Glue のワークフローは ETL のジョブやクローラーを連携させる仕組みで、学習や Model Registry への条件付き登録には向きません。",["AWS Glue のワークフロー"]],"2":["EventBridge Scheduler はジョブを定時に起動するだけで、処理から登録までのステップや条件分岐を定義する機能はありません。",["EventBridge Scheduler"]]},"MLA-C02-172":{"1":["変換ステップはバッチ変換で一括推論を行うステップで、評価値に応じて後続の処理を分岐させる機能はありません。",["変換ステップ（TransformStep）"]],"2":["処理ステップは前処理や評価の計算を行うもので、それだけでは AUC の値に応じて登録するかどうかを分岐できません。",["処理ステップ（ProcessingStep）のみ"]],"3":["チューニングステップはハイパーパラメータの探索を行うステップで、評価値に応じた分岐の制御は行いません。",["チューニングステップ（TuningStep）"]]},"MLA-C02-173":{"1":["クロスリージョンレプリケーションは S3 のオブジェクトを別リージョンに複製する機能で、パイプラインのステップの再実行を省くことはできません。",["クロスリージョンレプリケーション"]],"2":["マネージドスポットトレーニングは学習の料金を下げる機能で、変更のないステップの結果を再利用して実行自体を省くことはできません。",["マネージドスポットトレーニング"]],"3":["Model Monitor のベースラインは本番データの監視の基準となる統計で、パイプラインのステップの再実行とは関係ありません。",["Model Monitor のベースライン"]]},"MLA-C02-174":{"0":["承認ステータスは管理上の状態を表す属性で、推論の処理速度には影響しません。",["推論レイテンシーを短縮する"]],"1":["承認ステータスを変えても重みが暗号化されることはありません。暗号化は S3 や KMS の設定で行います。",["自動で暗号化する"]],"2":["承認は学習済みモデルを本番に進めてよいかの判断で、学習を再実行するきっかけではありません。",["学習を自動で再実行する"]]},"MLA-C02-175":{"0":["SQS はメッセージを受け渡すキューで、複数の処理の順序や分岐、承認待ちを含むワークフローを制御する機能はありません。",["Amazon SQS"]],"1":["CloudFront はコンテンツを配信する CDN で、Lambda や Glue、学習ジョブを連携させるワークフローの機能はありません。",["Amazon CloudFront"]],"3":["Elastic Beanstalk は Web アプリをデプロイ・運用するサービスで、複数のサービスを連携させるワークフローエンジンではありません。",["AWS Elastic Beanstalk"]]},"MLA-C02-176":{"0":["過去のデータキャプチャに対するバッチ変換は、実際のライブの本番トラフィックでの比較にならず、要件を満たしません。",["過去のデータキャプチャ"]],"1":["重み付けで 10% を送ると、その利用者には新モデルの応答が返ります。利用者への影響を避けたいという要件に反します。",["新モデルに 10% のトラフィックを送る"]],"3":["カナリアの移行では、切り替えた一部の利用者に新モデルの応答が実際に返るため、利用者に影響を与えないという要件に反します。",["カナリアトラフィック移行"]]},"MLA-C02-177":{"0":["1 時間ごとのポーリングでは承認からデプロイまでに遅延が生じ、ノートブックの実行は再現性も低くなります。イベント駆動のほうが確実です。",["1 時間ごとにポーリング","ノートブックを実行して"]],"2":["承認ステータスを参照しないと人による品質のゲートがなくなり、問題のあるモデルも本番に出てしまいます。",["承認ステータスは参照しない"]],"3":["定時実行ではマージや承認のタイミングに連動せず、承認を経ないモデルがデプロイされるおそれもあります。",["毎日決まった時間に"]]},"MLA-C02-178":{"0":["毎週の手動実行は運用負荷がかかり、実行漏れも起きます。自動で実行するという要件を満たしません。",["毎週ノートブックから手動で実行する"]],"1":["常時稼働の EC2 はサーバーの管理が必要で、週 1 回の実行のためにアイドル時間もコストがかかります。",["EC2 インスタンスを常時稼働させ"]],"3":["Model Monitor のスケジュールはデータやモデル品質の監視ジョブを実行するもので、学習パイプラインを起動する仕組みではありません。",["Model Monitor のスケジュール"]]},"MLA-C02-179":{"0":["実行のたびにスクリプトを書き換えると、ミスが起きやすく実行の再現性も保てません。",["実行のたびに書き換える"]],"1":["開発用の実行をやめると、小さなデータでの素早い検証ができなくなり、両方で実行したいという要件に反します。",["開発用の実行はやめる"]],"2":["定義をコピーすると、修正のたびに複数の定義を直す必要があり、反映漏れや差異が生じやすくなります。",["定義をコピーして別名で作成する"]]},"MLA-C02-180":{"0":["本番に直接デプロイすると、問題が利用者に影響してから気付くことになり、ステージングで検証してから進めるという要件に反します。",["本番に直接デプロイし"]],"1":["ローカル環境のテストだけでは本番に近いエンドポイントでの負荷テストや結合テストができず、合格を条件に本番へ進む仕組みもありません。",["開発者のローカル環境だけで"]],"2":["同時に更新すると、ステージングでのテスト結果を待たずに本番が変わり、検証のゲートとして機能しません。",["同時に更新する"]]},"MLA-C02-181":{"0":["テストデータでの評価では、実際の利用者のクリック率という本番での反応は測れません。",["開発環境のテストデータで評価する"]],"1":["シャドウテストでは新バージョンの結果が利用者に返らないため、クリック率のような利用者の反応は測れません。",["シャドウテスト"]],"3":["全トラフィックを切り替えると同時期の比較対象がなくなり、10% だけに返す要件にも反します。性能が悪ければ全利用者に影響します。",["全トラフィックを切り替えて"]]},"MLA-C02-182":{"0":["担当者の目視による判断では、後続の条件ステップで自動的に値を参照して分岐させることができません。",["担当者が目視で判断する"]],"1":["ハイパーパラメータは学習の設定値を渡す仕組みで、評価結果を後続の条件ステップに受け渡す方法ではありません。",["ハイパーパラメータとして渡す"]],"2":["パイプライン名は実行前に決まる識別子で、実行中に算出された AUC を入れて条件ステップから参照することはできません。",["パイプラインの名前に含める"]]},"MLA-C02-183":{"0":["レビューも評価もなく本番に反映すると、品質の低下を検知する仕組みがなく、まさに防ぎたい事態が起こります。",["レビューなしでそのまま本番に反映"]],"2":["プロンプトの文字数は回答品質の指標ではなく、短くなっても品質が下がることはあります。品質を確認するゲートになりません。",["文字数が減った場合だけ"]],"3":["苦情を待つのは品質の低下が本番に出た後の対応で、本番に反映される前に防ぐという要件を満たしません。",["苦情が来るまで様子を見る"]]},"MLA-C02-184":{"0":["月 1 回の手動実行では不定期に届くデータにすぐ対応できず、データの到着をきっかけに自動で実行する要件を満たしません。",["担当者が手動でパイプラインを実行"]],"1":["EC2 でのポーリングはサーバーの管理とコストがかかり、イベントで検知する方法に比べて運用負荷が高くなります。",["1 分ごとに S3 の一覧を取得"]],"3":["取引先に Studio へログインさせるのはアクセス管理の面で不適切で、データの到着を自動で検知する仕組みにもなりません。",["SageMaker Studio へのログインを依頼"]]},"MLA-C02-185":{"1":["別エンドポイントと Route 53 の加重ルーティングは追加のインフラ運用が必要で、手動で重みを戻すので自動ロールバックの要件を満たしません。",["Route 53 の加重ルーティング","手動で重みを戻す"]],"2":["ローリング更新ではごく一部のキャパシティだけで試せず、問題時に手動で作り直すため、数分以内に自動で戻すという要件を満たしません。",["全インスタンスを順番に","手動で作り直す"]],"3":["一度に全トラフィックを切り替えると、問題があった場合にすべての利用者に影響し、悪化時に自動で戻す仕組みもありません。",["全トラフィックを一度に切り替える"]]},"MLA-C02-186":{"2":["本番で学習し直すと、データサイエンス用アカウントで登録・検証したモデルとは別物になり、共有の目的を果たせません。コストも二重にかかります。",["最初から学習し直す"]],"3":["暗号化を解除してバケットを公開すると、誰でもモデルを取得できる状態になり、セキュリティ上不適切です。",["バケットを公開する"]],"4":["アクセスキーを埋め込むと漏えいのリスクがあり、IAM のベストプラクティスに反します。クロスアカウントではロールとリソースポリシーを使います。",["アクセスキーを本番アカウントのパイプラインに埋め込む"]]},"MLA-C02-187":{"0":["学習ステップを削除すると新しいデータでモデルを更新できなくなり、再学習の目的が失われます。一時的なエラーへの対処にもなりません。",["学習ステップを削除し"]],"2":["キャッシュは結果を再利用する機能で、無効にしても容量不足やクォータの一時的なエラーは解消しません。",["キャッシュを無効にする"]],"3":["学習コードや定義には問題がないため、作り直しても一時的なエラーは解消しません。手作業の負荷もかえって増えます。",["定義を毎回作り直す"]]},"MLA-C02-188":{"0":["承認をなくすと人による確認のゲートが消え、評価データに不備があれば性能の低いモデルがそのまま本番に出てしまいます。",["承認のステップをなくし"]],"2":["基準値を下げると性能の低いモデルがさらに合格しやすくなり、再発防止とは逆の結果になります。",["評価の基準値を下げて"]],"3":["すべて手作業にすると運用負荷が増え、人為的なミスも起きやすくなります。評価データの不備を検知する仕組みにもなりません。",["すべて手作業でデプロイする"]]},"MLA-C02-189":{"1":["DEFAULT エンドポイントは常に最新のバージョンを指すため、深夜に更新しても検証前の変更がそのまま本番に届き、すぐに戻すこともできません。",["DEFAULT エンドポイントを呼び出したまま"]],"2":["変更をやめるとエージェントを改善できず、頻繁に改善したいという前提に反します。安全なリリースの仕組みにもなりません。",["指示文の変更をやめ"]],"3":["変更のたびにランタイムを作り直してアプリのコードを書き換えるのは手間がかかり、すぐに切り戻すことも難しくなります。",["新しいエージェントランタイムを作成","ランタイムの ID を書き換えて"]]},"MLA-C02-190":{"0":["パイプラインは手動なら正常に完了しているため、デプロイ先のインスタンスタイプは起動しない原因になりません。問題はイベントがパイプラインを起動するまでの部分です。",["インスタンスタイプが GPU かどうか"]],"1":["ハイパーパラメータは学習の設定で、承認イベントからパイプラインが起動するかどうかとは関係ありません。",["ハイパーパラメータが前回と同じかどうか"]],"2":["ライフサイクルルールはオブジェクトの移行や削除の設定で、承認イベントで EventBridge のルールが動くかどうかとは関係ありません。",["ライフサイクルルールがあるかどうか"]]},"MLA-C02-191":{"0":["CPU 使用率はインスタンスの負荷を示す指標で、入力データの分布が学習時と変わったかどうかは分かりません。",["CPUUtilization"]],"1":["CloudTrail で数えられるのは API の呼び出しの記録で、入力データの中身や分布の変化は分かりません。",["呼び出し回数を数える"]],"2":["AWS Config はリソースの設定変更を記録するもので、推論に入力されるデータの分布の変化は監視できません。",["エンドポイントの設定変更を記録"]]},"MLA-C02-192":{"0":["WAF は HTTP リクエストのレベルでブロックする仕組みで、そのログには Bedrock Guardrails がプロンプトや応答を判定した結果は含まれません。",["AWS WAF のログ"]],"2":["CreateGuardrail の記録はガードレールを作成した設定変更の履歴で、実際にブロックされたリクエストの件数や傾向は分かりません。",["CreateGuardrail の呼び出し"]],"3":["VPC フローログは IP アドレスやポートなどの通信の記録で、ガードレールがどのリクエストをブロックしたかは分かりません。",["VPC フローログ"]]},"MLA-C02-193":{"0":["CPUCreditBalance はバースト可能な EC2 インスタンスの CPU クレジットの残高で、モデルコンテナのエラーは分かりません。",["CPUCreditBalance"]],"2":["BucketSizeBytes は S3 バケットの保存容量を示すメトリクスで、エンドポイントの推論エラーとは関係ありません。",["BucketSizeBytes"]],"3":["ConsumedReadCapacityUnits は DynamoDB の読み込みキャパシティの消費量で、SageMaker のエンドポイントのエラーは示しません。",["ConsumedReadCapacityUnits"]]},"MLA-C02-194":{"0":["VPC フローログは通信の送信元・宛先やポートなどを記録するだけで、プロンプトや出力の内容、トークン数は記録されません。",["VPC フローログ"]],"1":["AWS Config はリソースの設定を記録・評価するもので、各リクエストのプロンプトやモデルの出力は記録しません。",["AWS Config のルール"]],"3":["S3 のサーバーアクセスログはバケットへのリクエストの記録で、Bedrock の入力プロンプトや出力、トークン数は含まれません。",["S3 のサーバーアクセスログ"]]},"MLA-C02-195":{"1":["IAM ポリシーはアクセス権限の定義で、入力データの分布の変化を判断する比較の基準にはなりません。",["IAM ポリシー"]],"2":["Auto Scaling ポリシーはインスタンス数を増減させる設定で、特徴量の統計の比較基準にはなりません。",["Auto Scaling ポリシー"]],"3":["ハイパーパラメータはモデルの学習の設定で、入力データの分布がずれたかを判断する統計情報を含みません。",["ハイパーパラメータの一覧"]]},"MLA-C02-196":{"0":["S3 のサーバーアクセスログはバケットへのリクエストの記録で、推論コンテナが出力したエラーメッセージは含まれません。",["S3 のサーバーアクセスログ"]],"1":["Config の設定履歴はリソースの構成の変化を記録するもので、コンテナのアプリケーションログやスタックトレースは含まれません。",["AWS Config の設定履歴"]],"2":["Cost and Usage Report は料金と使用量の明細で、推論コンテナのエラー内容は確認できません。",["AWS Cost and Usage Report"]]},"MLA-C02-197":{"0":["学習前の一度きりの分析では、本番稼働中に時間とともに判定が偏ってくる変化を捉えられません。",["本番では監視しない"]],"2":["CloudTrail で分かるのは呼び出し元などの API の記録で、属性ごとの判定の偏りは分かりません。",["InvokeEndpoint の呼び出し元を確認"]],"3":["欠損率はデータ品質の一部しか表さず、特定の属性に対する承認率の差などのバイアスは分かりません。",["欠損率だけを"]]},"MLA-C02-198":{"0":["担当者が毎朝確認する方式では対応に遅れが出て運用負荷もかかり、しきい値を超えたら自動で起動する要件を満たしません。",["担当者が毎朝確認し"]],"2":["ドリフトの有無を見ずに毎晩再学習すると、不要な学習のコストが生じ、しきい値をきっかけに起動する要件にも合いません。",["ドリフトの有無は確認しない"]],"3":["AWS Config はリソースの構成を評価するサービスで、データのドリフトは検出できません。",["AWS Config のルールでドリフトを検出"]]},"MLA-C02-199":{"0":["月 1 回のログ確認では、ピーク時のスロットリングの増加にすぐ気付けず、通知の仕組みにもなりません。",["月に 1 回確認する"]],"2":["Inspector は EC2 やコンテナイメージなどの脆弱性を検査するサービスで、Bedrock のスロットリングは監視できません。",["Amazon Inspector"]],"3":["Trusted Advisor のセキュリティチェックは設定上のリスクを確認するもので、リクエストが制限されているかは分からず通知もできません。",["セキュリティチェック"]]},"MLA-C02-200":{"0":["学習ジョブのログは学習時の記録で、本番の予測でどの特徴量が強く効いているかの変化は分かりません。",["学習ジョブのログ"]],"1":["AWS Config はエンドポイントの設定変更を記録するだけで、予測に対する特徴量の寄与度の変化は監視できません。",["AWS Config でエンドポイントの設定変更"]],"3":["CPU 使用率はインスタンスの負荷を示すだけで、特徴量の寄与度や予測の根拠の変化は分かりません。",["CPU 使用率を監視する"]]},"MLA-C02-201":{"0":["キャプチャを無効にすると比較するデータがなくなり、ドリフトを検出できません。監視を続けたいという前提に反します。",["監視をやめる"]],"1":["インスタンスを増やしても S3 に保存されるキャプチャの量は減らず、インスタンスの料金が増えるだけです。",["インスタンス数を増やす"]],"4":["データキャプチャの保存先は S3 で、EBS には直接保存できません。EBS は S3 より保存単価も高く、費用削減になりません。",["Amazon EBS に保存する"]]},"MLA-C02-202":{"0":["しきい値を 0 にするとすべての予測が自動で確定し、信頼度の低い誤りも見逃されます。人が確認する仕組みもなくなります。",["しきい値を 0 に"]],"1":["全件を人が確認するとコストが大きく、結果を記録しないので再学習用のラベルとしても使えません。",["すべての予測を人が確認し","結果は記録しない"]],"3":["破棄して再提出を求めると利用者の負担が増え、人による確認結果を再学習に活用することもできません。",["破棄し","再提出を求める"]]},"MLA-C02-203":{"1":["インスタンスタイプは処理性能やコストに関わる設定で、入力データの分布の変化を監視することはできません。",["インスタンスタイプを変更する"]],"2":["オブジェクト数ではデータの件数の変化しか分からず、特徴量の分布が学習時と変わったかどうかは判断できません。",["S3 のオブジェクト数だけ"]],"3":["バッチ推論でも入力データをベースラインと比べる処理を組み込めば監視できます。切り替えの必要はなく、常時稼働のコストも増えます。",["バッチ推論は監視できない"]]},"MLA-C02-204":{"0":["AWS Health Dashboard は AWS 側のサービス障害やメンテナンスの情報を表示するもので、モデルの監視の設定状況や違反は分かりません。",["AWS Health Dashboard"]],"1":["Trusted Advisor はコストやセキュリティなどのベストプラクティスを確認するもので、モデルのモニタリングの状態はまとめて表示しません。",["AWS Trusted Advisor"]],"2":["手動で一覧表を作ると作成と更新の手間がかかり、数十個のモデルの最新の状態を正確に保つのが困難です。",["手動で一覧表を作る"]]},"MLA-C02-205":{"0":["AWS Config は Bedrock の設定変更を記録するだけで、トークン使用量の急増は検知できません。",["AWS Config で Bedrock の設定変更"]],"1":["VPC フローログは通信量の記録で、Bedrock のトークン使用量そのものや通常パターンからの逸脱は分かりません。",["VPC フローログの通信量"]],"2":["固定のしきい値は要件で避けたい方法で、時間帯による変動を考慮できないため誤検知や見逃しが増えます。1 日の合計では急増の検知も遅れます。",["固定のしきい値アラームを 1 つだけ"]]},"MLA-C02-206":{"0":["データキャプチャを無効にすると推論結果が残らず、正解ラベルと比較する対象がなくなって精度を計算できません。",["データキャプチャを無効にして"]],"1":["タイムスタンプの近さでは推論結果と正解ラベルを一意に対応付けられず、誤った組み合わせで不正確な精度になります。",["タイムスタンプの近い順に"]],"3":["環境変数はコンテナの設定値を渡す仕組みで、後から届く大量の正解ラベルを格納して推論結果と結合する用途には使えません。",["エンドポイントの環境変数に設定"]]},"MLA-C02-207":{"1":["毎日の無条件の再学習はコストが大きく、精度が下がっているかや劣化の原因が分からないまま運用することになります。",["監視を不要にする"]],"2":["レイテンシーやエラーはシステムの稼働状況を表す指標で、予測の精度の低下やデータの変化は分かりません。",["精度低下の代わりとして監視する"]],"3":["30 日間何も監視しないと劣化の兆候に早く気付けず、手動の集計は運用負荷も大きくなります。",["何も監視せず","手動で精度を集計する"]]},"MLA-C02-208":{"0":["Invocations は呼び出し回数を示すだけで、回答に根拠があるかどうかといった内容の品質は分かりません。",["Invocations メトリクス"]],"1":["temperature を毎日変えても品質を定量的に測る仕組みにはならず、条件が変わるため品質の推移も比較できなくなります。",["temperature を毎日変更して"]],"2":["レイテンシーは応答の速さの指標で、根拠のない回答が増えたかどうかという回答内容の品質は分かりません。",["レイテンシーの p99"]]},"MLA-C02-209":{"0":["タイムアウトを短くすると、コールドスタート中のリクエストが失敗して再試行が増えるだけで、原因の確認にも改善にもなりません。",["タイムアウトを短くして再試行を増やす"]],"1":["最大の GPU インスタンスを 24 時間稼働させると、利用が少ない時間も課金されてコストが過大になり、コストを抑える要件に反します。",["最大サイズの GPU インスタンス","24 時間稼働させる"]],"2":["サーバーレス推論はメモリに比例して計算資源も割り当てられるため、メモリを下げるとモデルの読み込みや推論がさらに遅くなります。",["メモリサイズを最小値に下げる"]]},"MLA-C02-210":{"0":["違反の原因は単位の誤りと実際の分布の変化で、特徴量を削除すると予測に必要な情報を失い、根本の原因も解決しません。",["特徴量をすべて削除して"]],"3":["ベースラインを作り直して違反を消すだけでは、単位の誤りのようなデータの不具合も見えなくなり、問題が隠れてしまいます。",["違反が出ないようにする"]],"4":["単位の誤ったデータのまま再学習すると誤りを学習してしまいます。直近のデータだけで評価もせずにデプロイするのも危険です。",["すべての違反に対して","直ちに直近のデータだけで再学習"]]},"MLA-C02-211":{"0":["Trusted Advisor は既存のリソースに対するベストプラクティスの確認で、デプロイ前のモデルを複数のインスタンスで負荷テストしません。",["AWS Trusted Advisor"]],"1":["Debugger のプロファイリングは学習ジョブの資源の使い方を分析する機能で、推論インスタンスの負荷テストは行いません。",["SageMaker Debugger"]],"2":["Compute Optimizer は既存リソースの使用実績に基づいて推奨する仕組みで、デプロイ前のモデルの負荷テストは行いません。",["AWS Compute Optimizer"]]},"MLA-C02-212":{"1":["S3 Intelligent-Tiering はストレージの保管料金を最適化する機能で、エンドポイントや学習ジョブのインスタンス料金は下がりません。",["S3 Intelligent-Tiering"]],"2":["AWS Budgets は予算を設定して超過を通知する仕組みで、料金そのものを割り引く効果はありません。",["AWS Budgets"]],"3":["EC2 のリザーブドインスタンスは SageMaker のインスタンスには適用されません。ファミリーやリージョンの変更にも柔軟に対応できません。",["EC2 のリザーブドインスタンス"]]},"MLA-C02-213":{"0":["月 1 回の処理のために 1 年契約の容量を確保すると、使わない期間も料金がかかり割高です。即時性が不要ならバッチ推論のほうが安くなります。",["1 年契約で購入する"]],"2":["オンデマンドの単価のままで、並列数を上げるとスロットリングも起きやすくなります。対応モデルではバッチ推論のほうが低料金です。",["並列数を最大にして呼び出す"]],"3":["最大出力トークン数を増やすと出力トークンの消費が増え得るため、コストは下がらずむしろ上がるおそれがあります。",["最大出力トークン数を上限まで増やす"]]},"MLA-C02-214":{"0":["メタデータフィルターはナレッジベースの検索対象を絞り込む機能で、毎回同じプロンプトの処理コストを下げる仕組みではありません。",["メタデータフィルター"]],"1":["ガードレールは有害な入出力を防ぐ安全性の機能で、共通部分の処理コストやレイテンシーを下げる効果はありません。",["Bedrock のガードレール"]],"3":["S3 Transfer Acceleration は S3 へのアップロードを高速化する機能で、モデルが入力トークンを処理するコストとは関係ありません。",["S3 Transfer Acceleration"]]},"MLA-C02-215":{"0":["Trainium は学習向けのアクセラレーターで、CPU で十分な軽量モデルの推論に使うのは過剰で料金当たりの性能も高まりません。",["AWS Trainium を搭載した学習用"]],"2":["CPU で十分な軽量モデルに大型 GPU を使うと、性能を活かせないまま料金だけが大きく増えます。",["大型 GPU インスタンス"]],"3":["軽量なモデルに最大サイズのメモリ最適化インスタンスを使うと、資源が余って過剰な費用になります。",["最大サイズのインスタンス"]]},"MLA-C02-216":{"0":["Auto Scaling ポリシーはインスタンス数を増減させる設定で、プロジェクトごとの費用を集計する仕組みではありません。",["1 つの Auto Scaling ポリシーにまとめる"]],"1":["リソース名は Cost Explorer の集計の軸にならず、名前を変えてもプロジェクトごとに費用を分けて確認できません。",["リソース名の先頭文字を変える"]],"2":["CloudWatch のダッシュボードはメトリクスを表示するもので、プロジェクトごとの費用を Cost Explorer で分けて確認できません。",["CloudWatch のダッシュボード"]]},"MLA-C02-217":{"0":["最小 1 台では、使われていない夜間や週末も GPU インスタンスが 1 台稼働し続け、その料金が残ります。",["最小 1 台で設定する"]],"1":["小さいタイプにしても 24 時間稼働を続ける限り、使わない時間の費用は残ります。",["24 時間稼働を続ける"]],"3":["Savings Plans は単価を割り引くだけで、使われていない時間も稼働していれば費用は発生し続けます。",["Savings Plans で割引する"]]},"MLA-C02-218":{"1":["バッチ変換は一括処理のジョブで、リアルタイムでの応答ができず、生成モデルの提供方式として要件に合いません。",["バッチ変換ジョブに切り替える"]],"2":["部署ごとに目的の異なる 6 つのモデルを 1 つにまとめて再学習するのは負担が大きく、モデルごとの資源やスケーリングの制御もできなくなります。",["1 つのモデルにマージして再学習"]],"3":["使用率が 15% の状態でインスタンスを大きくすると、余る資源と費用がさらに増え、インスタンス数も減りません。",["より大きなものに変更する"]]},"MLA-C02-219":{"0":["最大実行時間はジョブを打ち切るまでの上限で、延ばしてもインスタンスの起動待ちは短くなりません。",["最大実行時間を延ばす"]],"1":["S3 のバージョニングはオブジェクトの履歴を残す機能で、学習ジョブのインスタンスの起動待ちとは関係ありません。",["S3 のバージョニング"]],"3":["エンドポイントは推論用の仕組みで、学習ジョブの代わりにはなりません。常時稼働させるとアイドル時間の費用もかかります。",["常時稼働のエンドポイントで学習する"]]},"MLA-C02-220":{"1":["GPU の利用を禁止すると、GPU が必要な作業ができなくなり、利用者の作業を妨げないという要件に反します。",["全面的に禁止する"]],"2":["ドメインを作り直すとユーザー設定や保存した作業内容を失うおそれがあり、利用者の作業を妨げます。",["ドメインを毎週作り直す"]],"3":["毎朝スペースを削除すると作業中のファイルなどを失うおそれがあり、停止忘れの対策としては作業への影響が大きすぎます。",["すべてのスペースを削除する"]]},"MLA-C02-221":{"0":["最小台数を最大台数と同じにすると常に最大台数で稼働することになり、使用率が低い状態で費用がさらに増えます。",["最小インスタンス数を最大インスタンス数と同じに"]],"1":["使用率が 20% 未満で余裕があるのにインスタンスを増やすと、余る資源と費用がさらに増えます。",["インスタンス数を増やして"]],"3":["サンプリング率を上げると S3 の保存量が増えるだけで、過大な GPU インスタンスの費用は下がりません。",["サンプリング率を上げる"]]},"MLA-C02-222":{"1":["呼び出しログを無効にしても費用の配分には影響せず、調査に使える記録が失われるだけです。アプリケーションごとに請求を分ける仕組みにはなりません。",["モデル呼び出しログを無効にする"]],"2":["時間帯を分けても請求データにはアプリケーションの区別が記録されず、タグで費用を分けて把握することはできません。業務にも支障が出ます。",["呼び出す時間帯を分ける"]],"3":["プロンプトの文言は請求データに反映されないため、文言を変えてもアプリケーションごとの費用は分けられません。",["別々のプロンプトの文言を使う"]]},"MLA-C02-223":{"0":["ALB のパスベースルーティングは URL のパスで振り分けるだけで、質問の難しさを判断して適切なモデルを選ぶことはできません。",["パスベースルーティング"]],"1":["Route 53 の加重ルーティングは決めた割合で DNS の応答を振り分けるだけで、質問の内容や難しさは考慮しません。",["Route 53 の加重ルーティング"]],"2":["シャドウテストは新モデルを本番トラフィックの複製で検証する機能で、質問ごとにモデルを使い分けてコストを下げる仕組みではありません。",["シャドウテスト"]]},"MLA-C02-224":{"0":["何も調整せずに小型モデルへ置き換えると、大型モデルに近い精度は得られず、業務の品質が下がるおそれがあります。",["何も追加せず、そのまま置き換える"]],"1":["プロビジョンドスループットを追加すると大型モデルを使い続けるため費用はむしろ増え、小型モデルを用意する目的も果たせません。",["プロビジョンドスループットを追加購入"]],"3":["max_tokens を 1 にすると出力が 1 トークンで打ち切られ、分類や要約の結果として使えません。品質を保つ要件に反します。",["max_tokens を 1 にする"]]},"MLA-C02-225":{"0":["S3 Express One Zone は低レイテンシー向けで保存単価が S3 標準より高く、まれにしか参照しない大量データの保存コストは上がります。",["S3 Express One Zone"]],"1":["EBS の io2 は高性能なブロックストレージで保存単価が非常に高く、数百 TB の参照頻度の低いデータの保管には向きません。",["EBS の io2 ボリューム"]],"2":["古いデータは監査対応で参照する必要があるため、すべて削除すると監査の要件を満たせなくなります。",["古いデータをすべて削除する"]]},"MLA-C02-226":{"1":["CloudTrail の管理イベントでは InvokeModel のようなデータの操作は記録されず、トークン量やプロンプトの内容も分かりません。",["CloudTrail の管理イベントだけ"]],"2":["機能ごとにアカウントを分けると各アプリケーションの移行が必要になり、改修を最小限にする要件に反します。プロンプトの調査の仕組みにもなりません。",["別の AWS アカウントを作成し"]],"3":["全機能に推定処理を追加するのは改修が多く、推定値は請求データとも一致しません。プロンプトの内容まで遡ることもできません。",["トークン数を推定して","全機能に追加する"]]},"MLA-C02-227":{"0":["OverheadLatency が小さいため SageMaker 側の問題ではありません。ModelLatency と CPU の逼迫から、計算資源の不足に自分で対処すべき状況です。",["AWS サポートに問い合わせて待つ"]],"1":["データキャプチャは推論の入出力を記録する機能で、レイテンシーは改善しません。保存量が増えて費用も上がります。",["サンプリング率を 100% に上げる"]],"2":["タイムアウトや再試行を増やすと、CPU が逼迫したエンドポイントへの負荷がさらに高まり、応答の遅さは解消しません。",["タイムアウトと再試行回数を増やす"]]},"MLA-C02-228":{"0":["月末の請求書確認では予算の 80% に達した時点で通知できず、呼び出し量の制限もできません。口頭の注意は技術的な統制になりません。",["月末に請求書を確認し","口頭で注意する"]],"1":["安いモデルに変えても部署ごとの費用は把握できず、利用制限がなければ大量利用による予算超過を防げません。品質も下がるおそれがあります。",["利用制限は設けない"]],"2":["共通の予算では原因の部署を特定できず、全員のアクセス停止は業務への影響が大きすぎます。部署ごとのレート制限もできません。",["全部署共通の 1 つの予算アラート","全員停止する"]]},"MLA-C02-229":{"0":["Savings Plans は単価を割り引くだけで、夜間や休日も GPU インスタンスが稼働していれば費用は残ります。夜間の費用をなくす要件を満たしません。",["Savings Plans で割引を受ける"]],"2":["バッチ変換では対話的な LLM の利用ができず、翌日まで待たせることは業務時間中の利用の要件に合いません。",["翌日まで回答を待ってもらう"]],"3":["最小インスタンス数を 2 にすると、リクエストがない夜間も 2 台分の GPU 料金がかかり、費用はさらに増えます。",["最小インスタンス数を 2 にして"]]},"MLA-C02-230":{"0":["最大サイズの GPU を常時稼働させると、学習していない時間も費用がかかり、コスト削減とは逆の結果になります。",["常時稼働させる"]],"1":["最大実行時間を無制限にしても料金は下がらず、異常なジョブが止まらずに費用が膨らむおそれがあります。",["最大実行時間を無制限にする"]],"2":["データの 99% を捨てると学習データが大幅に不足して精度が落ち、精度を下げたくないという要件に反します。",["1% のサンプルだけで学習する"]]},"MLA-C02-231":{"0":["SageMaker Runtime の呼び出しは IAM で認可され、エンドポイントに API キーを設定する仕組みはありません。キーの配布は漏えいのリスクもあります。",["API キーを設定して"]],"2":["InvokeEndpoint は SageMaker Runtime の API で、セキュリティグループで呼び出し元を制御するものではありません。IP 制限では特定の IAM ロールに限定できません。",["セキュリティグループで"]],"3":["KMS のキーポリシーは暗号化キーの利用を制御するもので、エンドポイントを呼び出せる IAM ロールを制限するものではありません。",["KMS キーのキーポリシーで呼び出し元を制限"]]},"MLA-C02-232":{"1":["SSE-S3 は S3 が管理するキーで暗号化する方式で、自社管理の KMS キーを使う要件を満たしません。学習ボリュームの暗号化にも対応しません。",["SSE-S3"]],"2":["AWS マネージドキーは AWS が管理するキーで、キーポリシーやローテーションを自社で管理できず、自社管理のキーを使う要件を満たしません。",["AWS マネージドキー（aws/sagemaker）"]],"3":["SSE-C は KMS を使わずキーを自分で提供する方式で要件に合いません。キーをノートブックに保存するのも漏えいのおそれがあり安全ではありません。",["SSE-C","キーをノートブックに保存する"]]},"MLA-C02-233":{"0":["sagemaker:* を拒否するとノートブック自体が使えなくなり、ノートブック内のルート権限も残ります。インターネットへのアクセスも制御できません。",["ルートアクセスを有効のまま"]],"1":["パブリックサブネットにはインターネットへの直接の経路があり、インターネットへの直接アクセスを禁止する要件に反します。",["パブリックサブネットに配置し"]],"3":["ボリュームの暗号化は保存データの保護で、ルートアクセスの無効化やインターネットへのアクセス制御にはなりません。",["KMS で暗号化する"]]},"MLA-C02-234":{"0":["Cognito ユーザープールはアプリケーションの利用者を認証する仕組みで、実際の操作から IAM ロールの権限を絞り込む機能はありません。",["Amazon Cognito ユーザープール"]],"2":["AWS Artifact は AWS のコンプライアンスレポートや契約を入手するサービスで、IAM ポリシーを生成する機能はありません。",["AWS Artifact"]],"3":["Resource Access Manager はアカウント間でリソースを共有するサービスで、使われた操作に基づく最小権限のポリシーは作れません。",["Resource Access Manager"]]},"MLA-C02-235":{"0":["NAT ゲートウェイ経由ではインターネット側の公開エンドポイントへ通信することになり、インターネットを経由しない要件に反します。",["NAT ゲートウェイを作成して"]],"1":["インターネットゲートウェイを追加するとサブネットがパブリックになり、インターネットを経由した経路になってしまいます。",["インターネットゲートウェイをプライベートサブネット"]],"3":["S3 のゲートウェイエンドポイントは S3 への通信専用で、Bedrock のモデル呼び出しには使えません。",["S3 のゲートウェイエンドポイント"]]},"MLA-C02-236":{"0":["Bedrock では利用者の入力や出力が基盤モデルの学習に使われることはなく、モデルプロバイダーとも共有されません。",["学習に自動で使われる"]],"2":["Bedrock では転送中と保管中のデータが暗号化され、KMS のキーも利用できます。暗号化に対応していないという説明は誤りです。",["暗号化に対応していない"]],"3":["Bedrock に送ったデータは利用者のアカウントの範囲で扱われ、他の AWS アカウントの利用者が参照することはできません。",["他の AWS アカウントの利用者からも参照できる"]]},"MLA-C02-237":{"1":["WAF のレートベースルールは一定時間のリクエスト数を制限する機能で、応答に含まれる個人情報を検出してマスクすることはできません。",["レートベースルール"]],"2":["プロンプトキャッシュは繰り返す入力の処理コストを下げる機能で、応答の個人情報をマスクする機能はありません。",["プロンプトキャッシュ"]],"3":["学習前バイアス指標はデータの属性間の偏りを測るもので、チャットボットの応答に含まれる個人情報のマスクには使えません。",["学習前バイアス指標"]]},"MLA-C02-238":{"1":["パブリックサブネットにはインターネットへの経路があり、インバウンドを拒否してもアウトバウンドの通信は防げません。",["パブリックサブネットで実行し"]],"2":["NAT ゲートウェイはインターネットへの経路になるため、インターネットへの通信を完全に遮断する要件に反します。",["NAT ゲートウェイ経由で"]],"4":["暗号化はデータの保護で、ネットワークの遮断にはなりません。既定の構成のままではインターネットへの通信が可能です。",["ネットワーク構成は既定のまま"]]},"MLA-C02-239":{"0":["Model Monitor のレポートは本番でのデータやモデル品質の監視結果で、どのデータやコードで学習したかの来歴は示しません。",["Model Monitor の監視レポート"]],"2":["CloudTrail は API 呼び出しの記録で、データセットやコード、モデルの関係をたどりにくく、監査での説明に十分ではありません。",["CreateTrainingJob の記録だけ"]],"3":["S3 のアクセスログはオブジェクトへのリクエストの記録で、モデルがどのデータやパラメータで学習されたかは分かりません。",["S3 のサーバーアクセスログ"]]},"MLA-C02-240":{"1":["すべての版を無期限に保持すると個人情報が不要に長く残り、漏えい時の影響が大きくなります。リスクを抑える要件と逆です。",["無期限に保持する"]],"2":["全社員に閲覧権限を与えると、個人情報に必要のない人までアクセスでき、最小権限の原則に反してリスクが高まります。",["全社員の IAM グループに付与する"]],"4":["キャプチャを無効にするとドリフトなどの監視に必要なデータが残らず、CPU 使用率では入力データの変化は分かりません。",["データキャプチャを無効にし"]]},"MLA-C02-241":{"1":["メールでの周知は技術的な制御ではなく、承認外のモデルの呼び出しを確実に拒否することはできません。",["メールで共有する"]],"2":["ガードレールは入出力の内容をフィルタリングする機能で、承認外のモデルの呼び出しそのものを拒否することはできません。",["ガードレールを適用する"]],"3":["監視は呼び出された後に気付く仕組みで、承認外のモデルの呼び出しを事前に拒否することはできません。",["監視するだけにする"]]},"MLA-C02-242":{"0":["ログの出力はコンテナの動作を記録するだけで、コンテナが外部にデータを送信することは防げません。",["CloudWatch Logs に出力する"]],"2":["インスタンス数はスケーリングの設定で、コンテナの外部への通信を遮断する効果はありません。",["インスタンス数を 1 にする"]],"3":["プライベートリポジトリはイメージの保管場所へのアクセスを制限するだけで、実行中のコンテナの外部通信は防げません。",["プライベートリポジトリに置くだけ"]]},"MLA-C02-243":{"0":["タグはリソースに付ける目印で、記載しても実際に通信が暗号化されることはありません。",["タグに「暗号化済み」と記載する"]],"1":["バージョニングはオブジェクトの履歴を残す機能で、インスタンス間でやり取りされるデータの暗号化にはなりません。",["バージョニングを有効にする"]],"2":["インスタンスを 1 台にすると分散学習ができなくなり、複数のインスタンスで学習するという前提を満たせません。",["分散学習をやめる"]]},"MLA-C02-244":{"0":["プロファイルを毎日削除すると利用者の作業環境が失われるうえ、社外からのアクセスを防ぐ制御にもなりません。",["ユーザープロファイルを毎日削除する"]],"1":["インスタンスタイプの制限はコストや資源の管理で、アクセス元のネットワークを社内に限定する効果はありません。",["インスタンスタイプを制限する"]],"3":["名前を推測されにくくしても認証や送信元の制限にはならず、社外から署名付き URL を作成することは防げません。",["推測されにくい名前に変更する"]]},"MLA-C02-245":{"0":["フルアクセスを与えると氏名や住所の列も読めてしまい、文書のルールだけでは技術的に参照を防げません。",["フルアクセスを与え","文書で定める"]],"1":["インスタンスの数はアクセス制御と関係がなく、特定の列を参照させない仕組みにはなりません。",["インスタンスを列の数だけ用意する"]],"3":["列ごとにバケットを分けるのは実質的にテーブルの複製と分割で、要件に反し、データの管理や結合も複雑になります。",["列ごとに別の S3 バケットに分割"]]},"MLA-C02-246":{"1":["平文の環境変数や Git での管理では、リポジトリやジョブの設定を見られる人にパスワードが漏れてしまいます。",["平文で設定し","Git リポジトリで管理する"]],"2":["ノートブックのセルに書いて共有すると、パスワードが多くの人の目に触れ、漏えいの原因になります。",["ノートブックのセルに書いて共有する"]],"3":["Base64 は誰でも元に戻せるエンコードで暗号化ではありません。スクリプトに書く限り漏えいのリスクは変わりません。",["Base64 でエンコードして"]]},"MLA-C02-247":{"0":["システムプロンプトを長くしても、指示を無視させる入力を検出してブロックする仕組みにはならず、攻撃を確実には防げません。",["システムプロンプトを長くする"]],"2":["セッションのタイムアウトは接続を維持する時間の設定で、悪意のある入力を検出してブロックすることはできません。",["セッションのタイムアウトを短くする"]],"3":["temperature は出力のばらつきを調整する設定で、上げるとかえって予測しにくい応答になり、攻撃の防御にはなりません。",["temperature を上げる"]]},"MLA-C02-248":{"0":["作成後に確認して通知する方式は事後の検出で、違反するジョブの作成そのものは防げず、組織全体での強制にもなりません。",["作成後に Lambda 関数で設定を確認し"]],"2":["手順書と四半期ごとの監査は各チームの設定に頼る方法で、違反するジョブの作成を技術的に防ぐことはできません。",["設定手順書を配布し"]],"3":["ネットワーク分離を無効にするのはセキュリティを弱める方向で、VPC での実行や KMS による暗号化を強制する仕組みにもなりません。",["ネットワーク分離を無効にする"]]},"MLA-C02-249":{"0":["バケットを公開すると誰でもモデルアーティファクトを取得できるようになり、必要最小限の権限という要件に反する重大なリスクです。",["パブリックに公開する"]],"2":["KMS キーを削除すると、そのキーで暗号化されたアーティファクトは復号できなくなり、本番でもデプロイできません。",["KMS キーを削除して"]],"3":["ルートユーザーのアクセスキーは全権限を持ち、共有すると重大なセキュリティリスクです。最小権限の要件に反します。",["ルートユーザーのアクセスキー"]]},"MLA-C02-250":{"0":["Lambda 関数にデータベースのフルアクセスを付与すると、必要なテーブルの読み取りだけを与えるという最小権限の要件に反します。",["データベースのフルアクセスを付与し"]],"1":["システムプロンプトでの禁止はモデルが従わない場合があり、口座番号を確実にマスクする要件を満たせません。",["システムプロンプトで禁止する"]],"2":["NAT ゲートウェイ経由はインターネット側の経路で、AdministratorAccess は最小権限に反し、プロンプトの指示では確実にマスクできません。",["NAT ゲートウェイ経由","AdministratorAccess を付与して"]]}};
